void secureRandom(int *min, int *max) {
    static unsigned char buffer[256];
    static size_t pos = 0;
    static size_t len = 0;

    if (len == 0) {
        FILE *urandom = fopen("/dev/urandom", "rb");
        if (!urandom) {
            perror("Failed to open /dev/urandom");
            exit(EXIT_FAILURE);
        }
        fread(buffer, 1, sizeof(buffer), urandom);
        fclose(urandom);
        len = sizeof(buffer);
    }

    unsigned int rand = buffer[pos++];
    pos %= len;
    *min += rand % (*max - *min + 1);
}

void populateRecords(Record **records, long *offsets, int keyCount) {
    for (int i = 0; i < keyCount; i++) {
        secureRandom(&offsets[i], &keyCount);
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }
        records[i]->value = offsets[i];
    }
}

void logValue(int value) {
    // Implement thread-safe logging mechanism here
    printf("Generated value: %d\n", value);
}

int main() {
    int keyCount = 10;
    Record **records = malloc(keyCount * sizeof(Record *));
    long *offsets = malloc(keyCount * sizeof(long));
    if (!records || !offsets) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    populateRecords(records, offsets, keyCount);

    for (int i = 0; i < keyCount; i++) {
        logValue(records[i]->value);
        free(records[i]);
    }

    free(offsets);
    free(records);

    return 0;
}
