#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024

void print_usage() {
    printf("Usage: %s [-h|--manpage] [-c] [-s] [-o output_file] input_file\n", argv[0]);
}

void print_manpage() {
    printf("Detailed manual page for the program...\n");
}

int count_non_comment_lines(const char* filename, bool case_insensitive, bool skip_comments, const char* output_filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    int line_count = 0;
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Trim newline character
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') {
            line[len-1] = '\0';
        }

        // Check for comment and skip if needed
        if (skip_comments && line[0] == '#') {
            continue;
        }

        // Count non-comment lines
        line_count++;
    }

    fclose(file);

    // Write result to output file
    if (output_filename) {
        FILE* output_file = fopen(output_filename, "w");
        if (!output_file) {
            perror("Error opening output file");
            return -1;
        }
        fprintf(output_file, "%d\n", line_count);
        fclose(output_file);
    }

    return line_count;
}

int main(int argc, char* argv[]) {
    bool case_insensitive = false;
    bool skip_comments = false;
    const char* input_filename = NULL;
    const char* output_filename = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "--manpage") == 0) {
            print_manpage();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0) {
            case_insensitive = true;
        } else if (strcmp(argv[i], "-s") == 0) {
            skip_comments = true;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            output_filename = argv[i] + 3;
        } else {
            input_filename = argv[i];
        }
    }

    if (!input_filename) {
        print_usage();
        return 1;
    }

    int result = count_non_comment_lines(input_filename, case_insensitive, skip_comments, output_filename);
    if (result == -1) {
        return 1;
    }

    printf("Number of non-comment lines: %d\n", result);

    return 0;
}
