#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct Record {
    char** fields;
    int num_fields;
    struct Record* next;
} Record;

Record* create_record() {
    Record* rec = (Record*)malloc(sizeof(Record));
    rec->fields = NULL;
    rec->num_fields = 0;
    rec->next = NULL;
    return rec;
}

void free_record(Record* rec) {
    for (int i = 0; i < rec->num_fields; i++) {
        free(rec->fields[i]);
    }
    free(rec->fields);
    free(rec);
}

double compute_average_last_two(const char** fields, int num_fields) {
    if (num_fields < 2) return -1.0; // Not enough fields
    double sum = 0;
    for (int i = num_fields - 2; i < num_fields; i++) {
        sum += atof(fields[i]);
    }
    return sum / 2;
}

int resolve_hostname(const char* hostname, char* ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(ip_address, ipstr);
        freeaddrinfo(res); // all done with this structure
        return 0;
    }

    freeaddrinfo(res); // clean up
    return -1;
}

int main() {
    FILE* file = fopen("large_file.txt", "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    Record* head = create_record();
    Record* current = head;

    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), file)) {
        Record* new_rec = create_record();

        char* token = strtok(buffer, "\t ");
        int field_count = 0;
        while (token) {
            new_rec->fields = realloc(new_rec->fields, (field_count + 1) * sizeof(char*));
            new_rec->fields[field_count] = strdup(token);
            field_count++;
            token = strtok(NULL, "\t ");
        }
        new_rec->num_fields = field_count;

        double avg = compute_average_last_two((const char**)new_rec->fields, field_count);
        if (avg >= 0) {
            printf("Average of last two fields: %f\n", avg);
        } else {
            fprintf(stderr, "Invalid record format.\n");
        }

        current->next = new_rec;
        current = new_rec;
    }

    fclose(file);

    Record* rec = head;
    while (rec) {
        free_record(rec);
        Record* temp = rec->next;
        rec = temp;
    }

    return EXIT_SUCCESS;
}
