#define MAX_INTS 1000

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int is_valid_integer(const char *str) {
    if (*str == '\0') return 0;
    int sign = 1;
    if (*str == '-' || *str == '+') {
        sign = (*str++ == '-') ? -1 : 1;
    }
    while (isdigit(*str)) {
        str++;
    }
    return (*str == '\0' && sign != 0);
}

int* read_integers(FILE *file, int *count) {
    if (!file) {
        log_error("Failed to open file");
        return NULL;
    }

    int *ints = (int *)malloc(MAX_INTS * sizeof(int));
    if (!ints) {
        log_error("Memory allocation failed");
        return NULL;
    }

    *count = 0;
    char buffer[256];
    while (*count < MAX_INTS && fgets(buffer, sizeof(buffer), file)) {
        buffer[strcspn(buffer, "\r\n")] = '\0'; // Remove newline character
        if (is_valid_integer(buffer)) {
            ints[(*count)++] = atoi(buffer);
        } else {
            log_error("Malformed integer encountered");
        }
    }

    return ints;
}

void find_and_print_largest(int *ints, int count) {
    if (count == 0) {
        log_error("No integers found");
        return;
    }

    int largest = ints[0];
    for (int i = 1; i < count; i++) {
        if (ints[i] > largest) {
            largest = ints[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void free_integers(int *ints) {
    free(ints);
}
