import java.util.concurrent.TimeUnit;
import java.util.Random;

public class PokemonReportGenerator {

    public static void generateReport(Pokemon pokemon) {
        try {
            String name = fetchPokemonName(pokemon.getName());
            String type = fetchPokemonType(pokemon.getType());
            String weakness = determineWeakness(type);

            System.out.println("Detailed Report for " + name);
            System.out.println("Type: " + type);
            System.out.println("Weaknesses: " + weakness);
        } catch (Exception e) {
            System.err.println("Failed to generate report: " + e.getMessage());
        }
    }

    private static String fetchPokemonName(String name) throws Exception {
        // Simulate network delay
        Thread.sleep(new Random().nextInt(401) + 100);
        return System.getenv("POKEMON_NAME_SERVICE") + "_" + name;
    }

    private static String fetchPokemonType(String type) throws Exception {
        // Simulate network delay
        Thread.sleep(new Random().nextInt(401) + 100);

        switch (type.toUpperCase()) {
            case "FIRE":
                return System.getenv("POKEMON_TYPE_SERVICE") + "_FIRE";
            case "WATER":
                return System.getenv("POKEMON_TYPE_SERVICE") + "_WATER";
            case "ELECTRIC":
                return System.getenv("POKEMON_TYPE_SERVICE") + "_ELECTRIC";
            default:
                throw new Exception("Unsupported Pokemon type: " + type);
        }
    }

    private static String determineWeakness(String type) {
        switch (type.toUpperCase()) {
            case "FIRE":
                return "Water, Ground, Rock";
            case "WATER":
                return "Electric, Grass";
            case "ELECTRIC":
                return "Ground";
            default:
                return "Unknown weakness for: " + type;
        }
    }

    public static void main(String[] args) {
        Pokemon pokemon = new Pokemon("Pikachu", "electric");
        generateReport(pokemon);
    }
}

class Pokemon {
    private String name;
    private String type;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }
}
