    unsigned long next_nonce;
} NonceManager;

NonceManager nonce_manager = { PTHREAD_MUTEX_INITIALIZER, 0 };

CryptoFunc* get_available_crypto_functions(int *count) {
    int hash_count, cipher_count;
    HashFunction** hashes = crypto_api_get_hashes(&hash_count);
    CipherFunction** ciphers = crypto_api_get_ciphers(&cipher_count);

    *count = hash_count + cipher_count;

    CryptoFunc* result = (CryptoFunc*)malloc(*count * sizeof(CryptoFunc));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int i = 0;
    for (int j = 0; j < hash_count; ++j) {
        result[i].name = strdup(hashes[j]->name);
        result[i].impl = hashes[j]->implementation;
        result[i].params = hashes[j]->params;
        pthread_mutex_lock(&nonce_manager.lock);
        result[i].nonce = nonce_manager.next_nonce++;
        pthread_mutex_unlock(&nonce_manager.lock);
        ++i;
    }

    for (int j = 0; j < cipher_count; ++j) {
        result[i].name = strdup(ciphers[j]->name);
        result[i].impl = ciphers[j]->implementation;
        result[i].params = ciphers[j]->params;
        pthread_mutex_lock(&nonce_manager.lock);
        result[i].nonce = nonce_manager.next_nonce++;
        pthread_mutex_unlock(&nonce_manager.lock);
        ++i;
    }

    crypto_api_free_hashes(hashes, hash_count);
    crypto_api_free_ciphers(ciphers, cipher_count);

    return result;
}

void free_crypto_functions(CryptoFunc* funcs, int count) {
    for (int i = 0; i < count; ++i) {
        free(funcs[i].name);
    }
    free(funcs);
}

// Example usage
int main() {
    int count;
    CryptoFunc* functions = get_available_crypto_functions(&count);

    if (functions) {
        printf("Available cryptographic functions:\n");
        for (int i = 0; i < count; ++i) {
            printf("%s (Nonce: %lu)\n", functions[i].name, functions[i].nonce);
        }
        free_crypto_functions(functions, count);
    }

    return 0;
}
