#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <openssl/pem.h>
#include <stdio.h>
#include <stdlib.h>

// Function to perform cryptographic operations based on command line options
EVP_CIPHER_CTX *performCryptoOperation(const char *input, const char *options, FILE *logFile) {
    EVP_CIPHER_CTX *ctx = NULL;
    int outlen = 0, tmplen = 0;

    // Parse command line options and determine operation to perform

    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Generate random key and IV for encryption
    unsigned char key[32], iv[16];
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(logFile, "Error generating random bytes\n");
        return NULL;
    }

    // Load encryption algorithm based on command line options
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (!cipher) {
        fprintf(logFile, "Invalid encryption algorithm specified\n");
        return NULL;
    }

    // Create cipher context and initialize
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(logFile, "Error creating cipher context\n");
        return NULL;
    }
    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(logFile, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Perform encryption
    if (1 != EVP_EncryptUpdate(ctx, NULL, &outlen, input, strlen(input))) {
        fprintf(logFile, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (!EVP_EncryptFinal_ex(ctx, NULL, &tmplen)) {
        fprintf(logFile, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Log operation
    fprintf(logFile, "Encryption successful\n");

    // Clean up and return cipher context
    EVP_CIPHER_CTX_free(ctx);
    return ctx;
}
