#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    sem_t* semaphore;
    char* file_path;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int initial_value) {
    SemaphoreManager* manager = malloc(sizeof(SemaphoreManager));
    if (manager == NULL) {
        return NULL; // Handle memory allocation failure
    }

    // Generate a secure temporary file path
    manager->file_path = strdup("/tmp/sema.XXXXXX");
    int fd = mkstemp(manager->file_path);
    if (fd == -1) {
        free(manager);
        return NULL; // Handle error in creating temporary file
    }
    close(fd);

    // Initialize semaphore with the specified initial value
    manager->semaphore = sem_open(manager->file_path, O_CREAT | O_EXCL, 0600, initial_value);
    if (manager->semaphore == SEM_FAILED) {
        remove(manager->file_path); // Clean up temporary file on error
        free(manager);
        return NULL; // Handle semaphore initialization failure
    }

    return manager;
}

void destroy_semaphore_manager(SemaphoreManager* manager) {
    if (manager != NULL) {
        sem_close(manager->semaphore);
        sem_unlink(manager->file_path); // Remove the temporary file
        free(manager->file_path);
        free(manager);
    }
}

int semaphore_wait(SemaphoreManager* manager) {
    if (manager == NULL || manager->semaphore == SEM_FAILED) {
        return -1; // Handle invalid state
    }

    return sem_wait(manager->semaphore); // Decrement the semaphore value
}

int semaphore_post(SemaphoreManager* manager) {
    if (manager == NULL || manager->semaphore == SEM_FAILED) {
        return -1; // Handle invalid state
    }

    return sem_post(manager->semaphore); // Increment the semaphore value
}
