// Function to validate and parse a single configuration line
bool parseSetting(const std::string& line, std::vector<std::string>& args) {
    std::istringstream iss(line);
    std::string token;
    while (iss >> token) {
        // Basic validation: check if the token is not empty
        if (!token.empty()) {
            args.push_back(token);
        }
    }
    return !args.empty(); // Return false if no valid tokens were found
}

// Main function to read settings from a file and process them into command-line arguments
std::vector<std::string> processSettings(const std::string& filePath) {
    std::ifstream configFile(filePath);
    if (!configFile.is_open()) {
        throw std::runtime_error("Failed to open configuration file");
    }

    std::vector<std::string> args;
    int processedCount = 0;
    int errorCount = 0;

    std::string line;
    while (std::getline(configFile, line)) {
        if (parseSetting(line, args)) {
            ++processedCount;
        } else {
            ++errorCount;
            std::cerr << "Error: Invalid setting format in line: " << line << std::endl;
        }
    }

    configFile.close();
    std::cout << "Processed settings: " << processedCount << ", Errors: " << errorCount << std::endl;

    return args;
}

int main() {
    try {
        std::vector<std::string> settings = processSettings("config.txt");
        // Use settings for command-line arguments
        for (const auto& arg : settings) {
            std::cout << arg << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
