class DynamicArray {
private:
    std::vector<int> data;
    mutable std::mutex mutex;

public:
    void insertAfterTarget(int target, int value) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = std::find(data.begin(), data.end(), target);
        if (it != data.end()) {
            data.insert(it + 1, value);
        } else {
            data.push_back(value);
        }
    }

    // Other methods and members can be added as needed
};
