public:
    SessionIDGenerator() : rng_(seed_) {}

    std::string generateSessionID() {
        std::lock_guard<std::mutex> lock(mutex_);
        return "SID-" + std::to_string(sessionCounter_++) + "-" + generateRandomString();
    }

private:
    std::mt19937 rng_;
    unsigned long sessionCounter_ = 0;
    std::mutex mutex_;

    static std::random_device rd;
    static std::mt19937 seedGenerator;

    static void initializeSeedGenerator() {
        if (seedGenerator == nullptr) {
            seedGenerator = std::make_unique<std::mt19937>(rd());
        }
    }

    static unsigned long getSeed() {
        initializeSeedGenerator();
        return seedGenerator->operator()();
    }

    std::string generateRandomString() {
        const std::string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        std::uniform_int_distribution<> dist(0, chars.size() - 1);
        std::string id;
        for (int i = 0; i < 16; ++i) {
            id += chars[dist(rng_)];
        }
        return id;
    }
};

std::random_device SessionIDGenerator::rd;
std::unique_ptr<std::mt19937> SessionIDGenerator::seedGenerator;

