    public static string BuildAndExecuteQuery(Dictionary<string, object> filterCriteria, SqlConnection connection, string sqlTemplate)
    {
        try
        {
            using (SqlCommand command = new SqlCommand(sqlTemplate, connection))
            {
                // Construct the query dynamically based on filter criteria
                StringBuilder dynamicPart = new StringBuilder();
                List<SqlParameter> parameters = new List<SqlParameter>();

                foreach (var criterion in filterCriteria)
                {
                    if (dynamicPart.Length > 0) dynamicPart.Append(" AND ");
                    dynamicPart.AppendFormat("{0} @P{1}", criterion.Key, parameters.Count);
                    parameters.Add(new SqlParameter("@P" + parameters.Count, criterion.Value));
                }

                command.CommandText += " WHERE " + dynamicPart.ToString();

                // Execute the query
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    // Process the results if needed
                    return "Query executed successfully";
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions and provide meaningful feedback
            return "Error executing query: " + ex.Message;
        }
    }

    public static void Main(string[] args)
    {
        string connectionString = "YourConnectionStringHere";
        Dictionary<string, object> filterCriteria = new Dictionary<string, object>
        {
            { "Name", "John" },
            { "Age", 30 }
        };
        string sqlTemplate = "SELECT * FROM Users";

