import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.w3c.dom.Node;
import org.w3c.dom.Element;
import java.io.File;
import java.util.concurrent.ConcurrentHashMap;

public class GameServerConfig {
    private ConcurrentHashMap<String, String> configMap = new ConcurrentHashMap<>();

    public void loadConfig(String filePath) throws Exception {
        File xmlFile = new File(filePath);
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        dbFactory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbFactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbFactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbFactory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        dbFactory.setXIncludeAware(false);
        dbFactory.setExpandEntityReferences(false);

        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
        Document doc = dBuilder.parse(xmlFile);
        doc.getDocumentElement().normalize();

        NodeList nList = doc.getElementsByTagName("setting");
        for (int temp = 0; temp < nList.getLength(); temp++) {
            Node nNode = nList.item(temp);
            if (nNode.getNodeType() == Node.ELEMENT_NODE) {
                Element eElement = (Element) nNode;
                String key = eElement.getAttribute("name");
                String value = eElement.getTextContent();
                configMap.put(key, value);
            }
        }
    }

    public int getMaxPlayerCount() {
        return Integer.parseInt(configMap.getOrDefault("maxPlayerCount", "10"));
    }

    public int getServerTimeout() {
        return Integer.parseInt(configMap.getOrDefault("serverTimeout", "300"));
    }

    public int getMatchmakingInterval() {
        return Integer.parseInt(configMap.getOrDefault("matchmakingInterval", "60"));
    }
}
```

