using System;
using System.IO;
using System.Xml.XPath;

public class XmlParser
{
    private static readonly object _lockObject = new object();
    private string _tempDirectory;

    public XmlParser()
    {
        InitializeTempDirectory();
    }

    private void InitializeTempDirectory()
    {
        _tempDirectory = Environment.GetEnvironmentVariable("XML_DIR_PATH");
        if (string.IsNullOrEmpty(_tempDirectory))
        {
            _tempDirectory = Path.Combine(Environment.Is64BitOperatingSystem ? @"C:\Temp\xml" : @"/tmp/xml", "xml");
            if (!Directory.Exists(_tempDirectory))
            {
                try
                {
                    Directory.CreateDirectory(_tempDirectory);
                }
                catch (Exception ex)
                {
                    LogError($"Failed to create directory: {ex.Message}");
                    _tempDirectory = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "xml");
                }
            }
        }
        lock (_lockObject)
        {
            if (!Directory.Exists(_tempDirectory))
            {
                try
                {
                    Directory.CreateDirectory(_tempDirectory);
                }
                catch (Exception ex)
                {
                    LogError($"Failed to create directory: {ex.Message}");
                }
            }
        }
    }

    public XPathNavigator GetElementByName(string xmlFilePath, string elementName)
    {
        if (!File.Exists(xmlFilePath))
        {
            throw new FileNotFoundException("XML file not found", xmlFilePath);
        }

        try
        {
            using (var reader = XmlReader.Create(xmlFilePath))
            {
                var doc = new XPathDocument(reader);
                var navigator = doc.CreateNavigator();
                navigator.MoveToRoot();

                if (!navigator.SelectSingleNode($"//{elementName}"))
                {
                    throw new Exception("No element found with the given name.");
                }

                return navigator.SelectSingleNode($"//{elementName}");
            }
        }
        catch (Exception ex)
        {
            LogError($"XPath evaluation error: {ex.Message}");
            throw;
        }
    }

    private void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}
