using System;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

public class WebPageService
{
    private readonly ILogger<WebPageService> _logger;
    private readonly DatabaseContext _dbContext;

    public WebPageService(ILogger<WebPageService> logger, DatabaseContext dbContext)
    {
        _logger = logger;
        _dbContext = dbContext;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElementContent([FromBody] UpdateRequest request)
    {
        try
        {
            if (!IsValidRequest(request))
            {
                return BadRequest("Invalid input");
            }

            var pageSection = await _dbContext.PageSections.FindAsync(request.SectionId);
            if (pageSection == null)
            {
                return NotFound("Page section not found");
            }

            var element = await _dbContext.Elements.FindAsync(request.ElementId);
            if (element == null)
            {
                return NotFound("Element not found");
            }

            // Resolve conflicts and apply the latest change
            var latestContent = GetLatestContent(request.Content, pageSection.LatestContent);

            // Update the element content
            element.HtmlContent = latestContent;

            await _dbContext.SaveChangesAsync();

            _logger.LogInformation($"Successfully updated element {request.ElementId} in section {request.SectionId}");
            return Ok("Update successful");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to update element {request.ElementId} in section {request.SectionId}");
            return StatusCode(500, "Internal server error");
        }
    }

    private bool IsValidRequest(UpdateRequest request)
    {
        // Implement input validation logic here
        // Example: Check for allowed characters and structures
        return Regex.IsMatch(request.Content, @"^[\w\s\.,!?]*$") && request.SectionId > 0 && request.ElementId > 0;
    }

    private string GetLatestContent(string newContent, string currentContent)
    {
        // Implement logic to resolve conflicts and apply the latest change
        // Example: Return the newer content if it's different from the current content
        return !newContent.Equals(currentContent) ? newContent : currentContent;
