            throw new IllegalArgumentException("Invalid password");
        }
        // Check old password validity and update in database
        return true;
    }

    public boolean resetPassword(String username, String email) {
        String tempPassword = generateRandomPassword();
        sendEmail(email, "Temporary Password", "Your temporary password is: " + tempPassword);
        // Save temp password for the user in a secure manner
        return true;
    }

    private boolean isValidPassword(String password) {
        return Pattern.matches(PASSWORD_PATTERN, password) && !password.toLowerCase().contains(username.toLowerCase());
