["```javascript
const express = require('express');
const path = require('path');
const fs = require('fs').promises;
const sanitizeFilename = require('sanitize-filename');

const app = express();
const port = 3000;
const safeDirectory = '/safe/directory';

app.use(async (req, res, next) => {
  try {
    let requestedPath = req.path;
    let fullPath = path.join(safeDirectory, sanitizeFilename(requestedPath));

    if (!fullPath.startsWith(safeDirectory)) {
      return res.status(403).send('Access Denied');
    }

    const fileStat = await fs.stat(fullPath);
    if (fileStat.isDirectory()) {
      return res.status(403).send('Cannot access directories');
    }

    req.fullPath = fullPath;
    next();
  } catch (error) {
    res.status(500).send('Internal Server Error');
  }
});

app.use(express.static(path.join(__dirname, 'public')));

app.get('*', async (req, res) => {
  try {
    const fileContent = await fs.readFile(req.fullPath);
    res.contentType(path.extname(req.fullPath));
    res.send(fileContent);
  } catch (error) {
    if (error.code === 'ENOENT') {
      res.status(404).send('File Not Found');
    } else {
      res.status(500).send('Internal Server Error');
    }
  }
});

app.listen(port, () => {
  console.log(`Server is running on http://localhost:${port}`);
});
```

This code block sets up a Node.js application using Express to serve static files from a user-specified directory over HTTP. It includes mechanisms to sanitize the user-provided directory path, handle errors gracefully, and ensure performance optimization through efficient file access."]

