const executeTestsInParallel = async (tests, concurrencyLimit) => {
  const results = [];
  const executing = new Set();

  for (const test of tests) {
    const { label, category, testFunction } = test;

    const executeTest = async () => {
      try {
        console.log(`Running ${label}...`);
        await testFunction();
        console.log(`${label} passed.`);
      } catch (error) {
        console.error(`Failed ${label}:`, error);
      } finally {
        executing.delete(executeTest);
        if (executing.size < concurrencyLimit && tests.length > 0) {
          const nextTest = tests.shift();
          setTimeout(() => executing.add(nextTest.execute), 0);
        }
      }
    };

    executing.add(executeTest);
    if (executing.size < concurrencyLimit) {
      await executeTest();
    } else {
      await new Promise(resolve => setTimeout(resolve, 100));
    }
  }

  while (executing.size > 0) {
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  return results;
};

