["```javascript
function renderScripts(scripts) {
    const scriptPromises = scripts.map(script => {
        return new Promise((resolve, reject) => {
            const scriptTag = document.createElement('script');

            if (script.type) scriptTag.setAttribute('type', script.type);
            if (script.src) scriptTag.setAttribute('src', script.src);
            if (script.async) scriptTag.setAttribute('async', 'true');
            if (script.defer) scriptTag.setAttribute('defer', 'true');

            Object.keys(script).forEach(key => {
                if (key !== 'type' && key !== 'src' && key !== 'async' && key !== 'defer') {
                    scriptTag.setAttribute(`data-${key}`, script[key]);
                }
            });

            scriptTag.onload = () => resolve(scriptTag.outerHTML);
            scriptTag.onerror = () => reject(new Error(`Failed to load script: ${script.src}`));

            document.body.appendChild(scriptTag);
        });
    });

    return Promise.all(scriptPromises).then(renderedScripts => {
        const footerHtml = `<footer>${renderedScripts.join('')}</footer>`;
        return footerHtml;
    }).catch(error => {
        console.error('Error loading scripts:', error);
        throw error;
    });
}
