const MAX_CONCURRENT_INSTANCES = 5;
let currentInstances = 0;
let dataQueue = [];
let processingIntervalId;

function startService(apiEndpoint, delay) {
    if (currentInstances >= MAX_CONCURRENT_INSTANCES) return;

    currentInstances++;
    const intervalId = setInterval(async () => {
        if (dataQueue.length > 0) {
            try {
                await sendDataToAnalytics(apiEndpoint, dataQueue);
                dataQueue = [];
            } catch (error) {
                console.error("Failed to send data:", error);
            }
        }
    }, delay);

    processingIntervalId = intervalId;
}

function stopService() {
    if (processingIntervalId) {
        clearInterval(processingIntervalId);
        processingIntervalId = null;
    }
    currentInstances--;
}

async function sendDataToAnalytics(apiEndpoint, data) {
    try {
        const response = await fetch(apiEndpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(data)
        });
        if (!response.ok) throw new Error('Network response was not ok');
    } catch (error) {
        console.error("Error sending data to analytics:", error);
    }
}

function pauseService() {
    stopService();
}

function resumeService(apiEndpoint, delay) {
    startService(apiEndpoint, delay);
}

