import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceController {
    private ExecutorService executor;
    private ResourceMonitor resourceMonitor;
    private ExternalService externalService;
    private JobQueue jobQueue;
    private Logger logger;
    private CloudMonitoringTool cloudMonitoringTool;

    public ServiceController() {
        executor = Executors.newFixedThreadPool(10);
        resourceMonitor = new ResourceMonitor();
        externalService = new ExternalService();
        jobQueue = new JobQueue();
        logger = new Logger();
        cloudMonitoringTool = new CloudMonitoringTool();
    }

    public void startService() {
        logger.log("Starting service...");
        executor.submit(() -> processJobs());
    }

    public void stopService() {
        logger.log("Stopping service...");
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private void processJobs() {
        while (!Thread.currentThread().isInterrupted()) {
            Job job = externalService.fetchJob();
            if (job != null) {
                jobQueue.add(job);
            }

            double cpuUsage = resourceMonitor.getCPUUsage();
            double memoryUsage = resourceMonitor.getMemoryUsage();

            if (cpuUsage > 0.8 || memoryUsage > 0.8) {
                logger.log("High CPU/Memory usage detected. Adjusting scheduling...");
                try {
                    TimeUnit.SECONDS.sleep(5);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            } else {
                processNextJob();
            }

            cloudMonitoringTool.reportResourceUsage(cpuUsage, memoryUsage);
        }
    }

    private void processNextJob() {
        Job job = jobQueue.poll();
        if (job != null) {
            try {
                logger.log("Processing job: " + job.getId());
                job.execute();
                logger.log("Job processed successfully.");
            } catch (Exception e) {
                logger.log("Error processing job: " + job.getId(), e);
                cloudMonitoringTool.reportError(e);
            }
        }
    }
}

class ResourceMonitor {
    public double getCPUUsage() {
        // Simulate CPU usage
        return Math.random();
    }

    public double getMemoryUsage() {
        // Simulate memory usage
        return Math.random();
    }
}

class ExternalService {
    public Job fetchJob() {
        // Fetch job from external service
        return new Job(Math.random());
    }
}

class JobQueue {
    private Queue<Job> queue = new LinkedList<>();

    public void add(Job job) {
        queue.add(job);
    }

    public Job poll() {
        return queue.poll();
    }
}

class Job {
    private int id;

    public Job(double randomValue) {
        this.id = (int) (randomValue * 1000); // Simulate unique job ID
    }

    public void execute() throws Exception {
        // Simulate job processing
        Thread.sleep(1000);
    }

    public int getId() {
        return id;
    }
}

class Logger {
    public void log(String message) {
        System.out.println(message);
    }

    public void log(String message, Exception e) {
        System.err.println(message + " - Error: " + e.getMessage());
    }
}

class CloudMonitoringTool {
    public void reportResourceUsage(double cpuUsage, double memoryUsage) {
        // Report CPU and memory usage to cloud monitoring tool
        System.out.printf("CPU Usage: %.2f%%\nMemory Usage: %.2f%%\n", cpuUsage * 100, memoryUsage * 100);
    }

    public void reportError(Exception e) {
        // Report error to cloud monitoring tool
        System.err.println("Error reported: " + e.getMessage());
    }
