['```rust
use reqwest::{
    ClientBuilder,
    Certificate,
    Proxy,
};
use std::time::Duration;

pub struct HttpClientConfig {
    base_urls: Vec<String>,
    disable_certificate_validation: bool,
    proxy: Option<Proxy>,
}

impl HttpClientConfig {
    pub fn new(base_urls: Vec<&str>, disable_certificate_validation: bool, proxy: Option<&str>) -> Self {
        Self {
            base_urls: base_urls.into_iter().map(|url| url.to_string()).collect(),
            disable_certificate_validation,
            proxy: proxy.map(Proxy::all),
        }
    }

    pub fn build_client(&self) -> reqwest::Client {
        let mut builder = ClientBuilder::new()
            .timeout(Duration::from_secs(10))
            .tcp_keepalive(Duration::from_secs(30));

        if self.disable_certificate_validation {
            builder = builder.dangerously_disable_hostname_verification();
        }

        if let Some(proxy) = &self.proxy {
            builder = builder.proxy(proxy.clone());
        }

        builder.build().unwrap()
    }
}

pub struct HttpClient {
    client: reqwest::Client,
    base_urls: Vec<String>,
}

impl HttpClient {
    pub fn new(config: HttpClientConfig) -> Self {
        let client = config.build_client();
        Self {
            client,
            base_urls: config.base_urls,
        }
    }

    pub async fn request(&self, method: reqwest::Method, path: &str) -> Result<reqwest::Response, reqwest::Error> {
        for url in &self.base_urls {
            let full_url = format!("{}{}", url, path);
            match self.client.request(method.clone(), full_url).send().await {
                Ok(response) => return Ok(response),
                Err(_) => continue,
            }
        }

        Err(reqwest::Error::new(reqwest::error::ErrorKind::Other, "All base URLs failed"))
    }
}
