['```rust
use std::process::{Command, Stdio};
use std::fs::File;
use std::os::unix::fs::MetadataExt;
use std::time::{Instant, SystemTime};
use std::collections::HashMap;

fn compile_with_logging_and_error_handling(file_paths: &[&str], optimization_level: u32, debug_symbols: bool) -> Result<Vec<i32>, String> {
    let mut exit_codes = Vec::new();
    let start_time = Instant::now();

    for file_path in file_paths {
        let output_dir = "target/debug/";
        std::fs::create_dir_all(output_dir).unwrap();

        let cmd = Command::new("rustc")
            .arg(file_path)
            .args(&["-C", &format!("opt-level={}", optimization_level)])
            .arg("-o")
            .arg(format!("{}/{}", output_dir, file_path.split('.').next().unwrap()))
            .current_dir(".")
            .stderr(Stdio::piped())
            .spawn()
            .expect("Failed to execute command");

        let mut child = cmd.wait_with_output().expect("Failed to wait on child");
        exit_codes.push(child.status.code().unwrap());

        if !child.stderr.is_empty() {
            eprintln!("Error compiling {}: {}", file_path, String::from_utf8_lossy(&child.stderr));
        }

        let metadata = File::open(file_path).expect("Failed to open file").metadata().expect("Failed to get metadata");
        println!("File: {}, Size: {} bytes, Permissions: {:?}",
                 file_path,
                 metadata.len(),
                 metadata.permissions());
    }

    let duration = start_time.elapsed();
    println!("Total Compilation Time: {:?}", duration);

    Ok(exit_codes)
}
