const fs = require('fs');
const crypto = require('crypto');
const path = require('path');

// Caching mechanism using a Map
const cache = new Map();

function generateAndHashRandomString(length, charSet, password, configDir) {
    const configPath = path.join(configDir, 'config.json');
    try {
        let configData;
        if (cache.has(configDir)) {
            configData = cache.get(configDir);
        } else {
            configData = JSON.parse(fs.readFileSync(configPath, 'utf8'));
            cache.set(configDir, configData);
        }

        const defaultLength = configData.length || length;
        const defaultCharSet = configData.charSet || charSet;

        let randomString = '';
        for (let i = 0; i < defaultLength; i++) {
            randomString += defaultCharSet.charAt(Math.floor(Math.random() * defaultCharSet.length));
        }

        const hash = crypto.createHash('sha256').update(password).digest('hex');

        return { randomString, hash };
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.error(`Error: Configuration file not found at ${configPath}`);
        } else if (error.code === 'EISDIR') {
            console.error(`Error: The provided path is a directory, not a file.`);
        } else {
            console.error(`An unexpected error occurred: ${error.message}`);
        }
        throw error;
    }
}
