async function generatePEMCertificate(oauthRequest, callback) {
  try {
    // Extract private key and certificate from OAuth request
    const privateKey = oauthRequest.privateKey;
    const certificate = oauthRequest.certificate;

    // Merge private key and certificate into a single PEM file
    const pemCertificate = `-----BEGIN PRIVATE KEY-----
${privateKey}
-----END PRIVATE KEY-----
-----BEGIN CERTIFICATE-----
${certificate}
-----END CERTIFICATE-----`;

    // Store the combined certificate in an in-memory buffer
    const certificateBuffer = Buffer.from(pemCertificate);

    // Simulate fetching and writing to a secure storage (e.g., in-memory cache)
    await writeFileAsync('/secure/storage.pem', pemCertificate);
    console.log('PEM Certificate generated and stored successfully.');

    // Callback with the PEM certificate and success status
    callback(null, { pemCertificate, status: 'success' });
  } catch (error) {
    // Log any errors that occur during the process
    console.error('Error generating PEM Certificate:', error);

