['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_QUEUE_SIZE 1000

typedef struct {
    time_t timestamps[MAX_QUEUE_SIZE];
    unsigned int ids[MAX_QUEUE_SIZE];
    int front, rear;
} PacketQueue;

void initQueue(PacketQueue *queue) {
    queue->front = -1;
    queue->rear = -1;
}

int isFull(PacketQueue *queue) {
    return ((queue->rear + 1) % MAX_QUEUE_SIZE == queue->front);
}

int isEmpty(PacketQueue *queue) {
    return (queue->front == -1);
}

void enqueue(PacketQueue *queue, time_t timestamp, unsigned int id) {
    if (isFull(queue)) {
        printf("Queue is full\n");
        return;
    }
    if (isEmpty(queue))
        queue->front = 0;
    queue->rear = (queue->rear + 1) % MAX_QUEUE_SIZE;
    queue->timestamps[queue->rear] = timestamp;
    queue->ids[queue->rear] = id;
}

void dequeue(PacketQueue *queue, time_t *timestamp, unsigned int *id) {
    if (isEmpty(queue)) {
        printf("Queue is empty\n");
        return;
    }
    *timestamp = queue->timestamps[queue->front];
    *id = queue->ids[queue->front];
    if (queue->front == queue->rear)
        queue->front = -1, queue->rear = -1;
    else
        queue->front = (queue->front + 1) % MAX_QUEUE_SIZE;
}

unsigned int generateUniqueId() {
    static unsigned int seed = time(NULL);
    return rand_r(&seed) % 0xFFFFFFFF; // Non-cryptographic PRNG
}

time_t getLatestTimestampAndId(PacketQueue *queue, unsigned int *id) {
    if (isEmpty(queue)) {
        printf("Queue is empty\n");
        return -1;
    }
    time_t latestTimestamp = queue->timestamps[queue->rear];
    *id = queue->ids[queue->rear];
    return latestTimestamp;
}

int main() {
    PacketQueue packetQueue;
    initQueue(&packetQueue);

    enqueue(&packetQueue, time(NULL), generateUniqueId());
    enqueue(&packetQueue, time(NULL) + 10, generateUniqueId());

    unsigned int id;
    time_t timestamp = getLatestTimestampAndId(&packetQueue, &id);
    printf("Latest Timestamp: %ld, ID: %u\n", timestamp, id);

    return 0;
}
