    std::lock_guard<std::mutex> lock(mtx);

    static int attackCount = 0;
    static int cooldown = 1; // Initial cooldown
    static auto lastTime = std::chrono::high_resolution_clock::now();

    auto now = std::chrono::high_resolution_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastTime).count() < cooldown) {
        return selectAttackWithCooldown(); // Recursively call until cooldown is over
    }

    int attack = prngs[currentPrngIndex]();
    currentPrngIndex = (currentPrngIndex + 1) % prngs.size();

    lastTime = now;
    cooldown = (attackCount++ % 2 == 0) ? 3 : 2; // Dynamic cooldown adjustment

    return attack;
}

void startGame() {
    initializePRNGs();
    while (true) {
        int selectedAttack = selectAttackWithCooldown();
        std::cout << "Selected Attack: " << selectedAttack << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate game loop
    }
}

int main() {
    std::thread gameThread(startGame);
    gameThread.join();
    return 0;
}
```

This code snippet demonstrates a basic structure for the function you described. It includes PRNG initialization, attack selection with cooldown, and thread-safe execution. The cooldown adjustment logic is simplified; in a real-world scenario, you would integrate external performance metrics and game events to dynamically adjust the cooldown period.']

