using System;
using System.Security.Cryptography;

public class SecureRandomValueGenerator
{
    private int minValue;
    private int maxValue;
    private RandomNumberGenerator rng;

    public SecureRandomValueGenerator(int min, int max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        minValue = min;
        maxValue = max;
        rng = RandomNumberGenerator.Create();
    }

    public float GenerateRandomFloat()
    {
        byte[] buffer = new byte[4];
        rng.GetBytes(buffer);
        return BitConverter.ToSingle(buffer, 0) * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomInt()
    {
        byte[] buffer = new byte[sizeof(int)];
        rng.GetBytes(buffer);
        return BitConverter.ToInt32(buffer, 0) % (maxValue - minValue + 1) + minValue;
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}";
    }

    public byte[] GenerateRandomBytes(int length)
    {
        byte[] buffer = new byte[length];
        rng.GetBytes(buffer);
        return buffer;
    }

    public void SeedGenerator(byte[] seed)
    {
        if (seed == null || seed.Length == 0)
            throw new ArgumentException("Seed cannot be null or empty.");

        rng.Dispose();
        rng = RandomNumberGenerator.Create();
        rng.Seed(seed);
    }
}
