const { v4: uuidv4 } = require('uuid');
const axios = require('axios');

class AsyncReducer {
  constructor(initialValueUrl) {
    this.initialValueUrl = initialValueUrl;
    this.guidGenerator = new GUIDGenerator();
    this.errorCount = 0;
    this.maxErrorCount = 3;
    this.externalData = null;
  }

  async reduceArray(numbers, callback) {
    try {
      if (!this.externalData) {
        await this.fetchExternalData();
      }

      const guid = this.guidGenerator.generate();
      console.log(`Starting reduction with GUID: ${guid}`);

      let result = this.externalData;
      for (const num of numbers) {
        result = await callback(result, num);
      }

      console.log(`Reduction completed with GUID: ${guid}`);
      return result;
    } catch (error) {
      if (this.errorCount < this.maxErrorCount) {
        this.errorCount++;
        console.error(`Error during reduction. Attempting to restart...`);
        await this.reduceArray(numbers, callback);
      } else {
        console.error('Persistent failure in reduction. Giving up.');
        throw error;
      }
    }
  }

  async fetchExternalData() {
    try {
      const response = await axios.get(this.initialValueUrl);
      this.externalData = response.data;
      console.log('External data fetched successfully');
    } catch (error) {
      console.error('Failed to fetch external data. Retrying...');
      await new Promise(resolve => setTimeout(resolve, 2000));
      await this.fetchExternalData();
    }
  }
}

class GUIDGenerator {
  constructor() {
    this.lastTimestamp = Date.now();
  }

  generate() {
    const timestamp = Date.now();
    if (timestamp <= this.lastTimestamp) {
      this.lastTimestamp = timestamp + 1;
    } else {
      this.lastTimestamp = timestamp;
    }

    return `${uuidv4()}-${this.lastTimestamp}`;
  }
}

// Usage example:
const reducer = new AsyncReducer('https://api.example.com/initialValue');
const numbers = [1, 2, 3, 4, 5];
const callback = (acc, num) => Promise.resolve(acc + num);

reducer.reduceArray(numbers, callback)
  .then(result => console.log(`Final result: ${result}`))
  .catch(error => console.error('Error:', error));
```

### Notes:
1. **GUID Generation**: The `GUIDGenerator` class ensures that each GUID is unique within a 24-hour period by appending the current timestamp to a UUID.
2. **External Data Fetching**: The `fetchExternalData` method uses `axios` to fetch initial data and includes retry logic to handle transient failures.
3. **Error Handling**: The main reduction function (`reduceArray`) handles errors gracefully, attempting to restart up to a maximum number of times before giving up.
4. **Concurrency**: The function is designed to be asynchronous, allowing for better handling of large datasets or external delays.

This code provides a robust framework for performing asynchronous reductions with error handling and GUID generation. Adjustments may be needed based on specific environment and performance requirements."]

