#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*Callback)(char*);

char* processString(const char* input, size_t sizeLimit, Callback callback) {
    if (input == NULL || callback == NULL) {
        return NULL;
    }

    // Allocate memory for the output string with space for the slash and null terminator
    char* result = (char*)malloc((sizeLimit + 2) * sizeof(char));
    if (result == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy input to the result buffer, ensuring it does not exceed size limit
    strncpy(result, input, sizeLimit);
    result[sizeLimit] = '\0'; // Ensure null termination

    // Check for potential buffer overflow by comparing lengths
    if (strlen(input) > sizeLimit - 1) {
        free(result); // Free allocated memory before returning NULL
        return NULL;
    }

    // Process the string using the callback function
    callback(result);

    // Append a forward slash to the end of the string
    result[sizeLimit + 1] = '/'; // Use sizeLimit+1 as the position for the slash
    result[sizeLimit + 2] = '\0'; // Ensure null termination

    return result;
}

// Example callback function to demonstrate usage
void exampleCallback(char* str) {
    // Example operation: Convert string to uppercase
    for (size_t i = 0; str[i]; ++i) {
        str[i] = toupper(str[i]);
    }
}
