#define MAX_SEQUENCE_LENGTH 10
#define SUPPORTED_FILE_TYPES 3

const char* supported_types[SUPPORTED_FILE_TYPES] = {"txt", "jpg", "png"};

unsigned long calculate_sequence(const char* filename) {
    unsigned long sum = 0;
    for (int i = 2; i < strlen(filename); i += 4) {
        if (isprint(filename[i])) {
            sum += filename[i];
        } else {
            sum += '?'; // Placeholder for non-printable characters
        }
    }
    return sum % 10000000000ULL; // Truncate to 10 digits
}

int validate_file_type(const char* file_type) {
    for (int i = 0; i < SUPPORTED_FILE_TYPES; ++i) {
        if (strcmp(file_type, supported_types[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

char* generate_new_filename(const char* filename, const char* file_type, int max_length) {
    unsigned long sequence = calculate_sequence(filename);
    if (!validate_file_type(file_type)) {
        return NULL; // Invalid file type
    }

    int new_length = strlen(filename) + MAX_SEQUENCE_LENGTH + 1;
    if (new_length > max_length) {
        return NULL; // Exceeds maximum length
    }

    char* new_filename = (char*)malloc(new_length);
    if (!new_filename) {
        return NULL; // Memory allocation failed
    }

    strcpy(new_filename, filename);
    snprintf(strrchr(new_filename, '.') + 1, MAX_SEQUENCE_LENGTH + 1, "%lu", sequence);

    return new_filename;
}

int main() {
    const char* filename = "example.txt";
    const char* file_type = "txt";
    int max_length = 20;

    char* new_filename = generate_new_filename(filename, file_type, max_length);
    if (new_filename) {
        printf("New Filename: %s\n", new_filename);
        free(new_filename);
    } else {
        printf("Failed to generate new filename.\n");
    }

    return 0;
}
