    unsigned char *bitmap;
    int width, height;
} ThemeBitmap;

CipherContext* initialize_cipher(const char *password, int iterations) {
    CipherContext *ctx = (CipherContext *)malloc(sizeof(CipherContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) return NULL;

    unsigned char salt[8];
    if (!RAND_bytes(salt, sizeof(salt))) return NULL;

    unsigned char derived_key[32];
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, iterations, 32, EVP_sha256(), derived_key);

    memcpy(ctx->key, derived_key, sizeof(derived_key));
    if (!RAND_bytes(ctx->iv, sizeof(ctx->iv))) return NULL;

    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(CipherContext *ctx) {
    if (ctx->ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}

