#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int *execute_commands(const char *commands[], int num_commands) {
    int *exit_statuses = (int *)calloc(num_commands, sizeof(int));
    if (!exit_statuses) {
        perror("Failed to allocate memory for exit statuses");
        return NULL;
    }

    for (int i = 0; i < num_commands; ++i) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("Fork failed");
            free(exit_statuses);
            return NULL;
        } else if (pid == 0) {
            // Child process
            char *argv[256];
            int j = 0;
            for (char *token = strtok((char *)commands[i], " "); token != NULL; token = strtok(NULL, " ")) {
                argv[j++] = token;
            }
            argv[j] = NULL;

            if (execvp(argv[0], argv) == -1) {
                perror("Execvp failed");
                exit(EXIT_FAILURE);
            }
        } else {
            // Parent process
            int status;
            if (waitpid(pid, &status, 0) == -1) {
                perror("Waitpid failed");
                free(exit_statuses);
                return NULL;
            }
            if (WIFEXITED(status)) {
                exit_statuses[i] = WEXITSTATUS(status);
            } else if (WIFSIGNALED(status)) {
                printf("Command %d terminated by signal %d\n", i, WTERMSIG(status));
                exit_statuses[i] = -1;
            }
        }
    }

    return exit_statuses;
}

int main() {
    const char *commands[] = {"echo Hello", "ls /nonexistent_directory", "date"};
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    int *exit_statuses = execute_commands(commands, num_commands);
    if (exit_statuses) {
        for (int i = 0; i < num_commands; ++i) {
            printf("Command %d exited with status %d\n", i, exit_statuses[i]);
        }
        free(exit_statuses);
    }

    return 0;
}
