public class WebSiteManager
{
    public static void AddAndStartWebsite(string directoryPath, string siteName, EnvironmentSettings environmentSettings)
    {
        using (ServerManager serverManager = new ServerManager())
        {
            if (!Directory.Exists(directoryPath))
            {
                throw new DirectoryNotFoundException($"The specified directory does not exist: {directoryPath}");
            }

            string configFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configFilePath))
            {
                LogInfo("Web.config file not found in the specified directory.", serverManager.Log);
                return;
            }

            Site existingSite = serverManager.Sites.FirstOrDefault(s => s.Name == siteName);
            if (existingSite != null)
            {
                LogWarning($"A website with the name '{siteName}' already exists. Please use a unique site name.", serverManager.Log);
                return;
            }

            ApplicationPool appPool = serverManager.ApplicationPools.FirstOrDefault(ap => ap.ManagedRuntimeVersion == "v4.0");
            if (appPool == null)
            {
                LogError("No suitable application pool found for the new website.", serverManager.Log);
                return;
            }

            Site newSite = serverManager.Sites.Add(siteName, "http", "*", 80, directoryPath, appPool.Name);
            ApplyEnvironmentSettings(newSite, environmentSettings);

            newSite.Start();
            LogInfo($"Website '{siteName}' added and started successfully.", serverManager.Log);
