    private static void LogError(string message, ServerLog log)
    {
        log.WriteLine($"ERROR - {DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")} - Process ID: {Process.GetCurrentProcess().Id} - {message}");
    }
}

public class EnvironmentSettings
{
    public string ConnectionString { get; set; }
    public string LogLevel { get; set; }
    // Add other environment-specific settings as needed
}
