import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class DiskUsageManager {

    public static void main(String[] args) {
        // Configuration parameters
        String directoryPath = "C:\\path\\to\\directory";
        List<String> backupDirectories = new ArrayList<>();
        backupDirectories.add("C:\\path\\to\\backup1");
        backupDirectories.add("C:\\path\\to\\backup2");

        try {
            checkDiskUsage(directoryPath);
            clearDirectoryExceptBackups(directoryPath, backupDirectories);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void checkDiskUsage(String directoryPath) throws IOException {
        File directory = new File(directoryPath);
        if (!directory.exists() || !directory.isDirectory()) {
            throw new IllegalArgumentException("Invalid directory path");
        }

        ProcessBuilder processBuilder = new ProcessBuilder("dir", "/s");
        processBuilder.directory(directory);
        Process process = processBuilder.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Command execution failed with exit code " + exitCode);
        }
    }

    public static void clearDirectoryExceptBackups(String directoryPath, List<String> backupDirectories) throws IOException {
        Path directory = Paths.get(directoryPath);

        try (Files.walk(directory)) {
            for (Path path : Files.walk(directory)) {
                if (!backupDirectories.contains(path.toString()) && !path.equals(directory)) {
                    Files.delete(path);
                }
            }
        } catch (IOException e) {
            throw new IOException("Failed to clear directory", e);
        }
    }
}
