import java.io.FileInputStream;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class ConfigValidator {

    private static final String CONFIG_FILE_PATH = "config.properties";
    private static final int MAX_RETRIES = 5;
    private static final long RETRY_DELAY_MILLIS = 1000;

    public boolean validateConfig() {
        Properties properties = loadProperties(CONFIG_FILE_PATH);
        if (properties == null) {
            return false;
        }

        String apiKey = properties.getProperty("api_key");
        String endpointUrl = properties.getProperty("endpoint_url");
        String databaseConnectionString = properties.getProperty("database_connection_string");
        String timeoutDurationStr = properties.getProperty("timeout_duration");

        if (apiKey == null || apiKey.isEmpty()) {
            System.err.println("API Key is missing or empty.");
            return false;
        }

        if (endpointUrl == null || !isValidUrl(endpointUrl)) {
            System.err.println("Endpoint URL is missing or invalid.");
            return false;
        }

        if (databaseConnectionString == null || databaseConnectionString.isEmpty()) {
            System.err.println("Database Connection String is missing or empty.");
            return false;
        }

        long timeoutDuration = 0;
        try {
            timeoutDuration = Long.parseLong(timeoutDurationStr);
        } catch (NumberFormatException e) {
            System.err.println("Timeout duration is invalid.");
            return false;
        }

        if (timeoutDuration <= 0) {
            System.err.println("Timeout duration must be a positive number.");
            return false;
        }

        for (int i = 0; i < MAX_RETRIES; i++) {
            if (testEndpointConnection(endpointUrl, timeoutDuration)) {
                return true;
            }
            try {
                TimeUnit.MILLISECONDS.sleep((long) (RETRY_DELAY_MILLIS * Math.pow(2, i)));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }

        System.err.println("Failed to connect to the endpoint after multiple attempts.");
        return false;
    }

    private Properties loadProperties(String filePath) {
        try (FileInputStream fis = new FileInputStream(filePath)) {
            Properties properties = new Properties();
            properties.load(fis);
            return properties;
        } catch (IOException e) {
            System.err.println("Failed to load configuration file: " + e.getMessage());
            return null;
        }
    }

    private boolean isValidUrl(String url) {
        try {
            new URL(url).toURI();
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private boolean testEndpointConnection(String endpointUrl, long timeoutDuration) {
        try {
            HttpURLConnection connection = (HttpURLConnection) new URL(endpointUrl).openConnection();
            connection.setConnectTimeout((int) timeoutDuration);
            connection.setRequestMethod("GET");
            int responseCode = connection.getResponseCode();
            return responseCode == HttpURLConnection.HTTP_OK;
        } catch (IOException e) {
            System.err.println("Failed to connect to the endpoint: " + e.getMessage());
            return false;
        }
    }

    public static void main(String[] args) {
        ConfigValidator validator = new ConfigValidator();
        boolean isValid = validator.validateConfig();
        System.out.println("Configuration is valid: " + isValid);
    }
}
