using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Generic;

public class Base64DecryptionProcessor
{
    public string ProcessMessages(string inputFile, string outputDir, string configFilePath)
    {
        try
        {
            var keyIVConfig = LoadKeyIVConfig(configFilePath);
            var messages = File.ReadAllLines(inputFile);

            foreach (var message in messages)
            {
                var parts = message.Split(';');
                if (parts.Length != 3)
                {
                    LogError("Invalid message format.");
                    continue;
                }

                string base64Message = parts[0];
                string keyName = parts[1];
                string checksum = parts[2];

                if (!keyIVConfig.ContainsKey(keyName))
                {
                    LogError($"Key '{keyName}' not found in configuration.");
                    continue;
                }

                var config = keyIVConfig[keyName];
                byte[] decryptedBytes = DecryptMessage(base64Message, config.Key, config.IV);
                string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

                if (!ValidateChecksum(decryptedMessage, checksum, config.ChecksumAlgorithm))
                {
                    LogError($"Checksum validation failed for message using key '{keyName}'.");
                    continue;
                }

                File.WriteAllText(Path.Combine(outputDir, $"{keyName}.dec"), decryptedMessage);
            }

            return "Decryption and validation completed successfully.";
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            return null;
        }
    }

    private Dictionary<string, DecryptionConfig> LoadKeyIVConfig(string configFilePath)
    {
        // Implement logic to load key/IV configurations from the specified file.
        // This should parse the configuration file and populate a dictionary with key names as keys
        // and DecryptionConfig objects as values.
        return new Dictionary<string, DecryptionConfig>();
    }

    private byte[] DecryptMessage(string base64Message, byte[] key, byte[] iv)
    {
        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = key;
            tdes.IV = iv;
            tdes.Mode = CipherMode.CBC;

            ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV);
            byte[] decryptedBytes = Convert.FromBase64String(base64Message);

            using (MemoryStream msDecrypt = new MemoryStream(decryptedBytes))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    return csDecrypt.ToArray();
                }
            }
        }
    }

    private bool ValidateChecksum(string message, string checksum, string algorithm)
    {
        // Implement logic to validate the checksum of the decrypted message.
        using (HashAlgorithm hash = HashAlgorithm.Create(algorithm))
        {
            byte[] hashBytes = hash.ComputeHash(Encoding.UTF8.GetBytes(message));
            return Convert.ToBase64String(hashBytes) == checksum;
        }
    }

    private void LogError(string message)
    {
        // Implement logic to log error messages.
        Console.WriteLine($"ERROR: {message}");
    }
}

public class DecryptionConfig
{
    public byte[] Key { get; set; }
    public byte[] IV { get; set; }
    public string ChecksumAlgorithm { get; set; }
}
