using System.Threading.Tasks;

public class FileHasher
{
    public async Task ProcessFileAsync(string filePath)
    {
        using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
        {
            SHA1 sha1 = SHA1.Create();
            byte[] buffer = new byte[4096];
            int bytesRead;

            while ((bytesRead = await fileStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                sha1.TransformBlock(buffer, 0, bytesRead, null, 0);
            }

            sha1.TransformFinalBlock(new byte[0], 0, 0);
            byte[] hashBytes = sha1.Hash;

            // Process the hash (e.g., logging, sending to external service)
            await LogHashAsync(filePath, BitConverter.ToString(hashBytes).Replace("-", "").ToLower());
        }
    }

    private async Task LogHashAsync(string filePath, string hash)
    {
        // Simulate logging or sending metrics
        Console.WriteLine($"File: {filePath}, SHA-1: {hash}");
    }
}
