public class AesGcmDecryptionService
{
    private readonly Dictionary<int, byte[]> _keys = new Dictionary<int, byte[]>();
    private int _currentKeyIndex;

    public void AddKey(int keyId, byte[] key)
    {
        if (_keys.ContainsKey(keyId))
        {
            throw new ArgumentException("Key ID already exists.");
        }

        _keys[keyId] = key;
    }

    public void SetCurrentKeyIndex(int keyIndex)
    {
        if (!_keys.ContainsKey(keyIndex))
        {
            throw new ArgumentException("Invalid key index.");
        }

        _currentKeyIndex = keyIndex;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] aad, byte[] nonce)
    {
        if (!_keys.TryGetValue(_currentKeyIndex, out var currentKey))
        {
            throw new InvalidOperationException("No active key set.");
        }

        using (AesGcm aesGcm = AesGcm.Create(256))
        {
            try
            {
                aesGcm.Decrypt(currentKey, nonce, aad, ciphertext, out byte[] plaintext);
                return plaintext;
            }
            catch (CryptographicException)
            {
                // Fallback mechanism: Log the error and return an empty array or throw a custom exception.
                Console.WriteLine("Decryption failed. Please check the input data.");
                return Array.Empty<byte>();
            }
        }
    }

    public void InitializeKeyRotation(List<Tuple<int, byte[]>> keys)
    {
        foreach (var key in keys)
        {
            AddKey(key.Item1, key.Item2);
        }

        if (_keys.Count > 0)
        {
            SetCurrentKeyIndex(_keys.Keys.Min());
        }
    }
}
