use std::env;
use std::fs::{create_dir_all, DirEntry};
use std::path::{Path, PathBuf};
use log::{info, warn};

fn sanitize_name(name: &str) -> String {
    name.chars()
        .filter(|c| c.is_alphanumeric() || *c == '-' || *c == '_' || *c == '.')
        .collect::<String>()
}

fn create_directory(name: &str) -> Result<PathBuf, std::io::Error> {
    let sanitized_name = sanitize_name(name);
    let path = Path::new(&sanitized_name);

    if path.exists() && !path.is_dir() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::AlreadyExists,
            "Path already exists but is not a directory",
        ));
    }

    create_dir_all(path)?;
    info!("Directory created: {:?}", path);
    Ok(path.to_path_buf())
}

fn set_env_variable(name: &str, dir_path: &Path) -> Result<(), std::env::VarError> {
    let env_name = format!("{}_PATH", name.to_uppercase());
    if env::var(&env_name).is_ok() {
        warn!("Environment variable {} already set. Using existing path.", env_name);
    } else {
        env::set_var(env_name, dir_path);
        info!("Set environment variable {}: {:?}", env_name, dir_path);
    }
    Ok(())
}

fn manage_directory(name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = create_directory(name)?;
    set_env_variable(name, &dir_path)?;

    Ok(())
}
