import json
import logging
from abc import ABC, abstractmethod

# Setup basic configuration for logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class JSONProcessor(ABC):
    @abstractmethod
    def process(self, data: dict) -> None:
        pass

class FactoryRegistry:
    _registry = {}

    @classmethod
    def register(cls, name, factory_function):
        if not issubclass(factory_function, JSONProcessor):
            raise ValueError("Factory function must be a subclass of JSONProcessor")
        cls._registry[name] = factory_function

    @classmethod
    def get_factory(cls, name):
        return cls._registry.get(name)

class DynamicJSONProcessor(JSONProcessor):
    def __init__(self, factory_name: str):
        self.factory_name = factory_name
        self.factory = FactoryRegistry.get_factory(factory_name)

    def process(self, data: dict) -> None:
        if self.factory:
            instance = self.factory()
            instance.process(data)
        else:
            logger.error("No factory registered for %s", self.factory_name)

# Example usage
class SimpleProcessor(JSONProcessor):
    def process(self, data: dict) -> None:
        logger.info("Processing simple data: %s", data)

FactoryRegistry.register('simple', SimpleProcessor)

# Creating an instance dynamically and processing JSON
processor = DynamicJSONProcessor('simple')
json_data = {'key': 'value'}
processor.process(json_data)
