NFAPI_CRC_INDICATION_PDU_T* generateStructures(int N, int M) {
    if (N > MAX_N || M > MAX_M) {
        printf("Error: Input values exceed maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % M + 1;
        structures[i].RNTI = rand() % M + 1;
        structures[i].CRCFLAG = rand() % 2;
    }

    return structures;
}

int findLargestInteger(int* array, int size) {
    if (size <= 0) {
        printf("Error: Invalid input size.\n");
        return -1; // Error indicator
    }

    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    int N, M;
    printf("Enter the number of structures (N): ");
    scanf("%d", &N);
    printf("Enter the maximum value for input (M): ");
    scanf("%d", &M);

    NFAPI_CRC_INDICATION_PDU_T* structures = generateStructures(N, M);
    if (!structures) {
        return 1; // Error handling
    }

    int* array = malloc(M * sizeof(int));
    if (!array) {
        printf("Memory allocation failed.\n");
        free(structures);
        return 1; // Error handling
    }

    printf("Enter up to %d integers:\n", M);
    int count = 0;
    while (count < M && scanf("%d", &array[count]) == 1) {
        ++count;
    }

    int largest = findLargestInteger(array, count);
    if (largest != -1) {
        printf("The largest integer is: %d\n", largest);
    } else {
        printf("No valid integers entered.\n");
    }

    free(structures);
    free(array);
    return 0;
}
