typedef struct {
    int value;
} record;

int initialize_library(size_t offset_count, size_t key_count, size_t record_count, long *offsets, int *keys, record **records) {
    // Initialize OpenSSL
    if (!OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS | OPENSSL_INIT_LOAD_CONFIG, NULL)) {
        return -1;
    }

    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest_alias("sha1", "SHA");

    // Allocate memory for offsets
    if (!(offsets = (long *)malloc(offset_count * sizeof(long)))) {
        return -1;
    }

    // Initialize offsets with pseudo-random values
    if (!RAND_bytes((unsigned char *)offsets, offset_count * sizeof(long))) {
        free(offsets);
        return -1;
    }

    // Allocate memory for keys
    if (!(keys = (int *)malloc(key_count * sizeof(int)))) {
        free(offsets);
        return -1;
    }

    // Initialize keys with pseudo-random values
    if (!RAND_bytes((unsigned char *)keys, key_count * sizeof(int))) {
        free(keys);
        free(offsets);
        return -1;
    }

    // Allocate memory for records
    if (!(*records = (record *)malloc(record_count * sizeof(record)))) {
        free(keys);
        free(offsets);
        return -1;
    }

    // Initialize records with pseudo-random values within a specified range
    const int range = 1000; // Example range, adjust as needed
    for (size_t i = 0; i < record_count; ++i) {
        if (!RAND_bytes((unsigned char *)&(*records)[i].value, sizeof(int))) {
            free((*records));
            free(keys);
            free(offsets);
            return -1;
        }
        (*records)[i].value %= range;
    }

    return 0;
}

// Example usage
int main() {
    const size_t offset_count = 10;
    const size_t key_count = 5;
    const size_t record_count = 20;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    if (initialize_library(offset_count, key_count, record_count, &offsets, &keys, &records) != 0) {
        return -1;
    }

    // Use offsets, keys, and records as needed

    // Clean up
    free(records);
    free(keys);
    free(offsets);

    EVP_cleanup();

    return 0;
}
