int process_image_stream(char** file_paths, int num_files) {
    for (int i = 0; i < num_files; i++) {
        struct stat file_stat;
        if (stat(file_paths[i], &file_stat) != 0) {
            fprintf(stderr, "Error getting file stats: %s\n", strerror(errno));
            return -1;
        }

        if (file_stat.st_size > MAX_FILE_SIZE) {
            fprintf(stderr, "File size exceeds maximum limit: %s\n", file_paths[i]);
            continue;
        }

        int fd = open(file_paths[i], O_RDONLY);
        if (fd == -1) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
            return -1;
        }

        // Allocate memory for pixel data
        size_t pixel_data_size = calculate_pixel_data_size(file_stat.st_size);
        if (pixel_data_size == 0) {
            close(fd);
            fprintf(stderr, "Memory allocation error\n");
            return -1;
        }

        char* pixel_data = malloc(pixel_data_size);
        if (!pixel_data) {
            close(fd);
            fprintf(stderr, "Out of memory\n");
            return -1;
        }

        // Read pixel data from file
        ssize_t bytes_read = read(fd, pixel_data, pixel_data_size);
        if (bytes_read != pixel_data_size) {
            free(pixel_data);
            close(fd);
            fprintf(stderr, "Error reading file: %s\n", strerror(errno));
            return -1;
        }

        // Process image data
        process_image_data(pixel_data, bytes_read);

        // Free allocated memory and close file descriptor
        free(pixel_data);
        close(fd);
    }
    return 0;
}

size_t calculate_pixel_data_size(size_t file_size) {
    // Calculate the required size for pixel data based on file size
    // Ensure to handle potential integer overflows and under-allocation
