import hashlib
import os
import logging

def calculate_sha1_hash(file_path, chunk_size=65536):
    sha1 = hashlib.sha1()
    try:
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                sha1.update(data)
        return sha1.hexdigest()
    except IOError as e:
        logging.error(f"Error reading file {file_path}: {e}")
        return None

# Example usage
if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python script.py <file_path>")
    else:
        file_path = sys.argv[1]
        result = calculate_sha1_hash(file_path)
        if result:
            print(f"SHA-1 hash of {file_path}: {result}")
