typedef struct {
    unsigned char *digest;
} CipherObject;

CipherObject* performCryptoOperation(int *array, int size, const char *option) {
    CipherObject *cipher = (CipherObject *)malloc(sizeof(CipherObject));
    cipher->digest = (unsigned char *)malloc(SHA256_DIGEST_LENGTH);

    // Implement cryptographic operation using OpenSSL
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    for (int i = 0; i < size; i++) {
        SHA256_Update(&sha256, &array[i], sizeof(int));
    }
    SHA256_Final(cipher->digest, &sha256);

    return cipher;
}

void* unionFindCheckDisjointSets(UnionFind *uf, int a, int b) {
    clock_t start = clock();
    void *result = union_find_check_disjoint_sets(uf, a, b);
    clock_t end = clock();

    double execution_time = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Execution time for disjoint set check: %f ms\n", execution_time * 1000);

    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input_string> <option>\n", argv[0]);
        return 1;
    }

    // Parse input string and create integer array
    int *array = parse_input_string(argv[1]);
    if (!array) {
        fprintf(stderr, "Invalid input string\n");
        return 1;
    }

    // Initialize Union-Find data structure
    int size = sizeof(array) / sizeof(int);
    UnionFind *uf = union_find_init(size);

    // Perform cryptographic operation and Union-Find checks
    CipherObject *cipher = performCryptoOperation(array, size, argv[2]);
    void *result1 = unionFindCheckDisjointSets(uf, 0, 1);
    void *result2 = unionFindCheckDisjointSets(uf, 2, 3);

    // Clean up and free resources
    union_find_free(uf);
    free(array);
    free(cipher->digest);
    free(cipher);

    return 0;
}
