import jwt
from flask import Flask, request, jsonify, g
from functools import wraps
from time import time
from redis import Redis
from logging import getLogger

app = Flask(__name__)
redis_client = Redis(host='localhost', port=6379, db=0)
logger = getLogger('session_token_generator')

def generate_session_token(user_id):
    payload = {
        'user_id': user_id,
        'exp': time() + 3600  # Token expires in 1 hour
    }
    token = jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')
    return token

def authenticate_user(username, password):
    # Placeholder for actual authentication logic
    # Returns user_id if successful, None otherwise
    pass

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    user_id = authenticate_user(username, password)
    if user_id is None:
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_session_token(user_id)
    redis_client.set(token, user_id, ex=3600)  # Cache for 1 hour
    logger.info(f'Session token generated for user {user_id}')

    return jsonify({'token': token}), 200

def session_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'error': 'Missing session token'}), 401

        user_id = redis_client.get(token)
        if not user_id:
            try:
                payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
                user_id = payload['user_id']
                redis_client.setex(token, 3600, user_id)  # Refresh cache
            except jwt.ExpiredSignatureError:
                return jsonify({'error': 'Session token expired'}), 401
            except jwt.InvalidTokenError:
                return jsonify({'error': 'Invalid session token'}), 401

        g.user_id = user_id
        return f(*args, **kwargs)
    return decorated_function

@app.route('/protected', methods=['GET'])
