#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <boost/asio.hpp>
#include <boost/date_time/posix_time/posix_time.hpp>

class NetworkMonitor {
public:
    virtual ~NetworkMonitor() {}
    virtual std::string fetchTrafficData() = 0;
};

class MockNetworkMonitor : public NetworkMonitor {
public:
    MockNetworkMonitor(const std::vector<std::string>& responses) : responses(responses), index(0) {}

    std::string fetchTrafficData() override {
        if (index >= responses.size()) return "";
        return responses[index++];
    }

private:
    std::vector<std::string> responses;
    size_t index;
};

class TrafficProcessor {
public:
    void processFile(const std::string& filename, NetworkMonitor* monitor) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << std::endl;
            return;
        }

        std::vector<double> byteCounts;
        double sum = 0.0;
        size_t count = 0;

        while (std::getline(file, line)) {
            try {
                parseLine(line, byteCounts);
                if (byteCounts.size() >= 2) {
                    sum += byteCounts.back();
                    ++count;
                    if (count > 1) {
                        double average = sum / count;
                        std::cout << "Average Byte Count: " << average << std::endl;
                    }
                }
            } catch (const std::exception& e) {
                std::cerr << "Parsing error: " << e.what() << std::endl;
            }
        }

        file.close();
    }

private:
    void parseLine(const std::string& line, std::vector<double>& byteCounts) {
        std::istringstream iss(line);
        std::string field;
        while (std::getline(iss, field, ',')) {
            try {
                double value = std::stod(field);
                if (value >= 0) {
                    byteCounts.push_back(value);
                }
            } catch (const std::exception&) {}
        }
    }

private:
    std::string line;
};

int main() {
    MockNetworkMonitor monitor({"1024", "2048", "3072", "4096"});
    TrafficProcessor processor;
    processor.processFile("network_traffic.txt", &monitor);

    return 0;
}
