#define MAX_FILENAME_LENGTH 256

void log_error(const char *error_message) {
    time_t current_time = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file for writing.\n");
        return;
    }

    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, error_message);
    fclose(log_file);
}

char* get_new_filename(const char *original_filename) {
    if (strlen(original_filename) > MAX_FILENAME_LENGTH - 10) {
        log_error("Original filename too long to rename.");
        return NULL;
    }

    int vowel_count = 0, consonant_count = 0;
    for (int i = 0; original_filename[i] != '\0'; i++) {
        char ch = tolower(original_filename[i]);
        if (ch >= 'a' && ch <= 'z') {
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                vowel_count++;
            } else {
                consonant_count++;
            }
        }
    }

    int sequence_length = 2 * vowel_count + consonant_count;
    if (sequence_length > 10) {
        log_error("Invalid sequence length for new filename.");
        return NULL;
    }

    char *new_filename = malloc(MAX_FILENAME_LENGTH);
    if (new_filename == NULL) {
        log_error("Memory allocation failed for new filename.");
        return NULL;
    }

    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s_%d.%.*s",
             original_filename, sequence_length,
             (int)(MAX_FILENAME_LENGTH - strlen(original_filename) - 5),
             original_filename + strlen(original_filename) - strcspn(original_filename, ".")
            );

    return new_filename;
}

int main() {
    const char *original_filename = "example.txt";
    char *new_filename = get_new_filename(original_filename);
    if (new_filename != NULL) {
        printf("New filename: %s\n", new_filename);
        free(new_filename);
    }
    return 0;
}
