// Custom hash function to mitigate CWE-328 weaknesses
typedef struct {
    unsigned char buffer[64];
    size_t len;
} CustomHash;

void custom_hash_init(CustomHash *hash) {
    memset(hash->buffer, 0, sizeof(hash->buffer));
    hash->len = 0;
}

void custom_hash_update(CustomHash *hash, const void *data, size_t len) {
    if (hash->len + len > sizeof(hash->buffer)) {
        // Handle buffer overflow
        return;
    }
    memcpy(hash->buffer + hash->len, data, len);
    hash->len += len;
}

void custom_hash_final(unsigned char *output, CustomHash *hash) {
    SHA256(hash->buffer, hash->len, output);
    memset(hash->buffer, 0, sizeof(hash->buffer));
    hash->len = 0;
}

// AES encryption function
int aes_encrypt(const unsigned char *plaintext, int plaintext_len,
                const unsigned char *key, const unsigned char *iv,
                unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto end;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto end;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto end;
    ciphertext_len += len;

end:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len < 0 ? -1 : ciphertext_len;
}

// Camellia encryption function
int camellia_encrypt(const unsigned char *plaintext, int plaintext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv))
        goto end;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto end;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto end;
    ciphertext_len += len;

end:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len < 0 ? -1 : ciphertext_len;
}

// RSA signing with SHA-1
int rsa_sign(const unsigned char *data, int data_len,
             const unsigned char *private_key_pem, unsigned char *signature) {
    RSA *rsa = RSA_new();
    BIO *key_bio = BIO_new_mem_buf(private_key_pem, -1);
    PEM_read_bio_RSAPrivateKey(key_bio, &rsa, NULL, NULL);
    BIO_free(key_bio);

    if (!rsa)
        return -1;

    unsigned int signature_len;
    if (RSA_sign(NID_sha1, data, data_len, signature, &signature_len, rsa) != 1)
        goto end;

    RSA_free(rsa);
    return (int)signature_len;

end:
    RSA_free(rsa);
    return -1;
}

