    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int find_max_integer(int* array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

int process_nfaapi_crc_and_find_max(int N, int M) {
    if (N < MIN_N || N > MAX_N) {
        return -1; // Error: N is out of valid range
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indication_pdu_list) {
        return -2; // Error: Memory allocation failed
    }

    int total_memory_used = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int array_size = M * 1024; // Convert kilobytes to bytes

    int* integer_array = malloc(array_size * sizeof(int));
    if (!integer_array) {
        free(crc_indication_pdu_list);
        return -3; // Error: Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG = 12345;
        crc_indication_pdu_list[i].RNTI = rand() % 1000 + 1;
        crc_indication_pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    for (int i = 0; i < array_size / sizeof(int); i++) {
        scanf("%d", &integer_array[i]);
        total_memory_used += sizeof(int);
        if (total_memory_used > SYSTEM_MEMORY_LIMIT) {
            free(crc_indication_pdu_list);
            free(integer_array);
            return -4; // Error: Exceeded system memory limit
        }
    }

    int max_integer = find_max_integer(integer_array, array_size / sizeof(int));

    free(crc_indication_pdu_list);
    free(integer_array);

    printf("Max integer found: %d\n", max_integer);
    return 0;
}
