typedef struct {
    int value;
} record;

record* dynamic_array = NULL;
size_t array_size = 0;
size_t max_size = 1024;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
srand_r_data_t prng_state;

void initialize_prng() {
    srand_r(time(NULL), &prng_state);
}

int generate_unique_random(int min, int max) {
    pthread_mutex_lock(&mutex);
    int value;
    do {
        value = min + rand_r_r(&prng_state, max - min + 1);
    } while (value < min || value > max);
    pthread_mutex_unlock(&mutex);
    return value;
}

record* expand_array() {
    size_t new_size = array_size * 2;
    record* new_array = realloc(dynamic_array, new_size * sizeof(record));
    if (!new_array) {
        free(dynamic_array);
        dynamic_array = NULL;
        array_size = 0;
        return NULL;
    }
    dynamic_array = new_array;
    max_size = new_size;
    return dynamic_array;
}

record* create_record(int min, int max) {
    if (array_size >= max_size) {
        if (!expand_array()) {
            return NULL;
        }
    }

    record* new_record = &dynamic_array[array_size++];
    new_record->value = generate_unique_random(min, max);
    return new_record;
}

void log_record(record* record) {
    // Implement thread-safe logging mechanism here
    printf("Generated value: %d\n", record->value);
}

void cleanup() {
    free(dynamic_array);
    dynamic_array = NULL;
    array_size = 0;
    max_size = 0;
}
