#include <stdlib.h>
#include <stdint.h>

typedef struct Packet {
    uint32_t checksum;
    size_t payload_size;
    char* payload;
} Packet;

typedef struct MemoryPool {
    void* start;
    size_t total_size;
    size_t used_memory;
    size_t block_size;
} MemoryPool;

MemoryPool* create_memory_pool(size_t pool_size, size_t block_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->start = malloc(pool_size);
    if (!pool->start) {
        free(pool);
        return NULL;
    }

    pool->total_size = pool_size;
    pool->used_memory = 0;
    pool->block_size = block_size;

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->start);
    free(pool);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->used_memory + size > pool->total_size) return NULL;

    void* block = (char*)pool->start + pool->used_memory;
    pool->used_memory += size;
    return block;
}

Packet* create_packet(size_t payload_size, MemoryPool* pool) {
    Packet* packet = (Packet*)allocate_from_pool(pool, sizeof(Packet));
    if (!packet) return NULL;

    packet->payload_size = payload_size;
    packet->payload = (char*)allocate_from_pool(pool, payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    // Initialize checksum and payload
    packet->checksum = 0; // Placeholder for actual checksum calculation

    return packet;
}

void destroy_packet(Packet* packet, MemoryPool* pool) {
    free(packet->payload);
    free(packet);
}
