#include <semaphore.h>
#include <time.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB
#define GROWTH_FACTOR 1.5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    sem_t semaphore;
} NFAPI_LIST_T;

void init_list(NFAPI_LIST_T *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->count = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_init(&list->semaphore, 0, 1);
}

void add_structure(NFAPI_LIST_T *list) {
    sem_wait(&list->semaphore);

    if (list->count == list->capacity) {
        size_t new_capacity = (size_t)(list->capacity * GROWTH_FACTOR);
        if (new_capacity > MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            printf("Memory limit reached. Cannot grow list.\n");
            sem_post(&list->semaphore);
            return;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            printf("Memory allocation failed.\n");
            sem_post(&list->semaphore);
            return;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T new_struct;
    new_struct.RX_UE_INFORMATION_TAG = rand();
    new_struct.RNTI = rand();
    new_struct.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    list->data[list->count++] = new_struct;

    sem_post(&list->semaphore);
}

void delete_list(NFAPI_LIST_T *list) {
    sem_wait(&list->semaphore);
    free(list->data);
    sem_destroy(&list->semaphore);
}
