#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    int key;
    long offset;
} Record;

Record* record_storage = NULL;
int current_size = 0;

void initialize_record_storage(int seed) {
    srand(seed);
    if (record_storage != NULL) {
        free(record_storage);
        record_storage = NULL;
    }
    record_storage = malloc(MAX_RECORDS * sizeof(Record));
    if (record_storage == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void insert_record(int key, long offset) {
    if (current_size >= MAX_RECORDS) {
        fprintf(stderr, "Storage full\n");
        return;
    }
    record_storage[current_size].key = key;
    record_storage[current_size].offset = offset;
    current_size++;
}

void update_record(int key, long new_offset) {
    for (int i = 0; i < current_size; i++) {
        if (record_storage[i].key == key) {
            record_storage[i].offset = new_offset;
            return;
        }
    }
    fprintf(stderr, "Key not found\n");
}

void delete_record(int key) {
    int found = 0;
    for (int i = 0; i < current_size; i++) {
        if (record_storage[i].key == key) {
            found = 1;
            record_storage[i] = record_storage[current_size - 1];
            current_size--;
            break;
        }
    }
    if (!found) {
        fprintf(stderr, "Key not found\n");
    }
}

void free_record_storage() {
    if (record_storage != NULL) {
        free(record_storage);
        record_storage = NULL;
        current_size = 0;
    }
}

int main() {
    int seed = time(NULL);
    initialize_record_storage(seed);

    insert_record(1, 100L);
    update_record(1, 200L);
    delete_record(1);

    free_record_storage();
    return 0;
}
