#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_METADATA_SIZE 1024
#define MEMORY_BUDGET 10 * 1024 * 1024 // 10MB

typedef struct {
    uint8_t* data;
    size_t size;
} ImageMetadata;

typedef struct MemoryBlock {
    size_t allocated_size;
    struct MemoryBlock* next;
} MemoryBlock;

MemoryBlock* free_list = NULL;
size_t total_allocated_memory = 0;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_lock);

    if (total_allocated_memory + size > MEMORY_BUDGET) {
        // Handle memory allocation failure, e.g., log error or retry
        printf("Memory allocation failed. Budget exceeded.\n");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    void* ptr = malloc(size);
    if (!ptr) {
        // Handle malloc failure, e.g., log error or retry
        printf("Failed to allocate memory.\n");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    MemoryBlock* new_block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (!new_block) {
        free(ptr);
        // Handle malloc failure, e.g., log error or retry
        printf("Failed to allocate memory block.\n");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    new_block->allocated_size = size;
    new_block->next = free_list;
    free_list = new_block;

    total_allocated_memory += size;

    pthread_mutex_unlock(&memory_lock);
    return ptr;
}

void deallocate_memory(void* ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&memory_lock);

    MemoryBlock* current = free_list;
    MemoryBlock* previous = NULL;

    while (current != NULL && current->data != ptr) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        // Handle error, e.g., log message
        printf("Attempted to deallocate invalid memory.\n");
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    free(ptr);
    total_allocated_memory -= current->allocated_size;

    if (previous != NULL) {
        previous->next = current->next;
    } else {
        free_list = current->next;
    }

    free(current);

    pthread_mutex_unlock(&memory_lock);
}

ImageMetadata* process_image(const char* filename) {
    // Simulate reading image metadata
    ImageMetadata* metadata = (ImageMetadata*)allocate_memory(sizeof(ImageMetadata));
    if (!metadata) return NULL;

    metadata->size = rand() % MAX_METADATA_SIZE + 1;
    metadata->data = (uint8_t*)allocate_memory(metadata->size);
    if (!metadata->data) {
        free(metadata);
        return NULL;
    }

    // Simulate checksum calculation
    uint32_t checksum = 0;
    for (size_t i = 0; i < metadata->size; ++i) {
        checksum += metadata->data[i];
    }
    metadata->data[metadata->size] = (checksum & 0xFF);

    return metadata;
}

void free_image_metadata(ImageMetadata* metadata) {
    if (!metadata) return;

    deallocate_memory(metadata->data);
    deallocate_memory(metadata);
}

int main() {
    srand(time(NULL));

    ImageMetadata* img1 = process_image("image1.jpg");
    ImageMetadata* img2 = process_image("image2.jpg");

    free_image_metadata(img1);
    free_image_metadata(img2);

    return 0;
}
```

