        return NULL;
    }

    PacketHeader* headers = (PacketHeader*)malloc(numPackets * sizeof(PacketHeader));
    if (!headers) {
        fprintf(stderr, "Memory allocation failed for packet headers.\n");
        return NULL;
    }

    char* payloadPool = (char*)malloc(numPackets * PAYLOAD_SIZE);
    if (!payloadPool) {
        fprintf(stderr, "Memory allocation failed for payload pool.\n");
        free(headers);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < numPackets; ++i) {
        headers[i].packetID = i + 1;
        headers[i].timestamp = time(NULL);
        headers[i].payload = payloadPool + i * PAYLOAD_SIZE;
        // Simulate random data in payload
        for (int j = 0; j < PAYLOAD_SIZE; ++j) {
            headers[i].payload[j] = 'A' + rand() % 26;
        }
    }

    return headers;
}

void freePacketHeaders(PacketHeader* headers, int numPackets) {
    if (!headers || numPackets <= 0 || numPackets > MAX_PACKETS) {
        return;
    }

    free(headers);
