#define MAX_FILE_CHUNK_SIZE 1024 * 1024 // 1MB

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned char* read_file_chunk(const char* filename, size_t* chunk_size, size_t start_offset) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    if (fseek(file, start_offset, SEEK_SET) != 0) {
        perror("Failed to seek in file");
        fclose(file);
        return NULL;
    }

    *chunk_size = fread(NULL, 1, MAX_FILE_CHUNK_SIZE, file);
    unsigned char* chunk = malloc(*chunk_size);
    if (!chunk) {
        perror("Memory allocation failed for file chunk");
        fclose(file);
        return NULL;
    }

    if (fread(chunk, 1, *chunk_size, file) != *chunk_size) {
        perror("Failed to read file chunk");
        free(chunk);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return chunk;
}

void populate_nfapi_structures(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t* count, const unsigned char* file_chunk, size_t chunk_size) {
    *count = chunk_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (chunk_size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        fprintf(stderr, "Warning: Last chunk is incomplete and will be discarded\n");
        (*count)++;
    }

    *pdus = malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        perror("Memory allocation failed for NFAPI structures");
        return;
    }

    // Populate the structures with random data
    for (size_t i = 0; i < *count; i++) {
        (*pdus)[i].rx_ue_info_tag = rand() % MAX_RX_UE_INFORMATION_TAG_VALUE;
        (*pdus)[i].rnti = rand();
        (*pdus)[i].crc_indication_rel8_tag.crcflag = (rand() & 1) ? true : false;
    }
}

unsigned char* compute_sha1_hash(const unsigned char* data, size_t length) {
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1(data, length, hash);

    // Convert the hash to a hex digest
    unsigned char* hex_digest = malloc(SHA_DIGEST_LENGTH * 2 + 1);
    if (!hex_digest) {
        perror("Memory allocation failed for SHA-1 hex digest");
        return NULL;
    }

    for (int i = 0; i < SHA_DIGEST_LENGTH; i++) {
        sprintf(hex_digest + i * 2, "%02x", hash[i]);
    }

    return hex_digest;
}

int process_file(const char* filename) {
    unsigned char* file_chunk = NULL;
    size_t chunk_size = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    size_t pdu_count = 0;

    FILE* log_file = fopen("processing.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    // Resume from last checkpoint
    size_t last_checkpoint = get_last_checkpoint();

    while ((file_chunk = read_file_chunk(filename, &chunk_size, last_checkpoint)) != NULL) {
        populate_nfapi_structures(&pdus, &pdu_count, file_chunk, chunk_size);

        if (!log_operation(pdus, pdu_count)) {
            fprintf(log_file, "Error occurred during operation at checkpoint %zu\n", last_checkpoint);
            free(file_chunk);
            free(pdus);
            fclose(log_file);
            return -1;
        }

        last_checkpoint += chunk_size;
        free(file_chunk);
        free(pdus);
    }

    unsigned char* sha1_digest = compute_sha1_hash(read_whole_file(filename), get_file_length(filename));
    fprintf(log_file, "SHA-1 Hash: %s\n", sha1_digest);
    free(sha1_digest);
    fclose(log_file);

    return 0;
}

size_t get_last_checkpoint() {
    // Implementation to retrieve last checkpoint
    return 0; // Placeholder
}

bool log_operation(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t pdu_count) {
    // Implementation to log operation
    return true; // Placeholder
}

unsigned char* read_whole_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for SHA-1 computation");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t length = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char* buffer = malloc(length);
    if (!buffer) {
        perror("Memory allocation failed for SHA-1 buffer");
        fclose(file);
        return NULL;
    }

    fread(buffer, 1, length, file);
    fclose(file);
    return buffer;
}

size_t get_file_length(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for SHA-1 computation");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t length = ftell(file);
    fclose(file);
    return length;
}
