        fclose(file);
        return -1; // Exceeds maximum limits
    }

    fclose(file);
    return 0;
}

ROIS_CONTAINER* process_images(const char *config_filename) {
    int num_images, max_rois_per_image;
    if (read_config_file(config_filename, &num_images, &max_rois_per_image)) {
        return NULL; // Error reading configuration
    }

    size_t total_size = sizeof(ROIS_CONTAINER) + num_images * max_rois_per_image * sizeof(ROI *);
    ROIS_CONTAINER *rois_container = (ROIS_CONTAINER *)malloc(total_size);
    if (!rois_container) return NULL; // Memory allocation failed

    rois_container->total_rois = 0;

    for (int i = 0; i < num_images; ++i) {
        // Simulate loading ROIs from image files
        for (int j = 0; j < max_rois_per_image; ++j, ++rois_container->total_rois) {
            rois_container->rois[rois_container->total_rois - 1] = malloc(sizeof(ROI));
            if (!rois_container->rois[rois_container->total_rois - 1]) {
                // Handle memory allocation error for individual ROI
                while (rois_container->total_rois > 0) {
                    free(rois_container->rois[--rois_container->total_rois]);
                }
                free(rois_container);
                return NULL;
            }
        }
    }

    return rois_container;
}

void free_rois_container(ROIS_CONTAINER *rois_container) {
    for (int i = 0; i < rois_container->total_rois; ++i) {
        free(rois_container->rois[i]);
    }
    free(rois_container);
}
