NFAPI_CRC_INDICATION_PDU_T* generateNFAPICRCIndicationPDUs(int N, int supervisorID, const char* department, int timeout) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    MYSQL* conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "user", "password", "database", 0, NULL, 0)) {
        fprintf(stderr, "Connection failed: %s\n", mysql_error(conn));
        free(pdus);
        return NULL;
    }

    MYSQL_RES* res = NULL;
    char query[256];
    snprintf(query, sizeof(query), "SELECT name, city, address FROM Employees WHERE supervisor_id = %d AND department = '%s'", supervisorID, department);

    if (mysql_query(conn, query)) {
        fprintf(stderr, "Query failed: %s\n", mysql_error(conn));
        mysql_close(conn);
        free(pdus);
        return NULL;
    }

    res = mysql_use_result(conn);
    if (!res) {
        fprintf(stderr, "No results returned\n");
        mysql_close(conn);
        free(pdus);
        return NULL;
    }

    MYSQL_ROW row;
    int rowsAffected = 0;

    while ((row = mysql_fetch_row(res))) {
        // Process each employee row here
        printf("Employee Name: %s, City: %s, Address: %s\n", row[0], row[1], row[2]);
        rowsAffected++;
    }

    mysql_free_result(res);
    mysql_close(conn);

    if (rowsAffected == 0) {
        fprintf(stderr, "No employees found for the given supervisor ID and department\n");
        free(pdus);
        return NULL;
    }

    return pdus;
}
