#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct ROI {
    int x;
    int y;
    int width;
    int height;
} ROI;

typedef struct ROIS_CONTAINER {
    int num_images;
    ROI** rois;
} ROIS_CONTAINER;

int load_config(const char* filename, int* num_images, int* max_rois_per_image) {
    // Simulate loading config and validating integrity
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    fscanf(file, "%d %d", num_images, max_rois_per_image);
    fclose(file);

    // Validate config against limits
    if (*num_images <= 0 || *max_rois_per_image <= 0) {
        return -2;
    }

    return 0;
}

int allocate_memory(ROIS_CONTAINER** container, int num_images, int max_rois_per_image) {
    *container = (ROIS_CONTAINER*)malloc(sizeof(ROIS_CONTAINER));
    if (!*container) return -1;

    (*container)->num_images = num_images;
    (*container)->rois = (ROI**)calloc(num_images, sizeof(ROI*));
    if (!(*container)->rois) {
        free(*container);
        return -2;
    }

    for (int i = 0; i < num_images; ++i) {
        (*container)->rois[i] = (ROI*)calloc(max_rois_per_image, sizeof(ROI));
        if (!(*container)->rois[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) free((*container)->rois[j]);
            free((*container)->rois);
            free(*container);
            return -3;
        }
    }

    return 0;
}

void process_image_data(ROIS_CONTAINER* container, int image_index, int num_rois, ROI* rois) {
    for (int i = 0; i < num_rois; ++i) {
        container->rois[image_index][i] = rois[i];
    }
}

void free_container(ROIS_CONTAINER* container) {
    if (!container) return;

    for (int i = 0; i < container->num_images; ++i) {
        free(container->rois[i]);
    }

    free(container->rois);
    free(container);
}

int process_image_files(const char* config_filename, const char* image_filenames[]) {
    int num_images, max_rois_per_image;
    if (load_config(config_filename, &num_images, &max_rois_per_image) != 0) return -1;

    ROIS_CONTAINER* container = NULL;
    if (allocate_memory(&container, num_images, max_rois_per_image) != 0) {
        return -2;
    }

    for (int i = 0; i < num_images; ++i) {
        // Simulate loading image data and processing ROIs
        ROI rois[10]; // Example: fixed number of ROIs per image
        int num_rois = 5; // Example: fixed number of ROIs for demonstration

        process_image_data(container, i, num_rois, rois);
    }

    free_container(container);

    return 0;
}

int main() {
    const char* config_filename = "config.txt";
    const char* image_filenames[] = {"image1.jpg", "image2.jpg"};
    int result = process_image_files(config_filename, image_filenames);
    if (result != 0) {
        printf("Error processing image files: %d\n", result);
    }
    return 0;
}
