typedef struct PacketHeader {
    int payload_size;
} PacketHeader;

int allocate_payloads(PacketHeader *headers, int num_packets, size_t max_memory, char **payloads) {
    srand(time(NULL)); // Seed for random number generation
    size_t total_allocated = 0;

    for (int i = 0; i < num_packets; ++i) {
        if ((total_allocated + headers[i].payload_size) > max_memory) {
            return -1; // Insufficient memory
        }
        payloads[i] = (char *)malloc(headers[i].payload_size);
        if (!payloads[i]) {
            return -2; // Memory allocation failed
        }
        for (int j = 0; j < headers[i].payload_size; ++j) {
            payloads[i][j] = rand() % 256; // Fill with random data
        }
        total_allocated += headers[i].payload_size;
    }

    return 0; // Success
}

void free_payloads(char **payloads, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        if (payloads[i]) {
            free(payloads[i]);
            payloads[i] = NULL;
        }
    }
}
