#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_N 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

void log_creation(int RNTI, time_t timestamp) {
    printf("Created PDU with RNTI %d at %ld\n", RNTI, timestamp);
}

Node* create_crc_indication_list(int N) {
    if (N <= 0 || N > MAX_N) {
        fprintf(stderr, "Invalid value for N. Must be between 1 and %d.\n", MAX_N);
        return NULL;
    }

    Node* head = NULL;
    Node** current = &head;

    srand(time(NULL));
    time_t timestamp = time(NULL);

    for (int i = 0; i < N; ++i) {
        *current = (Node*)malloc(sizeof(Node));
        if (*current == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        (*current)->data.RX_UE_INFORMATION_TAG = i; // Assuming RX_UE_INFORMATION_TAG is used as an index for simplicity
        (*current)->data.RNTI = rand() % 1000; // Random RNTI value
        (*current)->data.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
        log_creation((*current)->data.RNTI, timestamp);
        (*current)->next = NULL;
        current = &(*current)->next;
    }

    return head;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
