#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* filename;
    size_t size;
    unsigned char* data;
} ImageMetadata;

typedef struct {
    ImageMetadata** metadataArray;
    size_t capacity;
    size_t count;
    size_t maxMemoryLimit;
} ImageCollection;

ImageCollection* createImageCollection(size_t initialCapacity, size_t maxMemory) {
    ImageCollection* collection = (ImageCollection*)malloc(sizeof(ImageCollection));
    if (collection == NULL) return NULL;

    collection->metadataArray = (ImageMetadata**)malloc(initialCapacity * sizeof(ImageMetadata*));
    if (collection->metadataArray == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->count = 0;
    collection->maxMemoryLimit = maxMemory;

    return collection;
}

void addImageToCollection(ImageCollection* collection, const char* filename, size_t size, unsigned char* data) {
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        ImageMetadata** newMetadataArray = (ImageMetadata**)realloc(collection->metadataArray, newCapacity * sizeof(ImageMetadata*));
        if (newMetadataArray == NULL) return;

        collection->metadataArray = newMetadataArray;
        collection->capacity = newCapacity;
    }

    if (size > collection->maxMemoryLimit - totalAllocatedMemory(collection)) return;

    ImageMetadata* metadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (metadata == NULL) return;

    metadata->filename = strdup(filename);
    metadata->size = size;
    metadata->data = data;

    collection->metadataArray[collection->count++] = metadata;
}

size_t totalAllocatedMemory(const ImageCollection* collection) {
    size_t memoryUsage = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        memoryUsage += sizeof(ImageMetadata) + strlen(collection->metadataArray[i]->filename) + collection->metadataArray[i]->size;
    }
    return memoryUsage;
}

void freeImageCollection(ImageCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->metadataArray[i]->data);
        free(collection->metadataArray[i]->filename);
        free(collection->metadataArray[i]);
    }
    free(collection->metadataArray);
    free(collection);
}
