#include <stdlib.h>
#include <stdint.h>
#include <errno.h>

#define MAX_MEMORY_LIMIT 1048576 // 1MB in bytes

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaipdu_array(size_t N) {
    if (N == 0) {
        return NULL; // Handle zero size input gracefully
    }

    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Check for integer overflow and memory limit
    if ((N > MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) ||
        (total_size > MAX_MEMORY_LIMIT)) {
        errno = ENOMEM; // Set error to indicate out of memory
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (array == NULL) {
        return NULL; // Return NULL if malloc fails
    }

    // Initialize the array with random data
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536; // Random RNTI within valid range
        array[i].CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2); // Randomly set CRCFLAG to either 0 or 1
    }

    return array;
}
