        LogEntry *new_entries = realloc(collection->entries, new_capacity * sizeof(LogEntry));
        if (new_entries == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }

    collection->entries[collection->size].timestamp = timestamp;
    collection->entries[collection->size].message = strdup(message);
    collection->entries[collection->size].severity_level = severity_level;
    collection->size++;
}

void freeLogCollection(LogCollection *collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->entries[i].message);
