// Function to initialize the linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    sem_init(&list->mutex, 0, 1);
    sem_init(&list->semaphore, 0, 1);
}

// Function to safely add a new node to the linked list
void safeAddNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    sem_wait(&list->mutex);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    sem_post(&list->mutex);
}

// Function to safely remove a node from the linked list
void safeRemoveNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data.RNTI &&
            current->data.CRCFLAG == data.CRCFLAG) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to destroy the linked list
void destroyLinkedList(LinkedList* list) {
    Node* temp;
    while (list->head != NULL) {
        temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    sem_destroy(&list->mutex);
    sem_destroy(&list->semaphore);
}

