#define MAX_IP_LEN 16
#define MAX_RETRIES 3

int resolve_hostname_to_ip(const char *hostname, u_char **ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allows IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            return -1;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            if (p->ai_family == AF_INET) { // Check for IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                inet_ntop(p->ai_family, &(ipv4->sin_addr), *ip_address, MAX_IP_LEN);
                freeaddrinfo(res); // Free the linked list
                return 0; // Success
            }
        }

        freeaddrinfo(res); // Free the linked list on failure
    }

    fprintf(stderr, "Failed to resolve hostname after %d attempts\n", MAX_RETRIES);
    return -1;
}

int main() {
    u_char ip_address[MAX_IP_LEN];
    const char *hostname = "example.com";

    if (resolve_hostname_to_ip(hostname, &ip_address) == 0) {
        printf("IP address: %s\n", ip_address);
    } else {
        printf("Failed to resolve hostname\n");
    }

    return 0;
}
