// Define constants and types
#define MAX_PACKET_BATCH 100
#define MEM_POOL_SIZE (MAX_PACKET_BATCH * 1024) // Pre-allocated memory pool size

typedef struct {
    unsigned char* header;
    unsigned char* payload;
} Packet;

typedef struct {
    Packet packets[MAX_PACKET_BATCH];
    int count;
    pthread_mutex_t lock;
} PacketQueue;

// Function prototypes
void* packetProcessingThread(void* arg);
void* jpegToPdfConversionThread(void* arg);
int allocatePacketMemory(Packet* packet, size_t headerSize, size_t payloadSize);
void freePacketMemory(Packet* packet);

int main() {
    // Initialize packet queue and memory pool
    PacketQueue packetQueue;
    pthread_mutex_init(&packetQueue.lock, NULL);

    // Create threads for packet processing and file conversion
    pthread_t packetThread, pdfConversionThread;

    pthread_create(&packetThread, NULL, packetProcessingThread, &packetQueue);
    pthread_create(&pdfConversionThread, NULL, jpegToPdfConversionThread, &packetQueue);

    // Wait for threads to finish
    pthread_join(packetThread, NULL);
    pthread_join(pdfConversionThread, NULL);

    return 0;
}

void* packetProcessingThread(void* arg) {
    PacketQueue* queue = (PacketQueue*)arg;

    while (1) {
        Packet packet;
        int headerSize = rand() % 128 + 1; // Random header size between 1 and 128
        int payloadSize = rand() % 4096 + 1; // Random payload size between 1 and 4096

        if (allocatePacketMemory(&packet, headerSize, payloadSize) == 0) {
            pthread_mutex_lock(&queue->lock);
            queue->packets[queue->count++] = packet;
            pthread_mutex_unlock(&queue->lock);

            // Simulate processing time
            sleep(1);
        } else {
            // Handle memory allocation failure
            printf("Memory allocation failed for packet\n");
        }
    }

    return NULL;
}

void* jpegToPdfConversionThread(void* arg) {
    PacketQueue* queue = (PacketQueue*)arg;

    while (1) {
        pthread_mutex_lock(&queue->lock);
        if (queue->count > 0) {
            Packet packet = queue->packets[--queue->count];
            pthread_mutex_unlock(&queue->lock);

            // Simulate JPEG to PDF conversion
            printf("Converting packet to PDF\n");

            freePacketMemory(&packet);
        } else {
            pthread_mutex_unlock(&queue->lock);
            sleep(1);
        }
    }

    return NULL;
}

int allocatePacketMemory(Packet* packet, size_t headerSize, size_t payloadSize) {
    // Implement memory allocation with integer overflow check
    if (headerSize > SIZE_MAX / sizeof(unsigned char) ||
        payloadSize > SIZE_MAX / sizeof(unsigned char)) {
        return -1; // Integer overflow detected
    }

    packet->header = malloc(headerSize * sizeof(unsigned char));
    packet->payload = malloc(payloadSize * sizeof(unsigned char));

    if (packet->header == NULL || packet->payload == NULL) {
        free(packet->header);
        free(packet->payload);
        return -1; // Memory allocation failed
    }

    return 0; // Success
}

void freePacketMemory(Packet* packet) {
    free(packet->header);
    free(packet->payload);
}
