#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

// Assume there's an existing image processing library with functions like:
void* loadImage(const char* path);
void resizeImage(void* image, int width, int height);
void saveImage(void* image, const char* outputPath);
void freeImage(void* image);

#define MAX_CONCURRENT_TASKS 10
#define INITIAL_MEMORY_LIMIT 1024 * 1024 * 10 // 10MB

typedef struct {
    const char* inputPath;
    int width;
    int height;
    const char* outputPath;
} ImageTask;

pthread_mutex_t memoryLock = PTHREAD_MUTEX_INITIALIZER;
int totalMemoryUsage = 0;
int memoryLimit = INITIAL_MEMORY_LIMIT;

void* processImage(void* arg) {
    ImageTask task = *(ImageTask*)arg;
    void* image = loadImage(task.inputPath);

    if (image == NULL) {
        fprintf(stderr, "Failed to load image: %s\n", task.inputPath);
        return NULL;
    }

    // Calculate new memory usage
    int newMemoryUsage = totalMemoryUsage + /* estimate of memory used by image */;

    pthread_mutex_lock(&memoryLock);
    if (newMemoryUsage > memoryLimit) {
        // Handle memory limit exceeded, possibly retry or fail
        fprintf(stderr, "Memory limit exceeded for task: %s\n", task.inputPath);
        free(image);
        return NULL;
    }
    totalMemoryUsage = newMemoryUsage;
    pthread_mutex_unlock(&memoryLock);

    resizeImage(image, task.width, task.height);
    saveImage(image, task.outputPath);
    freeImage(image);

    return NULL;
}

void processImageBatch(ImageTask tasks[], int count) {
    pthread_t threads[MAX_CONCURRENT_TASKS];

    for (int i = 0; i < count && i < MAX_CONCURRENT_TASKS; ++i) {
        if (pthread_create(&threads[i], NULL, processImage, &tasks[i]) != 0) {
            fprintf(stderr, "Failed to create thread for task: %s\n", tasks[i].inputPath);
        }
    }

    for (int i = 0; i < count && i < MAX_CONCURRENT_TASKS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage:
void* resizeImages(const char* inputPaths[], int widths[], int heights[], const char* outputPaths[], int count) {
    ImageTask tasks[count];

    for (int i = 0; i < count; ++i) {
        tasks[i].inputPath = inputPaths[i];
        tasks[i].width = widths[i];
        tasks[i].height = heights[i];
        tasks[i].outputPath = outputPaths[i];
    }

    processImageBatch(tasks, count);

    return NULL;
}
```

