    int size;
    char priority; // 'H' for high, 'L' for low
} PacketHeader;

void generateRandomData(char* data, int length) {
    for (int i = 0; i < length; i++) {
        data[i] = rand() % 256;
    }
}

int allocateMemoryForPackets(PacketHeader* headers, int count, char** payloads, int memoryLimit, int prioritizeHighPriority) {
    int allocatedSize = 0;
    for (int i = 0; i < count; i++) {
        if (prioritizeHighPriority && headers[i].priority == 'H') {
            if ((long long)allocatedSize + headers[i].size > (long long)memoryLimit) {
                break;
            }
            payloads[i] = (char*)malloc(headers[i].size);
            generateRandomData(payloads[i], headers[i].size);
            allocatedSize += headers[i].size;
        } else if (!prioritizeHighPriority && (long long)allocatedSize + headers[i].size <= (long long)memoryLimit) {
            payloads[i] = (char*)malloc(headers[i].size);
            generateRandomData(payloads[i], headers[i].size);
            allocatedSize += headers[i].size;
        }
    }
    return allocatedSize;
}

int main() {
    srand(time(NULL));
    PacketHeader headers[MAX_PACKETS];
    char* payloads[MAX_PACKETS];

