        headers[i].size = rand() % MAX_PAYLOAD_SIZE;
        headers[i].priority = rand() % 2 == 0 ? 'H' : 'L';
    }

    int totalAllocatedSize = allocateMemoryForPackets(headers, MAX_PACKETS, payloads, MEMORY_LIMIT, 1);

    printf("Total allocated size: %d bytes\n", totalAllocatedSize);

    // Free allocated memory
    for (int i = 0; i < MAX_PACKETS; i++) {
