#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    int width;
    int height;
    size_t file_size;
    char filename[MAX_FILENAME_LENGTH];
} ImageMetadata;

typedef struct Node {
    ImageMetadata metadata;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
} ImageList;

void initializeNode(Node** node, const ImageMetadata* metadata) {
    *node = (Node*)malloc(sizeof(Node));
    if (*node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(&(*node)->metadata, metadata, sizeof(ImageMetadata));
    (*node)->next = NULL;
}

void addImageToList(ImageList* list, const ImageMetadata* metadata) {
    Node* newNode;
    initializeNode(&newNode, metadata);

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
}

void iterateImageList(ImageList* list, void (*operation)(const ImageMetadata*)) {
    Node* current = list->head;
    while (current != NULL) {
        operation(&current->metadata);
        current = current->next;
    }
}

void freeImageList(ImageList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
}

int main() {
    ImageList imageList;
    imageList.head = NULL;
    imageList.tail = NULL;

    // Example usage
    ImageMetadata metadata1 = {800, 600, 2048, "image1.jpg"};
    ImageMetadata metadata2 = {1920, 1080, 3584, "image2.jpg"};

    addImageToList(&imageList, &metadata1);
    addImageToList(&imageList, &metadata2);

    iterateImageList(&imageList, [](const ImageMetadata* metadata) {
        printf("Width: %d, Height: %d, File Size: %zu, Filename: %s\n",
               metadata->width, metadata->height, metadata->file_size, metadata->filename);
    });

    freeImageList(&imageList);

    return 0;
}
```

This code snippet provides a basic implementation of managing a dynamic array of image processing structures using a linked list. It includes functions for adding images to the list, iterating over the list, and freeing the allocated memory when no longer needed. The example usage demonstrates how to add metadata for two images and print their details.']

