typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) {
        fprintf(stderr, "Memory allocation failed for DynamicArray.\n");
        return NULL;
    }
    da->array = realloc(da->array, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        fprintf(stderr, "Memory reallocation failed for DynamicArray array.\n");
        free(da);
        return NULL;
    }
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void dynamic_array_add(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T new_item) {
    if (da->size >= da->capacity) {
        da->capacity *= 2;
        da->array = realloc(da->array, da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!da->array) {
            fprintf(stderr, "Memory reallocation failed for DynamicArray array.\n");
            return;
        }
    }
    pthread_mutex_lock(&da->mutex);
    memcpy(&da->array[da->size], &new_item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size++;
    pthread_mutex_unlock(&da->mutex);
}

void dynamic_array_free(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

