NFAPI_CRC_INDICATION_PDU_T* create_packet(int packet_id, int payload_size) {
    NFAPI_CRC_INDICATION_PDU_T* packet = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (packet == NULL) {
        printf("Memory allocation failed for packet.\n");
        return NULL;
    }
    memset(packet, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    packet->crcflag = rand() % 2; // Randomly set CRCFLAG
    // Initialize other fields as per NFAPI_CRC_INDICATION_PDU_T structure

    void* payload = malloc(payload_size);
    if (payload == NULL) {
        printf("Memory allocation failed for payload.\n");
        free(packet);
        return NULL;
    }
    memset(payload, 0, payload_size);

    PacketHeader* header = (PacketHeader*)malloc(sizeof(PacketHeader));
    if (header == NULL) {
        printf("Memory allocation failed for header.\n");
        free(packet->payload);
        free(packet);
        return NULL;
    }
    header->packet_id = packet_id;
    header->timestamp = time(NULL);
    header->payload = payload;

    // Log memory usage and packet processing rate

    return packet;
}

void process_packets(int max_packets, int batch_size) {
    srand(time(NULL));
    for (int i = 0; i < max_packets; i += batch_size) {
        for (int j = 0; j < batch_size && i + j < max_packets; j++) {
            int payload_size = rand() % 1024 + 64; // Random payload size between 64 and 1087 bytes
            NFAPI_CRC_INDICATION_PDU_T* packet = create_packet(i + j, payload_size);
            if (packet != NULL) {
                // Process packet
                free(packet->payload);
                free(packet);
            }
        }
    }
}

