        fprintf(stderr, "Invalid input for freeing structures\n");
        return;
    }

    size_t required_size = (size_t)num_structs * STRUCT_SIZE;

    pthread_mutex_lock(&memory_lock);
    free(ptr);
    total_memory_used -= required_size;
