        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    // Create directory if it doesn't exist
    DIR* dir = opendir(directory_name);
    if (!dir) {
        if (mkdir(directory_name, 0755) != 0) {
            perror("Failed to create directory");
            free(array);
            return NULL;
        }
    } else {
        closedir(dir);
    }

    // Update environment variable representing the directory path
    char* env_var = getenv("CRC_DIR_PATH");
    if (!env_var || strlen(env_var) == 0) {
        setenv("CRC_DIR_PATH", directory_name, 1);
    }

    return array;
}
