    char* pixel_format;
} ImageMetaData;

void extract_metadata(const char* directory_path, ImageMetaData** meta_data) {
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    struct dirent* entry;
    int count = 0;

    // First pass: Count the number of files
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            count++;
        }
    }

    rewinddir(dir);

    // Allocate memory for metadata array
    *meta_data = (ImageMetaData*)malloc(count * sizeof(ImageMetaData));
    if (*meta_data == NULL) {
        perror("Error allocating memory");
        closedir(dir);
        return;
    }

    int index = 0;

    // Second pass: Extract metadata
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            (*meta_data)[index].filename = strdup(entry->d_name);
            // Assuming a function extract_image_info exists for extracting image info
            extract_image_info((*meta_data)[index].filename, &(*meta_data)[index]);
            index++;
        }
    }

    closedir(dir);
}

void free_metadata(ImageMetaData* meta_data, int count) {
    for (int i = 0; i < count; i++) {
        free(meta_data[i].filename);
        free(meta_data[i].pixel_format);
    }
    free(meta_data);
}
```

