#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024

typedef struct PacketHeader {
    int packet_id;
    int source_id;
} PacketHeader;

typedef struct DataBuffer {
    char buffer[MAX_PACKET_SIZE];
} DataBuffer;

typedef struct NetworkPacket {
    PacketHeader header;
    DataBuffer data;
    struct NetworkPacket* next;
} NetworkPacket;

NetworkPacket* process_packets(const unsigned char** packets, size_t packet_count) {
    NetworkPacket* head = NULL;
    NetworkPacket* tail = NULL;

    for (size_t i = 0; i < packet_count; ++i) {
        const unsigned char* packet = packets[i];

        // Validate packet header
        if (packet[0] != 'P' || packet[1] != 'K') continue;
        int packet_id = packet[2];
        int source_id = packet[3];

        // Calculate data size safely
        size_t data_size = 0;
        for (size_t j = 4; j < MAX_PACKET_SIZE && packet[j] != '\0'; ++j) {
            if (packet[j] == 'D') break;
            data_size++;
        }
        if (data_size > MAX_PACKET_SIZE - 4) continue;

        // Allocate memory for new packet
        NetworkPacket* new_packet = malloc(sizeof(NetworkPacket));
        if (!new_packet) continue;

        // Initialize packet fields
        new_packet->header.packet_id = packet_id;
        new_packet->header.source_id = source_id;
        memcpy(new_packet->data.buffer, &packet[4], data_size);
        new_packet->data.buffer[data_size] = '\0';
        new_packet->next = NULL;

        // Add new packet to linked list
        if (tail) {
            tail->next = new_packet;
        } else {
            head = new_packet;
        }
        tail = new_packet;
    }

    return head;
}

void log_packet_error(const char* error_message) {
    printf("Error: %s\n", error_message);
}
