int getMaxConcurrentThreads() {
    struct sysinfo info;
    if (sysinfo(&info) != 0) {
        return 1; // Default to a single thread if sysinfo fails
    }
    return info.procs / 2; // Example: half the number of processes as threads
}

void* workerThread(void* arg) {
    FileTaskQueue* taskQueue = (FileTaskQueue*)arg;
    while (1) {
        FileTask* fileTask = dequeueTask(taskQueue);
        if (fileTask == NULL) {
            break; // Exit thread if no more tasks are available
        }
        processFile(fileTask);
        free(fileTask); // Free the task after processing
    }
    return NULL;
}

void startThreadPool(FileTaskQueue* taskQueue, int maxThreads) {
    pthread_t* threads = (pthread_t*)malloc(maxThreads * sizeof(pthread_t));
    if (threads == NULL) {
        perror("Failed to allocate memory for thread pool");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < maxThreads; i++) {
        if (pthread_create(&threads[i], NULL, workerThread, taskQueue) != 0) {
            perror("Failed to create thread in thread pool");
            exit(EXIT_FAILURE);
        }
    }
    for (int i = 0; i < maxThreads; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

void processImageFiles(const char** filePaths, int numFiles) {
    FileTaskQueue taskQueue;
    initFileTaskQueue(&taskQueue);

    for (int i = 0; i < numFiles; i++) {
        size_t memoryRequired = calculateMemoryRequirement(filePaths[i], getFileFormat(filePaths[i]));
        if (memoryRequired == SIZE_MAX) {
            logError(filePaths[i], "Integer overflow", 0);
            continue;
        }
        FileTask* fileTask = malloc(sizeof(FileTask));
        if (fileTask == NULL) {
            logError(filePaths[i], "Memory allocation failed", memoryRequired);
            continue;
        }
        fileTask->filePath = strdup(filePaths[i]);
        fileTask->memoryRequired = memoryRequired;
        enqueueTask(&taskQueue, fileTask);
    }

    int maxThreads = getMaxConcurrentThreads();
    startThreadPool(&taskQueue, maxThreads);

    freeFileTaskQueue(&taskQueue);
}

int main() {
    const char* filePaths[] = {"image1.bin", "image2.bin", "image3.bin"};
    processImageFiles(filePaths, 3);
    return 0;
}
