    size_t size;
} FileMetadata;

typedef struct {
    Packet packets[MAX_PACKETS];
    FileMetadata files[MAX_FILES];
    size_t packet_count;
    size_t file_count;
    pthread_mutex_t lock;
} NetworkProcessor;

NetworkProcessor* create_network_processor() {
    NetworkProcessor* processor = (NetworkProcessor*)malloc(sizeof(NetworkProcessor));
    if (processor) {
        memset(processor, 0, sizeof(NetworkProcessor));
        pthread_mutex_init(&processor->lock, NULL);
    }
    return processor;
}

void destroy_network_processor(NetworkProcessor* processor) {
    if (processor) {
        for (size_t i = 0; i < processor->packet_count; ++i) {
            free(processor->packets[i].payload);
        }
        pthread_mutex_destroy(&processor->lock);
        free(processor);
    }
}

int add_packet(NetworkProcessor* processor, Packet packet) {
    if (pthread_mutex_lock(&processor->lock) != 0) {
        return -1;
    }

    if (processor->packet_count >= MAX_PACKETS) {
        pthread_mutex_unlock(&processor->lock);
        return -1;
    }
    processor->packets[processor->packet_count++] = packet;

    pthread_mutex_unlock(&processor->lock);
    return 0;
}

int add_file(NetworkProcessor* processor, FileMetadata file) {
    if (pthread_mutex_lock(&processor->lock) != 0) {
        return -1;
    }

    if (processor->file_count >= MAX_FILES) {
        pthread_mutex_unlock(&processor->lock);
        return -1;
    }
    processor->files[processor->file_count++] = file;

    pthread_mutex_unlock(&processor->lock);
    return 0;
}

