using System;
using System.IO;
using System.Collections.Generic;

public class NfaApiCrcIndicationPdu : ISerializable {
    public int RxUeInformationTag { get; set; }
    public uint Rnti { get; set; }
    public int CrcIndicationRel8Tag { get; set; }

    // Implementing ISerializable interface methods
    public void GetObjectData(SerializationInfo info, StreamingContext context) {
        info.AddValue("RxUeInformationTag", RxUeInformationTag);
        info.AddValue("Rnti", Rnti);
        info.AddValue("CrcIndicationRel8Tag", CrcIndicationRel8Tag);
    }

    protected NfaApiCrcIndicationPdu(SerializationInfo info, StreamingContext context) {
        RxUeInformationTag = info.GetInt32("RxUeInformationTag");
        Rnti = (uint)info.GetUInt32("Rnti");
        CrcIndicationRel8Tag = info.GetInt32("CrcIndicationRel8Tag");
    }
}

public class NfaApiDeserialization {
    public static List<NfaApiCrcIndicationPdu> DeserializeDataFromBinaryFile(string filePath) {
        List<NfaApiCrcIndicationPdu> data = new List<NfaApiCrcIndicationPdu>();

        try (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read)) {
            BinaryFormatter formatter = new BinaryFormatter();
            while (fileStream.Position < fileStream.Length) {
                object obj = formatter.Deserialize(fileStream);
                if (obj is NfaApiCrcIndicationPdu pdu) {
                    data.Add(pdu);
                }
            }
        } catch (Exception ex) {
            Console.WriteLine("Error during deserialization: " + ex.Message);
        }

        return data;
    }
}
