#include <string.h>

#define MAX_PACKETS 10000
#define MAX_IP_LENGTH 16 // Assuming IPv4 for simplicity

typedef struct {
    char ip[MAX_IP_LENGTH];
    size_t payload_size;
} PacketMetadata;

PacketMetadata* process_packets(const char** packet_data, size_t num_packets) {
    if (num_packets > MAX_PACKETS) {
        fprintf(stderr, "Error: Exceeds maximum number of packets.\n");
        return NULL;
    }

    // Calculate total memory required
    size_t header_overhead = sizeof(PacketMetadata);
    size_t total_memory_required = 0;

    for (size_t i = 0; i < num_packets; ++i) {
        PacketMetadata packet;
        strcpy(packet.ip, packet_data[i]);
        packet.payload_size = strlen(packet_data[i]) + 1; // Including null terminator

        total_memory_required += header_overhead + packet.payload_size;
    }

    if (total_memory_required > 500 * 1024 * 1024) {
        fprintf(stderr, "Error: Exceeds maximum memory limit.\n");
        return NULL;
    }

    // Allocate memory
    PacketMetadata* metadata = (PacketMetadata*)malloc(total_memory_required);
    if (!metadata) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Populate metadata
    char* current_pos = (char*)metadata;
    for (size_t i = 0; i < num_packets; ++i) {
        strcpy(current_pos, packet_data[i]);
        size_t payload_size = strlen(packet_data[i]) + 1;
        PacketMetadata* packet = (PacketMetadata*)current_pos;
        packet->payload_size = payload_size;
        strcpy(packet->ip, packet_data[i]);

        current_pos += header_overhead + payload_size;
    }

    return metadata;
}

// Example usage
int main() {
    const char* packets[MAX_PACKETS] = {"192.168.1.1", "10.0.0.1", "8.8.8.8"};
    size_t num_packets = 3;

    PacketMetadata* metadata = process_packets(packets, num_packets);
    if (metadata) {
        // Process the packets
        free(metadata); // Don't forget to free allocated memory
    }

    return 0;
}
