typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t count;
    time_t last_offload_time;
    int max_size;
    pthread_mutex_t lock;
} CRC_LIST;

void init_crc_list(CRC_LIST *list, int max_size) {
    list->head = list->tail = NULL;
    list->count = 0;
    list->last_offload_time = time(NULL);
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
}

void add_crc_indication(CRC_LIST *list) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        offload_old_entries(list);
    }
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    new_node->RNTI = rand() % 4096; // Example RNTI range
    new_node->CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    new_node->next = NULL;
    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
    } else {
        list->head = new_node;
        new_node->prev = NULL;
    }
    list->tail = new_node;
    list->count++;
    log_creation(new_node);
    pthread_mutex_unlock(&list->lock);
}

void offload_old_entries(CRC_LIST *list) {
    // Implement logic to offload and archive old entries
    pthread_mutex_lock(&list->lock);
    time_t current_time = time(NULL);
