#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t used_entries;
    size_t allocated_entries;
    pthread_mutex_t lock;
} CRC_LIST;

int init_crc_list(CRC_LIST *list, size_t initial_size) {
    list->entries = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        perror("Failed to allocate memory for CRC list");
        return -1;
    }
    list->used_entries = 0;
    list->allocated_entries = initial_size;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

int add_crc_entry(CRC_LIST *list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    if (pthread_mutex_lock(&list->lock) != 0) {
        perror("Failed to lock mutex");
        return -1;
    }

    if (list->used_entries >= list->allocated_entries) {
        size_t new_size = list->allocated_entries * 2;
        if (new_size > MAX_ENTRIES) {
            new_size = MAX_ENTRIES;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            perror("Failed to reallocate memory for CRC list");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->entries = new_entries;
        list->allocated_entries = new_size;
    }

    list->entries[list->used_entries].ue_info = ue_info;
    list->entries[list->used_entries].rnti = rnti;
    // Randomly set CRCFLAG
    list->entries[list->used_entries].crc_indication.crcflag = rand() % 2;

    list->used_entries++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_crc_list(CRC_LIST *list) {
    if (list->entries) {
        free(list->entries);
        list->entries = NULL;
    }
    pthread_mutex_destroy(&list->lock);
}
