#define NFAPI_CRC_INDICATION_PDU_T_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t allocated_size;
    size_t current_size;
    pthread_mutex_t lock;
} CustomMemoryPool;

CustomMemoryPool *create_custom_memory_pool(size_t max_entries) {
    CustomMemoryPool *pool = malloc(sizeof(CustomMemoryPool));
    pool->pool_size = max_entries * NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pool->pool = malloc(pool->pool_size);
    pool->allocated_size = 0;
    pool->current_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_custom_memory_pool(CustomMemoryPool *pool) {
    free(pool->pool);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_from_pool(CustomMemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated_size + NFAPI_CRC_INDICATION_PDU_T_SIZE > pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *entry = &pool->pool[pool->allocated_size];
    pool->allocated_size += NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pool->current_size++;
    pthread_mutex_unlock(&pool->lock);
    return entry;
}

void free_to_pool(CustomMemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&pool->lock);
    size_t index = (char *)entry - (char *)pool->pool;
    if (index % NFAPI_CRC_INDICATION_PDU_T_SIZE != 0 || index + NFAPI_CRC_INDICATION_PDU_T_SIZE > pool->allocated_size) {
        pthread_mutex_unlock(&pool->lock);
        return; // Invalid pointer
    }
    pool->allocated_size -= NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pool->current_size--;
    pthread_mutex_unlock(&pool->lock);
}

void insert_entry(CustomMemoryPool *pool, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *entry = allocate_from_pool(pool);
    if (entry != NULL) {
        entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        entry->RNTI = RNTI;
        entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    }
}

void iterate_forward(CustomMemoryPool *pool, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->current_size; i++) {
        callback(&pool->pool[i]);
    }
    pthread_mutex_unlock(&pool->lock);
}

void iterate_backward(CustomMemoryPool *pool, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = pool->current_size - 1; i < pool->current_size; i--) {
        callback(&pool->pool[i]);
    }
    pthread_mutex_unlock(&pool->lock);
}
