    int width;
    int height;
    size_t pixelCount;
} ImageMetadata;

int processImageFiles(const char* fileNames[], int numFiles, size_t maxMemory, ImageMetadata** metadata) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    size_t totalSize = 0;
    *metadata = NULL;

    for (int i = 0; i < numFiles; ++i) {
        FILE* file = fopen(fileNames[i], "rb");
        if (!file) {
            perror("Failed to open file");
            return -1;
        }

        // Simulate metadata extraction
        int width, height;
        size_t pixelCount;
        fscanf(file, "%d %d %zu", &width, &height, &pixelCount);

        ImageMetadata* newMetadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
        if (!newMetadata) {
            perror("Failed to allocate memory");
            fclose(file);
            return -1;
        }

        newMetadata->width = width;
        newMetadata->height = height;
        newMetadata->pixelCount = pixelCount;

        // Lock before updating shared data
        pthread_mutex_lock(&lock);
        if (totalSize + sizeof(ImageMetadata) > maxMemory) {
            free(newMetadata);
            fclose(file);
            pthread_mutex_unlock(&lock);
            return -1; // Memory limit exceeded
        }

        totalSize += sizeof(ImageMetadata);

        if (*metadata == NULL) {
            *metadata = newMetadata;
        } else {
            ImageMetadata* current = *metadata;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newMetadata;
        }

        fclose(file);
        pthread_mutex_unlock(&lock);
    }

    return numFiles; // All files processed successfully
}

// Example usage:
int main() {
    const char* fileNames[] = {"image1.jpg", "image2.png"};
    int numFiles = sizeof(fileNames) / sizeof(fileNames[0]);
    size_t maxMemory = 1024 * 1024 * 5; // 5MB limit
    ImageMetadata* metadata;

    int result = processImageFiles(fileNames, numFiles, maxMemory, &metadata);
    if (result >= 0) {
        printf("Processed %d images successfully.\n", result);
    } else {
        printf("Failed to process images: Error code %d\n", -result);
    }

    // Free allocated metadata
    ImageMetadata* current = metadata;
    while (current != NULL) {
        ImageMetadata* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
