}

int process_images(const char** file_paths, size_t num_files, size_t max_memory_size) {
    LRUCache* cache = create_cache(100);
    int processed_count = 0;

    for (size_t i = 0; i < num_files; ++i) {
        CacheEntry* entry;
        pthread_mutex_lock(&cache->lock);
        for (entry = cache->entries[0]; entry != NULL; entry = entry->next) {
            if (strcmp(entry->file_path, file_paths[i]) == 0) {
                // Cache hit
                printf("Cache hit: %s\n", file_paths[i]);
                pthread_mutex_unlock(&cache->lock);
                break;
            }
        }
        pthread_mutex_unlock(&cache->lock);

        if (entry == NULL) {
            // Cache miss
            printf("Cache miss: %s\n", file_paths[i]);

            ImageMetadata metadata;
            int result = process_image(file_paths[i], &metadata);
            if (result != 0) {
                // Handle error
                continue;
            }

            // Check memory usage and allocate new cache entry
            size_t new_memory_usage = sizeof(ImageMetadata) + strlen(file_paths[i]) + 1;
            // Implement logic to check and update memory usage

            CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
            new_entry->file_path = strdup(file_paths[i]);
            memcpy(&new_entry->metadata, &metadata, sizeof(ImageMetadata));
            new_entry->next = NULL;

            pthread_mutex_lock(&cache->lock);
            if (cache->count < cache->capacity) {
                // Add to cache
                size_t index = processed_count % cache->capacity;
                new_entry->next = cache->entries[index];
                cache->entries[index] = new_entry;
                ++cache->count;
            } else {
                // Evict least recently used entry
                CacheEntry* lru_entry = cache->entries[0];
                for (entry = lru_entry; entry != NULL; entry = entry->next) {
                    // Implement logic to determine LRU entry
                }
                free(lru_entry->file_path);
                free(lru_entry);
            }
            pthread_mutex_unlock(&cache->lock);

            ++processed_count;
        } else {
            // Cache hit, process metadata and continue
            // ...
        }
    }

    destroy_cache(cache);
    return processed_count;
}

int main() {
    const char* file_paths[] = {"image1.jpg", "image2.jpg", /* ... */};
    size_t num_files = sizeof(file_paths) / sizeof(file_paths[0]);
    size_t max_memory_size = 1024 * 1024 * 1024; // 1GB

    int result = process_images(file_paths, num_files, max_memory_size);
    printf("Processed %d images\n", result);

    return 0;
}
