EVP_CIPHER* initialize_cipher(int cipher_mode) {
    EVP_CIPHER* cipher = NULL;

    switch (cipher_mode) {
        case 1: // ECB
            cipher = EVP_des_ecb();
            break;
        case 2: // EDE
            cipher = EVP_des_ede_cbc();
            break;
        case 3: // EDE3
            cipher = EVP_des_ede3_cbc();
            break;
        case 4: // CFB
            cipher = EVP_des_cfb64();
            break;
        default:
            fprintf(stderr, "Invalid cipher mode\n");
    }

    return cipher;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdus(int N, int** cipher_key, EVP_CIPHER** chosen_cipher) {
