        return NULL;
    }

    size_t total_memory_needed = num_images * sizeof(ImageMetadata);
    if (total_memory_needed > max_memory_budget) {
        fprintf(stderr, "Memory budget exceeded: %zu bytes needed, %zu bytes available\n", total_memory_needed, max_memory_budget);
        return NULL;
