#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEADER_SIZE 16
#define OVERHEAD 8
#define MAX_PACKET_SIZE (1024 * 1024) // Example limit

typedef struct PacketHeader {
    uint32_t payload_size;
} PacketHeader;

uint32_t calculate_checksum(const void* data, size_t length) {
    const unsigned char* ptr = (const unsigned char*)data;
    uint32_t sum = 0;
    while (length--) {
        sum += *ptr++;
    }
    return sum & 0xFFFFFFFF;
}

int allocate_payload(PacketHeader* header, void** payload_ptr) {
    size_t total_size = HEADER_SIZE + OVERHEAD + header->payload_size;
    if (total_size > MAX_PACKET_SIZE) {
        return -1; // Overflow or too large
    }

    *payload_ptr = malloc(total_size);
    if (*payload_ptr == NULL) {
        return -2; // Allocation failed
    }

    // Align to 8-byte boundary
    uintptr_t addr = (uintptr_t)*payload_ptr;
    size_t padding = ((addr + OVERHEAD - 1) & ~(OVERHEAD - 1)) - addr;
    if (padding > header->payload_size) {
        free(*payload_ptr);
        return -3; // Insufficient space for payload
    }

    *payload_ptr += HEADER_SIZE + padding;
    return 0;
}

int process_packet(PacketHeader* header, const void* packet_data, size_t packet_size) {
    if (packet_size < HEADER_SIZE || packet_size != HEADER_SIZE + header->payload_size) {
        return -1; // Invalid packet size
    }

    void* payload_ptr;
    int result = allocate_payload(header, &payload_ptr);
    if (result != 0) {
        return result; // Allocation failed
    }

    memcpy(payload_ptr, packet_data + HEADER_SIZE, header->payload_size);

    uint32_t checksum = calculate_checksum(payload_ptr, header->payload_size);
    uint32_t received_checksum = *(uint32_t*)packet_data;
    if (checksum != received_checksum) {
        free(payload_ptr);
        return -2; // Checksum mismatch
    }

    // Process payload
    // ...

    free(payload_ptr);
    return 0;
}
