NFAPI_CRC_ARRAY_T* create_nfaip_crc_array(size_t initial_capacity, size_t max_size_kb) {
    if (initial_capacity > 10000 || max_size_kb * 1024 < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL;
    }

    NFAPI_CRC_ARRAY_T* array = malloc(sizeof(*array));
    if (!array) {
        return NULL;
    }

    size_t max_size_bytes = max_size_kb * 1024;
    size_t aligned_capacity = (initial_capacity + 3) & ~3; // Align to 4-byte boundary
    size_t total_size_bytes = aligned_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (total_size_bytes > max_size_bytes) {
        free(array);
        return NULL;
    }

    array->array = malloc(total_size_bytes);
    if (!array->array) {
        free(array);
        return NULL;
    }

    memset(array->array, 0, total_size_bytes);

    array->capacity = aligned_capacity;
    array->size = 0;
    array->max_size = max_size_bytes / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return array;
}

void destroy_nfaip_crc_array(NFAPI_CRC_ARRAY_T* array) {
