#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define OVERHEAD 16 // Fixed overhead for metadata

uint32_t calculate_checksum(uint64_t timestamp, const char *message) {
    uint32_t checksum = 0;
    for (int i = 0; message[i]; i++) {
        checksum += message[i];
    }
    return (checksum + timestamp) & 0xFFFFFFFF;
}

size_t aligned_size(size_t size) {
    return ((size + 7) / 8) * 8; // Align to the nearest 8-byte boundary
}

void* allocate_log_entry(uint64_t timestamp, const char *message, size_t *entry_size) {
    size_t message_len = strlen(message);
    if (message_len > SIZE_MAX - OVERHEAD - sizeof(uint32_t)) {
        return NULL; // Prevent overflow in total size calculation
    }

    *entry_size = aligned_size(OVERHEAD + sizeof(uint32_t) + message_len);
    void *entry = malloc(*entry_size);
    if (!entry) {
        return NULL; // Memory allocation failed
    }

    uint32_t *checksum_ptr = (uint32_t *)entry;
    char *message_ptr = (char *)(checksum_ptr + 1);

    *checksum_ptr = calculate_checksum(timestamp, message);
    memcpy(message_ptr, message, message_len);

    return entry;
}

void free_log_entry(void *entry) {
    free(entry);
}

int main() {
    uint64_t timestamp = 1234567890;
    const char *message = "Error: Disk space insufficient";

    size_t entry_size;
    void *log_entry = allocate_log_entry(timestamp, message, &entry_size);
    if (log_entry) {
        // Process log entry
        free_log_entry(log_entry);
    }

    return 0;
