#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define MIN_OVERHEAD 4
#define MAX_OVERHEAD 8

typedef struct packet {
    int payload_size;
    char *payload;
} Packet;

typedef struct memory_pool {
    void *pool_start;
    size_t pool_size;
    size_t block_size;
    int num_blocks;
    int free_index;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t pool_size, size_t block_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->pool_start = malloc(pool_size);
    mp->pool_size = pool_size;
    mp->block_size = block_size;
    mp->num_blocks = pool_size / block_size;
    mp->free_index = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void *memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_index >= mp->num_blocks) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool is full
    }
    void *block = ((char *)mp->pool_start) + (mp->free_index * mp->block_size);
    mp->free_index++;
    pthread_mutex_unlock(&mp->lock);
    return block;
}

void memory_pool_free(MemoryPool *mp, void *block) {
    pthread_mutex_lock(&mp->lock);
    int index = ((char *)block - (char *)mp->pool_start) / mp->block_size;
    if (index < 0 || index >= mp->num_blocks) {
        pthread_mutex_unlock(&mp->lock);
        return; // Invalid block
    }
    mp->free_index = index;
    pthread_mutex_unlock(&mp->lock);
}

int validate_packet(Packet *packet, MemoryPool *mp) {
    if (packet->payload_size <= 0 || packet->payload_size > MAX_PACKET_SIZE) {
        return -1; // Invalid payload size
    }

    char *aligned_payload = memory_pool_alloc(mp);
    if (!aligned_payload) {
        return -2; // Out of memory
    }

    memcpy(aligned_payload, packet->payload, packet->payload_size);

    // Compute and verify checksum here

    memory_pool_free(mp, aligned_payload);
    return 0; // Packet is valid
}

void *process_packets(void *arg) {
    MemoryPool *mp = (MemoryPool *)arg;
    while (1) {
        // Receive packet from network interface
        Packet packet;

        // Validate packet and process here

        int result = validate_packet(&packet, mp);
        if (result == -1) {
            printf("Invalid payload size\n");
        } else if (result == -2) {
            printf("Out of memory\n");
        }
    }
}

int main() {
    MemoryPool *mp = create_memory_pool(1024 * 1024, 64); // 1MB pool with 64-byte blocks

    pthread_t thread;
    pthread_create(&thread, NULL, process_packets, mp);

    // Wait for threads to finish (not applicable in this example)

    free(mp->pool_start);
    free(mp);

    return 0;
}
