typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t allocated_size;
    size_t used_size;
} MemoryPool;

void initialize_memory_pool(MemoryPool* pool, size_t initial_size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pool->allocated_size = initial_size;
    pool->used_size = 0;
}

void free_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    pool->pool = NULL;
    pool->allocated_size = 0;
    pool->used_size = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_entry(MemoryPool* pool) {
    if (pool->used_size >= pool->allocated_size) {
        size_t new_size = pool->allocated_size == 0 ? 1 : pool->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        pool->pool = new_pool;
        pool->allocated_size = new_size;
    }
    return &pool->pool[pool->used_size++];
}

void populate_entries(MemoryPool* pool, int max_entries, unsigned int seed) {
    srand(seed);
