#define MAX_STRUCTURES 1024 * 1024 // 1 MB limit for structures
#define POOL_SIZE 10 * 1024 * 1024   // 10 MB fixed size pool

typedef struct {
    int index;
    uint32_t crc_flags;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pool = NULL;
int pool_size = POOL_SIZE;
int allocated_count = 0;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure(int index, uint32_t crc_flags) {
    if (allocated_count >= MAX_STRUCTURES) {
        log_error("Maximum number of structures reached.");
        return NULL;
    }

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((pool + allocated_count) * struct_size > pool + POOL_SIZE) {
        log_error("Memory allocation exceeds pool limit.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structure = pool + allocated_count++;
    structure->index = index;
    structure->crc_flags = crc_flags;

    return structure;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        log_error("Usage: program_name <number_of_structures>");
        return 1;
    }

    int num_structures = atoi(argv[1]);
    if (num_structures <= 0 || num_structures > MAX_STRUCTURES) {
        log_error("Invalid number of structures specified.");
        return 1;
    }

    pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(POOL_SIZE);
    if (!pool) {
        log_error("Failed to allocate memory pool.");
        return 1;
    }

    for (int i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* structure = allocate_structure(i, 0x0); // Example CRC flags
        if (!structure) {
            log_error("Failed to allocate structure.");
            free(pool);
            return 1;
        }
    }

    // Simulate runtime queries
    for (int i = 0; i < allocated_count; ++i) {
        printf("Structure %d: Index=%d, CRC Flags=0x%X\n", i, pool[i].index, pool[i].crc_flags);
    }

    free(pool);
    return 0;
}
