#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILE_PATHS 10000

typedef struct {
    char name[256];
    size_t size;
    time_t last_modified;
} FileMetadata;

FileMetadata* process_file_paths(char** file_paths, int count) {
    if (count <= 0 || count > MAX_FILE_PATHS) {
        return NULL; // Invalid or too many file paths
    }

    FileMetadata* metadata = malloc(count * sizeof(FileMetadata));
    if (!metadata) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < count; i++) {
        FILE* file = fopen(file_paths[i], "r");
        if (file) {
            struct stat file_stat;
            if (fstat(fileno(file), &file_stat) == 0) {
                strncpy(metadata[i].name, basename(file_paths[i]), sizeof(metadata[i].name) - 1);
                metadata[i].size = file_stat.st_size;
                metadata[i].last_modified = file_stat.st_mtime;
            }
            fclose(file);
        } else {
            // Handle error in opening or reading file
            metadata[i].size = 0;
            metadata[i].last_modified = 0;
        }
    }

    return metadata;
}

// Example usage:
int main() {
    char* files[MAX_FILE_PATHS] = { "path/to/file1.txt", "path/to/file2.txt" };
    FileMetadata* file_metadata = process_file_paths(files, 2);

    if (file_metadata) {
        for (int i = 0; i < 2; i++) {
            printf("File: %s, Size: %zu bytes, Last Modified: %s", 
                   file_metadata[i].name, file_metadata[i].size, ctime(&file_metadata[i].last_modified));
        }
        free(file_metadata);
    } else {
        printf("Failed to process file paths.\n");
    }

    return 0;
}
