UserAccount users[MAX_USERS];
int user_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int ValidateRequest(Request *request) {
    // Validate request data
}

void SaveUser(UserAccount *user) {
    pthread_mutex_lock(&mutex);
    if (user_count < MAX_USERS) {
        memcpy(&users[user_count], user, sizeof(UserAccount));
        user_count++;
    } else {
        printf("Error: User count exceeded\n");
    }
    pthread_mutex_unlock(&mutex);
}

UserAccount* GetUser(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < user_count; i++) {
        if (users[i].id == id) {
            return &users[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

Response ProcessRequest(Request *request) {
    Response response;
    if (!ValidateRequest(request)) {
        response.message = "error";
        response.details = "Invalid request data";
        return response;
    }

    switch (request->action) {
        case CREATE:
            SaveUser(&request->user);
            break;
        case UPDATE:
            UserAccount *user = GetUser(request->id);
            if (user != NULL) {
                memcpy(user, &request->user, sizeof(UserAccount));
            }
            break;
        case DELETE:
            pthread_mutex_lock(&mutex);
            for (int i = 0; i < user_count; i++) {
                if (users[i].id == request->id) {
                    memmove(&users[i], &users[i + 1], (user_count - i - 1) * sizeof(UserAccount));
                    user_count--;
                    break;
                }
            }
            pthread_mutex_unlock(&mutex);
            break;
        default:
            response.message = "error";
            response.details = "Invalid action";
            return response;
    }

    response.message = "success";
    return response;
}
