    if (num_headers == 0 || max_memory == 0) {
        return -1; // Invalid input
    }

    size_t total_payload_size = 0;
    for (size_t i = 0; i < num_headers; ++i) {
        total_payload_size += headers[i]->payload_size;
        if (total_payload_size > max_memory) {
            return -2; // Exceeds maximum memory
        }
    }

    char* payload_buffer = malloc(total_payload_size);
    if (!payload_buffer) {
        return -3; // Memory allocation failed
    }

    PacketHeader** processed_headers = malloc(num_headers * sizeof(PacketHeader*));
    if (!processed_headers) {
        free(payload_buffer);
        return -4; // Memory allocation failed
    }

    size_t current_offset = 0;
    for (size_t i = 0; i < num_headers; ++i) {
        processed_headers[i] = malloc(sizeof(PacketHeader));
        if (!processed_headers[i]) {
            free_payload_buffers(processed_headers, i);
            free(payload_buffer);
            return -4; // Memory allocation failed
        }
        processed_headers[i]->payload_size = headers[i]->payload_size;
        processed_headers[i]->payload_data = payload_buffer + current_offset;
        memcpy(processed_headers[i]->payload_data, headers[i]->payload_data, headers[i]->payload_size);
        current_offset += headers[i]->payload_size;
    }

    // Process packets here
    free_payload_buffers(processed_headers, num_headers);
    free(payload_buffer);

    return 0; // Success
}

void free_payload_buffers(PacketHeader** headers, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (headers[i]) {
            free(headers[i]);
        }
    }
    free(headers);
}
