#define MAX_TAG_LENGTH 256
#define DEFAULT_MAX_TAGS 100

typedef struct ImageTag {
    int id;
    char tag[MAX_TAG_LENGTH];
} ImageTag;

typedef struct TagList {
    ImageTag *tags;
    size_t count;
    size_t capacity;
} TagList;

void init_tag_list(TagList *list, size_t initial_capacity) {
    list->tags = (ImageTag *)malloc(initial_capacity * sizeof(ImageTag));
    if (!list->tags) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
}

void resize_tag_list(TagList *list) {
    size_t new_capacity = list->capacity * 2;
    ImageTag *new_tags = (ImageTag *)realloc(list->tags, new_capacity * sizeof(ImageTag));
    if (!new_tags) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->tags = new_tags;
    list->capacity = new_capacity;
}

void add_tag(TagList *list, int id, const char *tag) {
    if (list->count >= list->capacity) {
        resize_tag_list(list);
    }
    list->tags[list->count].id = id;
    strncpy(list->tags[list->count].tag, tag, MAX_TAG_LENGTH - 1);
    list->tags[list->count].tag[MAX_TAG_LENGTH - 1] = '\0';
    list->count++;
}

void free_tag_list(TagList *list) {
    free(list->tags);
    list->tags = NULL;
    list->count = 0;
    list->capacity = 0;
}

// Example usage
int main() {
    TagList tag_list;
    init_tag_list(&tag_list, DEFAULT_MAX_TAGS);

    // Simulate adding tags from image files
    add_tag(&tag_list, 1, "sunset");
    add_tag(&tag_list, 2, "nature");
    add_tag(&tag_list, 3, "travel");

    // Process the tag list
    for (size_t i = 0; i < tag_list.count; i++) {
        printf("Image ID: %d, Tag: %s\n", tag_list.tags[i].id, tag_list.tags[i].tag);
    }

    free_tag_list(&tag_list);

    return 0;
}
