#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTS 1000
#define LIST_LIMIT 50

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(Node** head, NFAPI_CRC_INDICATION_PDU data) {
    if (*head == NULL) {
        *head = create_node(data);
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = create_node(data);
    }
}

void manage_list(Node** head, int N) {
    srand(time(0));
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % MAX_STRUCTS;
        pdu.RNTI = rand() % MAX_STRUCTS;
        pdu.CRC_INDICATION_REL8_TAG = rand() % MAX_STRUCTS;
        pdu.CRCFLAG = rand() % 2;

        if (i >= LIST_LIMIT) {
            Node* temp = *head;
            *head = (*head)->next;
            free(temp);
        }

        add_to_list(head, pdu);
    }
}

void free_list(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int main() {
    Node* head = NULL;
    int N;

    printf("Enter the number of structures to create: ");
    scanf("%d", &N);

    manage_list(&head, N);
    free_list(&head);

    return 0;
}
