#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_FRAMES_PER_PACKET 1024

typedef struct {
    uint32_t metadata;
} Frame;

typedef struct {
    int frame_count;
    Frame* frames;
} Packet;

Packet* create_packet(int frame_count) {
    if (frame_count <= 0 || frame_count > MAX_FRAMES_PER_PACKET) {
        return NULL; // Invalid frame count
    }

    Packet* packet = (Packet*)aligned_alloc(64, sizeof(Packet));
    if (!packet) {
        return NULL; // Memory allocation failed
    }

    packet->frame_count = frame_count;
    packet->frames = (Frame*)aligned_alloc(64, frame_count * sizeof(Frame));
    if (!packet->frames) {
        free(packet);
        return NULL; // Frame memory allocation failed
    }

    return packet;
}

void destroy_packet(Packet* packet) {
    if (!packet) {
        return;
    }

    aligned_free(packet->frames);
    aligned_free(packet);
}

int process_packets(Packet** packets, int packet_count) {
    for (int i = 0; i < packet_count; i++) {
        Packet* packet = packets[i];
        if (!packet) {
            continue; // Skip invalid packets
        }

        // Process each frame in the packet
        for (int j = 0; j < packet->frame_count; j++) {
            // Example processing: print metadata
            printf("Frame %d Metadata: %u\n", j, packet->frames[j].metadata);
        }
    }

    return 0;
}

int main() {
    int frame_counts[] = {100, 250, 768};
    Packet** packets = (Packet**)malloc(sizeof(Packet*) * sizeof(frame_counts) / sizeof(int));

    if (!packets) {
        fprintf(stderr, "Failed to allocate memory for packet array.\n");
        return -1;
    }

    for (int i = 0; i < sizeof(frame_counts) / sizeof(int); i++) {
        packets[i] = create_packet(frame_counts[i]);
        if (!packets[i]) {
            fprintf(stderr, "Failed to create packet %d\n", i);
            // Clean up already created packets
            for (int j = 0; j < i; j++) {
                destroy_packet(packets[j]);
            }
            free(packets);
            return -1;
        }
    }

    int result = process_packets(packets, sizeof(frame_counts) / sizeof(int));
    if (result != 0) {
        fprintf(stderr, "Packet processing failed.\n");
    }

    // Clean up all packets
    for (int i = 0; i < sizeof(frame_counts) / sizeof(int); i++) {
        destroy_packet(packets[i]);
    }
    free(packets);

    return result;
}
