#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define INITIAL_BUFFER_SIZE 10

typedef struct {
    char payload[MAX_PACKET_SIZE];
} NetworkPacket;

NetworkPacket* process_packets(char** packet_data, size_t* packet_sizes, size_t packet_count, size_t* total_size) {
    NetworkPacket* packets = (NetworkPacket*)malloc(INITIAL_BUFFER_SIZE * sizeof(NetworkPacket));
    if (!packets) return NULL; // Handle allocation failure

    *total_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        size_t payload_size = packet_sizes[i];
        if (payload_size > MAX_PACKET_SIZE) {
            printf("Packet %zu is too large. Truncating.\n", i);
            payload_size = MAX_PACKET_SIZE;
        }
        memcpy(packets[*total_size].payload, packet_data[i], payload_size);
        packets[*total_size].payload[payload_size] = '\0'; // Null-terminate the payload
        (*total_size)++;

        // Check for integer overflow before reallocating memory
        if (*total_size > (SIZE_MAX / sizeof(NetworkPacket)) - INITIAL_BUFFER_SIZE) {
            printf("Memory allocation would exceed system limit. Aborting.\n");
            free(packets);
            return NULL;
        }
        size_t new_size = *total_size + INITIAL_BUFFER_SIZE;
        NetworkPacket* new_packets = (NetworkPacket*)realloc(packets, new_size * sizeof(NetworkPacket));
        if (!new_packets) {
            printf("Memory reallocation failed. Aborting.\n");
            free(packets);
            return NULL;
        }
        packets = new_packets;
    }
    // Reduce memory usage by reallocating to exact size
    NetworkPacket* optimized_packets = (NetworkPacket*)realloc(packets, *total_size * sizeof(NetworkPacket));
    if (!optimized_packets) {
        printf("Final memory reallocation failed. Aborting.\n");
        free(packets);
        return NULL;
    }
    packets = optimized_packets;

    return packets;
}

int main() {
    // Example usage
    char* packet_data[] = {"Hello, ", "world!\n", "This is a test.", ""};
    size_t packet_sizes[] = {7, 6, 18, 0};
    size_t packet_count = sizeof(packet_data) / sizeof(packet_data[0]);
    size_t total_size;

    NetworkPacket* packets = process_packets(packet_data, packet_sizes, packet_count, &total_size);
    if (packets) {
        for (size_t i = 0; i < total_size; ++i) {
            printf("Packet %zu: %s\n", i, packets[i].payload);
        }
        free(packets);
    }

    return 0;
}
```

This code snippet defines a function `process_packets` that processes an array of packet data and sizes, storing the payloads in dynamically allocated `NetworkPacket` structures. It includes memory management checks to prevent integer overflow and excessive memory usage, as well as strategies for handling large packets by truncating them or logging them. The function also reallocates memory efficiently to minimize fragmentation and ensure optimal resource usage.']

