#define MAX_FILES 1024
#define MAX_SETTINGS_PER_FILE 1024

typedef struct {
    int num_settings;
    // Metadata for each setting
} Setting;

typedef struct {
    char *name;
    Setting settings[MAX_SETTINGS_PER_FILE];
} ConfigFile;

ConfigFile *files[MAX_FILES];
int total_settings = 0;
float average_settings = 0.0;

void add_file(const char *filename) {
    if (total_files >= MAX_FILES) {
        fprintf(stderr, "Error: Maximum number of files reached.\n");
        return;
    }
    ConfigFile *file = (ConfigFile *)malloc(sizeof(ConfigFile));
    file->name = strdup(filename);
    memset(file->settings, 0, sizeof(Setting) * MAX_SETTINGS_PER_FILE);
    total_settings++;
    average_settings = (average_settings * (total_files - 1) + file->num_settings) / total_files;
    files[total_files++] = file;
}

void add_setting(int file_index, int setting_index) {
    if (file_index < 0 || file_index >= total_files || setting_index < 0 || setting_index >= MAX_SETTINGS_PER_FILE) {
        fprintf(stderr, "Error: Invalid file or setting index.\n");
        return;
    }
    files[file_index]->settings[setting_index].num_settings++;
    average_settings = (average_settings * (total_files - 1) + files[file_index]->settings[setting_index].num_settings) / total_files;
}

void free_files() {
    for (int i = 0; i < total_files; i++) {
        free(files[i]->name);
        free(files[i]);
    }
    total_files = 0;
    average_settings = 0.0;
}
