#define MAX_STRUCTS 100000
#define BULK_ALLOC_SIZE 1024

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    pthread_mutex_t mutex;
} ThreadSafeStruct;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_structs(int N, pthread_mutex_t *global_lock) {
    if (N > MAX_STRUCTS || N <= 0) {
        return NULL; // Handle invalid input
    }

    int required_size = N / BULK_ALLOC_SIZE + (N % BULK_ALLOC_SIZE != 0);
    ThreadSafeStruct* thread_safe_structs = malloc(required_size * sizeof(ThreadSafeStruct));
    if (!thread_safe_structs) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_lock(global_lock); // Lock to ensure atomicity of allocation and population

    for (int i = 0; i < required_size; i++) {
        pthread_mutex_init(&thread_safe_structs[i].mutex, NULL);
    }

    for (int i = 0; i < N; i++) {
        int index = i / BULK_ALLOC_SIZE;
        pthread_mutex_lock(&thread_safe_structs[index].mutex);
        thread_safe_structs[index].ue_info_tag = generate_random_UE_info_tag(); // Implement this function
        thread_safe_structs[index].RNTI = generate_random_RNTI(); // Implement this function
        thread_safe_structs[index].crc_indication_rel8_tag.CRCFLAG = (rand() % 2); // Randomly set CRCFLAG
        pthread_mutex_unlock(&thread_safe_structs[index].mutex);
    }

    pthread_mutex_unlock(global_lock);

    return (NFAPI_CRC_INDICATION_PDU_T*) thread_safe_structs;
}

void free_structs(NFAPI_CRC_INDICATION_PDU_T* structs, int N) {
    ThreadSafeStruct* thread_safe_structs = (ThreadSafeStruct*) structs;

    for (int i = 0; i < MAX_STRUCTS / BULK_ALLOC_SIZE + 1; i++) {
        pthread_mutex_destroy(&thread_safe_structs[i].mutex);
    }

    free(thread_safe_structs);
}

