#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct {
    int width;
    int height;
    unsigned char* data;
} Image;

typedef struct {
    Image** images;
    size_t count;
    size_t max_count;
    size_t total_memory_usage;
    size_t max_memory_limit;
    pthread_mutex_t mutex;
} ImageList;

ImageList* create_image_list(size_t initial_capacity, size_t max_memory_limit) {
    ImageList* list = (ImageList*)malloc(sizeof(ImageList));
    if (!list) return NULL;

    list->images = (Image**)calloc(initial_capacity, sizeof(Image*));
    if (!list->images) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->max_count = initial_capacity;
    list->total_memory_usage = 0;
    list->max_memory_limit = max_memory_limit > MAX_MEMORY_LIMIT ? MAX_MEMORY_LIMIT : max_memory_limit;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_image_list(ImageList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->images[i]->data);
        free(list->images[i]);
    }

    free(list->images);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_image(ImageList* list, int width, int height, const unsigned char* data) {
    if (!list || !data) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_count) {
        Image** new_images = (Image**)realloc(list->images, sizeof(Image*) * (list->max_count + 1));
        if (!new_images) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->images = new_images;
        list->max_count++;
    }

    Image* img = (Image*)malloc(sizeof(Image));
    if (!img) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    size_t image_size = width * height * sizeof(unsigned char);
    if ((SIZE_MAX - list->total_memory_usage) < image_size) {
        free(img);
        pthread_mutex_unlock(&list->mutex);
        return -1; // Integer overflow check
    }

    img->width = width;
    img->height = height;
    img->data = (unsigned char*)malloc(image_size);
    if (!img->data) {
        free(img);
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    memcpy(img->data, data, image_size);

    list->images[list->count] = img;
    list->total_memory_usage += image_size;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_image(ImageList* list, size_t index) {
    if (!list || index >= list->count) return -1;

    pthread_mutex_lock(&list->mutex);

    Image* img = list->images[index];
    size_t image_size = img->width * img->height * sizeof(unsigned char);
    free(img->data);
    free(img);
    for (size_t i = index; i < list->count - 1; ++i) {
        list->images[i] = list->images[i + 1];
    }
    list->images[list->count - 1] = NULL;
    list->total_memory_usage -= image_size;
    list->count--;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

size_t get_image_count(ImageList* list) {
    if (!list) return 0;
    return list->count;
}
