    FILE *configFile = fopen("config.txt", "r");
    if (configFile == NULL) {
        fprintf(stderr, "Error opening config file.\n");
        return NULL;
    }

    char buffer[256];
    if (fgets(buffer, sizeof(buffer), configFile) == NULL) {
        fclose(configFile);
        fprintf(stderr, "Error reading from config file.\n");
        return NULL;
    }
    fclose(configFile);

    // Validate and parse the number of elements
    int numElements = 0;
    for (char *p = buffer; *p != '\0'; p++) {
        if (!isdigit(*p)) {
            fprintf(stderr, "Invalid config file content.\n");
            return NULL;
        }
    }
    numElements = atoi(buffer);
    if (numElements <= 0 || numElements > MAX_CONFIG_VALUE) {
        fprintf(stderr, "Invalid number of elements in config file.\n");
        return NULL;
    }

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize structures with random values
    for (int i = 0; i < numElements; i++) {
