        structures[i].RNTI = rand() % 16384; // Random RNTI value
        structures[i].CRC_INDICATION_REL8_TAG = rand();
        structures[i].CRCFLAG = (rand() % 2); // Random CRCFLAG value
    }

    return structures;
}

