int calculate_buffer_size(int num_instances) {
    size_t instance_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (num_instances < 0 || num_instances > INT_MAX / instance_size) {
        fprintf(stderr, "Error: Integer overflow detected in buffer size calculation.\n");
