#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void enqueue(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(LinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T data = {0};
    pthread_mutex_lock(&list->lock);
    if (list->head != NULL) {
        Node* temp = list->head;
        data = temp->data;
        list->head = list->head->next;
        if (list->head == NULL) {
            list->tail = NULL;
        }
        free(temp);
        list->size--;
    }
    pthread_mutex_unlock(&list->lock);
    return data;
}

void garbageCollect(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (/* Condition for garbage collection */) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void* producer(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    for (int i = 0; i < MAX_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = { /* Initialize data */ };
        enqueue(list, data);
    }
    return NULL;
}

void* consumer(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    for (int i = 0; i < MAX_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = dequeue(list);
        // Process data
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <N>\n", argv[0]);
        return 1;
    }

    int N = atoi(argv[1]);
    if (N <= 0 || N > MAX_SIZE) {
        printf("Invalid number of structures\n");
        return 1;
    }

    LinkedList list;
    initLinkedList(&list);

    pthread_t producerThread, consumerThread;
    pthread_create(&producerThread, NULL, producer, &list);
    pthread_create(&consumerThread, NULL, consumer, &list);

    pthread_join(producerThread, NULL);
    pthread_join(consumerThread, NULL);

    garbageCollect(&list);

    pthread_mutex_destroy(&list.lock);

    return 0;
}
