    CipherMode mode;
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CryptoContext;

CryptoContext* create_context(CipherMode mode, const unsigned char *key, int key_len, const unsigned char *iv, int iv_len) {
    CryptoContext *context = malloc(sizeof(CryptoContext));
    context->mode = mode;
    context->ctx = EVP_CIPHER_CTX_new();
    memcpy(context->key, key, key_len);
    memcpy(context->iv, iv, iv_len);

    switch (mode) {
        case DES_ECB:
            EVP_EncryptInit_ex(context->ctx, EVP_des_ecb(), NULL, context->key, NULL);
            break;
        case DES_EDE:
            EVP_EncryptInit_ex(context->ctx, EVP_des_ede3_cbc(), NULL, context->key, context->iv);
            break;
        case CFB:
            EVP_CIPHER_CTX_set_iv_length(context->ctx, iv_len);
            EVP_EncryptInit_ex(context->ctx, EVP_cfb128(), NULL, context->key, context->iv);
            break;
        default:
            EVP_CIPHER_CTX_free(context->ctx);
            free(context);
            return NULL;
    }

    return context;
}

void encrypt_data(CryptoContext *context, const unsigned char *input, int input_len, unsigned char *output) {
    int len = 0;
    int ciphertext_len = 0;

    if (context->mode == CFB) {
        EVP_EncryptUpdate(context->ctx, output, &len, input, input_len);
        ciphertext_len += len;
    } else {
        EVP_EncryptFinal_ex(context->ctx, output + len, &len);
        ciphertext_len += len;
    }

    memcpy(output + ciphertext_len, context->key, sizeof(context->key));
}

void decrypt_data(CryptoContext *context, const unsigned char *input, int input_len, unsigned char *output) {
    int len = 0;
    int plaintext_len = 0;

    if (context->mode == CFB) {
        EVP_DecryptUpdate(context->ctx, output, &len, input, input_len);
        plaintext_len += len;
    } else {
        EVP_DecryptFinal_ex(context->ctx, output + len, &len);
        plaintext_len += len;
    }

    memcpy(output + plaintext_len, context->key, sizeof(context->key));
}

void hmac_data(const unsigned char *data, int data_len, const unsigned char *secret, int secret_len, unsigned char *output) {
    HMAC(EVP_sha256(), secret, secret_len, data, data_len, output, NULL);
}

void destroy_context(CryptoContext *context) {
    EVP_CIPHER_CTX_free(context->ctx);
    free(context);
}
```

This code provides a basic structure for a cryptographic library in C. It includes functions to create and manage cryptographic contexts, encrypt and decrypt data using different modes, compute HMACs for integrity checking, and clean up resources. The actual implementation of the encryption and decryption logic is left as an exercise, depending on the specific cipher modes required (DES ECB, EDE, EDE3, CFB).']

