    }
}

NFAPI_CRC_INDICATION_PDU_T* getFromPool() {
    if (poolIndex >= POOL_SIZE) return NULL;
    NFAPI_CRC_INDICATION_PDU_T* pdu = memoryPool[poolIndex++];
    return pdu;
}

void freeToPool(NFAPI_CRC_INDICATION_PDU_T* pdu) {
