NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_list(uint32_t N, size_t memory_budget) {
    if (N == 0 || memory_budget == 0) return NULL;

    srand(time(NULL));
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t rx_tag_size = sizeof(RX_UE_INFORMATION_TAG);
    size_t rnti_size = sizeof(RNTI);
    size_t crc_tag_size = sizeof(CRC_INDICATION_REL8_TAG);

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(memory_budget);
    if (!pdu_list) return NULL;

    uint32_t max_structures = memory_budget / struct_size;
    if (max_structures < N) {
        N = max_structures;
    }

    for (uint32_t i = 0; i < N; i++) {
        RX_UE_INFORMATION_TAG *rx_tag = (RX_UE_INFORMATION_TAG*)malloc(rx_tag_size);
        if (!rx_tag) {
