    pthread_mutex_lock(lock);

    if (*count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(lock);
        return NULL; // Reached maximum limit
    }

    NFAPI_CRC_INDICATION_PDU_T** pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((*count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!pdu_list) {
        pthread_mutex_unlock(lock);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i <= *count; ++i) {
        pdu_list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu_list[i]) {
            // Handle partial allocation
            for (int j = 0; j < i; ++j) {
                free(pdu_list[j]);
            }
            free(pdu_list);
            pthread_mutex_unlock(lock);
            return NULL;
        }

        // Populate each structure with valid data and random CRCFLAG
    }

    *count += 1;
    pthread_mutex_unlock(lock);
    return pdu_list;
}

void free_pdu_list(NFAPI_CRC_INDICATION_PDU_T** pdu_list, int count, pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);

    for (int i = 0; i < count; ++i) {
        free(pdu_list[i]);
    }

    free(pdu_list);
    pthread_mutex_unlock(lock);
}
