#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Node* head = NULL;
int current_count = 0;

void log_event(const char* message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T create_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = (unsigned short)rand();
    pdu.CRCFLAG = rand() % 2;
    return pdu;
}

void* allocate_structure(void* arg) {
    pthread_mutex_lock(&mutex);
    if (current_count >= MAX_STRUCTURES) {
        log_event("Error: Maximum structure limit reached");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        log_event("Error: Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    new_node->data = create_random_pdu();
    new_node->prev = NULL;
    new_node->next = head;

    if (head != NULL) {
        head->prev = new_node;
    }
    head = new_node;

    current_count++;
    pthread_mutex_unlock(&mutex);

    return (void*)new_node;
}

Node* find_structure_by_rnti(unsigned short rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void delete_structure_by_rnti(unsigned short rnti) {
    pthread_mutex_lock(&mutex);
    Node* node_to_delete = find_structure_by_rnti(rnti);
    if (node_to_delete != NULL) {
        if (node_to_delete->prev != NULL) {
            node_to_delete->prev->next = node_to_delete->next;
        } else {
            head = node_to_delete->next;
        }
        if (node_to_delete->next != NULL) {
            node_to_delete->next->prev = node_to_delete->prev;
        }

        free(node_to_delete);
        current_count--;
    }
    pthread_mutex_unlock(&mutex);
}

void serialize_list(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        log_event("Error: Unable to open file for writing");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

int deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        log_event("Error: Unable to open file for reading");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            log_event("Error: Memory allocation failed during deserialization");
            fclose(file);
            return -1;
        }

        new_node->data = pdu;
        new_node->prev = NULL;
        new_node->next = head;

        if (head != NULL) {
            head->prev = new_node;
        }
        head = new_node;

        current_count++;
    }

    fclose(file);
    return 0;
}
