    if (M <= 0 || M > MAX_M) {
        return NULL; // Invalid input
    }

    size_t total_size = sizeof(BITMAP_INFO) * M;
    if (total_size > MAX_MEMORY_SIZE) {
        return NULL; // Exceeds maximum memory limit
    }

    BITMAP_INFO* array = malloc(total_size);
    if (!array) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < M; ++i) {
        array[i].size = rand() % MAX_BITMAP_SIZE + 1;
        array[i].data = (unsigned char*)malloc(array[i].size);
        if (!array[i].data) {
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(array[j].data);
            }
            free(array);
            return NULL;
        }

        // Initialize data with random bytes
        for (size_t j = 0; j < array[i].size; ++j) {
            array[i].data[j] = rand() % 256;
