using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using System.Xml.Schema;

public class GameConfigManager
{
    private readonly ConcurrentDictionary<string, XDocument> _configCache = new ConcurrentDictionary<string, XDocument>();
    private static readonly object _syncLock = new object();
    private static bool _logConfigurationChanges = true;

    public void LoadConfig(string filePath)
    {
        if (!_configCache.ContainsKey(filePath))
        {
            lock (_syncLock)
            {
                if (!_configCache.ContainsKey(filePath))
                {
                    try
                    {
                        var doc = XDocument.Load(filePath, LoadOptions.PreserveWhitespace | LoadOptions.SetLineInfo);
                        ValidateXml(doc);
                        _configCache[filePath] = doc;
                    }
                    catch (Exception ex)
                    {
                        LogError($"Failed to load config file {filePath}: {ex.Message}");
                    }
                }
            }
        }
    }

    public void SwitchConfig(string newFilePath)
    {
        LoadConfig(newFilePath);
    }

    public T GetSetting<T>(string filePath, string settingPath) where T : IConvertible
    {
        if (_configCache.TryGetValue(filePath, out var doc))
        {
            try
            {
                var value = doc.Descendants(settingPath).FirstOrDefault()?.Value;
                if (value != null)
                {
                    return (T)Convert.ChangeType(value, typeof(T));
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to retrieve setting from config file {filePath}: {ex.Message}");
            }
        }

        // Return default value if not found or conversion fails
        return default;
    }

    private void ValidateXml(XDocument doc)
    {
        var schemaSet = new XmlSchemaSet();
        schemaSet.Add(null, "config.xsd"); // Assume XSD file is named config.xsd

        doc.Validate(schemaSet, (sender, e) =>
        {
            LogError($"Validation error: {e.Message}");
        });
    }

    private void LogError(string message)
    {
        if (_logConfigurationChanges)
        {
            Console.Error.WriteLine(message);
        }
    }
}

