#define METADATA_OVERHEAD (sizeof(int) * 3 + sizeof(time_t)) // Assuming int for sequence number, error code, and time_t for timestamp

typedef struct PacketInfo {
    int sequence_number;
    time_t timestamp;
    int error_code;
} PacketInfo;

void* process_packets(int num_packets, const int packet_sizes[], int max_packet_size) {
    if (num_packets <= 0 || max_packet_size <= 0) {
        // Handle invalid input
        return NULL;
    }

    size_t total_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        if (packet_sizes[i] > max_packet_size) {
            // Packet exceeds maximum allowed size
            return NULL;
        }
        // Calculate total size with metadata overhead
        if ((total_size + packet_sizes[i] + METADATA_OVERHEAD) <= SIZE_MAX / 2) { // Check for potential overflow
            total_size += packet_sizes[i] + METADATA_OVERHEAD;
        } else {
            // Handle integer overflow
            return NULL;
        }
    }

    PacketInfo** packet_infos = (PacketInfo**)malloc(num_packets * sizeof(PacketInfo*));
    if (!packet_infos) {
        // Memory allocation failed
        return NULL;
    }

    char* buffer = (char*)malloc(total_size);
    if (!buffer) {
        // Memory allocation failed
        free(packet_infos);
        return NULL;
    }

    size_t offset = 0;
    for (int i = 0; i < num_packets; ++i) {
        packet_infos[i] = (PacketInfo*)(buffer + offset);
        packet_infos[i]->sequence_number = i + 1;
        packet_infos[i]->timestamp = time(NULL);
        packet_infos[i]->error_code = 0;

        memcpy(buffer + offset + METADATA_OVERHEAD, &packet_sizes[i], packet_sizes[i]);
        offset += packet_sizes[i] + METADATA_OVERHEAD;
    }

    return buffer;
}
```

