int current_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* create_struct_thread(void* arg) {
    pthread_mutex_lock(&mutex);
    if (current_count < MAX_STRUCTS) {
        NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_struct->RX_UE_INFORMATION_TAG = rand();
        new_struct->RNTI = rand();
        new_struct->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        struct_list[current_count++] = new_struct;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void delete_structs_thread(void* arg) {
    pthread_mutex_lock(&mutex);
    for (int i = current_count - 1; i >= 0; i--) {
        free(struct_list[i]);
        struct_list[i] = NULL;
    }
    current_count = 0;
    pthread_mutex_unlock(&mutex);
}

void test_function() {
    pthread_t threads[MAX_STRUCTS * 2];
    srand(time(NULL));

    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_create(&threads[i], NULL, create_struct_thread, NULL);
    }

    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_create(&threads[i], NULL, delete_structs_thread, NULL);
    }

    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
