    if (htmlLength > SIZE_MAX - 1024) { // Adjust the constant as needed
        response.success = 0;
        response.refreshPage = 0;
        return response; // Buffer too large to handle safely
    }
    size_t bufferSize = htmlLength + 1024;

    // Allocate memory for HTML content buffer
    char *htmlBuffer = (char *)malloc(bufferSize);
    if (htmlBuffer == NULL) {
        response.success = 0;
        response.refreshPage = 0;
        return response; // Memory allocation failed
    }

    // Copy HTML content to buffer
    strncpy(htmlBuffer, htmlContent, bufferSize);

    // Check service availability and resource limits
    if (!isServiceAvailable() || !checkResourceLimits()) {
        free(htmlBuffer);
        response.success = 0;
        response.refreshPage = 0;
        return response; // Service or resource constraints
    }

    // Update element content on the webpage
    updateElementContent(pageSectionID, elementID, htmlBuffer);

    // Free allocated memory
