#define MAX_FILE_SIZE 1024 * 1024

int load_resource_bundle(const char* file_path, NFAPI_CRC_INDICATION_PDU_T** bundle, int max_items) {
    if (file_path == NULL || bundle == NULL) {
        return -1; // Invalid input
    }

    // Validate file path for directory traversal attacks
    if (strstr(file_path, "..") != NULL || strstr(file_path, "/../") != NULL) {
        return -2; // Potential security risk
    }

    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        return -3; // File not found or permission denied
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size > MAX_FILE_SIZE || file_size <= 0) {
        fclose(file);
        return -4; // Invalid file size
    }

    *bundle = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_items);
    if (*bundle == NULL) {
        fclose(file);
        return -5; // Memory allocation failed
    }

    int item_count = 0;
    while (item_count < max_items && fread(*bundle + item_count, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        (*bundle)[item_count].crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        item_count++;
    }

    fclose(file);
    return item_count;
}
