#include <string.h>

#define MAX_FRAGMENTS 1024
#define FRAGMENT_SIZE 1500

typedef struct Fragment {
    uint16_t length;
    char data[FRAGMENT_SIZE];
} Fragment;

typedef struct Packet {
    size_t totalLength;
    char *payload;
} Packet;

Packet* processNetworkFragments(Fragment fragments[], int numFragments) {
    if (numFragments > MAX_FRAGMENTS) {
        return NULL; // Handle excessive number of fragments
    }

    // Calculate total payload length and allocate memory
    size_t totalLength = 0;
    for (int i = 0; i < numFragments; ++i) {
        totalLength += fragments[i].length;
    }

    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) {
        return NULL; // Handle memory allocation failure
    }
    packet->totalLength = totalLength;

    packet->payload = (char *)malloc(totalLength);
    if (!packet->payload) {
        free(packet); // Clean up on memory allocation failure
        return NULL;
    }

    // Aggregate fragments into the payload
    size_t offset = 0;
    for (int i = 0; i < numFragments; ++i) {
        memcpy(packet->payload + offset, fragments[i].data, fragments[i].length);
        offset += fragments[i].length;
    }

    return packet;
}

void freePacket(Packet *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}
