public class DatabaseExecutor {
    public static IDataReader ExecuteDynamicSqlQuery(List<object> values, string sqlCommand, SqlConnection connection) {
        if (values == null || sqlCommand == null || connection == null) {
            throw new ArgumentException("Parameters cannot be null.");
