typedef struct {
    uint32_t header;
    char *payload;
} PacketData;

int process_packets(uint8_t *buffer, size_t buffer_size, PacketData **packet_array, size_t max_alloc_size) {
    if (buffer == NULL || buffer_size == 0 || packet_array == NULL || max_alloc_size == 0) {
        return -1; // Invalid input
    }

    uint32_t total_payload_size = 0;
    size_t packet_count = 0;

    for (size_t i = 0; i < buffer_size;) {
        if ((i + sizeof(uint32_t)) > buffer_size) {
            break; // Not enough data left for payload size
        }

        uint32_t payload_size;
        memcpy(&payload_size, buffer + i, sizeof(payload_size));
        if (payload_size > UINT32_MAX - total_payload_size) {
            return -2; // Integer overflow detected
        }
        total_payload_size += payload_size;

        if ((i + sizeof(uint32_t) + payload_size) > buffer_size) {
            break; // Not enough data left for payload
        }

        if (total_payload_size > max_alloc_size) {
            return -3; // Exceeded maximum allowed size
        }

        PacketData *new_packet = (PacketData *)realloc(*packet_array, (packet_count + 1) * sizeof(PacketData));
        if (new_packet == NULL) {
            free(*packet_array);
            *packet_array = NULL;
            return -4; // Memory allocation failed
        }
        *packet_array = new_packet;

        (*packet_array)[packet_count].header = *(uint32_t *)(buffer + i);
        (*packet_array)[packet_count].payload = (char *)malloc(payload_size);
        if ((*packet_array)[packet_count].payload == NULL) {
            for (size_t j = 0; j <= packet_count; j++) {
                free((*packet_array)[j].payload);
            }
            free(*packet_array);
            *packet_array = NULL;
            return -5; // Payload memory allocation failed
        }
        memcpy((*packet_array)[packet_count].payload, buffer + i + sizeof(uint32_t), payload_size);

        packet_count++;
        i += sizeof(uint32_t) + payload_size;
    }

    return (int)packet_count; // Number of packets processed
}

// Example usage:
int main() {
    uint8_t buffer[] = { /* Your buffer data here */ };
    size_t buffer_size = sizeof(buffer);
    PacketData *packets = NULL;
    size_t max_alloc_size = 1024 * 1024; // 1MB

    int result = process_packets(buffer, buffer_size, &packets, max_alloc_size);

    if (result < 0) {
        printf("Error: %d\n", result);
    } else {
        printf("Processed %d packets.\n", result);
    }

    for (size_t i = 0; i < result; i++) {
        free(packets[i].payload);
    }
    free(packets);

    return 0;
}
