void processNetworkPackets(NetworkPacket* packets, size_t packetCount, size_t maxSessionMemory) {
    PacketData** packetArray = NULL;
    size_t allocatedMemory = 0;
    size_t currentBatchSize = 1; // Initial batch size
    size_t totalProcessed = 0;

    for (size_t i = 0; i < packetCount; ++i) {
        if (allocatedMemory + packets[i].payloadSize > maxSessionMemory) {
            // Handle memory overflow, e.g., reduce batch size or terminate processing
            break;
        }

        // Allocate memory for the current packet data
        PacketData* newPacket = malloc(sizeof(PacketData));
        if (!newPacket) {
            perror("Failed to allocate memory for packet");
            break;
        }

        // Copy packet data into the allocated memory
        newPacket->data = (uint8_t*)malloc(packets[i].payloadSize);
        if (!newPacket->data) {
            perror("Failed to allocate memory for packet payload");
            free(newPacket);
            break;
        }
        memcpy(newPacket->data, packets[i].data, packets[i].payloadSize);

        // Add the new packet to the array
        packetArray = realloc(packetArray, (totalProcessed + 1) * sizeof(PacketData*));
        if (!packetArray) {
            perror("Failed to reallocate memory for packet array");
            free(newPacket->data);
            free(newPacket);
            break;
        }
        packetArray[totalProcessed++] = newPacket;

        // Check if it's time to process the batch
        if (i + 1 >= currentBatchSize) {
            processBatch(packetArray, totalProcessed);
            totalProcessed = 0;
            // Adjust batch size based on performance metrics
            currentBatchSize = calculateNextBatchSize();
        }
    }

    // Process any remaining packets in the last batch
    if (totalProcessed > 0) {
        processBatch(packetArray, totalProcessed);
    }

    // Clean up allocated memory
    for (size_t j = 0; j < totalProcessed; ++j) {
        free(packetArray[j]->data);
        free(packetArray[j]);
    }
    free(packetArray);

    // Helper function to simulate processing a batch of packets
