using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public class NFAPI_CRC_INDICATION_PDU {
    public int RNTI { get; set; }
    // Define other properties as needed
}

public async Task ExecuteNFAPICRCIndicationPDU(List<NFAPI_CRC_INDICATION_PDU> pdus, SqlConnection connection, SqlCommand command) {
    if (pdus == null || pdus.Count == 0) {
        throw new ArgumentException("The list of NFAPI CRC Indication PDUs cannot be null or empty.");
    }

    using (SqlTransaction transaction = await connection.BeginAsync()) {
        try {
            foreach (var pdu in pdus) {
                command.Parameters.Clear();
                command.CommandText = "INSERT INTO NFAPICRCIndicationPDUs (RNTI) VALUES (@RNTI)";
                command.Parameters.AddWithValue("@RNTI", pdu.RNTI);

                await command.ExecuteNonQueryAsync(transaction);
            }

            await transaction.CommitAsync();
        } catch (Exception ex) {
            await transaction.RollbackAsync();
            throw new Exception("An error occurred while executing the SQL commands.", ex);
        }
    }
}
