typedef struct Image {
    char filename[256];
    int compressed_size;
    unsigned char *data;
} Image;

int process_image_files(const char *directory, int max_memory_kb) {
    FILE *dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    Image images[MAX_IMAGE_FILES];
    int image_count = 0;
    int total_compressed_size = 0;

    while (image_count < MAX_IMAGE_FILES) {
        struct dirent *entry = readdir(dir);
        if (!entry || entry->d_type != DT_REG) continue; // Skip non-regular files

        char filepath[1024];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory, entry->d_name);

        FILE *file = fopen(filepath, "rb");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        fseek(file, 0, SEEK_END);
        long file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (file_size > COMPRESSED_SIZE_LIMIT * 1024) {
            fprintf(stderr, "Skipping large image: %s\n", entry->d_name);
            fclose(file);
            continue;
        }

        unsigned char *data = malloc(file_size);
        if (!data) {
            perror("Failed to allocate memory for image data");
            fclose(file);
            break;
        }

        size_t bytes_read = fread(data, 1, file_size, file);
        if (bytes_read != file_size) {
            fprintf(stderr, "Error reading image: %s\n", entry->d_name);
            free(data);
            fclose(file);
            continue;
        }

        int compressed_size = compress_image_data(data, file_size); // Placeholder for compression function
        if (compressed_size < 0) {
            fprintf(stderr, "Failed to compress image: %s\n", entry->d_name);
            free(data);
            fclose(file);
            continue;
        }

        if (total_compressed_size + compressed_size > max_memory_kb * 1024) {
            fprintf(stderr, "Memory limit exceeded for image: %s\n", entry->d_name);
            free(data);
            fclose(file);
            break;
        }

        images[image_count].compressed_size = compressed_size;
        images[image_count].data = data;
        strncpy(images[image_count].filename, entry->d_name, sizeof(images[image_count].filename) - 1);
        image_count++;
        total_compressed_size += compressed_size;

        fclose(file);
    }

    closedir(dir);

    for (int i = 0; i < image_count; i++) {
        printf("Processed image: %s, Compressed size: %d bytes\n", images[i].filename, images[i].compressed_size);
        free(images[i].data); // Free allocated memory
    }

    return image_count;
}

// Placeholder function for actual compression logic
