typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t current_memory_usage;
    size_t memory_threshold;
} LinkedList;

NFAPI_CRC_INDICATION_PDU_T* createNewNode(unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) return NULL;
    newNode->next = NULL;
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return newNode;
}

void addNode(LinkedList* list, unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    if (list->current_memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->memory_threshold) {
        free(list->head);
        list->head = NULL;
        list->current_memory_usage = 0;
    }
    NFAPI_CRC_INDICATION_PDU_T* newNode = createNewNode(RX_UE_INFORMATION_TAG, RNTI);
    if (newNode != NULL) {
        newNode->next = list->head;
        list->head = newNode;
        list->current_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

void freeList(LinkedList* list) {
    while (list->head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    list->current_memory_usage = 0;
}
