DoublyLinkedList* create_list(size_t N) {
    if (N == 0 || N > UINT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL; // Handle edge case where N is zero or exceeds available system resources
    }

    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (list == NULL) {
        return NULL; // Memory allocation failed
    }

    list->head = list->tail = NULL;
    list->size = 0;
    list->capacity = N;

    return list;
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list == NULL || list->size >= list->capacity) {
        return -1; // List is full or invalid
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return -2; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
    return 0; // Node inserted successfully
