    size_t length;
} NetworkPacket;

// Function to process network packets
void process_packets(int num_packets, int* packet_sizes, int max_packet_size) {
    if (num_packets <= 0 || !packet_sizes || max_packet_size <= 0) {
        printf("Invalid input parameters.\n");
        return;
    }

    // Calculate total memory required for packet data and NFAPI structures
    size_t total_memory = 0;
    for (int i = 0; i < num_packets; i++) {
        if (packet_sizes[i] > max_packet_size) {
            printf("Packet %d exceeds maximum allowed size.\n", i);
            return;
        }
        // Add space for packet data, NFAPI structure, and metadata
        total_memory += sizeof(NetworkPacket) + sizeof(NFAPI_Packet) + packet_sizes[i];
    }

    // Check for integer overflow during memory allocation
    if (total_memory > SIZE_MAX / 2) {
        printf("Memory allocation would exceed maximum size.\n");
        return;
    }

    // Allocate memory for packets and NFAPI structures
    NetworkPacket** packets = (NetworkPacket**)malloc(num_packets * sizeof(NetworkPacket*));
    NFAPI_Packet* nfapi_packets = (NFAPI_Packet*)malloc(total_memory - num_packets * sizeof(NetworkPacket));

    if (!packets || !nfapi_packets) {
        printf("Memory allocation failed.\n");
        free(packets);
        free(nfapi_packets);
        return;
    }

    // Initialize packet pointers and NFAPI structures
    size_t offset = 0;
    for (int i = 0; i < num_packets; i++) {
        packets[i] = (NetworkPacket*)(nfapi_packets + i) + 1;
        packets[i]->data = (uint8_t*)packets[i] + sizeof(NFAPI_Packet);
        packets[i]->length = packet_sizes[i];
        nfapi_packets[i].sequence_number = i; // Example metadata
        nfapi_packets[i].timestamp = (uint32_t)time(NULL); // Example metadata
    }

    // Process each packet
    for (int i = 0; i < num_packets; i++) {
        // Example processing: calculate checksum
        uint16_t checksum = 0;
        for (size_t j = 0; j < packets[i]->length; j++) {
            checksum += packets[i]->data[j];
        }
        if (checksum != packets[i]->data[packets[i]->length - 2] + packets[i]->data[packets[i]->length - 1]) {
            printf("Checksum error in packet %d.\n", i);
            continue;
        }

        // Process the packet data here
        printf("Processing packet %d with size %zu\n", i, packets[i]->length);
    }

    // Free allocated memory
    free(packets);
    free(nfapi_packets);

    printf("Packet processing completed.\n");
}

int main() {
    int num_packets = 3;
    int packet_sizes[] = {100, 200, 300};
    int max_packet_size = 512;

    pthread_t thread;
    pthread_create(&thread, NULL, (void*)process_packets, &num_packets);
    pthread_join(thread, NULL);

    return 0;
}
