#define MAX_IMAGE_ID 1000000

typedef struct JPEG_IMAGE_T {
    int IMAGE_ID;
    int WIDTH;
    int HEIGHT;
} JPEG_IMAGE_T;

typedef struct Node {
    JPEG_IMAGE_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    size_t count;
} List;

List* createList() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        return NULL;
    }
    list->head = list->tail = NULL;
    list->count = 0;
    return list;
}

void destroyList(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

Node* createNode(const JPEG_IMAGE_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL;
    }
    node->data = *data;
    node->next = node->prev = NULL;
    return node;
}

int append(List* list, const JPEG_IMAGE_T* data) {
    if (list->count >= MAX_IMAGE_ID) {
        return -1; // Overflow check
    }
    Node* newNode = createNode(data);
    if (!newNode) {
        return -2; // Memory allocation failure
    }
    if (list->tail) {
        list->tail->next = newNode;
        newNode->prev = list->tail;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->count++;
    return 0;
}

int prepend(List* list, const JPEG_IMAGE_T* data) {
    if (list->count >= MAX_IMAGE_ID) {
        return -1; // Overflow check
    }
    Node* newNode = createNode(data);
    if (!newNode) {
        return -2; // Memory allocation failure
    }
    if (list->head) {
        list->head->prev = newNode;
        newNode->next = list->head;
    } else {
        list->tail = newNode;
    }
    list->head = newNode;
    list->count++;
    return 0;
}

void delete(List* list, int image_id) {
    Node* current = list->head;
    while (current && current->data.IMAGE_ID != image_id) {
        current = current->next;
    }
    if (current) {
        if (current->prev) {
            current->prev->next = current->next;
        } else {
            list->head = current->next;
        }
        if (current->next) {
            current->next->prev = current->prev;
        } else {
            list->tail = current->prev;
        }
        free(current);
        list->count--;
    }
}

JPEG_IMAGE_T* getImage(List* list, int image_id) {
    Node* current = list->head;
    while (current && current->data.IMAGE_ID != image_id) {
        current = current->next;
    }
    return current ? &current->data : NULL;
}
