#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 100000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initializeList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = data;
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void* offloadThread(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    while (1) {
        sleep(60); // Check every minute
        pthread_mutex_lock(&list->lock);
        while (list->size > MAX_ENTRIES) {
            Node* nodeToRemove = list->head;
            list->head = nodeToRemove->next;
            if (list->head != NULL) {
                list->head->prev = NULL;
            } else {
                list->tail = NULL;
            }
            free(nodeToRemove);
            list->size--;
        }
        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

void logCrcIndication(DoublyLinkedList* list, int N) {
    if (N <= 0 || N > MAX_ENTRIES) {
        fprintf(stderr, "Invalid value for N\n");
        return;
    }

    pthread_t offloadThreadId;
    pthread_create(&offloadThreadId, NULL, offloadThread, list);

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 1000,
            .RNTI = rand() % 65536,
            .CRC_INDICATION_REL8_TAG = rand() % 2
        };
        insertNode(list, pdu);
    }

    pthread_join(offloadThreadId, NULL);
}

int main() {
    DoublyLinkedList list;
    initializeList(&list);

    logCrcIndication(&list, 5000); // Example usage

    return 0;
}
