            fclose(fp);
            return NULL;
        }
        num_images++;
    }

    // Rewind file pointer to start reading metadata
    fseek(fp, 0, SEEK_SET);

    // Allocate memory safely using a safer alternative if available
    ImageMetadata* metadata = (ImageMetadata*)malloc(num_images * sizeof(ImageMetadata));
    if (!metadata) {
        perror("Failed to allocate memory for image metadata");
        fclose(fp);
        return NULL;
    }

    // Read and validate metadata from the configuration file
    size_t count = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%s %d %d", metadata[count].filename, &metadata[count].width, &metadata[count].height) != 3) {
            fprintf(stderr, "Invalid data format in configuration file\n");
            free(metadata);
            fclose(fp);
            return NULL;
        }
        if (metadata[count].width <= 0 || metadata[count].height <= 0) {
            fprintf(stderr, "Invalid image dimensions found in configuration file\n");
            free(metadata);
            fclose(fp);
            return NULL;
        }
        count++;
    }

    fclose(fp);
    return metadata;
}
