#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IMAGES 10000

typedef struct {
    char name[256];
    int width;
    int height;
    size_t size;
    unsigned long hash;
} ImageMetadata;

int readConfigFile(const char *filename, int *image_count) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    if (fscanf(file, "%d", image_count) != 1 || *image_count <= 0) {
        fclose(file);
        return -2;
    }

    if (*image_count > MAX_IMAGES) {
        fclose(file);
        return -3;
    }

    fclose(file);
    return 0;
}

unsigned long calculateHash(const char *data, size_t length) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < length; i++) {
        hash = ((hash << 5) + hash) + data[i];
    }
    return hash;
}

int processImages(const char *config_filename, ImageMetadata **metadata) {
    int image_count;
    if (readConfigFile(config_filename, &image_count) != 0) {
        return -1;
    }

    size_t metadata_size = image_count * sizeof(ImageMetadata);
    *metadata = malloc(metadata_size);
    if (!*metadata) return -2;

    FILE *file = fopen(config_filename, "r");
    if (!file) {
        free(*metadata);
        return -3;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < image_count; i++) {
        ImageMetadata *img = &(*metadata)[i];
        char path[512];
        if (fscanf(file, "%s", path) != 1 || strlen(path) >= sizeof(img->name)) {
            pthread_mutex_destroy(&mutex);
            fclose(file);
            free(*metadata);
            return -4;
        }

        FILE *img_file = fopen(path, "rb");
        if (!img_file) continue;

        fseek(img_file, 0, SEEK_END);
        img->size = (size_t)ftell(img_file);
        fseek(img_file, 0, SEEK_SET);

        if (img->size > 0) {
            char *data = malloc(img->size);
            if (data) {
                fread(data, 1, img->size, img_file);
                pthread_mutex_lock(&mutex);
                strncpy(img->name, path, sizeof(img->name));
                fclose(img_file);
                img->hash = calculateHash(data, img->size);
                free(data);
                pthread_mutex_unlock(&mutex);
            } else {
                fclose(img_file);
            }
        } else {
            fclose(img_file);
        }
    }

    pthread_mutex_destroy(&mutex);
    fclose(file);
    return 0;
}
