// Function to safely allocate memory
void* safe_malloc(size_t size, const char* function_name) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed in %s\n", function_name);
        exit(1);
    }
    return ptr;
}

// Function to process image files
void process_image_files(int num_images) {
    ImageMetadata *metadata = safe_malloc(num_images * sizeof(ImageMetadata), __FUNCTION__);

    // Simulate reading metadata from a distributed configuration service
    for (int i = 0; i < num_images; i++) {
        strcpy(metadata[i].filename, "image_");
        sprintf((char*)&metadata[i].width, "%d", rand() % 1000);
        sprintf((char*)&metadata[i].height, "%d", rand() % 1000);
    }

    // Validate and update cache in a background worker thread
    pthread_t cache_thread;
    if (pthread_create(&cache_thread, NULL, update_cache, metadata) != 0) {
        fprintf(stderr, "Failed to create cache thread\n");
        exit(1);
    }

    pthread_join(cache_thread, NULL);

    // Free allocated memory
    free(metadata);
}

