    ImageMetadata *metadata = (ImageMetadata *)arg;

    for (int i = 0; i < num_images; i++) {
        if (!is_valid_metadata(&metadata[i])) {
            fprintf(stderr, "Invalid metadata detected\n");
        }
        // Simulate updating cache
        sleep(1);
    }

    return NULL;
}

