#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_BANDWIDTH 1000 // Maximum bandwidth in kilobytes
#define MIN_BANDWIDTH 500  // Minimum bandwidth in kilobytes

typedef struct NetworkPacket {
    int id;
    int sub_packet_count;
    int total_size_kb;
} NetworkPacket;

typedef struct ListNode {
    NetworkPacket *packet;
    struct ListNode *next;
} ListNode;

ListNode* head = NULL;
int current_bandwidth = 500; // Initial bandwidth in kilobytes
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
clock_t start_time, end_time;
double total_processing_time = 0.0;
long long total_packets_processed = 0;

void* process_packet(void* packet) {
    NetworkPacket *new_packet = (NetworkPacket*)packet;
    pthread_mutex_lock(&lock);

    // Check bandwidth limit
    if (current_bandwidth + new_packet->total_size_kb > MAX_BANDWIDTH) {
        printf("Bandwidth limit exceeded. Processing paused.\n");
        while (current_bandwidth + new_packet->total_size_kb > current_bandwidth) {
            // Wait for bandwidth to be freed
        }
    }

    // Adjust bandwidth if necessary
    if (current_bandwidth < MIN_BANDWIDTH) {
        current_bandwidth = MIN_BANDWIDTH;
    } else if (current_bandwidth > MAX_BANDWIDTH) {
        current_bandwidth = MAX_BANDWIDTH;
    }

    // Insert packet into the list based on priority and size
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    new_node->packet = new_packet;
    new_node->next = NULL;

    if (!head || (new_packet->total_size_kb < head->packet->total_size_kb && new_packet->id > head->packet->id)) {
        new_node->next = head;
        head = new_node;
    } else {
        ListNode* current = head;
        while (current->next != NULL && ((current->next->packet->total_size_kb < new_packet->total_size_kb) || (current->next->packet->id > new_packet->id))) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    // Update bandwidth and performance metrics
    current_bandwidth += new_packet->total_size_kb;
    end_time = clock();
    total_processing_time += (double)(end_time - start_time) / CLOCKS_PER_SEC;
    total_packets_processed++;

    pthread_mutex_unlock(&lock);
    return NULL;
}

void* monitor_performance(void* arg) {
    while (1) {
        sleep(10); // Monitor every 10 seconds
        printf("Average processing time: %f\n", total_processing_time / total_packets_processed);
        printf("Total packets processed: %lld\n", total_packets_processed);
    }
    return NULL;
}

void* memory_leak_detection(void* arg) {
    while (1) {
        sleep(60); // Check every 60 seconds
        // Implement memory leak detection logic here
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread, leak_thread;

    pthread_create(&monitor_thread, NULL, monitor_performance, NULL);
    pthread_create(&leak_thread, NULL, memory_leak_detection, NULL);

    // Simulate processing packets
    for (int i = 0; i < 1000000; i++) {
        NetworkPacket *new_packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
        new_packet->id = i;
        new_packet->sub_packet_count = rand() % 10 + 1;
        new_packet->total_size_kb = rand() % 100 + 1;

        pthread_create(&threads[i], NULL, process_packet, (void*)new_packet);
    }

    for (int i = 0; i < 1000000; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_join(monitor_thread, NULL);
    pthread_join(leak_thread, NULL);

    return 0;
}
