#define MAX_LIST_SIZE 1000

struct RX_UE_INFORMATION_TAG {
    int someData;
};

struct RNTI {
    int id;
};

struct CRC_INDICATION_REL8_TAG {
    bool CRCFLAG;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

class NFAPIListPopulator {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> apiList;
    time_t lastCallTime;

public:
    NFAPIListPopulator() : lastCallTime(std::time(nullptr)) {}

    void populateNFAPIListWithRandomCRCIndications() {
        auto now = std::time(nullptr);
        if (now - lastCallTime < 9) {
            std::cout << "Cooldown period not yet completed. Please try again later." << std::endl;
            return;
        }

        lastCallTime = now;

        apiList.clear();
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, MAX_LIST_SIZE - 1);

        int listSize = dis(gen);
        apiList.resize(listSize);

        for (int i = 0; i < listSize; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rx_ue_info_tag.someData = dis(gen); // Populate with random data
            pdu.rnti.id = dis(gen);
            pdu.crc_indication_rel8_tag.CRCFLAG = (dis(gen) % 2 == 0); // Randomly set CRCFLAG

            apiList.push_back(pdu);
        }
    }

    void printAPIList() {
        for (const auto& pdu : apiList) {
            std::cout << "RX_UE_INFORMATION_TAG: someData = " << pdu.rx_ue_info_tag.someData
                      << ", RNTI: id = " << pdu.rnti.id
                      << ", CRC_INDICATION_REL8_TAG: CRCFLAG = " << (pdu.crc_indication_rel8_tag.CRCFLAG ? "true" : "false")
                      << std::endl;
        }
    }
};

int main() {
    NFAPIListPopulator populator;
    populator.populateNFAPIListWithRandomCRCIndications();
    populator.printAPIList();
    return 0;
}
