#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define MAX_BUFFER_POOL_SIZE 10

typedef struct {
    char header[MAX_PACKET_SIZE];
    size_t payload_size;
} Packet;

typedef struct {
    char buffer[MAX_BUFFER_POOL_SIZE][MAX_PACKET_SIZE];
    size_t used_buffers;
    pthread_mutex_t lock;
} BufferPool;

void initialize_buffer_pool(BufferPool *pool) {
    pool->used_buffers = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

int process_packet(BufferPool *pool, Packet *packet) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_buffers >= MAX_BUFFER_POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Buffer pool is full
    }

    size_t total_size = packet->payload_size + sizeof(packet->header);
    if (total_size > MAX_PACKET_SIZE * MAX_BUFFER_POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return -2; // Exceeded system-wide limit
    }

    int buffer_index = pool->used_buffers;
    pool->used_buffers++;
    pthread_mutex_unlock(&pool->lock);

    memcpy(pool->buffer[buffer_index], packet->header, sizeof(packet->header));
    if (packet->payload_size > 0) {
        memcpy(pool->buffer[buffer_index] + sizeof(packet->header), packet->payload, packet->payload_size);
    }

    return buffer_index;
}

void *handle_packets(void *arg) {
    BufferPool *pool = (BufferPool *)arg;

    // Simulate processing packets
    for (int i = 0; i < 10; i++) {
        Packet packet;
        // Populate packet with data

        int result = process_packet(pool, &packet);
        if (result == -1) {
            printf("Buffer pool is full\n");
        } else if (result == -2) {
            printf("Exceeded system-wide limit\n");
        }
    }

    return NULL;
}

int main() {
    BufferPool pool;
    initialize_buffer_pool(&pool);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, handle_packets, &pool);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
