#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint32_t length;
    void* payload;
} Packet;

int process_packets(Packet** packets, size_t packet_count, char** combined_data) {
    if (packet_count == 0) {
        *combined_data = NULL;
        return 0;
    }

    // Calculate the total data size
    uint64_t total_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        if (packets[i]->length > UINT32_MAX - total_size) {
            *combined_data = NULL;
            return -1; // Integer overflow detected
        }
        total_size += packets[i]->length;
    }

    // Allocate buffer for combined data
    char* buffer = (char*)malloc(total_size);
    if (!buffer) {
        *combined_data = NULL;
        return -2; // Memory allocation failed
    }

    // Combine packets into the buffer
    char* write_ptr = buffer;
    for (size_t i = 0; i < packet_count; ++i) {
        memcpy(write_ptr, packets[i]->payload, packets[i]->length);
        write_ptr += packets[i]->length;
    }

    *combined_data = buffer;
    return total_size;
}
