#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define INITIAL_BUFFER_SIZE 4096

typedef struct Packet {
    int length;
    char data[MAX_PACKET_SIZE];
} Packet;

typedef struct {
    char *buffer;
    size_t buffer_size;
    size_t total_data_size;
    pthread_mutex_t lock;
} PacketBuffer;

PacketBuffer *create_packet_buffer() {
    PacketBuffer *pb = (PacketBuffer *)malloc(sizeof(PacketBuffer));
    if (!pb) return NULL;

    pb->buffer = (char *)malloc(INITIAL_BUFFER_SIZE);
    if (!pb->buffer) {
        free(pb);
        return NULL;
    }

    pb->buffer_size = INITIAL_BUFFER_SIZE;
    pb->total_data_size = 0;
    pthread_mutex_init(&pb->lock, NULL);

    return pb;
}

void destroy_packet_buffer(PacketBuffer *pb) {
    if (pb->buffer) free(pb->buffer);
    pthread_mutex_destroy(&pb->lock);
    free(pb);
}

int add_packet_to_buffer(PacketBuffer *pb, Packet packet) {
    pthread_mutex_lock(&pb->lock);

    // Check for potential overflow
    if ((size_t)packet.length > SIZE_MAX - pb->total_data_size) {
        pthread_mutex_unlock(&pb->lock);
        return -1; // Overflow detected
    }

    // Resize buffer if necessary
    while (pb->buffer_size <= pb->total_data_size + packet.length) {
        size_t new_size = pb->buffer_size * 2;
        char *new_buffer = realloc(pb->buffer, new_size);
        if (!new_buffer) {
            pthread_mutex_unlock(&pb->lock);
            return -1; // Memory allocation failed
        }
        pb->buffer = new_buffer;
        pb->buffer_size = new_size;
    }

    // Add packet to buffer and update total data size
    memcpy(pb->buffer + pb->total_data_size, packet.data, packet.length);
    pb->total_data_size += packet.length;

    pthread_mutex_unlock(&pb->lock);
    return 0; // Success
}

size_t get_total_data_size(PacketBuffer *pb) {
    return pb->total_data_size;
}
```

This code provides a basic implementation of a thread-safe packet buffer for processing network packets. It includes functions to create and destroy the buffer, add packets to the buffer, and retrieve the total data size. The buffer dynamically resizes itself when necessary to accommodate incoming packets while preventing integer overflows.

To ensure the function is memory efficient and can handle varying packet sizes efficiently, this implementation uses a thread-safe mechanism with mutex locks for concurrent access control. This helps prevent race conditions and data corruption that could occur if multiple threads tried to modify the buffer simultaneously.

The code demonstrates how to manage a dynamic buffer for storing packet data and handle potential overflow errors gracefully. It also includes mechanisms to resize the buffer when necessary, ensuring it can accommodate packets of varying sizes without causing memory allocation failures or data loss.

Please note that this implementation is simplified for demonstration purposes and does not include advanced error handling or sophisticated reassembly logic for out-of-order packets. For a production environment, additional features such as packet sequencing and error recovery mechanisms would be required to fully meet the task requirements while maintaining performance and reliability.']

