#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    size_t total_size;
    size_t max_size_in_bytes;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_linked_list(size_t max_size_in_bytes) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        return NULL;
    }
    list->head = NULL;
    list->total_size = 0;
    list->max_size_in_bytes = max_size_in_bytes;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    struct Node* current = list->head;
    while (current != NULL) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->total_size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool add_to_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (list->total_size + struct_size > list->max_size_in_bytes) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    struct Node* new_node = (struct Node*)malloc(struct_size);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    new_node->data.RX_UE_INFORMATION_TAG = rand() % 256;
    new_node->data.RNTI = rand() % 0xFFFF;
    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256;
    new_node->data.CRCFLAG = (rand() % 2) ? true : false;
    new_node->next = list->head;
    list->head = new_node;
    list->total_size += struct_size;
