} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t total_size;
    size_t max_size_in_bytes;
    pthread_mutex_t mutex;
} LinkedList;

void init_linkedList(LinkedList* list, size_t max_size) {
    list->head = NULL;
    list->total_size = 0;
    list->max_size_in_bytes = max_size;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (list->total_size + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->max_size_in_bytes) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Exceeds max size
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void remove_from_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            (*current)->data.RNTI == data.RNTI &&
            (*current)->data.CRC_INDICATION_REL8_TAG == data.CRC_INDICATION_REL8_TAG) {
            Node* temp = *current;
            *current = (*current)->next;
            list->total_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            free(temp);
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void destroy_linkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->total_size = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int check_list_integrity(LinkedList* list) {
