    ImageMetadata *metadata_array;
    size_t allocated_size;
    size_t used_size;
    size_t max_size_in_bytes;
    pthread_mutex_t mutex;
} ImageMetadataManager;

ImageMetadataManager* create_manager(size_t max_size_in_bytes) {
    ImageMetadataManager *manager = (ImageMetadataManager*)malloc(sizeof(ImageMetadataManager));
    manager->metadata_array = (ImageMetadata*)malloc(max_size_in_bytes);
    if (!manager || !manager->metadata_array) {
        free(manager);
        return NULL;
    }
    manager->allocated_size = max_size_in_bytes;
    manager->used_size = 0;
    manager->max_size_in_bytes = max_size_in_bytes;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_manager(ImageMetadataManager *manager) {
    free(manager->metadata_array);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_metadata(ImageMetadataManager *manager, const char *file_path, int width, int height) {
    pthread_mutex_lock(&manager->mutex);

    if (width <= 0 || height <= 0 || manager->used_size + sizeof(ImageMetadata) > manager->max_size_in_bytes) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    ImageMetadata *metadata = (ImageMetadata*)(manager->metadata_array + manager->used_size / sizeof(ImageMetadata));
    strncpy(metadata->file_path, file_path, MAX_IMAGE_METADATA_SIZE - 1);
    metadata->width = width;
    metadata->height = height;

    manager->used_size += sizeof(ImageMetadata);

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

