    if (manager == NULL) {
        return -1; // Memory allocation failed
    }

    if (add_metadata(manager, "path/to/image.jpg", 800, 600) != 0) {
        destroy_manager(manager);
        return -1; // Adding metadata failed
    }

    // Continue adding more metadata or perform other operations

    destroy_manager(manager);
    return 0;
}
