#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_N 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_nfaapi_crc_list() {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_nfaapi_crc_list(NFAPI_CRC_LIST_T* list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int read_config_file(const char* filename, int* n) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;
    fscanf(file, "%d", n);
    fclose(file);
    return 0;
}

void populate_nfaapi_crc_list(NFAPI_CRC_LIST_T* list, int n) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) break;
        new_node->RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->RNTI = rand() % 1024;
        new_node->CRCFLAG = rand() % 2;
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void* test_populate_nfaapi_crc_list(void* arg) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)arg;
    int n = rand() % MAX_N + 1;
    populate_nfaapi_crc_list(list, n);
    return NULL;
}

int main() {
    int n;
    if (read_config_file("config.txt", &n) != 0) {
        fprintf(stderr, "Failed to read configuration file\n");
        return 1;
    }

    NFAPI_CRC_LIST_T* list = create_nfaapi_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for CRC list\n");
        return 1;
    }

    pthread_t threads[MAX_N];
    for (int i = 0; i < MAX_N; i++) {
        pthread_create(&threads[i], NULL, test_populate_nfaapi_crc_list, list);
    }
    for (int i = 0; i < MAX_N; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_nfaapi_crc_list(list);

    return 0;
}
```

