#define MAX_STRUCT_SIZE 1024
#define MIN_CRCFLAG 0
#define MAX_CRCFLAG 1

typedef struct {
    uint8_t payload[MAX_STRUCT_SIZE];
} NFAPICRCIndicationPDU_T;

int generateStructures(const char* inputFile, const char* outputFile, int numStructs, int maxPayloadSize) {
    FILE *input = fopen(inputFile, "rb");
    if (!input) {
        perror("Failed to open input file");
        return -1;
    }

    NFAPICRCIndicationPDU_T *structs = (NFAPICRCIndicationPDU_T*)malloc(numStructs * sizeof(NFAPICRCIndicationPDU_T));
    if (!structs) {
        perror("Failed to allocate memory for structures");
        fclose(input);
        return -1;
    }

    // Assuming the binary file contains RX_UE_INFORMATION_TAG, RNTI, and payload data
    uint8_t tagBuffer[MAX_STRUCT_SIZE];
    uint16_t rnti;
    size_t bytesRead;

    for (int i = 0; i < numStructs; ++i) {
        // Read RX_UE_INFORMATION_TAG
        bytesRead = fread(tagBuffer, sizeof(uint8_t), sizeof(RX_UE_INFORMATION_TAG), input);
        if (bytesRead != sizeof(RX_UE_INFORMATION_TAG)) {
            perror("Failed to read RX_UE_INFORMATION_TAG");
            free(structs);
            fclose(input);
            return -1;
        }
        memcpy(&structs[i].payload, tagBuffer, bytesRead);

        // Read RNTI
        fread(&rnti, sizeof(uint16_t), 1, input);
        if (ferror(input)) {
            perror("Failed to read RNTI");
            free(structs);
            fclose(input);
            return -1;
        }
        memcpy(&structs[i].payload[sizeof(RX_UE_INFORMATION_TAG)], &rnti, sizeof(rnti));

        // Generate random CRCFLAG
        uint8_t crcflag = (rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1)) + MIN_CRCFLAG;

        // Fill payload with zeros or other data as per transformation rules
        memset(&structs[i].payload[sizeof(RX_UE_INFORMATION_TAG) + sizeof(rnti)], 0, maxPayloadSize - (sizeof(RX_UE_INFORMATION_TAG) + sizeof(rnti)));

        // Append CRCFLAG at the end of payload
        structs[i].payload[maxPayloadSize - 1] = crcflag;
    }

    fclose(input);

    FILE *output = fopen(outputFile, "wb");
    if (!output) {
        perror("Failed to open output file");
        free(structs);
        return -1;
    }

    for (int i = 0; i < numStructs; ++i) {
        fwrite(&structs[i].payload, sizeof(uint8_t), maxPayloadSize, output);
    }

    fclose(output);
    free(structs);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules> <num_structs> <max_payload_size>\n", argv[0]);
        return -1;
    }

    int numStructs = atoi(argv[4]);
    int maxPayloadSize = atoi(argv[5]);

    if (numStructs <= 0 || maxPayloadSize <= 0) {
        fprintf(stderr, "Invalid number of structures or payload size\n");
        return -1;
    }

    return generateStructures(argv[1], argv[2], numStructs, maxPayloadSize);
}
