#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_IMAGE_SIZE 1024 * 1024 // Maximum size of an image frame

typedef struct {
    int width;
    int height;
    time_t timestamp;
    char pixels[MAX_IMAGE_SIZE];
} image_t;

typedef struct {
    image_t *images;
    int front;
    int rear;
    int count;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ring_buffer_t;

void init_ring_buffer(ring_buffer_t *rb, int n) {
    rb->images = (image_t *)malloc(n * sizeof(image_t));
    rb->front = 0;
    rb->rear = -1;
    rb->count = 0;
    rb->capacity = n;
    pthread_mutex_init(&rb->mutex, NULL);
    pthread_cond_init(&rb->not_full, NULL);
    pthread_cond_init(&rb->not_empty, NULL);
}

void destroy_ring_buffer(ring_buffer_t *rb) {
    free(rb->images);
    pthread_mutex_destroy(&rb->mutex);
    pthread_cond_destroy(&rb->not_full);
    pthread_cond_destroy(&rb->not_empty);
}

void enqueue_image(ring_buffer_t *rb, image_t *img) {
    pthread_mutex_lock(&rb->mutex);
    while (rb->count == rb->capacity) {
        pthread_cond_wait(&rb->not_full, &rb->mutex);
    }
    rb->rear = (rb->rear + 1) % rb->capacity;
    rb->images[rb->rear] = *img;
    rb->count++;
    pthread_cond_signal(&rb->not_empty);
    pthread_mutex_unlock(&rb->mutex);
}

image_t dequeue_image(ring_buffer_t *rb) {
    image_t img;
    pthread_mutex_lock(&rb->mutex);
    while (rb->count == 0) {
        pthread_cond_wait(&rb->not_empty, &rb->mutex);
    }
    img = rb->images[rb->front];
    rb->front = (rb->front + 1) % rb->capacity;
    rb->count--;
    pthread_cond_signal(&rb->not_full);
    pthread_mutex_unlock(&rb->mutex);
    return img;
}

