#define MAX_PACKET_LENGTH 1500
#define DEFAULT_MEMORY_LIMIT (10 * 1024 * 1024) // 10 MB

typedef struct {
    int protocol_version;
    size_t packet_length;
    uint32_t sequence_number;
} NetworkPacketHeader;

int addPacketHeader(NetworkPacketHeader **headers, size_t *num_headers, size_t *allocated_headers, size_t max_memory_limit, const NetworkPacketHeader *new_header) {
    if (new_header->packet_length > MAX_PACKET_LENGTH) {
        fprintf(stderr, "Error: Packet length exceeds maximum allowed value.\n");
        return -1;
    }

    // Calculate the new memory required
    size_t new_memory = (*num_headers + 1) * sizeof(NetworkPacketHeader);
    if (new_memory < *allocated_headers) {
        // Handle potential overflow
        fprintf(stderr, "Error: Integer overflow detected.\n");
        return -1;
    }

    // Check if the new memory allocation will exceed the limit
    if (new_memory > max_memory_limit) {
        fprintf(stderr, "Error: Memory limit exceeded.\n");
        return -1;
    }

    // Resize the array if necessary
    if (*num_headers == *allocated_headers) {
        size_t old_allocated = *allocated_headers;
        *allocated_headers *= 2;
        NetworkPacketHeader *new_headers = realloc(*headers, *allocated_headers * sizeof(NetworkPacketHeader));
        if (new_headers == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            return -1;
        }
        *headers = new_headers;

        // Initialize the new elements
        for (size_t i = old_allocated; i < *allocated_headers; i++) {
            memset(&(*headers)[i], 0, sizeof(NetworkPacketHeader));
        }
    }

    // Add the new packet header
    (*headers)[*num_headers++] = *new_header;
    return 0;
}

int processNetworkPackets(NetworkPacketHeader **headers, size_t *num_headers, size_t *allocated_headers, size_t max_memory_limit, const NetworkPacketHeader *packet_data, size_t num_packets) {
    for (size_t i = 0; i < num_packets; i++) {
        if (addPacketHeader(headers, num_headers, allocated_headers, max_memory_limit, &packet_data[i]) != 0) {
            return -1;
        }
    }
    return 0;
}

int main() {
    NetworkPacketHeader packet_headers[100];
    size_t num_headers = 0;
    size_t allocated_headers = 0;
    size_t max_memory_limit = DEFAULT_MEMORY_LIMIT;

    // Simulate receiving packet headers
    NetworkPacketHeader new_header = {4, 1500, 1};
    if (processNetworkPackets(&packet_headers, &num_headers, &allocated_headers, max_memory_limit, &new_header, 1) != 0) {
        fprintf(stderr, "Error processing packets.\n");
        return -1;
    }

    printf("Packet headers processed successfully.\n");
    return 0;
}
