    int head;
    int tail;
    int count;
} FixedSizeAllocator;

FixedSizeAllocator* createAllocator() {
    FixedSizeAllocator *allocator = (FixedSizeAllocator*)malloc(sizeof(FixedSizeAllocator));
    allocator->head = 0;
    allocator->tail = 0;
    allocator->count = 0;
    return allocator;
}

void destroyAllocator(FixedSizeAllocator *allocator) {
    free(allocator);
}

int allocateStruct(FixedSizeAllocator *allocator, NFAPI_CRC_INDICATION_PDU_T **pStruct) {
    if (allocator->count == MAX_STRUCTURES) {
        fprintf(stderr, "Allocator is full\n");
        return -1;
    }
    int index = allocator->tail;
    allocator->tail = (allocator->tail + 1) % MAX_STRUCTURES;
    allocator->count++;
    *pStruct = &allocator->data[index];
    return 0;
}

void deallocateStruct(FixedSizeAllocator *allocator, NFAPI_CRC_INDICATION_PDU_T *pStruct) {
    int index = pStruct - allocator->data;
    if (index == allocator->tail) {
        fprintf(stderr, "Attempt to deallocate non-allocated memory\n");
        return;
    }
    if (index >= MAX_STRUCTURES || index < 0) {
        fprintf(stderr, "Invalid pointer\n");
        return;
    }
    allocator->count--;
}

