        pStruct->RX_UE_INFORMATION_TAG = rand() % 1000;
        pStruct->RNTI = rand() % 1000;
        pStruct->CRCFLAG = rand() & 1;
    }
    return structs;
}

void freeStructs(NFAPI_CRC_INDICATION_PDU_T *structs, int n, FixedSizeAllocator *allocator) {
    for (int i = 0; i < n; i++) {
        deallocateStruct(allocator, &structs[i]);
