typedef struct {
    int protocol_version;
    int packet_length;
    int sequence_number;
} NetworkPacketHeader;

int process_packets(const char* stream, size_t max_memory) {
    NetworkPacketHeader* headers = (NetworkPacketHeader*)malloc(max_memory * sizeof(NetworkPacketHeader));
    if (!headers) {
        perror("Failed to allocate memory");
        return -1;
    }

    time_t start_time = time(NULL);
    int packet_count = 0;

    while ((stream[0] != '\0') && (packet_count < MAX_PACKETS)) {
        NetworkPacketHeader header;
        if (sscanf(stream, "%d %d %d", &header.protocol_version, &header.packet_length, &header.sequence_number) != 3) {
            fprintf(stderr, "Invalid packet format\n");
            free(headers);
            return -1;
        }

        if (header.packet_length > MAX_LENGTH) {
            fprintf(stderr, "Packet length exceeds maximum allowed\n");
            free(headers);
            return -1;
        }

        headers[packet_count++] = header;

        // Simulate processing time
        usleep(1000); // 1 millisecond

        stream += strlen(stream) + 1; // Move to next packet in the stream
    }

    double elapsed_time = difftime(time(NULL), start_time);
    if (elapsed_time > 5.0) {
        fprintf(stderr, "Processing took longer than expected\n");
        free(headers);
        return -1;
    }

    double memory_used = packet_count * sizeof(NetworkPacketHeader);
    double memory_limit = max_memory / 100.0 * MEMORY_LIMIT;

    if (memory_used > memory_limit) {
        fprintf(stderr, "Memory usage exceeds limit\n");
        free(headers);
        return -1;
    }

    printf("Processed %d packets successfully\n", packet_count);
    free(headers);
    return 0;
}
