#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_LENGTH 1500
#define DEFAULT_MEMORY_LIMIT (1024 * 1024) // 1 MB

typedef struct {
    uint8_t protocol_version;
    uint32_t packet_length;
    uint64_t sequence_number;
} NetworkPacketHeader;

typedef struct {
    NetworkPacketHeader* headers;
    size_t allocated_count;
    size_t used_count;
    size_t memory_limit;
    pthread_mutex_t lock;
} PacketManager;

PacketManager* create_packet_manager(size_t initial_size, size_t memory_limit) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->headers = (NetworkPacketHeader*)calloc(initial_size, sizeof(NetworkPacketHeader));
    if (!manager->headers) {
        free(manager);
        return NULL;
    }

    manager->allocated_count = initial_size;
    manager->used_count = 0;
    manager->memory_limit = memory_limit;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_packet_manager(PacketManager* manager) {
    if (!manager) return;

    free(manager->headers);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_packet_header(PacketManager* manager, NetworkPacketHeader header) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used_count >= manager->allocated_count) {
        size_t new_size = manager->allocated_count * 2;
        if ((new_size / 2) != manager->allocated_count || new_size > manager->memory_limit / sizeof(NetworkPacketHeader)) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Integer overflow or memory limit exceeded
        }

        NetworkPacketHeader* new_headers = (NetworkPacketHeader*)realloc(manager->headers, new_size * sizeof(NetworkPacketHeader));
        if (!new_headers) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Memory allocation failed
        }
        manager->headers = new_headers;
        manager->allocated_count = new_size;
    }

    manager->headers[manager->used_count++] = header;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

size_t get_allocated_memory(PacketManager* manager) {
    return manager->allocated_count * sizeof(NetworkPacketHeader);
}

void set_max_memory_limit(PacketManager* manager, size_t new_limit) {
    pthread_mutex_lock(&manager->lock);

    if (new_limit < manager->used_count * sizeof(NetworkPacketHeader)) {
        pthread_mutex_unlock(&manager->lock);
        return; // New limit is smaller than current memory usage
    }

    manager->memory_limit = new_limit;

    pthread_mutex_unlock(&manager->lock);
}

size_t get_max_memory_limit(PacketManager* manager) {
    pthread_mutex_lock(&manager->lock);

    size_t limit = manager->memory_limit;

    pthread_mutex_unlock(&manager->lock);
    return limit;
}
