typedef struct Packet {
    uint16_t header_size;
    uint32_t payload_size;
} Packet;

typedef struct BufferManager {
    uint8_t *buffer;
    size_t buffer_size;
    size_t used_space;
    Packet *packet_list;
    size_t packet_count;
    size_t max_packets;
} BufferManager;

BufferManager* create_buffer_manager(size_t initial_buffer_size, size_t max_packets) {
    BufferManager *manager = (BufferManager*)malloc(sizeof(BufferManager));
    manager->buffer = (uint8_t*)malloc(initial_buffer_size);
    manager->buffer_size = initial_buffer_size;
    manager->used_space = 0;
    manager->packet_list = (Packet*)malloc(max_packets * sizeof(Packet));
    manager->packet_count = 0;
    manager->max_packets = max_packets;
    return manager;
}

void destroy_buffer_manager(BufferManager *manager) {
    free(manager->buffer);
    free(manager->packet_list);
    free(manager);
}

int add_packet(BufferManager *manager, Packet *packet) {
    if (manager->used_space + packet->header_size + packet->payload_size > manager->buffer_size) {
        return -1; // Not enough space
    }

    uint8_t *ptr = manager->buffer + manager->used_space;
    memcpy(ptr, &packet->header_size, sizeof(uint16_t));
    ptr += sizeof(uint16_t);
    memcpy(ptr, packet->payload, packet->payload_size);
    ptr += packet->payload_size;

    manager->packet_list[manager->packet_count] = *packet;
    manager->used_space += packet->header_size + packet->payload_size;
    manager->packet_count++;

    return 0; // Success
}

