    if (file == NULL) {
        perror("Failed to open file for reading");
        return 0;
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = (size_t)ftell(file);
    fclose(file);

    // Allocate memory for ImageMetaData structure and image data
