    if (metaData == NULL) {
        perror("Failed to allocate memory for ImageMetaData");
        return 0;
    }

    void* imageData = malloc(fileSize);
    if (imageData == NULL) {
        perror("Failed to allocate memory for image data");
        free(metaData);
        return 0;
    }

    metaData->dataSize = fileSize;
    metaData->data = imageData;

    // Return the total memory required
    size_t totalMemory = sizeof(ImageMetaData) + fileSize;
    return totalMemory;
}

