        return -1; // Integer overflow or no space needed
    }

    if (new_used_space > manager->total_allocated) {
        size_t new_alloc = manager->total_allocated * 2;
        if (new_alloc < new_used_space) new_alloc = new_used_space;

        char* new_buffer = realloc(manager->buffer, new_alloc);
        if (!new_buffer) return -2; // Realloc failed

        manager->buffer = new_buffer;
        manager->total_allocated = new_alloc;
    }

    memcpy(&manager->buffer[manager->used_space], &packet->payload_size, sizeof(size_t));
    memcpy(&manager->buffer[manager->used_space + sizeof(size_t)], packet->payload, packet->payload_size);
    manager->used_space = new_used_space;

    return 0; // Success
}

int main() {
    BufferManager* buffer_manager = init_buffer_manager();
    if (!buffer_manager) {
        printf("Failed to initialize buffer manager\n");
        return 1;
    }

    Packet packet = {5, "hello"};
    if (add_packet_to_buffer(buffer_manager, &packet) != 0) {
        printf("Failed to add packet to buffer\n");
        free_buffer_manager(buffer_manager);
        return 1;
    }

    // Process the buffer as needed

    free_buffer_manager(buffer_manager);
    return 0;
}
