        image_metadata = (ImageMetaData*)realloc(image_metadata, (total_images + 1) * sizeof(ImageMetaData));
        if (!image_metadata) {
            perror("Failed to allocate memory for image metadata array");
            free(meta_data->data);
            free(meta_data);
            continue;
        }

        memcpy(&image_metadata[total_images], meta_data, sizeof(ImageMetaData));
        total_images++;
