#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY 2 * 1024 * 1024 // 2 MB
#define SLAB_SIZE 512 * 1024 // 512 KB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct Slab {
    void* memory;
    size_t size;
    size_t used;
    struct Slab* next;
} Slab;

typedef struct List {
    Node* head;
    Node* tail;
    Slab* slab_head;
    pthread_mutex_t lock;
    size_t total_memory_used;
} List;

void initialize_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->slab_head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->total_memory_used = 0;
}

Node* allocate_node(List* list) {
    if (list->total_memory_used + SLAB_SIZE > MAX_MEMORY) {
        return NULL; // Memory limit reached
    }

    if (!list->slab_head || list->slab_head->used >= SLAB_SIZE) {
        Slab* new_slab = (Slab*)malloc(sizeof(Slab));
        if (!new_slab) return NULL;

        new_slab->memory = malloc(SLAB_SIZE);
        if (!new_slab->memory) {
            free(new_slab);
            return NULL;
        }

        new_slab->size = SLAB_SIZE;
        new_slab->used = 0;
        new_slab->next = list->slab_head;
        list->slab_head = new_slab;
    }

    Node* node = (Node*)(list->slab_head->memory + list->slab_head->used);
    list->slab_head->used += sizeof(Node);

    pthread_mutex_lock(&list->lock);
    list->total_memory_used += sizeof(Node);
    pthread_mutex_unlock(&list->lock);

    return node;
}

void free_node(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    list->total_memory_used -= sizeof(Node);
    pthread_mutex_unlock(&list->lock);
}

int insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = allocate_node(list);
    if (!new_node) return -1;

    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) list->tail->next = new_node;
    list->tail = new_node;
    if (!list->head) list->head = new_node;

    return 0;
}

int delete_node(List* list, Node* node) {
    if (!node) return -1;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (list->tail == node) list->tail = node->prev;
    if (list->head == node) list->head = node->next;

    free_node(list, node);

    return 0;
}

void iterate_list(List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);
    for (Node* current = list->head; current != NULL; current = current->next) {
        callback(current->data);
    }
    pthread_mutex_unlock(&list->lock);
}

// Stress test and other utilities would be implemented separately
```

This code provides a basic structure for managing a doubly-linked list of `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe operations. It includes functions for initializing the list, allocating and freeing nodes using a slab allocator within specified memory limits, inserting and deleting nodes, and iterating over the list. The actual concurrency control mechanisms, stress test implementation, and other utilities are not included here and would need to be added based on specific requirements and testing scenarios.']

