    pthread_mutex_t mutex;
} DoublyLinkedList;

void custom_malloc(void** ptr, size_t size) {
    *ptr = malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

DoublyLinkedList* create_linked_list(int N) {
    DoublyLinkedList* list = (DoublyLinkedList*)custom_malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);

    for (int i = 0; i < N; i++) {
        Node* newNode = (Node*)custom_malloc(sizeof(Node));
        newNode->data.RX_UE_INFORMATION_TAG = rand();
        newNode->data.RNTI = rand() % 65536;
        newNode->data.CRCFLAG = rand() % 2;
        newNode->prev = list->tail;
        newNode->next = NULL;

        if (list->head == NULL) {
            list->head = newNode;
        } else {
            list->tail->next = newNode;
        }
        list->tail = newNode;
    }

    return list;
}

void print_linked_list(DoublyLinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }
}

void free_linked_list(DoublyLinkedList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        custom_free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    custom_free(list);
}
```

This code provides a basic implementation of a doubly-linked list with custom memory allocation and synchronization. It includes functions to create, print, and free the linked list while ensuring thread safety using mutexes.']

