int read_int_array(int *arr, int max_size) {
    int count = 0;
    while (count < max_size && scanf("%d", &arr[count]) == 1) {
        ++count;
    }
    return count;
}

int find_largest_integer(int *arr, int size) {
    if (size == 0) return INT_MIN; // Return smallest possible int if no valid input
    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

int process_nfaapi_crc_indications(int N, int M) {
    // Check for potential integer overflow
    if ((long long)N * sizeof(NFAPI_CRC_INDICATION_PDU_T) / sizeof(NFAPI_CRC_INDICATION_PDU_T) != (size_t)N ||
        (long long)M * sizeof(int) / sizeof(int) != (size_t)M) {
        return -1; // Error indicator for overflow
    }

    NFAPI_CRC_INDICATION_PDU_T *indicators = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indicators) {
        return -2; // Error indicator for memory allocation failure
    }

    for (int i = 0; i < N; ++i) {
        indicators[i].RX_UE_INFORMATION_TAG = rand() % M;
        indicators[i].RNTI = rand() % M;
        indicators[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    int *input_arr = malloc(M * sizeof(int));
    if (!input_arr) {
        free(indicators);
        return -3; // Error indicator for memory allocation failure
    }

    int count = read_int_array(input_arr, M);

    int largest = find_largest_integer(input_arr, count);

    free(indicators);
    free(input_arr);

    if (largest == INT_MIN) {
        return -4; // Error indicator for no valid input
    }

    return largest;
}
