#define MAX_PACKET_SIZE 1024
#define INITIAL_PACKET_COUNT 100

typedef struct {
    int PacketID;
    time_t Timestamp;
    size_t PacketSize;
} PacketMetaData;

typedef struct {
    PacketMetaData* packets;
    size_t count;
    size_t capacity;
} PacketArray;

typedef struct {
    FILE* logFile;
    char** logs;
    size_t count;
    size_t capacity;
} LogArray;

void initializePacketArray(PacketArray* packetArray) {
    packetArray->packets = malloc(INITIAL_PACKET_COUNT * sizeof(PacketMetaData));
    if (packetArray->packets == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    packetArray->count = 0;
    packetArray->capacity = INITIAL_PACKET_COUNT;
}

void initializeLogArray(LogArray* logArray) {
    logArray->logs = malloc(INITIAL_PACKET_COUNT * sizeof(char*));
    if (logArray->logs == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    logArray->count = 0;
    logArray->capacity = INITIAL_PACKET_COUNT;
}

void appendToPacketArray(PacketArray* packetArray, PacketMetaData packet) {
    if (packetArray->count >= packetArray->capacity) {
        size_t newCapacity = packetArray->capacity * 2;
        PacketMetaData* newPackets = realloc(packetArray->packets, newCapacity * sizeof(PacketMetaData));
        if (newPackets == NULL) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        packetArray->packets = newPackets;
        packetArray->capacity = newCapacity;
    }
    packetArray->packets[packetArray->count++] = packet;
}

void appendToLogArray(LogArray* logArray, const char* message) {
    if (logArray->count >= logArray->capacity) {
        size_t newCapacity = logArray->capacity * 2;
        char** newLogs = realloc(logArray->logs, newCapacity * sizeof(char*));
        if (newLogs == NULL) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        logArray->logs = newLogs;
        logArray->capacity = newCapacity;
    }
    logArray->logs[logArray->count++] = strdup(message); // Use strdup to copy the string
}

void processPackets(PacketMetaData* packets, size_t packetCount, PacketArray* packetArray, LogArray* logArray) {
    for (size_t i = 0; i < packetCount; ++i) {
        if (packets[i].PacketSize > MAX_PACKET_SIZE) {
            char* logMessage = malloc(MAX_PACKET_SIZE * sizeof(char));
            snprintf(logMessage, MAX_PACKET_SIZE, "Oversized Packet: ID=%d, Size=%zu", packets[i].PacketID, packets[i].PacketSize);
            appendToLogArray(logArray, logMessage);
        } else {
            appendToPacketArray(packetArray, packets[i]);
        }
    }
}

// Example usage
int main() {
    PacketMetaData packets[10] = { /* Initialize with actual packet data */ };
    PacketArray packetArray;
    LogArray logArray;

    initializePacketArray(&packetArray);
    initializeLogArray(&logArray);

    processPackets(packets, 10, &packetArray, &logArray);

    // Clean up
    for (size_t i = 0; i < packetArray.count; ++i) {
        free(packetArray.packets[i].Timestamp); // Assuming Timestamp is dynamically allocated
    }
    free(packetArray.packets);
    for (size_t i = 0; i < logArray.count; ++i) {
        free(logArray.logs[i]);
    }
    free(logArray.logs);

    return 0;
}
