#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct Packet {
    uint16_t metadata_size;
    uint32_t payload_size;
    void* data;
} Packet;

typedef enum {
    LOW_PRIORITY,
    MEDIUM_PRIORITY,
    HIGH_PRIORITY
} PriorityLevel;

typedef struct BufferManager {
    size_t buffer_size;
    Packet* packets;
    size_t packet_count;
    size_t max_packet_count;
    PriorityLevel priority;
    FILE* log_file;
} BufferManager;

BufferManager* create_buffer_manager(size_t initial_capacity, PriorityLevel priority) {
    BufferManager* manager = (BufferManager*)malloc(sizeof(BufferManager));
    if (!manager) return NULL;

    manager->buffer_size = 0;
    manager->packets = NULL;
    manager->packet_count = 0;
    manager->max_packet_count = initial_capacity;
    manager->priority = priority;
    manager->log_file = fopen("buffer_manager.log", "w");
    if (!manager->log_file) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_buffer_manager(BufferManager* manager) {
    for (size_t i = 0; i < manager->packet_count; ++i) {
        free(manager->packets[i].data);
    }
    free(manager->packets);
    fclose(manager->log_file);
    free(manager);
}

int add_packet(BufferManager* manager, uint16_t metadata_size, uint32_t payload_size) {
    if (manager->packet_count >= manager->max_packet_count) {
        size_t new_capacity = manager->max_packet_count * 2;
        Packet* new_packets = realloc(manager->packets, new_capacity * sizeof(Packet));
        if (!new_packets) return -1;
        manager->packets = new_packets;
        manager->max_packet_count = new_capacity;
    }

    Packet* packet = &manager->packets[manager->packet_count++];
    packet->metadata_size = metadata_size;
    packet->payload_size = payload_size;

    size_t data_size = metadata_size + payload_size + sizeof(uint32_t); // Including a size field for the payload
    packet->data = malloc(data_size);
    if (!packet->data) return -1;

    fprintf(manager->log_file, "Added packet, total packets: %zu\n", manager->packet_count);
    return 0;
}

void log_metrics(BufferManager* manager) {
    fprintf(manager->log_file, "Buffer size: %zu bytes\n", manager->buffer_size);
    fprintf(manager->log_file, "Current packet count: %zu\n", manager->packet_count);
}
