// Define the structure for a network packet
typedef struct Packet {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_size;
    void* payload;
} Packet;

// Function to create a new packet
Packet* create_packet(size_t payload_size) {
    // Allocate memory for the packet structure and payload
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->payload_size = payload_size;
    packet->payload = malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    // Initialize metadata fields (for example purposes)
    time(&packet->timestamp);
    memset(packet->source_ip, 0, sizeof(packet->source_ip));
    memset(packet->destination_ip, 0, sizeof(packet->destination_ip));

    return packet;
}

// Function to free a packet and its payload
void free_packet(Packet* packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

// Function to process incoming network packets
Packet** process_packets(size_t initial_capacity, size_t max_payload_size) {
    // Allocate an array of packet pointers with initial capacity
    Packet** packet_array = (Packet**)malloc(initial_capacity * sizeof(Packet*));
    if (!packet_array) return NULL;

    size_t current_capacity = initial_capacity;
    size_t count = 0;

    // Simulate processing incoming packets (example logic)
    while (1) {
        // Allocate a new packet with random payload size
        size_t payload_size = rand() % max_payload_size + 1;
        Packet* packet = create_packet(payload_size);
        if (!packet) break; // Handle allocation failure

        // Simulate receiving packet data (example logic)
        snprintf(packet->source_ip, sizeof(packet->source_ip), "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(packet->destination_ip, sizeof(packet->destination_ip), "10.0.%d.%d", rand() % 256, rand() % 256);

        // Add packet to the array
        if (count >= current_capacity) {
            // Double the capacity if needed
            current_capacity *= 2;
            Packet** new_array = (Packet**)realloc(packet_array, current_capacity * sizeof(Packet*));
            if (!new_array) break; // Handle allocation failure
            packet_array = new_array;
        }
        packet_array[count++] = packet;

        // Simulate end of incoming stream (example logic)
        if (rand() % 10 == 0) break;
    }

    // Resize array to fit exactly the number of packets
    Packet** resized_array = (Packet**)realloc(packet_array, count * sizeof(Packet*));
    if (resized_array && resized_array != packet_array) {
        free(packet_array);
        packet_array = resized_array;
    }

    return packet_array;
}

// Function to free all packets in the array and the array itself
void free_packets(Packet** packet_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free_packet(packet_array[i]);
    }
    free(packet_array);
}
