typedef struct BufferInstance {
    size_t buffer_size;
    void* buffer;
    pthread_mutex_t lock;
} BufferInstance;

BufferInstance* create_buffer_instance(size_t initial_size) {
    BufferInstance* instance = malloc(sizeof(BufferInstance));
    if (instance == NULL) {
        perror("Failed to allocate memory for BufferInstance");
        return NULL;
    }

    instance->buffer_size = initial_size;
    instance->buffer = malloc(initial_size);
    if (instance->buffer == NULL) {
        perror("Failed to allocate memory for buffer");
        free(instance);
        return NULL;
    }

    pthread_mutex_init(&instance->lock, NULL);
    return instance;
}

void destroy_buffer_instance(BufferInstance* instance) {
    if (instance != NULL) {
        pthread_mutex_destroy(&instance->lock);
        free(instance->buffer);
        free(instance);
    }
}

int add_packet_to_buffer(BufferInstance* instance, const void* packet, size_t packet_size) {
    pthread_mutex_lock(&instance->lock);

    // Check if there is enough space in the buffer
    if (packet_size > instance->buffer_size) {
        fprintf(stderr, "Packet too large for current buffer size\n");
        pthread_mutex_unlock(&instance->lock);
        return -1;
    }

    // Simulate adding packet to buffer
    memcpy(instance->buffer, packet, packet_size);

    pthread_mutex_unlock(&instance->lock);
    return 0;
}

void* get_buffer(BufferInstance* instance) {
    return instance->buffer;
}

size_t get_buffer_size(BufferInstance* instance) {
    return instance->buffer_size;
}
