IMAGE_SEGMENT_T* process_image_segments(const char* directory_path, size_t* num_segments) {
    DIR *dir;
    struct dirent *ent;
    IMAGE_SEGMENT_T *segments = NULL;
    size_t total_segments = 0;

    dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return NULL;
    }

    // Count the number of files in the directory
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") != 0 && strcmp(ent->d_name, "..") != 0) {
            total_segments++;
        }
    }
    closedir(dir);

    if (total_segments == 0) {
        printf("No image files found in the directory.\n");
        return NULL;
    }

    // Allocate memory for all segments
    segments = malloc(total_segments * sizeof(IMAGE_SEGMENT_T));
    if (segments == NULL) {
        perror("Failed to allocate memory for image segments");
        return NULL;
    }

    dir = opendir(directory_path);
    size_t segment_index = 0;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") != 0 && strcmp(ent->d_name, "..") != 0) {
            snprintf(segments[segment_index].filename, MAX_FILENAME_LENGTH, "%s/%s", directory_path, ent->d_name);
            segments[segment_index].id = segment_index;
            // Initialize other segment-specific fields here
            segment_index++;
        }
    }
    closedir(dir);

    *num_segments = total_segments;
    return segments;
}
