#include <arpa/inet.h>

#define BUFFER_SIZE 1024

int process_image_files(int file_count, char **file_names) {
    int total_size = 0;
    for (int i = 0; i < file_count; i++) {
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock == -1) {
            perror("Failed to create socket");
            return -1;
        }
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(8080);
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
            perror("Failed to connect");
            close(sock);
            return -1;
        }

        send(sock, file_names[i], strlen(file_names[i]), 0);
        int response_size = recv(sock, &total_size, sizeof(total_size), 0);
        if (response_size != sizeof(total_size)) {
            perror("Failed to receive total size");
            close(sock);
            return -1;
        }

        close(sock);
    }

    void *buffer = malloc((size_t)total_size);
    if (!buffer) {
        perror("Memory allocation failed");
        return -1;
    }

    int received_bytes = 0;
    for (int i = 0; i < file_count; i++) {
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock == -1) {
            perror("Failed to create socket");
            free(buffer);
            return -1;
        }
        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(8080);
        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
            perror("Failed to connect");
            close(sock);
            free(buffer);
            return -1;
        }

        send(sock, file_names[i], strlen(file_names[i]), 0);
        char *buffer_ptr = buffer + received_bytes;
        int remaining_size = total_size - received_bytes;
        while (remaining_size > 0) {
            int bytes_received = recv(sock, buffer_ptr, remaining_size, 0);
            if (bytes_received == -1) {
                perror("Failed to receive data");
                close(sock);
                free(buffer);
                return -1;
            }
            buffer_ptr += bytes_received;
            received_bytes += bytes_received;
            remaining_size -= bytes_received;
        }

        close(sock);
    }

    // Process the aggregated metadata
    // ...

    free(buffer);
    return 0;
}
