            size_t bytes_read, sha1_len;
            unsigned char sha1[SHA_DIGEST_LENGTH];

            snprintf(filepath, sizeof(filepath), "%s/%s", directory_path, entry->d_name);

            if ((file = fopen(filepath, "rb")) == NULL) {
                perror("Failed to open file");
                continue;
            }

            (*segments)[current_index].segment_id = current_index + 1;
            strncpy((*segments)[current_index].filename, entry->d_name, MAX_FILENAME_LENGTH - 1);

            // Read file in chunks
            while ((bytes_read = fread((*segments)[current_index].segment_data, 1, sizeof((*segments)[current_index].segment_data), file)) > 0) {
                SHA1((*segments)[current_index].segment_data, bytes_read, sha1);
                SHA1_Init(&sha1[bytes_read]);
            }

            fclose(file);
            current_index++;
        }
    }

    closedir(dir);
    return 0;
}
