typedef struct {
    char* data;
    size_t length;
} IMAGE_SEGMENT_T;

IMAGE_SEGMENT_T* processImageDirectory(const char* directory_path, int* num_files, int* total_segments) {
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return NULL;
    }

    struct dirent* entry;
    IMAGE_FILE_T* files = malloc(0); // Dynamically allocate memory for file list
    int current_files = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue; // Skip current and parent directories

        struct stat file_stat;
        char full_path[MAX_FILENAME_LENGTH];
        snprintf(full_path, MAX_FILENAME_LENGTH, "%s/%s", directory_path, entry->d_name);

        if (stat(full_path, &file_stat) == -1) {
            perror("Failed to get file stats");
            continue;
        }

        if (S_ISREG(file_stat.st_mode)) { // Check if it's a regular file
            current_files++;
            files = realloc(files, current_files * sizeof(IMAGE_FILE_T));
            strcpy(files[current_files - 1].filename, full_path);
            // Assume each file has one segment for simplicity
            files[current_files - 1].segment_count = 1;
        }
    }

    closedir(dir);

    if (num_files != NULL)
        *num_files = current_files;

    IMAGE_SEGMENT_T* segments = malloc(0); // Dynamically allocate memory for segment list
    int current_segments = 0;

    for (int i = 0; i < current_files; i++) {
        FILE* file = fopen(files[i].filename, "rb");
        if (file == NULL) {
            perror("Failed to open file");
            continue;
        }

        IMAGE_SEGMENT_T segment;
        size_t bytes_read = fread(segment.data, sizeof(char), segment.length, file);
        // Assume each segment is read into memory for simplicity
        segments = realloc(segments, (current_segments + 1) * sizeof(IMAGE_SEGMENT_T));
        memcpy(&segments[current_segments], &segment, sizeof(IMAGE_SEGMENT_T));
        current_segments++;
        fclose(file);
    }

    if (total_segments != NULL)
        *total_segments = current_segments;

    free(files); // Free allocated memory for file list
    return segments;
}
