#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 1000
#define MAX_PACKET_SIZE 256

typedef struct {
    unsigned char *data;
    size_t length;
} PacketInfo;

PacketInfo* process_packets(const unsigned char *stream, size_t stream_size) {
    if (stream_size == 0 || stream_size > MAX_PACKET_SIZE * MAX_PACKETS) {
        return NULL; // Invalid stream
    }

    PacketInfo *packets = malloc(MAX_PACKETS * sizeof(PacketInfo));
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    size_t packet_count = 0;
    const unsigned char *current = stream;

    while (current < stream + stream_size && packet_count < MAX_PACKETS) {
        size_t packet_length = (size_t)*current;
        current++;

        if (current + packet_length > stream + stream_size || packet_length == 0) {
            free(packets);
            return NULL; // Invalid packet length
        }

        packets[packet_count].data = malloc(packet_length);
        if (!packets[packet_count].data) {
            for (size_t i = 0; i < packet_count; i++) {
                free(packets[i].data);
            }
            free(packets);
            return NULL; // Memory allocation failed
        }

        memcpy(packets[packet_count].data, current, packet_length);
        packets[packet_count].length = packet_length;

        current += packet_length;
        packet_count++;
    }

    if (current != stream + stream_size) {
        for (size_t i = 0; i < packet_count; i++) {
            free(packets[i].data);
        }
        free(packets);
        return NULL; // Invalid packet format
    }

    packets[packet_count].data = NULL;
    packets[packet_count].length = 0;

    return packets;
}

void free_packets(PacketInfo *packets) {
    for (size_t i = 0; packets[i].data != NULL; i++) {
        free(packets[i].data);
    }
    free(packets);
}
