#define MAX_PACKET_SIZE 65536
#define MIN_PACKET_SIZE 128
#define MAX_CONCURRENT_PACKETS 1024

typedef struct {
    int length;
    char payload[];
} PacketHeader;

int validate_packet_size(int size) {
    return size >= MIN_PACKET_SIZE && size <= MAX_PACKET_SIZE;
}

PacketHeader* allocate_packet(int size) {
    if (!validate_packet_size(size)) {
        return NULL;
    }
    PacketHeader *packet = (PacketHeader*)malloc(sizeof(PacketHeader) + size);
    if (packet == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    packet->length = size;
    return packet;
}

void free_packet(PacketHeader* packet) {
    free(packet);
}

void process_packet(PacketHeader* packet) {
    // Process the packet payload
    printf("Processing packet with length: %d\n", packet->length);
}

typedef struct {
    int fd;
    int max_packet_size;
} NetworkContext;

NetworkContext ctx = {0};

void* packet_processor(void* arg) {
    PacketHeader* packets[MAX_CONCURRENT_PACKETS];
    int packet_count = 0;

    while (1) {
        // Simulate receiving a packet
        if (packet_count >= MAX_CONCURRENT_PACKETS) {
            for (int i = 0; i < packet_count; i++) {
                process_packet(packets[i]);
                free_packet(packets[i]);
            }
            packet_count = 0;
        }

        int payload_size = rand() % (ctx.max_packet_size - MIN_PACKET_SIZE + 1) + MIN_PACKET_SIZE;
        packets[packet_count++] = allocate_packet(payload_size);
    }

    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s max_packet_size\n", argv[0]);
        return EXIT_FAILURE;
    }

    ctx.max_packet_size = atoi(argv[1]);

    pthread_t threads[MAX_CONCURRENT_PACKETS];
    for (int i = 0; i < MAX_CONCURRENT_PACKETS; i++) {
        if (pthread_create(&threads[i], NULL, packet_processor, NULL) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_PACKETS; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
