#include <stdlib.h>
#include <string.h>

#define MAX_FRAMES_PER_PACKET 1024

typedef struct {
    void* buffer;
    size_t allocated_size;
    size_t used_size;
} FrameBuffer;

int process_packets(FrameBuffer* fb, const void** packets, size_t packet_count) {
    if (!fb || !packets || packet_count == 0) {
        return -1; // Invalid input
    }

    size_t total_frames = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        const void* packet = packets[i];
        // Assuming each packet is a pointer to an array of frames and the number of frames is stored at the beginning
        size_t frame_count = *(const size_t*)packet;
        total_frames += frame_count;

        if (total_frames > SIZE_MAX / sizeof(void*)) {
            return -1; // Integer overflow detected
        }
    }

    // Calculate new buffer size, ensuring it's a multiple of the size of void* for alignment
    size_t new_size = (total_frames + MAX_FRAMES_PER_PACKET - 1) / MAX_FRAMES_PER_PACKET * MAX_FRAMES_PER_PACKET;
    if (new_size > fb->allocated_size) {
        // Reallocate buffer with the new size
        void* new_buffer = realloc(fb->buffer, new_size * sizeof(void*));
        if (!new_buffer) {
            return -1; // Memory allocation failed
        }
        fb->buffer = new_buffer;
        fb->allocated_size = new_size;
    }

    // Copy frames into the buffer (assuming each packet is followed by its frames in memory)
    size_t offset = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        const void* packet = packets[i];
        size_t frame_count = *(const size_t*)packet;
        memcpy((char*)fb->buffer + offset * sizeof(void*), (const char*)packet + sizeof(size_t), frame_count * sizeof(void*));
        offset += frame_count;
    }

    fb->used_size = total_frames;

    return 0; // Success
}
```

This code defines a `FrameBuffer` structure to manage the dynamically allocated buffer for storing frames. The `process_packets` function processes an array of packets, each containing a number of frames, and stores these frames in the buffer. It calculates the total number of frames and reallocates the buffer if necessary, ensuring it's large enough to hold all frames without causing overflow. Error handling is included for invalid input and memory allocation failures. The function efficiently manages memory usage and minimizes fragmentation by only allocating what's needed."]

