        new_node->CRC_INDICATION_REL8_TAG = rand() % 256; // Example random value
        new_node->CRCFLAG = rand() % 2; // Example random value
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
}

