    }

    image_t* images = (image_t*)malloc(num_images * sizeof(image_t));
    if (!images) {
        return -2; // Error: Memory allocation failed
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_images; ++i) {
        FILE* file = fopen(filenames[i], "rb");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", filenames[i]);
            continue;
        }

        fseek(file, 0, SEEK_END);
        size_t size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (size > MAX_FILE_SIZE) {
            fprintf(stderr, "File size too large: %s\n", filenames[i]);
            fclose(file);
            continue;
        }

        images[i].file_size = size;

        // Read metadata and dimensions from file
        // ...

        fclose(file);
    }

    pthread_mutex_unlock(&mutex);

    free(images);
    return 0; // Success
}
