ImageTask** manageTasks(int num_tasks, size_t max_memory) {
    if (num_tasks <= 0 || max_memory == 0) {
        return NULL;
    }

    ImageTask** tasks = (ImageTask**)malloc(num_tasks * sizeof(ImageTask*));
    if (!tasks) {
        fprintf(stderr, "Memory allocation failed for task pointers.\n");
        return NULL;
    }

    size_t total_metadata_size = num_tasks * sizeof(int); // Simplified assumption
    size_t total_image_data_size = 0;

    for (int i = 0; i < num_tasks; ++i) {
        ImageTask* task = (ImageTask*)malloc(sizeof(ImageTask));
        if (!task) {
            fprintf(stderr, "Memory allocation failed for task %d.\n", i);
            // Free previously allocated tasks
            for (int j = 0; j < i; ++j) {
                free(tasks[j]);
            }
            free(tasks);
            return NULL;
        }

        task->id = i;
        task->metadata_size = sizeof(int); // Simplified assumption

        // Simulate image data size calculation
        size_t image_data_size = rand() % (max_memory - total_metadata_size) + 1;

        if ((total_image_data_size + image_data_size) > max_memory) {
            fprintf(stderr, "Exceeds maximum memory limit. Task %d not allocated.\n", i);
            free(task);
            // Free previously allocated tasks
            for (int j = 0; j < i; ++j) {
                free(tasks[j]);
            }
            free(tasks);
            return NULL;
        }

        task->processed_image_data = (char*)malloc(image_data_size);
        if (!task->processed_image_data) {
            fprintf(stderr, "Memory allocation failed for image data of task %d.\n", i);
            free(task);
            // Free previously allocated tasks
            for (int j = 0; j < i; ++j) {
                free(tasks[j]);
            }
            free(tasks);
            return NULL;
        }

        total_metadata_size += task->metadata_size;
        total_image_data_size += image_data_size;

        tasks[i] = task;
    }

    return tasks;
}

void freeTasks(ImageTask** tasks, int num_tasks) {
    if (tasks) {
        for (int i = 0; i < num_tasks; ++i) {
            if (tasks[i]) {
                free(tasks[i]->processed_image_data);
                free(tasks[i]);
            }
        }
        free(tasks);
    }
}

int main() {
    int num_tasks = 10;
    size_t max_memory = 1024 * 1024; // 1MB

    ImageTask** tasks = manageTasks(num_tasks, max_memory);
    if (tasks) {
        printf("Tasks allocated successfully.\n");
        freeTasks(tasks, num_tasks);
    } else {
        printf("Failed to allocate tasks.\n");
    }

    return 0;
}
