typedef struct List {
    Node* head;
    size_t count;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = *data;
    node->next = NULL;
    return node;
}

void add_to_list(List* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = create_node(data);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
        ++list->count;
    }
}

void remove_from_list(List* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (current->data == *data) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            --list->count;
