Image* createImageArray(int numImages, int imageWidth, int imageHeight) {
    if (numImages <= 0 || imageWidth <= 0 || imageHeight <= 0) {
        return NULL;
    }

    // Calculate total memory required for the images and their pixel data
    size_t totalSize = numImages * sizeof(Image);
    totalSize += numImages * imageWidth * imageHeight;

    // Allocate memory for the Image array
    Image* imageArray = (Image*)malloc(totalSize);
    if (!imageArray) {
        return NULL; // Memory allocation failed
    }

    // Initialize each Image structure and allocate pixel data
    unsigned char* pixelPtr = ((unsigned char*)(imageArray + numImages));
    for (int i = 0; i < numImages; i++) {
        imageArray[i].width = imageWidth;
        imageArray[i].height = imageHeight;
        imageArray[i].pixels = pixelPtr;
        pixelPtr += imageWidth * imageHeight;
    }

    return imageArray;
}

// Example usage
int main() {
    int numImages = 10;
    int imageWidth = 800;
    int imageHeight = 600;

    Image* images = createImageArray(numImages, imageWidth, imageHeight);
    if (images) {
        // Use the image array...
        free(images); // Don't forget to free allocated memory
    }

    return 0;
