        structs[i].RNTI = (unsigned short)(rand() % 65536);
        structs[i].CRC_INDICATION_REL8_TAG = rand() % INT_MAX;
        structs[i].CRCFLAG = (char)rand();
    }

    return structs;
}

int resolveHostname(const char* hostname, u_char* ip) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[MAX_IP_LEN];

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);

        if (inaddr_any(ip)) {
            memcpy(ip, ipstr, strlen(ipstr));
            freeaddrinfo(res); // Free the linked list
            return 0; // Success
        }
    }

    freeaddrinfo(res); // Free the linked list on failure
    return -1; // No suitable IP address found
}

void freeStructs(NFAPI_CRC_INDICATION_PDU_T* structs, int N) {
    if (structs) {
        free(structs);
    }
}

int main() {
    const char* hostname = "example.com";
    u_char ip[MAX_IP_LEN];

    NFAPI_CRC_INDICATION_PDU_T* structs = generate_NFAPIStructs(10);
    if (!structs) {
        fprintf(stderr, "Failed to generate NFAPIStructs\n");
        return -1;
    }

    int result = resolveHostname(hostname, ip);
    if (result == 0) {
        printf("Resolved IP: %s\n", ip);
    } else {
        printf("Failed to resolve hostname\n");
    }

    freeStructs(structs, 10);

    return 0;
}
