// Define the packet structure
typedef struct Packet {
    int id;
    unsigned long timestamp;
    char *payload;
    size_t payload_size;
} Packet;

// Function to calculate total memory required for packets
size_t calculate_total_memory(const Packet *packets, int num_packets) {
    size_t total = 0;
    for (int i = 0; i < num_packets; ++i) {
        // Check for integer overflow
        if ((total > SIZE_MAX - packets[i].payload_size)) {
            fprintf(stderr, "Error: Integer overflow detected.\n");
            exit(EXIT_FAILURE);
        }
        total += sizeof(Packet) + packets[i].payload_size;
    }
    return total;
}

// Function to process packets efficiently
void process_packets(const Packet *packets, int num_packets) {
    // Calculate total memory required
    size_t total_memory = calculate_total_memory(packets, num_packets);

    // Allocate memory in a single operation
    char *memory_block = (char *)malloc(total_memory);
    if (!memory_block) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    char *current_ptr = memory_block;
    for (int i = 0; i < num_packets; ++i) {
        // Initialize packet structure in the allocated memory
        Packet *packet = (Packet *)current_ptr;
        packet->id = packets[i].id;
        packet->timestamp = packets[i].timestamp;

        // Copy payload data
        packet->payload_size = packets[i].payload_size;
        packet->payload = current_ptr + sizeof(Packet);
        memcpy(packet->payload, packets[i].payload, packets[i].payload_size);

        // Move pointer for the next packet
        current_ptr += sizeof(Packet) + packets[i].payload_size;
    }

    // Process each packet (simulated)
    for (int i = 0; i < num_packets; ++i) {
        Packet *packet = (Packet *)(memory_block + i * (sizeof(Packet) + packets[i].payload_size));
        printf("Packet ID: %d, Timestamp: %lu, Payload Size: %zu\n", packet->id, packet->timestamp, packet->payload_size);
    }

    // Free allocated memory
    free(memory_block);
}

int main() {
    // Example usage
    Packet packets[] = {
        {1, 1633072800, "Hello", 5},
        {2, 1633072801, "World!", 6}
    };
    int num_packets = sizeof(packets) / sizeof(packets[0]);

    process_packets(packets, num_packets);

    return 0;
}
