// Custom memory pool functions (simplified example)
typedef struct {
    void *pool;
    size_t block_size;
    int max_blocks;
    int free_count;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size, int max_blocks) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->max_blocks = max_blocks;
    mp->free_count = max_blocks;
    mp->pool = calloc(max_blocks, block_size);
    return mp;
}

void *allocate_from_pool(MemoryPool *mp) {
    if (mp->free_count <= 0) {
        return NULL; // Pool is empty
    }
    mp->free_count--;
    return mp->pool + (mp->max_blocks - mp->free_count - 1) * mp->block_size;
}

void free_to_pool(MemoryPool *mp, void *ptr) {
    size_t offset = ((char *)ptr - (char *)mp->pool) / mp->block_size;
    if (offset >= mp->max_blocks || mp->free_count >= mp->max_blocks) {
        return; // Invalid pointer or pool is full
    }
    mp->free_count++;
}

