#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_PACKETS 1024

typedef struct {
    void *payload;
    size_t length;
    time_t timestamp;
} Packet;

Packet packet_pool[MAX_PACKETS];
int pool_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int process_packets(void **packets, int max_packets, size_t max_memory) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < max_packets; ++i) {
        if (pool_index >= MAX_PACKETS) {
            pthread_mutex_unlock(&mutex);
            return -1; // Pool overflow
        }

        Packet *packet = &packet_pool[pool_index++];
        size_t packet_size = sizeof(Packet);

        // Allocate memory for the payload ensuring alignment requirements
        size_t aligned_payload_size = ((packet_size + 7) / 8) * 8;
        if (aligned_payload_size + packet_size > max_memory) {
            pthread_mutex_unlock(&mutex);
            return -2; // Memory allocation limit exceeded
        }

        void *payload_ptr = malloc(aligned_payload_size);
        if (!payload_ptr) {
            pthread_mutex_unlock(&mutex);
            return -3; // Failed to allocate memory for payload
        }

        packet->payload = payload_ptr;
        packet->length = aligned_payload_size;
        packet->timestamp = time(NULL);

        packets[i] = packet;
    }

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}
```

