#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    // Define the structure fields as per NFAPI_CRC_INDICATION_PDU_T
} RX_UE_INFORMATION_TAG;

typedef struct {
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    bool is_allocated;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

bool nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->mutex);
        return false; // List is full
    }
    list->elements[list->count++] = new_element;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    if (index < 0 || index >= list->count) {
        return false; // Invalid index
    }
    pthread_mutex_lock(&list->mutex);
    for (; index < list->count - 1; ++index) {
        list->elements[index] = list->elements[index + 1];
    }
    list->count--;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void nfapi_crc_indication_list_cleanup(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
