typedef struct {
    char filename[256];
    size_t filesize;
    unsigned int checksum;
} ImageMetadata;

ImageMetadata* process_image_metadata(int num_entries, FILE* stream) {
    if (num_entries <= 0 || stream == NULL) {
        return NULL; // Invalid input
    }

    // Calculate the total memory requirement for the list
    size_t max_filename_size = 256;
    size_t total_memory_required = num_entries * (sizeof(ImageMetadata) + max_filename_size);

    // Allocate memory for the list of ImageMetadata structures
    ImageMetadata* metadata_list = (ImageMetadata*)malloc(total_memory_required);
    if (metadata_list == NULL) {
        return NULL; // Memory allocation failed
    }

    // Read each image metadata entry from the network stream and populate the list
    for (int i = 0; i < num_entries; ++i) {
        ImageMetadata* current_entry = &metadata_list[i];
        if (fread(current_entry->filename, sizeof(char), max_filename_size, stream) != max_filename_size ||
            fread(&current_entry->filesize, sizeof(size_t), 1, stream) != 1 ||
            fread(&current_entry->checksum, sizeof(unsigned int), 1, stream) != 1) {
            free(metadata_list);
            return NULL; // Read failed
        }
    }

    return metadata_list;
}
