#define MAX_STRUCTURES 1000
#define MAX_MEMORY_ALLOCATION_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int width;
    int height;
    float contrast;
    // other image processing parameters
} IMAGE_PROCESSING_STRUCT;

IMAGE_PROCESSING_STRUCT** image_processing_array = NULL;
int array_size = 0;
size_t total_memory_used = 0;

int resize_image_processing_array(int new_size) {
    if (new_size > MAX_STRUCTURES) return -1; // Check for size limit

    IMAGE_PROCESSING_STRUCT** new_array = realloc(image_processing_array, new_size * sizeof(IMAGE_PROCESSING_STRUCT*));
    if (!new_array) return -2; // Handle memory allocation failure

    image_processing_array = new_array;
    array_size = new_size;

    return 0; // Success
}

int add_image_processing_task(int width, int height, float contrast) {
    if (total_memory_used + sizeof(IMAGE_PROCESSING_STRUCT*) > MAX_MEMORY_ALLOCATION_LIMIT) return -1; // Check memory limit

    if (array_size == 0 || image_processing_array[array_size - 1] != NULL) {
        if (resize_image_processing_array(array_size + 1)) return -2; // Resize array if needed
    }

    IMAGE_PROCESSING_STRUCT* new_task = malloc(sizeof(IMAGE_PROCESSING_STRUCT));
    if (!new_task) return -3; // Handle memory allocation failure

    new_task->width = width;
    new_task->height = height;
    new_task->contrast = contrast;

    total_memory_used += sizeof(IMAGE_PROCESSING_STRUCT);
    image_processing_array[array_size - 1] = new_task;

    return 0; // Success
}

void free_image_processing_array() {
    for (int i = 0; i < array_size; i++) {
        if (image_processing_array[i]) {
            free(image_processing_array[i]);
            total_memory_used -= sizeof(IMAGE_PROCESSING_STRUCT);
        }
    }

    if (image_processing_array) {
        free(image_processing_array);
        image_processing_array = NULL;
        array_size = 0;
        total_memory_used = 0;
    }
}

int main() {
    // Example usage
    add_image_processing_task(800, 600, 1.2);
