typedef struct AudioMetadata {
    char filename[MAX_FILENAME_LENGTH];
    int duration_ms;
    int bitrate_bps;
    int sample_rate_hz;
} AudioMetadata;

int calculateMemoryRequirement(int numEntries, int maxFilenameLength) {
    // Calculate the total memory required for the list of AudioMetadata structures
    return numEntries * (sizeof(AudioMetadata) + maxFilenameLength);
}

AudioMetadata* processAudioMetadataStream(int* numEntries, char** metadataStream) {
    if (*numEntries <= 0 || !metadataStream) {
        fprintf(stderr, "Invalid input: Number of entries must be positive and metadata stream must not be null.\n");
        return NULL;
    }

    // Calculate the total memory required for the list
    int totalMemory = calculateMemoryRequirement(*numEntries, MAX_FILENAME_LENGTH);
    AudioMetadata* audioMetadataList = (AudioMetadata*)malloc(totalMemory);

    if (!audioMetadataList) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Process each metadata entry and populate the list
    for (int i = 0; i < *numEntries; i++) {
        AudioMetadata* currentEntry = audioMetadataList + i;
        char* entryData = metadataStream[i];

        if (strlen(entryData) >= MAX_FILENAME_LENGTH - 1) {
            fprintf(stderr, "Filename exceeds maximum length.\n");
            free(audioMetadataList);
            return NULL;
        }

        // Parse the entry data and populate the structure
        sscanf(entryData, "%255s %d %d %d", currentEntry->filename, &currentEntry->duration_ms, &currentEntry->bitrate_bps, &currentEntry->sample_rate_hz);
    }

    return audioMetadataList;
}

int main() {
    int numEntries = 3;
    char* metadataStream[] = {
        "song1.mp3 300000 128000 44100",
        "song2.wav 150000 192000 48000",
        "song3.ogg 450000 64000 22050"
    };

    AudioMetadata* metadataList = processAudioMetadataStream(&numEntries, metadataStream);

    if (metadataList) {
        for (int i = 0; i < numEntries; i++) {
            printf("Filename: %s\nDuration: %d ms\nBitrate: %d bps\nSample Rate: %d Hz\n\n", 
                   metadataList[i].filename, metadataList[i].duration_ms, metadataList[i].bitrate_bps, metadataList[i].sample_rate_hz);
        }
        free(metadataList);
    }

    return 0;
}
