PacketManager* create_packet_manager(size_t initial_capacity, size_t memory_limit) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (manager == NULL) {
        return NULL; // Handle memory allocation failure
    }
    manager->packets = (PacketMetadata*)malloc(initial_capacity * sizeof(PacketMetadata));
    if (manager->packets == NULL) {
        free(manager);
        return NULL; // Handle memory allocation failure
    }
    manager->max_packets = initial_capacity;
    manager->current_packets = 0;
    manager->total_size = 0;
    manager->memory_limit_bytes = memory_limit;
    return manager;
}

void destroy_packet_manager(PacketManager* manager) {
    if (manager != NULL) {
        free(manager->packets);
        free(manager);
    }
}

int process_packet(PacketManager* manager, PacketMetadata packet) {
    if (manager == NULL || manager->current_packets >= manager->max_packets) {
        return -1; // Manager is invalid or full
    }

    size_t packet_size = sizeof(PacketMetadata);
    if ((manager->total_size + packet_size) > manager->memory_limit_bytes) {
        // Implement memory truncation strategy
        // For example, remove packets with lower integrity flags first
        // ...

        if ((manager->total_size + packet_size) > manager->memory_limit_bytes) {
            return 0; // Memory limit exceeded even after truncation
        }
    }

    manager->packets[manager->current_packets++] = packet;
    manager->total_size += packet_size;
    return 1; // Packet processed successfully
}

void report_packet_stats(PacketManager* manager, int* packets_processed, int* packets_retained) {
    if (manager != NULL) {
        *packets_processed = manager->current_packets;
        *packets_retained = manager->current_packets;
    } else {
        *packets_processed = 0;
        *packets_retained = 0;
    }
}

int main() {
