    if (manager != NULL) {
        PacketMetadata packet = {time(NULL), 150, 1}; // Example packet metadata
        int result = process_packet(manager, packet);
        if (result == 1) {
            printf("Packet processed successfully.\n");
        } else {
            printf("Failed to process packet or memory limit exceeded.\n");
        }

        int packets_processed, packets_retained;
        report_packet_stats(manager, &packets_processed, &packets_retained);
        printf("Processed Packets: %d\n", packets_processed);
        printf("Retained Packets: %d\n", packets_retained);

        destroy_packet_manager(manager);
    } else {
        printf("Failed to create packet manager.\n");
    }

    return 0;
}
