#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t mutex;
} NFAPICrcIndicationPool;

NFAPICrcIndicationPool* create_crc_indication_pool(size_t initial_size) {
    if (initial_size == 0) return NULL;

    NFAPICrcIndicationPool *pool = malloc(sizeof(NFAPICrcIndicationPool));
    if (!pool) return NULL;

    pool->pdu_array = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdu_array) {
        free(pool);
        return NULL;
    }

    pool->allocated_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void destroy_crc_indication_pool(NFAPICrcIndicationPool *pool) {
    if (pool) {
        free(pool->pdu_array);
        pthread_mutex_destroy(&pool->mutex);
        free(pool);
    }
}

int add_crc_indication(NFAPICrcIndicationPool *pool, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    if (!pool || pool->used_count >= pool->allocated_size) return -1;

    pthread_mutex_lock(&pool->mutex);

    pool->pdu_array[pool->used_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pool->pdu_array[pool->used_count].RNTI = RNTI;
    pool->pdu_array[pool->used_count].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    pool->used_count++;

    pthread_mutex_unlock(&pool->mutex);

    return 0;
}

int resize_crc_indication_pool(NFAPICrcIndicationPool *pool, size_t new_size) {
    if (!pool || new_size <= pool->allocated_size) return -1;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(pool->pdu_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    pool->pdu_array = new_array;
    pool->allocated_size = new_size;

    return 0;
}
