        return -3; // Configuration read error
    }

    if (N <= 0 || actual_max_memory <= 0) {
        return -4; // Invalid values in configuration
    }

    *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) {
        return -5; // Memory allocation failed
    }

