#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000
#define MAX_MEMORY 500000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
int allocated_structures = 0;
size_t total_allocated_memory = 0;
size_t max_allocations = 0;
double average_allocation_time = 0.0;
FILE *log_file;

void log_statistics() {
    fprintf(log_file, "Allocated Structures: %d\n", allocated_structures);
    fprintf(log_file, "Total Memory Allocated: %zu bytes\n", total_allocated_memory);
    fprintf(log_file, "Max Allocation Attempts: %zu\n", max_allocations);
    fprintf(log_file, "Average Allocation Time: %.2f ms\n", average_allocation_time);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    struct timespec start, end;
    long seconds_elapsed;
    long nanoseconds_elapsed;
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    clock_gettime(CLOCK_MONOTONIC, &start);

    pthread_mutex_lock(&memory_lock);
    if (allocated_structures >= MAX_STRUCTURES || total_allocated_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY) {
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    allocated_structures++;
    total_allocated_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (allocated_structures > max_allocations)
        max_allocations = allocated_structures;

    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;

    pthread_mutex_unlock(&memory_lock);

    clock_gettime(CLOCK_MONOTONIC, &end);
    seconds_elapsed = end.tv_sec - start.tv_sec;
    nanoseconds_elapsed = end.tv_nsec - start.tv_nsec;
    average_allocation_time = ((seconds_elapsed * 1000) + (nanoseconds_elapsed / 1e6)) / allocated_structures;

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&memory_lock);
    if (pdu != NULL) {
        free(pdu);
        allocated_structures--;
        total_allocated_memory -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    pthread_mutex_unlock(&memory_lock);
}

void* thread_function(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu();
    if (pdu != NULL) {
        // Process the pdu
        free_pdu(pdu);
    } else {
        // Queue non-critical tasks or handle low-resource scenario
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_STRUCTURES];
    log_file = fopen("memory_log.txt", "w");

    srand(time(NULL));

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, NULL) != 0) {
            perror("Failed to create thread");
            break;
        }
    }

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_join(threads[i], NULL);
    }

    log_statistics();
    fclose(log_file);

    return 0;
}
