async function processImageSizes(imageSizes, maxRetries = 3) {
    let result = 0;
    const retry = async (fn, retries) => {
        try {
            return await fn();
        } catch (error) {
            if (--retries > 0) {
                console.warn(`Attempt ${maxRetries - retries}: Failed. Retrying...`);
                return await retry(fn, retries);
            }
            throw error;
        }
    };

    for (const size of imageSizes) {
        try {
            const processedSize = await retry(async () => {
                // Simulate asynchronous processing
                return new Promise((resolve) => setTimeout(() => resolve(size * 2), 100));
            });
            result += processedSize;
            console.log(`Processed size: ${processedSize}`);
        } catch (error) {
            console.error(`Failed to process size: ${size}`, error);
        }
    }

    return result;
}

