typedef enum {
    MAX_STRUCTS = 1000,
    ERROR_INVALID_INPUT = -1,
    ERROR_MEMORY_ALLOCATION_FAILURE = -2
} ErrorCode;

ErrorCode createRxIndicationList(NFAPI_CRC_INDICATION_PDU_T** head, uint32_t* count) {
