#include <stdlib.h>
#include <stdio.h>

#define MAX_MEMORY 1024 * 1024 // 1MB limit for simplicity

typedef struct {
    int width;
    int height;
} IMAGE_HEADER;

typedef struct JPEG_IMAGE_T {
    IMAGE_HEADER header;
    unsigned char* pixel_data;
    struct JPEG_IMAGE_T* next;
} JPEG_IMAGE_T;

JPEG_IMAGE_T* create_jpeg_image_list(int N, int* widths, int* heights, unsigned char** data, size_t* sizes) {
    JPEG_IMAGE_T* head = NULL;
    JPEG_IMAGE_T** current = &head;
    size_t total_allocated = 0;

    for (int i = 0; i < N; ++i) {
        if (total_allocated + sizes[i] > MAX_MEMORY) {
            printf("Memory limit exceeded. Allocation aborted.\n");
            return head;
        }

        JPEG_IMAGE_T* new_image = (JPEG_IMAGE_T*)malloc(sizeof(JPEG_IMAGE_T));
        if (!new_image) {
            printf("Memory allocation failed for image %d\n", i);
            break;
        }

        new_image->header.width = widths[i];
        new_image->header.height = heights[i];
        new_image->pixel_data = (unsigned char*)malloc(sizes[i]);
        if (!new_image->pixel_data) {
            printf("Memory allocation failed for pixel data of image %d\n", i);
            free(new_image);
            break;
        }

        memcpy(new_image->pixel_data, data[i], sizes[i]);

        new_image->next = NULL;
        *current = new_image;
        current = &new_image->next;

        total_allocated += sizes[i];
    }

    return head;
}

// Example usage
int main() {
    int widths[] = {1024, 800, 640};
    int heights[] = {768, 600, 480};
    size_t sizes[] = {1024 * 768 * 3, 800 * 600 * 3, 640 * 480 * 3}; // RGB images
    unsigned char* data[] = {(unsigned char*)"data1", (unsigned char*)"data2", (unsigned char*)"data3"};

    JPEG_IMAGE_T* image_list = create_jpeg_image_list(3, widths, heights, data, sizes);

    // Clean up allocated memory
    while (image_list) {
        JPEG_IMAGE_T* temp = image_list;
        free(temp->pixel_data);
        free(temp);
        image_list = temp->next;
    }

    return 0;
}
```

