IMAGE_METADATA** process_image_queue(int num_images, FILE* image_files[], int* total_processed, int timeout) {
    IMAGE_METADATA** metadata_list = (IMAGE_METADATA**)malloc(num_images * sizeof(IMAGE_METADATA*));
    if (!metadata_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_images; ++i) {
        IMAGE_METADATA* img_metadata = (IMAGE_METADATA*)malloc(sizeof(IMAGE_METADATA));
        if (!img_metadata) {
            fprintf(stderr, "Memory allocation failed for image %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(metadata_list[j]->pixel_data);
                free(metadata_list[j]);
            }
            free(metadata_list);
            return NULL;
        }

        // Simulate reading metadata and pixel data from file
        fread(&img_metadata->id, sizeof(int), 1, image_files[i]);
        fread(&img_metadata->width, sizeof(int), 1, image_files[i]);
        fread(&img_metadata->height, sizeof(int), 1, image_files[i]);

        size_t pixel_data_size = img_metadata->width * img_metadata->height;
        img_metadata->pixel_data = (unsigned char*)malloc(pixel_data_size);
        if (!img_metadata->pixel_data) {
            fprintf(stderr, "Memory allocation failed for pixel data of image %d\n", i);
            // Free previously allocated memory
            free(img_metadata);
            for (int j = 0; j < i; ++j) {
                free(metadata_list[j]->pixel_data);
                free(metadata_list[j]);
            }
            free(metadata_list);
            return NULL;
        }

        fread(img_metadata->pixel_data, sizeof(unsigned char), pixel_data_size, image_files[i]);

        metadata_list[i] = img_metadata;

        // Simulate processing time
        sleep(timeout);

        (*total_processed)++;
    }

    return metadata_list;
}
