typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *blocks;
    size_t pool_size;
    size_t used_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t pool_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->blocks = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }
    pool->pool_size = pool_size;
    pool->used_blocks = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->blocks);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_block(MemoryPool *pool) {
    if (pool->used_blocks >= pool->pool_size) return NULL;
    return &pool->blocks[pool->used_blocks++];
}

void deallocate_block(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *block) {
    for (size_t i = 0; i < pool->used_blocks; ++i) {
        if (&pool->blocks[i] == block) {
            pool->used_blocks--;
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_structs(size_t N, MemoryPool *pool) {
    if (N > MAX_N || N <= 0) return NULL;

    if (!pool) {
        pool = create_memory_pool(N);
        if (!pool) return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % MAX_N;
        array[i].RNTI = 12345; // Constant RNTI value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG (0 or 1)
    }

    return array;
}

void free_nfaapi_structs(NFAPI_CRC_INDICATION_PDU_T *array, size_t N, MemoryPool *pool) {
    if (array) free(array);
    if (pool) destroy_memory_pool(pool);
}
