#define MAX_TAG_COUNT 1024

typedef struct {
    uint64_t timestamp;
    uint32_t packet_id;
    uint16_t sequence_number;
} Tag;

Tag* process_packet_tags(const uint8_t* data, size_t data_size, size_t max_tags) {
    if (max_tags > MAX_TAG_COUNT) {
        return NULL; // Exceeds maximum allowed tags
    }

    Tag* tags = (Tag*)malloc(max_tags * sizeof(Tag));
    if (!tags) {
        return NULL; // Memory allocation failed
    }

    // Process the incoming packet data and initialize tags
    size_t tag_count = 0;
    while (data_size >= sizeof(Tag)) {
        if (tag_count >= max_tags) {
            free(tags);
            return NULL; // More tags than expected
        }
        tags[tag_count].timestamp = *((uint64_t*)data);
        data += sizeof(uint64_t);
        tags[tag_count].packet_id = *((uint32_t*)data);
        data += sizeof(uint32_t);
        tags[tag_count].sequence_number = *((uint16_t*)data);
        data += sizeof(uint16_t);

        tag_count++;
        data_size -= sizeof(Tag);
    }

    return tags;
}

void free_tags(Tag* tags) {
    if (tags) {
        free(tags);
    }
}
