#define MAX_LAYERS 1000
#define MIN_LAYER_SIZE 32
#define MAX_FILE_SIZE (1024 * 1024 * 1024) // 1GB

typedef struct ImageLayer {
    int width;
    int height;
    unsigned char* data;
    struct ImageLayer* next;
} ImageLayer;

ImageLayer* create_layer(int width, int height, unsigned char* data) {
    ImageLayer* layer = (ImageLayer*)malloc(sizeof(ImageLayer));
    if (layer == NULL) return NULL;
    layer->width = width;
    layer->height = height;
    layer->data = data;
    layer->next = NULL;
    return layer;
}

int read_image_file(const char* filename, ImageLayer** layers) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return -1;

    // Read header to get number of layers
    int num_layers;
    fread(&num_layers, sizeof(int), 1, file);
    if (num_layers < 0 || num_layers > MAX_LAYERS) {
        fclose(file);
        return -2;
    }

    for (int i = 0; i < num_layers; ++i) {
        int width, height;
        fread(&width, sizeof(int), 1, file);
        fread(&height, sizeof(int), 1, file);

        if (width < MIN_LAYER_SIZE || height < MIN_LAYER_SIZE ||
            width * height > MAX_FILE_SIZE / num_layers) {
            fclose(file);
            return -3;
        }

        // Allocate memory for layer data
        unsigned char* data = (unsigned char*)malloc(width * height);
        if (data == NULL) {
            fclose(file);
            return -4;
        }
        fread(data, 1, width * height, file);

        // Add layer to linked list
        ImageLayer* new_layer = create_layer(width, height, data);
        if (new_layer == NULL) {
            free(data);
            fclose(file);
            return -5;
        }

        if (*layers == NULL) {
            *layers = new_layer;
        } else {
            ImageLayer* current = *layers;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_layer;
        }
    }

    fclose(file);
    return 0;
}

void free_layers(ImageLayer* layers) {
    ImageLayer* current = layers;
    while (current != NULL) {
        ImageLayer* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}

int main() {
    char directory[] = "path/to/image/directory";
    DIR* dir = opendir(directory);
    if (dir == NULL) return -1;

    struct dirent* entry;
    ImageLayer* layers = NULL;

    while ((entry = readdir(dir)) != NULL) {
        const char* filename = entry->d_name;
        if (filename[0] != '.' && strstr(filename, ".img") != NULL) {
            int result = read_image_file(filename, &layers);
            if (result < 0) {
                printf("Error reading file %s: %d\n", filename, result);
                free_layers(layers);
                return -1;
            }
        }
    }

    closedir(dir);

    // Process the linked list of layers
    // ...

    free_layers(layers);

    return 0;
}
```

This code snippet provides a basic structure for managing image layers in C. It includes functions to create layers, read image files into a linked list, and free the allocated memory when done. The main function demonstrates how to open a directory, read all `.img` files, and process the linked list of layers. Error handling is implemented for file reading and directory traversal, and efficient memory management is considered by dynamically allocating memory as needed and freeing it properly at the end.']

