NFAPI_CRC_INDICATION_PDU_T* allocate_nfaipdu_array(int num_structs, int max_structs, size_t element_size) {
    if (num_structs <= 0 || num_structs > max_structs) {
        errno = EINVAL;
        return NULL;
    }

    size_t total_memory_needed = (size_t)num_structs * element_size;

    // Check for integer overflow
    if (total_memory_needed / num_structs != element_size) {
        errno = EOVERFLOW;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(total_memory_needed);
    if (!array) {
        if (errno == ENOMEM) {
            // Fallback mechanism: reduce the number of structures
            while (num_structs > 0) {
                total_memory_needed = (size_t)num_structs * element_size;
                if (total_memory_needed / num_structs != element_size) {
                    break; // Overflow occurred, stop reducing
                }
                array = malloc(total_memory_needed);
                if (array) {
                    return array;
                } else if (errno == ENOMEM && num_structs > 1) {
                    num_structs /= 2; // Reduce by half
                } else {
                    break; // Cannot allocate, stop trying
                }
            }
        }
        return NULL;
    }

    return array;
}
