#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_MEMORY_BUDGET 1024 * 1024 * 1024 // 1GB

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t allocated_size;
    size_t used_size;
    sem_t mutex;
    sem_t space_available;
    sem_t item_added;
} DynamicArray;

void init_dynamic_array(DynamicArray* da) {
    da->array = NULL;
    da->allocated_size = 0;
    da->used_size = 0;
    sem_init(&da->mutex, 0, 1);
    sem_init(&da->space_available, 0, MAX_MEMORY_BUDGET / sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_init(&da->item_added, 0, 0);
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da->array != NULL) {
        free(da->array);
        da->array = NULL;
    }
    sem_destroy(&da->mutex);
    sem_destroy(&da->space_available);
    sem_destroy(&da->item_added);
}

int add_to_dynamic_array(DynamicArray* da, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_wait(&da->mutex);
    if (da->used_size >= da->allocated_size) {
        size_t new_size = da->allocated_size ? da->allocated_size * 2 : 1;
        while (new_size < da->used_size + 1) {
            new_size *= 2;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            sem_post(&da->mutex);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->allocated_size = new_size;
    }
    da->array[da->used_size++] = *pdu;
    sem_post(&da->mutex);
    sem_post(&da->item_added);
    sem_wait(&da->space_available); // Ensure we don't exceed memory budget
    return 0; // Success
}

void* producer_thread(void* arg) {
    DynamicArray* da = (DynamicArray*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (1) {
        // Populate pdu with valid data
        if (add_to_dynamic_array(da, &pdu) == -1) {
            log_error("Memory allocation failed");
            break; // Handle memory allocation failure
        }
    }
    return NULL;
}

void* consumer_thread(void* arg) {
    DynamicArray* da = (DynamicArray*)arg;
    while (1) {
        sem_wait(&da->item_added);
        sem_wait(&da->mutex);
        if (da->used_size > 0) {
            NFAPI_CRC_INDICATION_PDU_T pdu = da->array[--da->used_size];
            sem_post(&da->mutex);
            process_pdu(pdu); // Process the PDU
        } else {
            sem_post(&da->mutex);
            break; // No more items to process
        }
    }
    return NULL;
}
