#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>

#define MAX_IMAGE_PATH 256
#define MAX_TAG_LENGTH 128
#define SYSTEM_MEMORY_LIMIT (1024 * 1024 * 1024) // 1GB

typedef struct {
    char path[MAX_IMAGE_PATH];
    int width;
    int height;
    char tags[MAX_TAG_LENGTH];
} Image;

Image* image_array = NULL;
int image_count = 0;
pthread_mutex_t mutex;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_warning(const char* message) {
    fprintf(stderr, "Warning: %s\n", message);
}

void process_image_file(const char* path) {
    // Simulate reading image data and metadata
    Image new_image;
    strcpy(new_image.path, path);
    new_image.width = rand() % 1000 + 1;
    new_image.height = rand() % 1000 + 1;

    pthread_mutex_lock(&mutex);
    if (image_count >= SYSTEM_MEMORY_LIMIT / sizeof(Image)) {
        log_warning("System memory limit reached. Unable to process more images.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    image_array[image_count++] = new_image;
    pthread_mutex_unlock(&mutex);
}

void* scan_directory(void* arg) {
    char* directory_path = (char*)arg;
    DIR* dir = opendir(directory_path);
    if (!dir) {
        log_error("Failed to open directory");
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char path[MAX_IMAGE_PATH];
        snprintf(path, sizeof(path), "%s/%s", directory_path, entry->d_name);

        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            scan_directory(path);
        } else if (entry->d_type == DT_REG) {
            process_image_file(path);
        }
    }

    closedir(dir);
    return NULL;
}

void initialize_image_processing() {
    pthread_mutex_init(&mutex, NULL);
}

void finalize_image_processing() {
    for (int i = 0; i < image_count; i++) {
        // Simulate freeing memory for each image structure
        memset(&image_array[i], 0, sizeof(Image));
    }
    free(image_array);
    pthread_mutex_destroy(&mutex);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        log_error("Usage: %s <directory_path>", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_image_processing();

    image_array = (Image*)malloc(SYSTEM_MEMORY_LIMIT);
    if (!image_array) {
        log_error("Failed to allocate memory for image array");
        finalize_image_processing();
        return EXIT_FAILURE;
    }

    scan_directory(argv[1]);

    finalize_image_processing();
    return EXIT_SUCCESS;
}
