#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define MAX_FRAMES 1000
#define MIN_FRAME_SIZE 1024

typedef struct {
    unsigned char *data;
    size_t size;
} Frame;

typedef struct {
    Frame frames[MAX_FRAMES];
    int head, tail, count;
    pthread_mutex_t lock;
    sem_t empty, full;
} FrameQueue;

FrameQueue queue;

void init_queue() {
    queue.head = queue.tail = queue.count = 0;
    pthread_mutex_init(&queue.lock, NULL);
    sem_init(&queue.empty, 0, MAX_FRAMES);
    sem_init(&queue.full, 0, 0);
}

int enqueue(Frame frame) {
    sem_wait(&queue.empty);
    pthread_mutex_lock(&queue.lock);
    queue.frames[queue.tail] = frame;
    queue.tail = (queue.tail + 1) % MAX_FRAMES;
    queue.count++;
    pthread_mutex_unlock(&queue.lock);
    sem_post(&queue.full);
    return 0;
}

int dequeue(Frame *frame) {
    sem_wait(&queue.full);
    pthread_mutex_lock(&queue.lock);
    if (queue.count == 0) {
        pthread_mutex_unlock(&queue.lock);
        return -1; // Queue is empty
    }
    *frame = queue.frames[queue.head];
    queue.head = (queue.head + 1) % MAX_FRAMES;
    queue.count--;
    pthread_mutex_unlock(&queue.lock);
    sem_post(&queue.empty);
    return 0;
}

void destroy_queue() {
    pthread_mutex_destroy(&queue.lock);
    sem_destroy(&queue.empty);
    sem_destroy(&queue.full);
}
