#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* messages;
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
} CRC_Indication_Queue;

void initialize_queue(CRC_Indication_Queue* queue, size_t capacity) {
    queue->messages = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->capacity = capacity;
    queue->count = 0;
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue(CRC_Indication_Queue* queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count < queue->capacity) {
        queue->messages[queue->tail].RX_UE_INFORMATION_TAG = rand() % 100; // Example value
        queue->messages[queue->tail].RNTI = rand() % 1000; // Example value
        queue->messages[queue->tail].CRCFLAG = rand() % 2; // Random CRC flag
        queue->tail = (queue->tail + 1) % queue->capacity;
        queue->count++;
    }
    pthread_mutex_unlock(&queue->lock);
}

void* iterator(CRC_Indication_Queue* queue, void** prev) {
    pthread_mutex_lock(&queue->lock);
    if (*prev == NULL || *prev != &queue->messages[queue->tail - 1]) {
        *prev = &queue->messages[(queue->head + (int)(*prev ? (char*)*prev - (char*)&queue->messages[0] : 0)) % queue->capacity];
    } else {
        *prev = NULL;
    }
    pthread_mutex_unlock(&queue->lock);
    return *prev;
}

void* get_current(CRC_Indication_Queue* queue, void** prev) {
    return iterator(queue, prev);
}
