typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* dynamic_array = NULL;
int array_size = 0;

void initialize_dynamic_array(int requested_size) {
    pthread_mutex_lock(&array_lock);
    if (dynamic_array != NULL) {
        free(dynamic_array);
        dynamic_array = NULL;
        array_size = 0;
    }
    int aligned_size = ((requested_size * NFAPI_CRC_INDICATION_PDU_T_SIZE + 3) & ~3); // Align to 4-byte boundary
    int total_memory_required = aligned_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (total_memory_required > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Requested size exceeds memory limit.\n");
        pthread_mutex_unlock(&array_lock);
        return;
    }

    dynamic_array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(4, total_memory_required); // Allocate aligned memory
    if (dynamic_array == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&array_lock);
        return;
    }

    for (int i = 0; i < requested_size; ++i) {
        dynamic_array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
        dynamic_array[i].RNTI = rand() % 1000; // Example initialization
        dynamic_array[i].CRCFLAG = (rand() % 2 == 0) ? 0 : 1; // Randomly set CRCFLAG
    }

    array_size = requested_size;
    pthread_mutex_unlock(&array_lock);
}

void* manage_dynamic_array(void* arg) {
    int requested_size = *(int*)arg;
    initialize_dynamic_array(requested_size);
    return NULL;
}

int main() {
