    int request1 = 5000, request2 = 3000;

    pthread_create(&thread1, NULL, manage_dynamic_array, &request1);
    pthread_create(&thread2, NULL, manage_dynamic_array, &request2);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    if (dynamic_array != NULL) {
        free(dynamic_array);
        dynamic_array = NULL;
    }

    return 0;
}
