#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1GB limit

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaipdu(int num_structs, size_t struct_size) {
    if (num_structs > MAX_MEMORY_USAGE / struct_size) {
        fprintf(stderr, "Error: Requested number of structures exceeds system's available resources.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_structs * struct_size);
    if (!list) {
        perror("Failed to allocate memory for NFAPI CRC indications.");
        return NULL;
    }

    for (int i = 0; i < num_structs; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand() % 65536; // Random RNTI within the valid range
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
    }

    return list;
}

void serialize_to_file(NFAPI_CRC_INDICATION_PDU_T* list, int num_structs, size_t struct_size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization.");
        return;
    }

    size_t bytes_written = fwrite(list, struct_size, num_structs, file);
    if (bytes_written != num_structs * struct_size) {
        fprintf(stderr, "Error: Failed to write all data to file.\n");
    } else {
        printf("Data serialized successfully.\n");
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_from_file(const char* filename, size_t struct_size) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization.");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long int file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int num_structs = file_size / struct_size;
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_structs * struct_size);
    if (!list) {
        perror("Failed to allocate memory for deserialized data.");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(list, struct_size, num_structs, file);
    if (bytes_read != num_structs * struct_size) {
        fprintf(stderr, "Error: Failed to read all data from file.\n");
        free(list);
        list = NULL;
    } else {
        printf("Data deserialized successfully.\n");
    }

    fclose(file);
    return list;
}

int main() {
    int num_structs = 10000;
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    NFAPI_CRC_INDICATION_PDU_T* nfaipdu_list = create_and_populate_nfaipdu(num_structs, struct_size);
    if (nfaipdu_list) {
        serialize_to_file(nfaipdu_list, num_structs, struct_size, "nfaipdu_data.bin");
        NFAPI_CRC_INDICATION_PDU_T* deserialized_list = deserialize_from_file("nfaipdu_data.bin", struct_size);
        free(nfaipdu_list);
        free(deserialized_list);
    }

    return 0;
}
