#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    time_t last_offload_time;
    int offload_threshold;
    int max_entries;
} LinkedList;

LinkedList* create_linked_list(int N, int offload_threshold) {
    if (N <= 0 || offload_threshold < 1) return NULL;

    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->last_offload_time = time(NULL);
    list->offload_threshold = offload_threshold;
    list->max_entries = N;

    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list);
}

void add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head != NULL) {
        list->head->prev = new_node;
    } else {
        list->tail = new_node;
    }
    list->head = new_node;
    list->size++;

    if (list->size > list->max_entries && time(NULL) - list->last_offload_time > 60) {
        // Initiate background process for offloading
        list->last_offload_time = time(NULL);
        pthread_cond_signal(&list->cond);
    }

    pthread_mutex_unlock(&list->lock);
}

void* offload_process(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        pthread_mutex_lock(&list->lock);
        if (list->size <= list->max_entries || time(NULL) - list->last_offload_time < 60) {
            pthread_cond_wait(&list->cond, &list->lock);
        }

        Node* current = list->head;
        while (current != NULL && list->size > list->max_entries) {
            // Archive old entries
            Node* next = current->next;
            free(current);
            current = next;
            list->size--;
        }
        pthread_mutex_unlock(&list->lock);

        // Perform offloading to external storage or another process
        // ...
    }

    return NULL;
}

void log_entry(NFAPI_CRC_INDICATION_PDU_T data) {
