void* allocateNFAPICRCIndicationPDUs(size_t numStructures, size_t maxStructSize, size_t *pageSize) {
    if (numStructures > SIZE_MAX / maxStructSize) {
        // Handle integer overflow
        errno = EOVERFLOW;
        return NULL;
    }

    size_t totalSize = numStructures * maxStructSize;

    // Round up to the nearest page boundary
    *pageSize = getpagesize();
    size_t alignedSize = (totalSize + (*pageSize - 1)) & ~(*pageSize - 1);

    void *ptr = malloc(alignedSize);
    if (!ptr) {
        // Handle memory allocation failure
        errno = ENOMEM;
        return NULL;
    }

    // Initialize structures
    for (size_t i = 0; i < numStructures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)(ptr + i * maxStructSize);
        pdu->RNTI = rand() % 65536; // Random RNTI
        memset(&pdu->RX_UE_INFORMATION_TAG, 0, sizeof(RX_UE_INFORMATION_TAG)); // Initialize RX_UE_INFORMATION_TAG
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;
    }

    return ptr;
}
