// Function to allocate memory safely and handle potential overflow
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to process packet headers and payloads
int process_packets(struct PacketHeader* headers, int count, size_t max_memory) {
    size_t total_payload_size = 0;

    // Calculate total payload size
    for (int i = 0; i < count; ++i) {
        if (headers[i].payload_size > SIZE_MAX - total_payload_size) {
            fprintf(stderr, "Integer overflow detected\n");
            return -1;
        }
        total_payload_size += headers[i].payload_size;

        // Check if allocating memory exceeds max_memory
        if (total_payload_size > max_memory) {
            fprintf(stderr, "Memory limit exceeded\n");
            return -1;
        }
    }

    // Allocate memory for all payloads
    void* payload_buffer = safe_malloc(total_payload_size);

    // Process each packet
    for (int i = 0; i < count; ++i) {
        memcpy(payload_buffer + total_payload_size - headers[i].payload_size, headers[i].payload, headers[i].payload_size);
    }

    // Free allocated memory
    free(payload_buffer);

    return 0;
}

// Custom hash function to handle potential integer overflow scenarios
void custom_hash(const unsigned char* data, size_t length, unsigned char* output) {
    uint64_t hash_value = 0;

    for (size_t i = 0; i < length; ++i) {
        if (hash_value > UINT64_MAX - (uint64_t)data[i]) {
            fprintf(stderr, "Integer overflow detected\n");
            return;
        }
        hash_value += data[i];
    }

    memcpy(output, &hash_value, sizeof(hash_value));
}

