    size_t totalSize = numImages * sizeof(ImageMetadata);
    if (totalSize > maxArraySize) {
        fprintf(stderr, "Not enough space for all metadata entries.\n");
        return NULL;
    }

    // Align the structures for cache efficiency
    size_t alignment = alignof(ImageMetadata);
    size_t alignedTotalSize = (totalSize + alignment - 1) & ~(alignment - 1);

    if (alignedTotalSize > maxArraySize) {
        fprintf(stderr, "Not enough space after alignment.\n");
        return NULL;
    }

    ImageMetadata* metadata = (ImageMetadata*)malloc(alignedTotalSize);
    if (!metadata) {
        perror("Failed to allocate memory for image metadata.");
        return NULL;
    }

    // Populate the allocated memory with sample data
    for (int i = 0; i < numImages; i++) {
        snprintf(metadata[i].filePath, MAX_PATH_LENGTH, "image%d.jpg", i);
        metadata[i].width = rand() % (MAX_IMAGE_WIDTH + 1);
        metadata[i].height = rand() % (MAX_IMAGE_HEIGHT + 1);
