typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    void* data;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct CustomMemoryPool {
    size_t node_size;
    size_t max_entries;
    size_t current_entries;
    MemoryPoolNode* head;
    pthread_mutex_t lock;
} CustomMemoryPool;

CustomMemoryPool* create_memory_pool(size_t entry_size, size_t max_entries) {
    CustomMemoryPool* pool = (CustomMemoryPool*)malloc(sizeof(CustomMemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->node_size = entry_size + sizeof(MemoryPoolNode);
    pool->max_entries = max_entries;
    pool->current_entries = 0;
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(CustomMemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_entries >= pool->max_entries) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void* data = malloc(pool->node_size);
    if (!data) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    MemoryPoolNode* node = (MemoryPoolNode*)data;
    node->next = pool->head;
    pool->head = node;
    pool->current_entries++;
    pthread_mutex_unlock(&pool->lock);
    return data + sizeof(MemoryPoolNode);
}

void free_to_pool(CustomMemoryPool* pool, void* data) {
    pthread_mutex_lock(&pool->lock);
    MemoryPoolNode* node = (MemoryPoolNode*)((char*)data - sizeof(MemoryPoolNode));
    node->next = pool->head;
    pool->head = node;
    pool->current_entries--;
    pthread_mutex_unlock(&pool->lock);
}

void reset_pool(CustomMemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    MemoryPoolNode* current = pool->head;
    while (current) {
        MemoryPoolNode* next = current->next;
        free(current);
        current = next;
    }
    pool->head = NULL;
    pool->current_entries = 0;
    pthread_mutex_unlock(&pool->lock);
}

void destroy_memory_pool(CustomMemoryPool* pool) {
    reset_pool(pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

