ImageMetadata* process_image_files(int *imageCount) {
    ImageMetadata *metadataArray = NULL;
    int capacity = INITIAL_CAPACITY;
    int currentSize = 0;

    metadataArray = (ImageMetadata *)malloc(capacity * sizeof(ImageMetadata));
    if (metadataArray == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        char filePath[MAX_FILE_PATH_LENGTH];
        int width, height, bitDepth;

        // Read file path from standard input
        if (fgets(filePath, sizeof(filePath), stdin) == NULL) {
            break;
        }

        // Remove newline character if present
        size_t len = strlen(filePath);
        if (len > 0 && filePath[len - 1] == '\n') {
            filePath[len - 1] = '\0';
        }

        // Extract metadata from file path (simplified example)
        width = rand() % 1920 + 1;
        height = rand() % 1080 + 1;
        bitDepth = rand() % 32 + 1;

        if (currentSize == capacity) {
            capacity *= 2;
            metadataArray = (ImageMetadata *)realloc(metadataArray, capacity * sizeof(ImageMetadata));
            if (metadataArray == NULL) {
                fprintf(stderr, "Memory reallocation failed.\n");
                exit(EXIT_FAILURE);
            }
        }

        metadataArray[currentSize].width = width;
        metadataArray[currentSize].height = height;
        metadataArray[currentSize].bitDepth = bitDepth;
        strcpy(metadataArray[currentSize].filePath, filePath);

        currentSize++;
    }

    *imageCount = currentSize;
    return metadataArray;
