#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define INITIAL_CAPACITY 10

typedef struct ImageMetadata {
    char *filePath;
    int width;
    int height;
    int bitDepth;
    uint64_t uniqueID;
    struct ImageMetadata *next;
} ImageMetadata;

uint64_t hashString(const char *str) {
    uint64_t hash = 14695981039346656037ULL; // A prime number
    for (size_t i = 0; str[i] != '\0'; i++) {
        hash ^= (uint64_t)str[i];
        hash *= 1099511628211ULL;
    }
    return hash;
}

ImageMetadata *createImageNode(const char *filePath, int width, int height, int bitDepth) {
    ImageMetadata *node = (ImageMetadata *)malloc(sizeof(ImageMetadata));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->filePath = strdup(filePath);
    node->width = width;
    node->height = height;
    node->bitDepth = bitDepth;
    node->uniqueID = hashString(filePath);
    node->next = NULL;
    return node;
}

ImageMetadata **resizeLinkedList(ImageMetadata **list, size_t *capacity) {
    *capacity *= 2;
    ImageMetadata **newList = (ImageMetadata **)realloc(*list, (*capacity) * sizeof(ImageMetadata *));
    if (newList == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    return newList;
}

void processImageFiles(char **filePaths, size_t numFiles, ImageMetadata ***imageList, size_t *listCapacity) {
    for (size_t i = 0; i < numFiles; i++) {
        // Simulated image metadata extraction
        int width = rand() % 1920 + 1;
        int height = rand() % 1080 + 1;
        int bitDepth = rand() % 33 + 1;

        if (*imageList == NULL) {
            *imageList = (ImageMetadata **)malloc((*listCapacity) * sizeof(ImageMetadata *));
            if (*imageList == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
        } else if (i >= *listCapacity) {
            *imageList = resizeLinkedList(*imageList, listCapacity);
        }

        (*imageList)[i] = createImageNode(filePaths[i], width, height, bitDepth);
    }
}

void freeImageMetadata(ImageMetadata **list, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(list[i]->filePath);
        free(list[i]);
    }
    free(list);
}

int main() {
    // Example usage
    char *filePaths[] = {"image1.jpg", "image2.png", "image3.bmp"};
    size_t numFiles = sizeof(filePaths) / sizeof(filePaths[0]);

    ImageMetadata **imageList = NULL;
    size_t listCapacity = INITIAL_CAPACITY;

    processImageFiles((char **)filePaths, numFiles, &imageList, &listCapacity);

    // Process the image metadata...

    freeImageMetadata(imageList, numFiles);

    return 0;
}
