    list->count = 0;
    list->capacity = INITIAL_BUFFER_SIZE;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_image_list(ImageList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->images);
    pthread_mutex_unlock(&list->mutex);
    free(list);
