int add_image_to_list(ImageList *list, const char *path, int width, int height, int bit_depth) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        ImageMetadata *new_images = (ImageMetadata *)realloc(list->images, new_capacity * sizeof(ImageMetadata));
        if (!new_images) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->images = new_images;
        list->capacity = new_capacity;
    }

    strcpy(list->images[list->count].path, path);
    list->images[list->count].width = width;
    list->images[list->count].height = height;
    list->images[list->count].bit_depth = bit_depth;

