#include <stdint.h>
#include <string.h>

typedef struct {
    uint16_t protocol;
    uint32_t payload_size;
} PacketHeader;

#define MAX_PACKETS 1024
#define MAX_RETRIES 5

void* allocate_payloads(PacketHeader headers[], int packet_count, size_t max_memory) {
    size_t total_payload_size = 0;
    for (int i = 0; i < packet_count; ++i) {
        if (headers[i].payload_size > UINT32_MAX - total_payload_size) {
            fprintf(stderr, "Payload size too large to add.\n");
            return NULL;
        }
        total_payload_size += headers[i].payload_size;
    }

    if (total_payload_size > max_memory) {
        fprintf(stderr, "Total payload size exceeds maximum memory limit.\n");
        return NULL;
    }

    void* payloads = malloc(total_payload_size);
    if (!payloads) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    uint8_t* current_payload = (uint8_t*)payloads;
    for (int i = 0; i < packet_count; ++i) {
        void* payload = malloc(headers[i].payload_size);
        if (!payload) {
            fprintf(stderr, "Failed to allocate memory for payload %d.\n", i);
            // Free previously allocated payloads
            while (current_payload != (uint8_t*)payloads) {
                free(current_payload - headers[i].payload_size);
                current_payload -= headers[i].payload_size;
            }
            free(payloads);
            return NULL;
        }

        memcpy(payload, &headers[i], sizeof(PacketHeader));
        current_payload = payload + headers[i].payload_size;
    }

    return payloads;
}

int main() {
    PacketHeader headers[MAX_PACKETS];
    int packet_count = 3; // Example number of packets
    size_t max_memory = 1024 * 1024; // 1MB

    // Populate headers with example data
    headers[0].protocol = 0x0800; // IPv4
    headers[0].payload_size = 1500;
    headers[1].protocol = 0x86DD; // IPv6
    headers[1].payload_size = 2000;
    headers[2].protocol = 0x0800; // IPv4
    headers[2].payload_size = 1500;

    void* payloads = allocate_payloads(headers, packet_count, max_memory);
    if (payloads) {
        printf("Payloads allocated successfully.\n");
        free(payloads);
    } else {
        printf("Failed to allocate payloads.\n");
    }

    return 0;
}
