#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* payload;
    size_t length;
} PacketData;

PacketData* process_packets(const char* config_file_path, int** interface_max_sizes, int num_interfaces) {
    FILE* file = fopen(config_file_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    // Read the number of packets from the file
    int num_packets;
    if (fscanf(file, "%d", &num_packets) != 1) {
        fprintf(stderr, "Invalid format in configuration file\n");
        fclose(file);
        return NULL;
    }

    PacketData* packets = malloc(num_packets * sizeof(PacketData));
    if (!packets) {
        perror("Failed to allocate memory for packet data");
        fclose(file);
        return NULL;
    }

    // Process each packet
    for (int i = 0; i < num_packets; ++i) {
        size_t total_length = 0;
        int interface_index;

        // Read the interface index and payload length from the file
        if (fscanf(file, "%d %zu", &interface_index, &packets[i].length) != 2 || interface_index >= num_interfaces) {
            fprintf(stderr, "Invalid format in configuration file for packet %d\n", i + 1);
            free(packets);
            fclose(file);
            return NULL;
        }

        // Calculate the total length of the payload
        if (total_length + packets[i].length > INT_MAX - interface_max_sizes[interface_index]) {
            fprintf(stderr, "Packet size exceeds maximum allowed for interface %d\n", interface_index);
            free(packets);
            fclose(file);
            return NULL;
        }
        total_length += packets[i].length;

        // Allocate memory for the payload
        packets[i].payload = malloc(interface_max_sizes[interface_index] * sizeof(char));
        if (!packets[i].payload) {
            perror("Failed to allocate memory for packet payload");
            free(packets);
            fclose(file);
            return NULL;
        }

        // Read the payload from the file
        size_t bytes_read = fread(packets[i].payload, 1, packets[i].length, file);
        if (bytes_read != packets[i].length) {
            fprintf(stderr, "Failed to read complete packet payload for packet %d\n", i + 1);
            free(packets[i].payload);
            free(packets);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return packets;
}
