#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPIS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pduArray;
    size_t currentCount;
    size_t maxCount;
    pthread_mutex_t mutex;
} NFAPICollection;

NFAPICollection* createNFAPICollection(size_t initialSize, size_t maxSize) {
    NFAPICollection* collection = (NFAPICollection*)malloc(sizeof(NFAPICollection));
    if (collection == NULL) {
        return NULL; // Memory allocation failed
    }

    collection->pduArray = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialSize, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (collection->pduArray == NULL) {
        free(collection);
        return NULL; // Memory allocation failed
    }

    collection->currentCount = 0;
    collection->maxCount = maxSize;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroyNFAPICollection(NFAPICollection* collection) {
    if (collection != NULL) {
        free(collection->pduArray);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int addNFAPICRCIndication(NFAPICollection* collection, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (collection == NULL || RX_UE_INFORMATION_TAG < 0 || RNTI < 0 || CRCFLAG < 0) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&collection->mutex);
    if (collection->currentCount >= collection->maxCount) {
        pthread_mutex_unlock(&collection->mutex);
        return -2; // Collection is full
    }

    NFAPI_CRC_INDICATION_PDU_T* newPDU = &collection->pduArray[collection->currentCount];
    newPDU->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newPDU->RNTI = RNTI;
    newPDU->CRCFLAG = CRCFLAG;
    collection->currentCount++;
    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

int validateNFAPICRCIndication(NFAPICollection* collection, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (collection == NULL || RX_UE_INFORMATION_TAG < 0 || RNTI < 0) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->currentCount; ++i) {
        if (collection->pduArray[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && 
            collection->pduArray[i].RNTI == RNTI) {
            pthread_mutex_unlock(&collection->mutex);
            return 0; // Valid
        }
    }
    pthread_mutex_unlock(&collection->mutex);

    return -2; // Invalid or not found
}
