#include <string.h>

#define CONFIG_FILE "network_config.txt"

typedef struct {
    void* payload;
    size_t length;
} PacketData;

int readConfigFile(char** interfaceNames, size_t* maxPacketSizes, int* numInterfaces) {
    FILE* file = fopen(CONFIG_FILE, "r");
    if (!file) return -1;

    *numInterfaces = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Process each line to read interface names and max packet sizes
        // Example: eth0 1500
        int parsedInterfaces = sscanf(line, "%*s %zu", &maxPacketSizes[*numInterfaces]);
        if (parsedInterfaces != 1) continue;
        (*numInterfaces)++;
    }
    fclose(file);
    return 0;
}

int processPackets(PacketData** packetArray, size_t* packetArraySize) {
    int numInterfaces;
    char** interfaceNames = NULL;
    size_t* maxPacketSizes = NULL;

    if (readConfigFile(interfaceNames, maxPacketSizes, &numInterfaces) != 0) return -1;

    *packetArray = NULL;
    *packetArraySize = 0;
    size_t totalMemoryNeeded = 0;

    // Calculate total memory needed
    for (int i = 0; i < numInterfaces; i++) {
        if (maxPacketSizes[i] == 0) continue; // Skip invalid or zero max packet sizes

        // Check for integer overflow
        if ((size_t)-1 / sizeof(PacketData) <= maxPacketSizes[i]) return -1;

        totalMemoryNeeded += maxPacketSizes[i] * sizeof(PacketData);
    }

    // Allocate memory for packet array
    *packetArray = (PacketData*)malloc(totalMemoryNeeded);
    if (!*packetArray) {
        free(interfaceNames);
        free(maxPacketSizes);
        return -1;
    }
    *packetArraySize = totalMemoryNeeded / sizeof(PacketData);

    // Initialize packet data (simulated)
    for (size_t i = 0; i < *packetArraySize; i++) {
        (*packetArray)[i].payload = malloc(1024); // Allocate payload memory
        (*packetArray)[i].length = 1024;
    }

    free(interfaceNames);
    free(maxPacketSizes);
    return 0;
}

int main() {
    PacketData* packetArray = NULL;
    size_t packetArraySize;

    if (processPackets(&packetArray, &packetArraySize) != 0) {
        fprintf(stderr, "Failed to process packets.\n");
        return EXIT_FAILURE;
    }

    // Process the packets here

    for (size_t i = 0; i < packetArraySize; i++) {
        free(packetArray[i].payload);
    }
    free(packetArray);

    return EXIT_SUCCESS;
}
