#include <limits.h>

#define MAX_ELEMENTS 10000
#define MAX_MEMORY_CONSUMPTION 1024 * 1024 // 1MB

typedef struct {
    int tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int rnti;
} RNTI;

typedef struct {
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

int allocate_nfaapi_crc_pdu(int N, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (N < 0) {
        return -1; // Negative input is not allowed
    }

    if (N > MAX_ELEMENTS) {
        return -2; // Exceeds maximum number of elements
    }

    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (required_memory > MAX_MEMORY_CONSUMPTION) {
        return -3; // Exceeds maximum memory consumption
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_memory);
    if (*array == NULL) {
