#include <pthread.h>
#include <time.h>

#define MAX_POOL_SIZE 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    uint32_t crcflag;
    time_t timestamp;
    uint32_t seq_num;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_POOL_SIZE];
    pthread_mutex_t lock;
    size_t current_size;
    size_t max_size;
} CRCIndicationPool;

CRCIndicationPool *create_pool(size_t max_size) {
    if (max_size > MAX_POOL_SIZE) return NULL;
    CRCIndicationPool *pool = malloc(sizeof(CRCIndicationPool));
    if (!pool) return NULL;
    pool->max_size = max_size;
    pthread_mutex_init(&pool->lock, NULL);
    pool->current_size = 0;
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        pool->pool[i] = NULL;
    }
    return pool;
}

void destroy_pool(CRCIndicationPool *pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        if (pool->pool[i]) {
            free(pool->pool[i]);
        }
    }
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T *get_from_pool(CRCIndicationPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->current_size < pool->max_size) {
        for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
            if (!pool->pool[i]) {
                pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (pdu) {
                    pool->pool[i] = pdu;
                    pool->current_size++;
                    break;
                }
            }
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void put_to_pool(CRCIndicationPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        if (pool->pool[i] == pdu) {
            free(pdu);
            pool->pool[i] = NULL;
            pool->current_size--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

size_t get_pool_size(CRCIndicationPool *pool) {
    size_t size;
    pthread_mutex_lock(&pool->lock);
    size = pool->current_size;
    pthread_mutex_unlock(&pool->lock);
    return size;
}
