#define MAX_HOSTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_and_populate_array(NFAPI_CRC_INDICATION_PDU_T **pdu_array, u_char ***ip_addresses, char *hostnames[], int num_hosts, FILE *log_fd) {
    if (num_hosts > MAX_HOSTS || num_hosts < 0) {
        fprintf(log_fd, "Error: Invalid number of hostnames.\n");
        return -1;
    }

    *pdu_array = malloc(num_hosts * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_array == NULL) {
        perror("Failed to allocate memory for PDU array");
        return -2;
    }

    *ip_addresses = malloc(num_hosts * sizeof(u_char *));
    if (*ip_addresses == NULL) {
        free(*pdu_array);
        perror("Failed to allocate memory for IP addresses array");
        return -3;
    }

    int i, j;
    struct addrinfo hints, *res, *p;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    for (i = 0; i < num_hosts; ++i) {
        if ((j = getaddrinfo(hostnames[i], NULL, &hints, &res)) != 0) {
            fprintf(log_fd, "getaddrinfo: %s\n", gai_strerror(j));
            continue;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            void *addr;
            char *ipver;

            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
                ipver = "IPv4";
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
                ipver = "IPv6";
            }

            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
            (*ip_addresses)[i] = strdup(ipstr);

            if ((*ip_addresses)[i] == NULL) {
                freeaddrinfo(res);
                free(*pdu_array);
                free(*ip_addresses);
                perror("Failed to allocate memory for IP address string");
                return -4;
            }

            break; // Use the first result
        }
        freeaddrinfo(res);

        (*pdu_array)[i].RX_UE_INFORMATION_TAG = rand();
        (*pdu_array)[i].RNTI = rand() % 65536;
        (*pdu_array)[i].CRC_INDICATION_REL8_TAG = rand();
        (*pdu_array)[i].CRCFLAG = (rand() % 2) ? 'Y' : 'N';
    }

    return num_hosts; // Return the number of successfully resolved hosts
}
