#include <stdio.h>
#include <stdlib.h>

// Define the NetworkSegment structure
typedef struct NetworkSegment {
    int segmentData; // Example data field
    struct NetworkSegment *next;
} NetworkSegment;

// Define the NetworkPacket structure
typedef struct NetworkPacket {
    int header; // Example header field
    NetworkSegment *segments;
    struct NetworkPacket *next;
} NetworkPacket;

// Function to create a new NetworkPacket
NetworkPacket* createPacket(int header) {
    NetworkPacket *newPacket = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (newPacket == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newPacket->header = header;
    newPacket->segments = NULL;
    newPacket->next = NULL;
    return newPacket;
}

// Function to add a segment to a packet
NetworkSegment* addSegment(NetworkPacket *packet, int data) {
    NetworkSegment *newSegment = (NetworkSegment*)malloc(sizeof(NetworkSegment));
    if (newSegment == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newSegment->segmentData = data;
    newSegment->next = packet->segments;
    packet->segments = newSegment;
    return newSegment;
}

// Function to process a variable number of network packets
void processNetworkPackets(int numPackets, int *metadata) {
    NetworkPacket **packetList = (NetworkPacket**)malloc(numPackets * sizeof(NetworkPacket*));
    if (packetList == NULL) {
        return; // Handle memory allocation failure
    }

    for (int i = 0; i < numPackets; i++) {
        packetList[i] = createPacket(metadata[i]);
        if (packetList[i] == NULL) {
            // Handle error in creating a packet
            continue;
        }
        // Simulate adding segments based on metadata
        for (int j = 0; j < metadata[i]; j++) {
            NetworkSegment *segment = addSegment(packetList[i], j);
            if (segment == NULL) {
                // Handle error in adding segment
                break;
            }
        }
    }

    // Process the linked list of packets
    for (int i = 0; i < numPackets; i++) {
        NetworkPacket *currentPacket = packetList[i];
        while (currentPacket != NULL) {
            // Process each packet and its segments
            printf("Header: %d\n", currentPacket->header);
            NetworkSegment *segment = currentPacket->segments;
            while (segment != NULL) {
                printf("Segment Data: %d\n", segment->segmentData);
                segment = segment->next;
            }
            currentPacket = currentPacket->next;
        }
    }

    // Free allocated memory
    for (int i = 0; i < numPackets; i++) {
        NetworkPacket *currentPacket = packetList[i];
        while (currentPacket != NULL) {
            NetworkSegment *segment = currentPacket->segments;
            while (segment != NULL) {
                NetworkSegment *tempSegment = segment;
                segment = segment->next;
                free(tempSegment);
            }
            NetworkPacket *tempPacket = currentPacket;
            currentPacket = currentPacket->next;
            free(tempPacket);
        }
    }
    free(packetList);
}
