#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define constants and structures
#define METADATA_SIZE 16 // Example metadata size

typedef struct {
    int* packet_sizes;
    int num_packets;
    int max_packet_size;
} PacketData;

typedef struct {
    void* buffer;
    int total_buffer_size;
    pthread_mutex_t mutex;
} BufferManager;

// Function to calculate required buffer size
int calculate_required_size(PacketData* data, int max_packet_size) {
    int metadata_overhead = METADATA_SIZE * data->num_packets;
    int payload_size = 0;

    for (int i = 0; i < data->num_packets; ++i) {
        if (data->packet_sizes[i] > max_packet_size) {
            // Handle error: packet too large
            return -1;
        }
        payload_size += data->packet_sizes[i];
    }

    int total_size = metadata_overhead + payload_size;

    // Check for integer overflow
    if ((metadata_overhead / METADATA_SIZE != data->num_packets) ||
        (payload_size > INT_MAX - metadata_overhead)) {
        return -1;
    }

    return total_size;
}

// Function to allocate memory for buffer
void* allocate_buffer(int size) {
    void* buffer = malloc(size);
    if (!buffer) {
        // Handle error: failed to allocate memory
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return buffer;
}

// Thread-safe function to process packets and store them in buffer
void* process_packets(void* arg) {
    BufferManager* manager = (BufferManager*)arg;
    PacketData* data = // Get packet data from shared resource or thread-local storage

    pthread_mutex_lock(&manager->mutex);

    int required_size = calculate_required_size(data, manager->max_packet_size);
    if (required_size < 0) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL; // Handle error: invalid or too large packets
    }

    if (required_size > manager->total_buffer_size) {
        manager->buffer = realloc(manager->buffer, required_size);
        if (!manager->buffer) {
            pthread_mutex_unlock(&manager->mutex);
            // Handle error: failed to reallocate memory
            return NULL;
        }
        manager->total_buffer_size = required_size;
    }

    char* buffer_ptr = (char*)manager->buffer + METADATA_SIZE * data->num_packets;

    for (int i = 0; i < data->num_packets; ++i) {
        // Copy packet payload to buffer
        memcpy(buffer_ptr, data->payloads[i], data->packet_sizes[i]);
        buffer_ptr += data->packet_sizes[i];
    }

    pthread_mutex_unlock(&manager->mutex);
    return manager->buffer;
}

int main() {
    BufferManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
