#include <pthread.h>

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

struct MemoryPool {
    size_t total_memory;
    size_t used_memory;
    NFAPI_CRC_INDICATION_PDU_T* memory_block;
    pthread_mutex_t mutex;
};

int allocate_linkedList(NFAPI_CRC_INDICATION_PDU_T** list, struct MemoryPool* pool, int num_elements) {
    if (num_elements <= 0 || pool->total_memory == 0 || pool->used_memory >= pool->total_memory) {
        return -1; // Invalid allocation or memory budget exhausted
    }

    pthread_mutex_lock(&pool->mutex);
    size_t required_memory = num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > pool->total_memory - pool->used_memory) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Not enough memory
    }

    *list = &pool->memory_block[pool->used_memory / sizeof(NFAPI_CRC_INDICATION_PDU_T)];
    pool->used_memory += required_memory;
    pthread_mutex_unlock(&pool->mutex);

    return 0; // Successful allocation
}

int main() {
    struct MemoryPool pool = { .total_memory = 1024 * 1024, .used_memory = 0 };
    pthread_mutex_init(&pool.mutex, NULL);
    NFAPI_CRC_INDICATION_PDU_T* linkedList;

    if (allocate_linkedList(&linkedList, &pool, 100) == 0) {
        // Successfully allocated memory for 100 elements
        printf("Memory allocation successful.\n");
    } else {
        printf("Memory allocation failed.\n");
    }

    pthread_mutex_destroy(&pool.mutex);
    return 0;
}
