    if (total_rois > MAX_ROIS) {
        fprintf(stderr, "Too many ROIs in batch\n");
        fclose(batch_file);
        return -1;
    }

    size_t total_memory_required = total_rois * sizeof(ROI_STRUCT_T);
    if (total_memory_required > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded\n");
        fclose(batch_file);
        return -1;
    }

    *roi_array = (ROI_STRUCT_T*)calloc(total_rois, sizeof(ROI_STRUCT_T));
    if (!*roi_array) {
        perror("Failed to allocate memory for ROIs");
        fclose(batch_file);
        return -1;
