    size_t roi_index = 0;
    // Simulate reading ROI data from the batch file
    while (fread(&(*roi_array)[roi_index].region_id, sizeof(uint32_t), 1, batch_file) == 1 &&
           fread(&(*roi_array)[roi_index].x, sizeof(int32_t), 1, batch_file) == 1 &&
           fread(&(*roi_array)[roi_index].y, sizeof(int32_t), 1, batch_file) == 1 &&
           fread(&(*roi_array)[roi_index].width, sizeof(int32_t), 1, batch_file) == 1 &&
           fread(&(*roi_array)[roi_index].height, sizeof(int32_t), 1, batch_file) == 1 &&
           fread(&(*roi_array)[roi_index++].is_active, sizeof(bool), 1, batch_file) == 1);

    if (ferror(batch_file)) {
        perror("Failed to read ROI data from batch file");
        free(*roi_array);
        fclose(batch_file);
        return -1;
    }

    *roi_count = roi_index;
    fclose(batch_file);
    return 0;
}

