#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list(size_t max_size) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU* get_node(LinkedList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Index out of bounds
    }
    Node* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return &current->data;
}

void update_node(LinkedList* list, size_t index, NFAPI_CRC_INDICATION_PDU data) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return; // Index out of bounds
    }
    Node* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    current->data = data;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL));
    LinkedList* list = create_list(10000);

    NFAPI_CRC_INDICATION_PDU new_data = {1, 2, (rand() % 256)};
    add_node(list, new_data);

    NFAPI_CRC_INDICATION_PDU* retrieved_data = get_node(list, 0);
    if (retrieved_data != NULL) {
        printf("Retrieved data: RX_UE_INFORMATION_TAG=%u, RNTI=%hu, CRC_INDICATION_REL8_TAG=%hhu\n",
               retrieved_data->RX_UE_INFORMATION_TAG, retrieved_data->RNTI, retrieved_data->CRC_INDICATION_REL8_TAG);
    }

    update_node(list, 0, (NFAPI_CRC_INDICATION_PDU){3, 4, (rand() % 256)});

    destroy_list(list);

    return 0;
}
