#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int count;
} DoublyLinkedList;

void initializeList(DoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

int isValidInput(int value, int min, int max) {
    return (value >= min && value <= max);
}

NFAPI_CRC_INDICATION_PDU_T* createNode() {
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

void insertNode(DoublyLinkedList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (!isValidInput(list->count + 1, 0, MAX_ELEMENTS)) {
        printf("Cannot insert more elements. Maximum limit reached.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *newNode = createNode();
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (list->count == 0) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->count++;
}

void validateList(DoublyLinkedList *list) {
    if (list == NULL || list->head == NULL) {
        printf("Invalid list\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->next != NULL && current->next->prev != current) {
            printf("Misaligned pointers detected\n");
            return;
        }
        current = current->next;
    }
}

void freeList(DoublyLinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    initializeList(list);
}

int main() {
    srand(time(NULL));
    DoublyLinkedList myList;
    initializeList(&myList);

    int numElements;
    printf("Enter the number of elements (1-%d): ", MAX_ELEMENTS);
    scanf("%d", &numElements);

    if (!isValidInput(numElements, 1, MAX_ELEMENTS)) {
        printf("Invalid input. Number of elements must be between 1 and %d.\n", MAX_ELEMENTS);
        return 1;
    }

    for (int i = 0; i < numElements; i++) {
        insertNode(&myList, rand(), rand(), rand());
    }

    validateList(&myList);

    freeList(&myList);

    return 0;
}
