#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DLL {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} DLL;

void initDLL(DLL* dll) {
    dll->head = NULL;
    dll->tail = NULL;
    dll->size = 0;
    pthread_mutex_init(&dll->lock, NULL);
    pthread_cond_init(&dll->cond, NULL);
}

void insertDLL(DLL* dll, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&dll->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->prev = dll->tail;
    newNode->next = NULL;

    if (dll->tail != NULL) {
        dll->tail->next = newNode;
    } else {
        dll->head = newNode;
    }
    dll->tail = newNode;
    dll->size++;

    pthread_cond_signal(&dll->cond);
    pthread_mutex_unlock(&dll->lock);
}

void deleteDLL(DLL* dll, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&dll->lock);
    Node* current = dll->head;

    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data.RNTI &&
            current->data.CRC_INDICATION_REL8_TAG == data.CRC_INDICATION_REL8_TAG) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                dll->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                dll->tail = current->prev;
            }
            free(current);
            dll->size--;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&dll->lock);
}

void* logWorker(void* arg) {
    DLL* dll = (DLL*)arg;
    time_t lastUpdate = time(NULL);
    int totalCount = 0;

    while (1) {
        pthread_mutex_lock(&dll->lock);

        if (time(NULL) - lastUpdate >= 60) {
            totalCount = dll->size;
            lastUpdate = time(NULL);
        }

        pthread_cond_wait(&dll->cond, &dll->lock);

        pthread_mutex_unlock(&dll->lock);
    }

    return NULL;
}

// Main function to populate the DLL
DLL* createCRCIndicationPDULinkedList(int N) {
    if (N <= 0 || N > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Handle invalid input
        return NULL;
    }

    DLL* dll = (DLL*)malloc(sizeof(DLL));
    initDLL(dll);

    pthread_t logThread;
    pthread_create(&logThread, NULL, logWorker, dll);
    pthread_detach(logThread);

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand() % 1024,
            .CRC_INDICATION_REL8_TAG = (rand() & 1) ? 1 : 0
        };
        insertDLL(dll, data);
    }

    return dll;
}

// Function to retrieve real-time statistics
void getRealTimeStatistics(DLL* dll, int* activeEntries, double* avgCRCFlag, int* mostFrequentRNTI) {
    pthread_mutex_lock(&dll->lock);
    *activeEntries = dll->size;

    int crcSum = 0;
    int rntiCount[1024] = {0};
    int maxCount = 0;
    int frequentRNTI = -1;

    Node* current = dll->head;
    while (current != NULL) {
        crcSum += current->data.CRC_INDICATION_REL8_TAG;
        rntiCount[current->data.RNTI]++;
        if (rntiCount[current->data.RNTI] > maxCount) {
            maxCount = rntiCount[current->data.RNTI];
            frequentRNTI = current->data.RNTI;
        }
        current = current->next;
    }

    *avgCRCFlag = (double)crcSum / dll->size;
    if (*activeEntries > 0) {
        *mostFrequentRNTI = frequentRNTI;
    } else {
        *mostFrequentRNTI = -1;
    }

    pthread_mutex_unlock(&dll->lock);
}
