} PacketData;

PacketData* process_packets(size_t* total_packets) {
    // Simulated configuration reading with potential errors
    size_t num_interfaces = 3; // Example number of interfaces
    size_t max_packet_size_per_interface[] = {1024, 512, 256}; // Max packet sizes for each interface

    // Calculate total packets based on configuration
    if (num_interfaces == 0 || *total_packets == 0) {
        fprintf(stderr, "Invalid configuration: No interfaces or packets to process.\n");
        return NULL;
    }

    size_t expected_total_packets = num_interfaces * *total_packets;
    if (expected_total_packets > SIZE_MAX / sizeof(PacketData)) {
        fprintf(stderr, "Integer overflow in total packet calculation.\n");
        return NULL;
    }

    PacketData* packets = (PacketData*)malloc(expected_total_packets * sizeof(PacketData));
    if (packets == NULL) {
        fprintf(stderr, "Memory allocation failed for packets.\n");
        return NULL;
    }

    // Simulate packet processing
    for (size_t i = 0; i < expected_total_packets; ++i) {
        size_t interface = i % num_interfaces;
        size_t packet_size = rand() % max_packet_size_per_interface[interface] + 1;

        packets[i].payload = (char*)malloc(packet_size);
        if (packets[i].payload == NULL) {
            fprintf(stderr, "Memory allocation failed for packet payload.\n");
            // Free previously allocated memory before exiting
            for (size_t j = 0; j < i; ++j) free(packets[j].payload);
            free(packets);
            return NULL;
        }

        packets[i].length = packet_size;
        // Simulate payload content with random data
        for (size_t j = 0; j < packet_size; ++j) {
            packets[i].payload[j] = 'A' + rand() % 26;
        }
    }

    return packets;
}

void free_packets(PacketData* packets, size_t total_packets) {
    if (packets != NULL) {
        for (size_t i = 0; i < total_packets; ++i) {
