#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_PACKETS 1000
#define MAX_MEMORY_BUDGET 1024 * 1024 // 1 MB

typedef struct Packet {
    uint32_t reported_length;
    void* payload;
} Packet;

typedef struct MemoryPool {
    uint8_t* memory;
    size_t total_size;
    size_t used_size;
    uint32_t packet_count;
    Packet packets[MAX_PACKETS];
} MemoryPool;

int init_memory_pool(MemoryPool* pool, size_t budget) {
    if (budget > MAX_MEMORY_BUDGET) return -1; // Exceeds max budget
    pool->memory = (uint8_t*)malloc(budget);
    if (!pool->memory) return -2; // Memory allocation failed
    pool->total_size = budget;
    pool->used_size = 0;
    pool->packet_count = 0;
    return 0;
}

int add_packet(MemoryPool* pool, Packet packet) {
    size_t payload_size = packet.reported_length;
    if (payload_size > MAX_MEMORY_BUDGET - pool->used_size) return -3; // Payload too large for budget
    if (pool->packet_count >= MAX_PACKETS) return -4; // Too many packets

    // Simulate payload allocation, in practice use memory management functions
    void* payload_addr = pool->memory + pool->used_size;
    memcpy(payload_addr, packet.payload, payload_size);

    Packet* new_packet = &pool->packets[pool->packet_count++];
    new_packet->reported_length = packet.reported_length;
    new_packet->payload = payload_addr;

    pool->used_size += payload_size;
    return 0;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool->memory) {
        free(pool->memory);
        pool->memory = NULL;
    }
}

int main() {
    MemoryPool pool;
    Packet packet1 = {1024, "Sample payload"};
    Packet packet2 = {512, "Another payload"};

    init_memory_pool(&pool, 1024 * 1024); // Initialize with 1 MB budget
    add_packet(&pool, packet1);
    add_packet(&pool, packet2);

    free_memory_pool(&pool);
    return 0;
}
```

