#include <stdlib.h>
#include <string.h>

typedef struct Packet {
    char *payload;
    size_t payload_size;
} Packet;

typedef struct NetworkInterface {
    int id;
    size_t max_packet_size;
    size_t max_packets;
    int priority;
    Packet *queue;
    size_t queue_size;
    size_t allocated_memory;
} NetworkInterface;

typedef struct NetworkSystem {
    NetworkInterface **interfaces;
    size_t interface_count;
    size_t memory_limit;
} NetworkSystem;

NetworkSystem* create_network_system(size_t memory_limit) {
    NetworkSystem *system = (NetworkSystem*)malloc(sizeof(NetworkSystem));
    system->interfaces = NULL;
    system->interface_count = 0;
    system->memory_limit = memory_limit;
    return system;
}

void add_interface(NetworkSystem *system, int id, size_t max_packet_size, size_t max_packets, int priority) {
    NetworkInterface *interface = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    interface->id = id;
    interface->max_packet_size = max_packet_size;
    interface->max_packets = max_packets;
    interface->priority = priority;
    interface->queue = NULL;
    interface->queue_size = 0;
    interface->allocated_memory = 0;

    system->interface_count++;
    system->interfaces = realloc(system->interfaces, system->interface_count * sizeof(NetworkInterface*));
    system->interfaces[system->interface_count - 1] = interface;
}

void enqueue_packet(NetworkSystem *system, int interface_id, const char *payload, size_t payload_size) {
    for (size_t i = 0; i < system->interface_count; i++) {
        if (system->interfaces[i]->id == interface_id) {
            if (payload_size > system->interfaces[i]->max_packet_size) {
                // Handle error: packet too large
                return;
            }

            if ((system->interfaces[i]->allocated_memory + payload_size) > system->memory_limit) {
                // Handle error: memory limit exceeded
                return;
            }

            Packet *new_packet = (Packet*)realloc(system->interfaces[i]->queue, 
                                                 (system->interfaces[i]->queue_size + 1) * sizeof(Packet));
            new_packet[system->interfaces[i]->queue_size].payload = (char*)malloc(payload_size);
            memcpy(new_packet[system->interfaces[i]->queue_size].payload, payload, payload_size);
            new_packet[system->interfaces[i]->queue_size].payload_size = payload_size;
            system->interfaces[i]->queue = new_packet;
            system->interfaces[i]->queue_size++;
            system->interfaces[i]->allocated_memory += payload_size;
            break;
        }
    }
}

void destroy_network_system(NetworkSystem *system) {
    for (size_t i = 0; i < system->interface_count; i++) {
        for (size_t j = 0; j < system->interfaces[i]->queue_size; j++) {
            free(system->interfaces[i]->queue[j].payload);
        }
        free(system->interfaces[i]->queue);
        free(system->interfaces[i]);
    }
    free(system->interfaces);
    free(system);
}
