typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    ERROR_OUT_OF_MEMORY,
    ERROR_INTEGER_OVERFLOW,
    ERROR_NETWORK_FAILURE
} ErrorCode;

ErrorCode create_node(NFAPI_CRC_INDICATION_PDU_T **head, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        return ERROR_OUT_OF_MEMORY;
    }

    new_node->ue_info_tag = ue_info_tag;
    new_node->rnti = rnti;
    new_node->crc_flag = rand() % 2; // Randomly set CRCFLAG
    new_node->next = *head;

    *head = new_node;
    return SUCCESS;
}

ErrorCode delete_node(NFAPI_CRC_INDICATION_PDU_T **head, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    NFAPI_CRC_INDICATION_PDU_T *previous = NULL;

    while (current != NULL) {
        if (current->rnti == rnti) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return SUCCESS;
        }
        previous = current;
        current = current->next;
    }

    return ERROR_NETWORK_FAILURE; // Node not found
}

ErrorCode fetch_max_nodes(int *max_nodes) {
    // Simulate fetching max_nodes from an external configuration service
    *max_nodes = 1000; // Example value
    return SUCCESS;
}

void log_node_operation(const char *operation, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, ErrorCode result) {
    time_t now = time(NULL);
    printf("%s %ld: Operation=%s UE_INFO_TAG=%d RNTI=%u Result=%d\n", __FILE__, now, operation, ue_info_tag, rnti, result);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int max_nodes;

    if (fetch_max_nodes(&max_nodes) != SUCCESS) {
        log_node_operation("FETCH_MAX_NODES", 0, 0, ERROR_NETWORK_FAILURE);
        return -1;
    }

    for (int i = 0; i < max_nodes; i++) {
        ErrorCode result = create_node(&head, i, rand() % 65536); // Random RNTI
        if (result != SUCCESS) {
            log_node_operation("CREATE_NODE", i, rand() % 65536, result);
            break;
        }
    }

    // Simulate periodic cleanup
    while (head != NULL) {
        ErrorCode result = delete_node(&head, head->rnti);
        if (result != SUCCESS) {
            log_node_operation("DELETE_NODE", head->ue_info_tag, head->rnti, result);
        }
    }

    return 0;
}
