#define MAX_PACKET_SIZE 1024
#define MAX_MEMORY_BUDGET (10 * 1024 * 1024) // 10 MB

typedef struct Packet {
    int payload_length;
    char* payload;
} Packet;

Packet* allocate_packet(int length, const void* data) {
    if (length > INT_MAX - sizeof(Packet)) {
        fprintf(stderr, "Error: Payload length too large.\n");
        return NULL;
    }
    Packet* packet = malloc(sizeof(Packet) + length);
    if (!packet) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }
    packet->payload_length = length;
    memcpy(packet->payload, data, length);
    return packet;
}

void free_packet(Packet* packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

int process_packets(const Packet** packets, int count) {
    size_t total_memory_used = 0;
    for (int i = 0; i < count; ++i) {
        if ((total_memory_used + sizeof(Packet) + packets[i]->payload_length) > MAX_MEMORY_BUDGET) {
