        int attempts = 0;
        while (attempts < RETRY_COUNT) {
            if (fetchMetadata(metadata, i) == 0) {
                break; // Successfully fetched metadata
            }
            attempts++;
            printf("Failed to fetch metadata for image %d. Retrying...\n", i);
        }
        if (attempts >= RETRY_COUNT) {
            printf("Failed to fetch metadata for image %d after multiple attempts.\n", i);
