#define MAX_STRUCTURES 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} PoolAllocator;

void initialize_pool(PoolAllocator *pool) {
    pool->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        perror("Failed to allocate memory for pool");
        exit(EXIT_FAILURE);
    }
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_from_pool(PoolAllocator *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == MAX_STRUCTURES) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = &pool->data[pool->count++];
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_to_pool(PoolAllocator *pool, NFAPI_CRC_INDICATION_PDU_T *ptr) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (&pool->data[i] == ptr) {
            pool->data[i] = pool->data[--pool->count];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

