    NetworkParameters *params = get_network_parameters(); // Assume function to get network parameters
    size_t attempted = 0, validated = 0, discarded = 0;
    clock_t start_time = clock();

    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = generate_and_validate_structure(pool, params);
        attempted++;
        if (pdu) {
            validated++;
        } else {
            discarded++;
        }
        free_to_pool(pool, pdu); // Free structure back to pool
    }

    clock_t end_time = clock();
    double elapsed_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    log_metrics(attempted, validated, discarded, elapsed_time);

    return NULL;
}

int main() {
    PoolAllocator pool;
    initialize_pool(&pool);
    pthread_t threads[NUM_THREADS];
    NetworkParameters params; // Assume structure to hold network parameters

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, &pool) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
