} JPEG_IMAGE_T;

int allocate_image_collection(int max_images, size_t image_size, int max_memory_kb) {
    if (max_images > MAX_IMAGES) {
        fprintf(stderr, "Error: Maximum number of images exceeds system-defined limit.\n");
        return -1;
    }

    // Calculate the total memory required
    size_t total_memory = max_images * image_size;

    // Check for integer overflow
    if (total_memory / max_images != image_size) {
        fprintf(stderr, "Error: Integer overflow detected while calculating memory requirements.\n");
        return -1;
    }

    // Validate that the total memory does not exceed the maximum allowed
    if (total_memory > (size_t)(max_memory_kb * 1024)) {
        fprintf(stderr, "Error: Total memory exceeds specified limit.\n");
        return -1;
    }

    JPEG_IMAGE_T* image_collection = malloc(total_memory);
    if (!image_collection) {
        fprintf(stderr, "Error: Unable to allocate memory for image collection.\n");
        return -1;
    }

    // Populate each structure with unique image dimensions and compression level
    srand(time(NULL));
    int used_combinations[MAX_IMAGES][3] = {0};
    int num_images = 0;

    while (num_images < max_images) {
        int width, height, compression_level;
        do {
            width = rand() % 1920 + 1; // Random width between 1 and 1920
            height = rand() % 1080 + 1; // Random height between 1 and 1080
            compression_level = rand() % 100 + 1; // Random compression level between 1 and 100
        } while (used_combinations[num_images][0] == width && 
                 used_combinations[num_images][1] == height && 
                 used_combinations[num_images][2] == compression_level);

        image_collection[num_images].width = width;
        image_collection[num_images].height = height;
        image_collection[num_images].compression_level = compression_level;

        used_combinations[num_images][0] = width;
        used_combinations[num_images][1] = height;
        used_combinations[num_images][2] = compression_level;

        num_images++;
    }

    // Log memory usage
    printf("Allocated %zu bytes for image collection.\n", total_memory);

    // Free allocated memory (for demonstration purposes, not in actual implementation)
    free(image_collection);

    return 0;
}

int main() {
    int max_images = 512; // Example value
    size_t image_size = sizeof(JPEG_IMAGE_T);
    int max_memory_kb = MAX_MEMORY_KB;

    if (allocate_image_collection(max_images, image_size, max_memory_kb) == 0) {
        printf("Image collection allocated successfully.\n");
    } else {
        printf("Failed to allocate image collection.\n");
    }

    return 0;
}
