NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_crc_indication_pdus(int num_structures, char* input_filename) {
    // Calculate the size of the filename based on ASCII values
    int filename_size = 0;
    for (int i = 2; i < strlen(input_filename); i += 4) {
        if (i + 3 < strlen(input_filename)) {
            filename_size += input_filename[i] + input_filename[i+1] + input_filename[i+2] + input_filename[i+3];
        }
    }
    filename_size = (filename_size > 10) ? 10 : filename_size;

    // Replace non-printable characters with '_'
    for (int i = 0; i < strlen(input_filename); i++) {
        if (!isprint(input_filename[i])) {
            input_filename[i] = '_';
        }
    }

    // Create new filename
    char new_filename[MAX_FILENAME_LENGTH];
    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s_%.*d.%s",
             input_filename, filename_size, filename_size,
             "tmp"); // Assuming "tmp" is a placeholder for actual supported type

    // Validate target file type
    int is_supported = 0;
    for (int i = 0; i < MAX_SUPPORTED_TYPES; i++) {
        if (strcmp(new_filename + strlen(new_filename) - strlen(SUPPORTED_TYPES[i]), SUPPORTED_TYPES[i]) == 0) {
            is_supported = 1;
            break;
        }
    }
    if (!is_supported) {
        fprintf(stderr, "Unsupported file type\n");
        return NULL;
    }

    // Allocate memory for the array
    size_t total_memory = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_memory > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation exceeds limit\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory);
    if (!pdu_array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Populate the array
    srand(time(NULL));
    for (int i = 0; i < num_structures; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_array[i].RNTI = rand() % 2048;
