    if (path_count > max_img_count || memory_limit <= 0) return -1;

    *images = (img_t*)malloc(sizeof(img_t) * path_count);
    if (*images == NULL) return -2; // Memory allocation failed

    int total_memory_used = 0;
    for (int i = 0; i < path_count; ++i) {
        // Simulate loading image properties and memory allocation
        img_t* img = &(*images)[i];
        img->width = rand() % 256 + 1; // Random width between 1 and 256 pixels
        img->height = rand() % 256 + 1; // Random height between 1 and 256 pixels
        img->metadata_size = rand() % (1024 * 1024); // Random metadata size up to 1MB

        int image_memory = calculate_image_memory(img);
        if ((total_memory_used + image_memory) > memory_limit) {
            free(*images); // Free allocated memory if exceeding the limit
            return -3; // Memory allocation failed due to limit exceeded
        }

        img->pixels = (unsigned char*)malloc(image_memory);
        if (img->pixels == NULL) {
            for (int j = 0; j < i; ++j) {
                free((*images)[j].pixels); // Free previously allocated memory on failure
            }
            free(*images);
            return -2; // Memory allocation failed
        }

        total_memory_used += image_memory;
    }

    return path_count; // Return the number of images loaded successfully
}

int main() {
    char* paths[MAX_IMG_COUNT];
    for (int i = 0; i < MAX_IMG_COUNT; ++i) {
        paths[i] = (char*)malloc(256);
        sprintf(paths[i], "image%d.jpg", i); // Simulated image paths
    }

    img_t* images;
    int result = load_images(paths, MAX_IMG_COUNT, MAX_IMG_COUNT, MEMORY_LIMIT, &images);

    if (result >= 0) {
        printf("Loaded %d images successfully.\n", result);
        for (int i = 0; i < result; ++i) {
            free(images[i].pixels);
        }
        free(images);
    } else {
        printf("Failed to load images. Error code: %d\n", result);
    }

    for (int i = 0; i < MAX_IMG_COUNT; ++i) {
        free(paths[i]);
    }

    return 0;
}
