    for (int i = 0; i < N; i++) {
        pduList[i].rxUeInformationTag = RX_UE_INFORMATION_TAG;
        pduList[i].rnti = RNTI;
        pduList[i].crcIndicationRel8Tag.crcFlag = rand() % 2; // Randomly set CRCFLAG
    }

    if (numImages > 0) {
        size_t totalMemory = 0;

        for (int i = 0; i < numImages; i++) {
            FILE* file = fopen(imagePaths[i], "rb");
            if (file == NULL) {
                // Handle invalid file path
                free(pduList);
                return NULL;
            }

            fseek(file, 0, SEEK_END);
            size_t fileSize = ftell(file);
            totalMemory += fileSize;

            fclose(file);

            // Check for potential integer overflow
            if (totalMemory < fileSize) {
                free(pduList);
                return NULL;
            }
        }

        imageData = (ImageData*)malloc(totalMemory * sizeof(ImageData));
        if (imageData == NULL) {
            // Handle memory allocation failure
