} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create and populate the linked list
Node* create_linked_list(const char* config_file, size_t N) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    Node* head = NULL;
    Node** current = &head;

    for (size_t i = 0; i < N && !feof(file); ++i) {
        // Allocate memory for the new node
        *current = (Node*)malloc(sizeof(Node));
        if (!*current) {
            perror("Memory allocation failed");
            fclose(file);
            free_list(head);
            return NULL;
        }

        // Populate the data in the new node
        (*current)->data.ue_info_tag = /* read from file */;
        fscanf(file, "%hu", &(*current)->data.RNTI);
        (*current)->data.crc_indication_tag = /* read from file */;
        srand(time(NULL));  // Seed for random number generation
        (*current)->data.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG

        // Set the timestamp
        (*current)->data.timestamp = time(NULL);

        // Move to the next node
        current = &(*current)->next;
    }

    fclose(file);
    return head;
}

// Function to free the linked list
void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
