void init_memory_pool(MemoryPool *pool, size_t initial_capacity) {
    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->pool = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pool->pool == NULL) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void resize_memory_pool(MemoryPool *pool, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pool == NULL) {
        perror("Failed to reallocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    pool->pool = new_pool;
    pool->capacity = new_capacity;
}

int allocate_from_memory_pool(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity == 0 ? MAX_POOL_SIZE : pool->capacity * 2;
        resize_memory_pool(pool, new_capacity);
    }
    *item = pool->pool[pool->size++];
    pthread_mutex_unlock(&pool->lock);
