void* process_packet(PacketHeader header, void** memory_pool, size_t* pool_size) {
    if (header.payload_length > MAX_PACKET_SIZE) {
        printf("Error: Payload length exceeds maximum packet size.\n");
        return NULL;
    }

    // Calculate the required memory for the payload
    size_t required_memory = sizeof(PacketHeader) + header.payload_length;

    if (*pool_size < required_memory) {
        printf("Error: Memory limit exceeded. Unable to process packet.\n");
        return NULL;
    }

    // Allocate memory from the pool
    void* payload_ptr = *memory_pool;
    *memory_pool += required_memory;
    *pool_size -= required_memory;

    // Fill the payload with random data
    srand(time(NULL));
    for (size_t i = 0; i < header.payload_length; ++i) {
