    for (int i = 0; i < numCards * maxPdusPerCard; ++i) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            while (head) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
