        newNode->data.RNTI = rand() % 256; // Example range
        newNode->data.CRCFLAG = rand() % 2; // Randomly set to 0 or 1

        *current = newNode;
        current = &newNode->next;
    }

    *current = NULL;
    return head;
}

void serializeLinkedList(Node* head, const char* filename) {
