#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 1000
#define DEFAULT_TIMEOUT 5

typedef struct {
    int rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct QueueNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct QueueNode* next;
} QueueNode;

typedef struct {
    QueueNode* front;
    QueueNode* rear;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ThreadPoolQueue;

void initialize_queue(ThreadPoolQueue* queue) {
    queue->front = NULL;
    queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

void enqueue(ThreadPoolQueue* queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) {
        // Handle allocation failure
        return;
    }
    newNode->pdu = pdu;
    newNode->next = NULL;
    if (queue->rear) {
        queue->rear->next = newNode;
    } else {
        queue->front = newNode;
    }
    queue->rear = newNode;
    queue->size++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(ThreadPoolQueue* queue) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    QueueNode* node = queue->front;
    pdu = node->pdu;
    if (queue->front == queue->rear) {
        queue->front = NULL;
        queue->rear = NULL;
    } else {
        queue->front = node->next;
    }
    free(node);
    queue->size--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return pdu;
}

void* worker_thread(void* arg) {
    ThreadPoolQueue* queue = (ThreadPoolQueue*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = dequeue(queue);
        // Process the PDU
        // Handle potential errors during processing
    }
    return NULL;
}

int main() {
    int num_structures = 100;
    ThreadPoolQueue queue;
    initialize_queue(&queue);

    pthread_t* threads = (pthread_t*)malloc(num_structures * sizeof(pthread_t));
    if (!threads) {
        // Handle allocation failure
        return -1;
    }

    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_information_tag = rand() % 1000;
        pdu.rnti = rand() % 65535;
        pdu.crc_indication_rel8_flag = (rand() % 2);

        enqueue(&queue, pdu);
    }

    for (int i = 0; i < num_structures; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &queue);
    }

    for (int i = 0; i < num_structures; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);

    return 0;
}
