RandomRangeGenerator* createRandomRangeGenerator(int min, int max) {
    if (max < min) {
        return NULL; // Invalid range
    }
    RandomRangeGenerator* generator = (RandomRangeGenerator*)malloc(sizeof(RandomRangeGenerator));
    if (!generator) {
        return NULL; // Memory allocation failed
    }
    generator->minVal = min;
    generator->maxVal = max;
    return generator;
}

float generateFloatInRange(RandomRangeGenerator* generator) {
    return ((float)(rand() % (generator->maxVal - generator->minVal + 1))) / RAND_MAX * (generator->maxVal - generator->minVal) + generator->minVal;
}

int generateIntInRange(RandomRangeGenerator* generator) {
    return rand() % (generator->maxVal - generator->minVal + 1) + generator->minVal;
}

void destroyRandomRangeGenerator(RandomRangeGenerator* generator) {
