#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int find_max_integer(int* array, size_t length) {
    if (length == 0) return INT_MIN;
    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

NFAPI_CRC_INDICATION_PDU_T* populate_crc_indications(size_t N, size_t M, size_t max_mem) {
    if (M == 0 || max_mem == 0) return NULL;

    // Calculate the required memory for the integer array and CRC structures
    size_t array_size = M * sizeof(int);
    size_t struct_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_size = array_size + struct_size;

    if (total_size > max_mem) {
        fprintf(stderr, "Not enough memory available.\n");
        return NULL;
    }

    // Allocate memory for the integer array
    int* integers = malloc(array_size);
    if (!integers) {
        fprintf(stderr, "Failed to allocate memory for integer array.\n");
        return NULL;
    }

    // Read integers from standard input
    size_t read_count = 0;
    while (read_count < M && scanf("%d", &integers[read_count]) == 1) {
        ++read_count;
    }
    if (read_count != M) {
        fprintf(stderr, "Failed to read the required number of integers.\n");
        free(integers);
        return NULL;
    }

    // Find the maximum integer in the array
    int max_int = find_max_integer(integers, read_count);

    // Allocate memory for the CRC structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = malloc(struct_size);
    if (!crc_indications) {
        fprintf(stderr, "Failed to allocate memory for CRC structures.\n");
        free(integers);
        return NULL;
    }

    // Populate the CRC structures
    for (size_t i = 0; i < N; ++i) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % max_int + 1;
        crc_indications[i].RNTI = rand() % max_int + 1;
        crc_indications[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 0 : 1; // Randomly set CRCFLAG
    }

    // Free the integer array memory
    free(integers);

    return crc_indications;
}
