    pthread_t threads[16];
    ImageMeta** meta_array = malloc(sizeof(ImageMeta*) * (num_images + 1));
    meta_array[0] = NULL;

    for (int i = 1; i <= num_images; i++) {
        meta_array[i] = malloc(sizeof(ImageMeta));
        strncpy(meta_array[i]->path, file_paths[i - 1], MAX_IMAGE_PATH - 1);
