    for (int i = 0; i < 16; i++) {
        int indices[2];
        indices[0] = batch_size;
        indices[1] = (ImageMeta**)meta_array;
        pthread_create(&threads[i], NULL, process_images, &indices);
    }

    for (int i = 0; i < 16; i++) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
