#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to hold metadata and pixel data
typedef struct ImageFile {
    char* filename;
    size_t metadata_size;
    void* metadata;
    size_t pixel_data_size;
    void* pixel_data;
    int validation_error;
} ImageFile;

// Define a structure for the buffer pool
typedef struct BufferPool {
    size_t buffer_size;
    void** buffers;
    size_t buffer_count;
    size_t available_buffers;
} BufferPool;

// Initialize the buffer pool
void init_buffer_pool(BufferPool* pool, size_t buffer_size, size_t initial_count) {
    pool->buffer_size = buffer_size;
    pool->buffers = (void**)malloc(initial_count * sizeof(void*));
    pool->buffer_count = initial_count;
    pool->available_buffers = initial_count;

    for (size_t i = 0; i < initial_count; ++i) {
        pool->buffers[i] = malloc(buffer_size);
    }
}

// Get a buffer from the pool
void* get_buffer(BufferPool* pool) {
    if (pool->available_buffers == 0) {
        // Resize the pool by doubling its size
        pool->buffer_count *= 2;
        pool->buffers = (void**)realloc(pool->buffers, pool->buffer_count * sizeof(void*));

        for (size_t i = pool->buffer_count / 2; i < pool->buffer_count; ++i) {
            pool->buffers[i] = malloc(pool->buffer_size);
        }
    }

    void* buffer = pool->buffers[pool->available_buffers - 1];
    --pool->available_buffers;
    return buffer;
}

// Return a buffer to the pool
void return_buffer(BufferPool* pool, void* buffer) {
    pool->buffers[pool->available_buffers++] = buffer;
}

// Function to process an image file
int process_image_file(ImageFile* file, BufferPool* pool) {
    // Validate metadata and pixel data against schema
    if (validate_metadata(file->metadata, file->metadata_size)) {
        file->validation_error = 1;
        return -1; // Validation failed
    }

    if (validate_pixel_data(file->pixel_data, file->pixel_data_size)) {
        file->validation_error = 1;
        return -2; // Validation failed
    }

    // Process the image data using buffers from the pool
    void* buffer = get_buffer(pool);
    memcpy(buffer, file->metadata, file->metadata_size);
    process_pixel_data(file->pixel_data, file->pixel_data_size, buffer);

    // Return buffer to the pool after processing
    return_buffer(pool, buffer);

    return 0; // Processing successful
}

// Function to add an image file to the list and process it
int add_and_process_image_file(ImageFile* files, size_t* count, BufferPool* pool, char* filename) {
    ImageFile new_file;
    new_file.filename = filename;

    // Read metadata and pixel data from the file
    read_metadata(&new_file);
    read_pixel_data(&new_file);

    // Process the image file
    int result = process_image_file(&new_file, pool);

    if (result != 0) {
        // Handle validation or processing failure
        files[*count].validation_error = new_file.validation_error;
        return result;
    }

    // Add the processed file to the list
    files[*count] = new_file;
    ++(*count);

    return 0; // File added and processed successfully
}

// Function to summarize successful and failed operations
void summarize_operations(ImageFile* files, size_t count) {
    int successful_count = 0;
    for (size_t i = 0; i < count; ++i) {
        if (files[i].validation_error == 0) {
            ++successful_count;
        }
    }

    printf("Successful operations: %d\n", successful_count);
    printf("Failed operations: %zu\n", count - successful_count);
}

// Main function to demonstrate the usage
int main() {
    const size_t max_files = 100;
    ImageFile files[max_files];
    BufferPool pool;

    init_buffer_pool(&pool, 4096, 10); // Example buffer size and initial count

    // Add and process image files incrementally
    for (size_t i = 0; i < max_files; ++i) {
        char filename[256];
        snprintf(filename, sizeof(filename), "image%d.jpg", i);
        add_and_process_image_file(files, &i, &pool, filename);
    }

    // Summarize operations
    summarize_operations(files, max_files);

    return 0;
}
```

