#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_TAG_ID 1000
#define MIN_RNTI 1
#define MAX_RNTI 16777215

typedef struct {
    uint32_t tag_id;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    uint32_t rnti;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indications(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of structures: %d\n", N);
        return NULL;
    }

    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * (size_t)N;
    if (total_size / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Integer overflow detected during memory allocation\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(total_size);
    if (!list) {
        perror("Failed to allocate memory for NFAPI CRC indications");
        return NULL;
    }

    uint32_t tag_id_pool[MAX_TAG_ID + 1];
    memset(tag_id_pool, 0, sizeof(tag_id_pool));
    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        list[i].rx_tag.tag_id = tag_id_pool[0];
        while (tag_id_pool[list[i].rx_tag.tag_id] != 0) {
            list[i].rx_tag.tag_id = rand() % (MAX_TAG_ID + 1);
        }
        tag_id_pool[list[i].rx_tag.tag_id] = 1;

        if (list[i].rx_tag.tag_id > MAX_TAG_ID || list[i].rx_tag.tag_id < 0) {
            fprintf(stderr, "Invalid tag ID: %u\n", list[i].rx_tag.tag_id);
            free(list);
            return NULL;
        }

        list[i].rnti = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
        if (list[i].rnti < MIN_RNTI || list[i].rnti > MAX_RNTI) {
            fprintf(stderr, "Invalid RNTI: %u\n", list[i].rnti);
            free(list);
            return NULL;
        }

        list[i].crc_flag = rand() & 1;
    }

