    struct dirent *ent;
    ImageSet image_set = {NULL, 0};

    dir = opendir(".");
    if (dir != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (has_image_extension(ent->d_name)) {
                Image *image = allocate_image(ent->d_name);
                if (image) {
                    image_set.images = realloc(image_set.images, (image_set.count + 1) * sizeof(Image *));
                    image_set.images[image_set.count] = image;
                    image_set.count++;
                }
            }
        }
        closedir(dir);
    }

    pthread_t thread;
    pthread_create(&thread, NULL, process_images, &image_set);
    pthread_join(thread, NULL);

    // Free allocated memory
    for (int i = 0; i < image_set.count; i++) {
        free(image_set.images[i]);
    }
    free(image_set.images);

    return 0;
}
