pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;
uint8_t* memory_pool = NULL;
size_t pool_size = 0;
size_t used_memory = 0;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&memory_pool_lock);
    if (used_memory + size > pool_size) {
        pthread_mutex_unlock(&memory_pool_lock);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[used_memory];
    used_memory += size;
    pthread_mutex_unlock(&memory_pool_lock);
    return ptr;
}

void initialize_memory_pool(size_t initial_size) {
    pool_size = initial_size;
    memory_pool = (uint8_t*)malloc(pool_size);
    if (!memory_pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    used_memory = 0;
}

