        fprintf(stderr, "Invalid number of elements or memory limit exceeded.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdsch_pdu_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
