        while (1) {
            int tag = rand() % 1024; // Generate a random tag
            if (i == 0 || find(unique_tags, i, tag)) { // Check for uniqueness
                unique_tags[i] = tag;
                pdsch_pdu_array[i].ue_info.RX_UE_INFORMATION_TAG = tag;
                break;
