typedef struct Image {
    uint32_t width;
    uint32_t height;
    uint32_t channels;
    size_t size;
    uint8_t *data;
} Image;

Image* process_image(const char *filename, size_t initial_buffer_size) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    Image *image = (Image *)malloc(sizeof(Image));
    if (!image) goto cleanup_file;

    image->width = 0;
    image->height = 0;
    image->channels = 0;
    image->size = initial_buffer_size;
    image->data = (uint8_t *)malloc(image->size);
    if (!image->data) goto cleanup_image;

    size_t bytes_read = fread(image->data, sizeof(uint8_t), image->size, file);
    if (bytes_read < image->size) {
        size_t new_size = initial_buffer_size * 2;
        uint8_t *new_data = (uint8_t *)realloc(image->data, new_size);
        if (!new_data) goto cleanup_image;

        image->data = new_data;
        image->size = new_size;

        bytes_read += fread(image->data + bytes_read, sizeof(uint8_t), new_size - bytes_read, file);
    }

    fclose(file);

    return image;

cleanup_image:
    free(image->data);
cleanup_file:
    fclose(file);
    free(image);
    return NULL;
}
