#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct AESCipherContext {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[16];
} AESCipherContext;

int initializeNfadecrypt(int numStructs, const char *password, int hashAlgo, AESCipherContext **cipherCtx) {
    if (numStructs <= 0 || password == NULL) {
        return -1; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(numStructs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < numStructs; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 10000;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        list[i].CRCFLAG = rand() % 256;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        free(list);
        return -3; // Failed to create cipher context
    }

    unsigned char key[32];
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, 10000, hashAlgo, sizeof(key), key)) {
        EVP_CIPHER_CTX_free(ctx);
        free(list);
        return -4; // Failed to derive key
    }

    if (RAND_bytes(list->iv, sizeof(list->iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(list);
        return -5; // Failed to generate IV
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, list->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(list);
        return -6; // Failed to initialize cipher
    }

    *cipherCtx = malloc(sizeof(AESCipherContext));
    if (*cipherCtx == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        free(list);
        return -7; // Memory allocation failed for cipher context wrapper
    }
    (*cipherCtx)->ctx = ctx;
    memcpy((*cipherCtx)->iv, list->iv, sizeof(list->iv));

    free(list);
    return 0; // Success
}

void cleanupAESCipherContext(AESCipherContext *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}
