int manage_image_processing_and_crc_allocation(const char* metadata_file, const char* env_var_name) {
    FILE* file = fopen(metadata_file, "r");
    if (!file) return -1; // Failed to open metadata file

    int num_images;
    size_t total_memory_usage = 0;
    fscanf(file, "%d", &num_images);

    Image* images = (Image*)malloc(num_images * sizeof(Image));
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_images * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!images || !crc_indications) {
        free(images);
        free(crc_indications);
        fclose(file);
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < num_images; ++i) {
        size_t file_size;
        fscanf(file, "%255s %zu", images[i].filename, &file_size);

        if (file_size > MAX_IMAGE_SIZE || file_size + total_memory_usage > MAX_MEMORY_USAGE) {
            free(images);
            free(crc_indications);
            fclose(file);
            return -1; // Invalid file size or memory overflow
        }

        total_memory_usage += file_size;

        images[i].width = rand() % 8000; // Random width between 0 and 7999 pixels
        images[i].height = rand() % 6000; // Random height between 0 and 5999 pixels

        crc_indications[i].RX_UE_INFORMATION_TAG = (unsigned int)rand();
        crc_indications[i].RNTI = (unsigned short)rand();
        crc_indications[i].CRC_INDICATION_REL8_TAG = (unsigned char)rand();
    }

    fclose(file);

    // Create directory if not exists
    DIR* dir = opendir(env_var_name);
    if (!dir) {
        mkdir(env_var_name, 0755);
        putenv(strdup((char*)malloc(strlen(env_var_name) + 10)));
        sprintf(getenv(env_var_name), "%s", env_var_name);
    }

    // Free allocated memory
    free(images);
    free(crc_indications);

    return num_images;
}
