        list[i].crc_indication_rel8_tag = rand();
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return list;
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int num_structures, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed for serialization");
        return;
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_structures, file);
    fclose(file);
}

int deserialize_list(NFAPI_CRC_INDICATION_PDU_T** list, int* num_structures, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("File opening failed for deserialization");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *num_structures = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (*num_structures <= 0) {
        fprintf(stderr, "Error: Invalid file size for deserialization\n");
        fclose(file);
        return -1;
    }

    // Check for potential integer overflow
    if ((long long)*num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T) < *num_structures) {
        fprintf(stderr, "Error: Integer overflow detected during deserialization\n");
        fclose(file);
        return -1;
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        perror("Memory allocation failed for deserialization");
        fclose(file);
        return -1;
    }

    fread(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *num_structures, file);
    fclose(file);

    return 0;
}
