#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int width;
    int height;
    char format[10];
    void* pixel_data;
} ImageProcessingStructure;

typedef struct {
    ImageProcessingStructure** structures;
    size_t count;
    size_t max_count;
    size_t memory_limit;
    pthread_mutex_t mutex;
} ImageList;

ImageList* create_image_list(size_t initial_capacity, size_t memory_limit) {
    ImageList* list = (ImageList*)malloc(sizeof(ImageList));
    if (!list) return NULL;

    list->structures = (ImageProcessingStructure**)calloc(initial_capacity, sizeof(ImageProcessingStructure*));
    if (!list->structures) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->max_count = initial_capacity;
    list->memory_limit = memory_limit;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_image_list(ImageList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->structures[i]->pixel_data);
        free(list->structures[i]);
    }
    free(list->structures);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_image(ImageList* list, int width, int height, char* format) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_count) {
        size_t new_capacity = list->max_count * 2;
        ImageProcessingStructure** new_structures = (ImageProcessingStructure**)realloc(list->structures, new_capacity * sizeof(ImageProcessingStructure*));
        if (!new_structures) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->structures = new_structures;
        list->max_count = new_capacity;
    }

    size_t pixel_data_size = width * height * 3; // Assuming RGB format
    void* pixel_data = malloc(pixel_data_size);
    if (!pixel_data) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }

    list->structures[list->count] = (ImageProcessingStructure*)malloc(sizeof(ImageProcessingStructure));
    if (!list->structures[list->count]) {
        free(pixel_data);
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }

    list->structures[list->count]->width = width;
    list->structures[list->count]->height = height;
    strcpy(list->structures[list->count]->format, format);
    list->structures[list->count]->pixel_data = pixel_data;

    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void monitor_memory_usage(ImageList* list) {
    size_t total_memory_used = 0;
    for (size_t i = 0; i < list->count; ++i) {
        total_memory_used += list->structures[i]->width * list->structures[i]->height * 3;
    }
    printf("Total memory used: %zu bytes\n", total_memory_used);
}

