    char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdus(int N) {
    if (N <= 0 || N > MAX_PDUS) {
        printf("Invalid number of PDUs. Must be between 1 and %d.\n", MAX_PDUS);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
