        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Assuming RX_UE_INFORMATION_TAG is within 0-999
        pdus[i].RNTI = (unsigned short)(rand() % 65535); // RNTI is a 16-bit unsigned integer
        pdus[i].CRC_INDICATION_REL8_TAG = (char)(rand() % 2); // CRCFLAG can be 0 or 1
    }

    return pdus;
}

