#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct PacketHeader {
    int payload_length;
    char *payload_buffer;
    struct PacketHeader *next;
} PacketHeader;

typedef struct {
    size_t max_memory_usage_per_packet;
    pthread_mutex_t lock;
    PacketHeader *head;
} PacketQueue;

PacketQueue* create_packet_queue(size_t max_memory) {
    PacketQueue *queue = (PacketQueue *)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->max_memory_usage_per_packet = max_memory;
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_packet_queue(PacketQueue *queue) {
    PacketHeader *current = queue->head;
    while (current != NULL) {
        PacketHeader *next = current->next;
        free(current->payload_buffer);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int enqueue_packet(PacketQueue *queue, int payload_length, const char *payload_data) {
    pthread_mutex_lock(&queue->lock);

    if (payload_length > queue->max_memory_usage_per_packet) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Exceeds maximum memory usage per packet
    }

    PacketHeader *new_packet = (PacketHeader *)malloc(sizeof(PacketHeader));
    if (!new_packet) {
        pthread_mutex_unlock(&queue->lock);
        return -2; // Memory allocation failed
    }

    new_packet->payload_length = payload_length;
    new_packet->payload_buffer = (char *)malloc(payload_length * sizeof(char));
    if (!new_packet->payload_buffer) {
        free(new_packet);
        pthread_mutex_unlock(&queue->lock);
        return -3; // Payload buffer allocation failed
    }

    memcpy(new_packet->payload_buffer, payload_data, payload_length);
    new_packet->next = queue->head;
    queue->head = new_packet;

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

PacketHeader* dequeue_packet(PacketQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    if (queue->head == NULL) {
        pthread_mutex_unlock(&queue->lock);
        return NULL; // No packets available
    }

    PacketHeader *packet = queue->head;
    queue->head = packet->next;

    pthread_mutex_unlock(&queue->lock);

    return packet;
}

void free_packet(PacketHeader *packet) {
    if (packet != NULL) {
        free(packet->payload_buffer);
        free(packet);
    }
}
