typedef struct {
    void* memory;
    size_t allocated;
    size_t max_memory;
} MemoryManager;

MemoryManager manager;

void init_memory_manager(size_t max_memory) {
    manager.memory = malloc(max_memory);
    if (manager.memory == NULL) {
        // Handle allocation failure
    }
    manager.allocated = 0;
    manager.max_memory = max_memory;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (manager.allocated + pdu_size > manager.max_memory) {
        // Handle memory allocation failure
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)(manager.memory + manager.allocated);
    manager.allocated += pdu_size;
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Assuming all PDUs are allocated contiguously
    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((char*)pdu + pdu_size > (char*)manager.memory + manager.allocated) {
        // Handle invalid pointer
        return;
    }
    manager.allocated -= pdu_size;
}

void* allocate_memory(size_t size) {
    void* ptr = realloc(manager.memory, manager.allocated + size);
    if (ptr == NULL) {
        // Handle allocation failure
        return NULL;
    }
    manager.memory = ptr;
    manager.allocated += size;
    return ptr;
}

void free_memory(void* ptr) {
    size_t size_to_free = manager.allocated - ((char*)ptr - (char*)manager.memory);
    if (size_to_free > manager.allocated || ptr < manager.memory || ptr >= (char*)manager.memory + manager.allocated) {
        // Handle invalid pointer
        return;
    }
    manager.allocated -= size_to_free;
}

pthread_mutex_t lock;

void* allocate_thread_safe(size_t size) {
    pthread_mutex_lock(&lock);
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation failure
    }
    pthread_mutex_unlock(&lock);
    return ptr;
}

void free_thread_safe(void* ptr) {
    pthread_mutex_lock(&lock);
    free(ptr);
    pthread_mutex_unlock(&lock);
}
