NFAPI_CRC_INDICATION_PDU_T* allocate_napi_pdu(int num_structures, int max_retries) {
    size_t chunk_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;

    for (int retry = 0; retry < max_retries; ++retry) {
        // Calculate the total memory required
        size_t total_memory = num_structures * chunk_size;

        // Check for integer overflow
        if (num_structures > SIZE_MAX / chunk_size) {
            printf("Error: Integer overflow in memory allocation calculation.\n");
            return NULL;
        }

        // Attempt to allocate memory
        pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory);
        if (pdus != NULL) {
            break; // Success, exit the loop
        }

        printf("Attempt %d: Memory allocation failed. Retrying...\n", retry + 1);
    }

    if (pdus == NULL) {
        printf("Error: Failed to allocate memory after %d retries.\n", max_retries);
        return NULL;
    }

    // Initialize the structures
    for (int i = 0; i < num_structures; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = rand() % 1024; // Random RNTI between 0 and 1023
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRCFLAG (0 or 1)
    }

    return pdus;
}

void free_napi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdus, int num_structures) {
