#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_linked_list(size_t initial_size) {
    if (initial_size == 0 || initial_size > SIZE_MAX / sizeof(Node)) {
        return NULL; // Handle invalid initial size
    }

    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&list->mutex, &attr);

    for (size_t i = 0; i < initial_size; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            destroy_linked_list(list);
            return NULL; // Memory allocation failed
        }

        list->head = new_node;
        list->size++;
    }

    return list;
}

void destroy_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void remove_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T key) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;

    while (current && !(current->data == key)) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        return; // Key not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

size_t get_list_size(LinkedList* list) {
    size_t size = 0;
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        size++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return size;
}
