#include <string.h>

#define MAX_PACKET_SIZE 1024

typedef struct NetworkPacket {
    char *payload;
    size_t payload_size;
    struct NetworkPacket *next;
} NetworkPacket;

NetworkPacket* create_network_packet(const char *payload, size_t payload_size) {
    if (payload_size > MAX_PACKET_SIZE) {
        return NULL; // Prevent excessively large packets
    }

    NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
    if (!packet) {
        return NULL; // Handle memory allocation failure
    }

    packet->payload = (char *)malloc(payload_size);
    if (!packet->payload) {
        free(packet); // Clean up partially allocated packet
        return NULL;
    }

    memcpy(packet->payload, payload, payload_size);
    packet->payload_size = payload_size;
    packet->next = NULL;

    return packet;
}

void free_network_packet(NetworkPacket *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

NetworkPacket* process_packets(const char **headers, size_t num_headers, size_t max_payload_size) {
    NetworkPacket *head = NULL;
    NetworkPacket *tail = NULL;

    for (size_t i = 0; i < num_headers; ++i) {
        const char *header = headers[i];
        size_t payload_size = strlen(header); // Example: header length as payload size

        if (payload_size > max_payload_size || payload_size > MAX_PACKET_SIZE) {
            continue; // Skip invalid or excessively large packets
        }

        NetworkPacket *packet = create_network_packet(header, payload_size);
        if (!packet) {
            free_network_packets(head); // Free already allocated packets on error
            return NULL;
        }

        if (head == NULL) {
            head = packet;
        } else {
            tail->next = packet;
        }
        tail = packet;
    }

    return head;
}

void free_network_packets(NetworkPacket *head) {
    NetworkPacket *current = head;
    while (current) {
        NetworkPacket *next = current->next;
        free_network_packet(current);
        current = next;
    }
}
