NFAPI_CRC_INDICATION_PDU_T* generateNFAPDUs(int numImages, int maxLayers) {
    if (numImages <= 0 || maxLayers <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(numImages * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory for PDUs");
        return NULL;
