int parse_config_file(const char *filename, int *num_images, int *layers_per_image) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    fscanf(file, "%d %d", num_images, layers_per_image);
    fclose(file);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* populate_array(int num_images, int layers_per_image, int *num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_images * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (int i = 0; i < num_images; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        int image_size = layers_per_image * sizeof(int);
        array[i].image_data = (int*)malloc(image_size);
        if (!array[i].image_data) {
            free(array);
            return NULL;
        }
        for (int j = 0; j < layers_per_image; j++) {
            array[i].image_data[j] = rand();
        }

        int metadata_size = sizeof(int);
        array[i].metadata = (int*)malloc(metadata_size);
        if (!array[i].metadata) {
            free(array[i].image_data);
            free(array);
            return NULL;
        }
        *array[i].metadata = i;
    }

    *num_elements = num_images;
    return array;
}

void clean_up(NFAPI_CRC_INDICATION_PDU_T *array, int num_images) {
    for (int i = 0; i < num_images; i++) {
        free(array[i].image_data);
        free(array[i].metadata);
    }
    free(array);
}

int main() {
    int num_images, layers_per_image;
    if (parse_config_file("config.txt", &num_images, &layers_per_image) != 0) {
        printf("Error parsing config file\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = populate_array(num_images, layers_per_image, NULL);
    if (!array) {
        printf("Error populating array\n");
        return -1;
    }

    // Use the array as needed
    clean_up(array, num_images);

    return 0;
}
