typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
    size_t max_size;
} LinkedList;

LinkedList* create_linked_list(size_t max_size) {
    if (max_size == 0) {
        return NULL; // Invalid max_size
    }
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        return NULL; // Memory allocation failed
    }
    list->head = list->tail = NULL;
    list->count = 0;
    list->max_size = max_size;
    return list;
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= list->max_size) {
        return -1; // List is full
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return -2; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = NULL;
    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    return 0; // Success
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Example usage:
int main() {
    size_t max_size = 1000; // Maximum number of structures
    LinkedList* list = create_linked_list(max_size);
    if (list == NULL) {
        fprintf(stderr, "Failed to create linked list\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {12345, 67890, 1};
    int result = add_to_list(list, pdu);
    if (result != 0) {
        fprintf(stderr, "Failed to add to list: %d\n", result);
        free_list(list);
        return 1;
    }

    // Continue adding elements as needed...

    free_list(list);
    return 0;
}
