    TASK_PRIORITY_HIGH,
    TASK_PRIORITY_LOW
} TaskPriority;

typedef struct {
    TileData tile_data;
    TaskPriority priority;
} ImageTask;

ImageTask task_queue[MAX_TASKS];
int task_count = 0;
int free_slots = MAX_TASKS;

void enqueue_task(const TileData *tile_data, TaskPriority priority) {
    if (task_count >= MAX_TASKS || free_slots <= 0) return;

    task_queue[task_count++] = (ImageTask){*tile_data, priority};
    free_slots--;
}

bool dequeue_task(ImageTask *task) {
    if (task_count == 0) return false;

    *task = task_queue[--task_count];
    free_slots++;
    return true;
}

void process_image_tasks() {
    while (dequeue_task(&task)) {
        // Simulate processing
        printf("Processing tile with metadata size %u and buffer size %u\n",
               task.tile_data.metadata_size, task.tile_data.buffer_size);
    }
}

uint32_t calculate_tile_memory(const TileData *tile_data) {
    uint64_t total_memory = (uint64_t)tile_data->metadata_size + (uint64_t)tile_data->buffer_size;

    if (total_memory > UINT32_MAX) {
        fprintf(stderr, "Memory allocation too large\n");
        return 0;
    }

    return (uint32_t)total_memory;
}

