        tile_data.metadata_size = rand() % 1024;
        tile_data.buffer_size = rand() % 4096;

        uint32_t memory_required = calculate_tile_memory(&tile_data);
        if (memory_required > available_memory) {
            // Adjust priority or defer non-critical operations
            continue;
        }

        enqueue_task(&tile_data, TASK_PRIORITY_HIGH);
    }

    process_image_tasks();
}

int main() {
