void process_files(int argc, char **argv) {
    const char *crc_dir = getenv("CRC_DIR");
    if (!crc_dir) {
        crc_dir = "default_crc_directory";
        mkdir(crc_dir, 0755);
    }

    DIR *dir;
    struct dirent *entry;
    dir = opendir(crc_dir);
    if (!dir) {
        log_error("Failed to open directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".nfa")) {
            char file_path[256];
            snprintf(file_path, sizeof(file_path), "%s/%s", crc_dir, entry->d_name);

            int fd = open(file_path, O_RDONLY);
            if (fd == -1) {
                log_error("Failed to open file");
                continue;
            }

            off_t file_size = lseek(fd, 0, SEEK_END);
            if (file_size == -1 || file_size > INT_MAX) {
                close(fd);
                log_error("File size too large or invalid");
                continue;
            }

            lseek(fd, 0, SEEK_SET);
            NFAPI_CRC_INDICATION_PDU_T *last_pdu = NULL;
            off_t offset = 0;
            size_t pdu_size;

            while ((last_pdu = read_pdu(fd, &pdu_size)) != NULL) {
                offset += pdu_size;
            }

            if (offset != file_size || last_pdu == NULL) {
                close(fd);
                log_error("Invalid file format");
                continue;
            }

            uint32_t calculated_crc = crc32_checksum(file_path, file_size);
            if (calculated_crc != last_pdu->crc_value) {
                log_error("CRC mismatch in file");
            } else {
                printf("File %s is valid\n", file_path);
            }

            free(last_pdu);
            close(fd);
        }
    }

    closedir(dir);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [file1] [file2] ...\n", argv[0]);
        return 1;
    }

    process_files(argc, argv);

    return 0;
}
