    char data[MAX_PACKET_SIZE];
    size_t length;
    struct Packet* next;
} Packet;

typedef struct LinkedList {
    Packet* head;
    Packet* tail;
    size_t current_memory_usage;
    size_t memory_limit;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->current_memory_usage = 0;
    list->memory_limit = MAX_MEMORY_LIMIT;
    return list;
}

void add_packet(LinkedList* list, const char* data, size_t length) {
    if (length > MAX_PACKET_SIZE) {
        printf("Packet too large\n");
        return;
    }

    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) {
        printf("Memory allocation failed\n");
        return;
    }

    memcpy(new_packet->data, data, length);
    new_packet->length = length;
    new_packet->next = NULL;

    if (!list->head) {
        list->head = list->tail = new_packet;
    } else {
        list->tail->next = new_packet;
        list->tail = new_packet;
    }

    list->current_memory_usage += length;

    if (list->current_memory_usage > list->memory_limit) {
        printf("Memory limit exceeded\n");
        remove_packets(list, list->head);
    }
}

void remove_packets(LinkedList* list, Packet* start) {
    while (start != NULL) {
        Packet* next = start->next;
        free(start);
        start = next;
        list->current_memory_usage -= AVG_PACKET_SIZE; // Approximate
    }
    list->head = list->tail = NULL;
}

void destroy_linked_list(LinkedList* list) {
    remove_packets(list, list->head);
    free(list);
}
