Packet* create_packet(uint32_t id, uint64_t timestamp, const void* payload, size_t length) {
    if (length > SIZE_MAX - sizeof(Packet)) {
        fprintf(stderr, "Payload length too large to allocate\n");
        return NULL;
    }

    Packet* packet = malloc(sizeof(Packet) + length);
    if (!packet) {
        perror("Failed to allocate memory for packet");
        return NULL;
    }

    packet->id = id;
    packet->timestamp = timestamp;
    packet->payload_length = length;
    memcpy(packet->payload, payload, length);

    return packet;
}

void destroy_packet(Packet* packet) {
    if (packet) {
        free(packet);
    }
}

