    uint64_t timestamp = 1633075200; // Example timestamp
    const char payload[] = "Hello, World!";
    size_t length = strlen(payload) + 1;

    Packet* packet = create_packet(id, timestamp, payload, length);
    if (packet) {
        printf("Packet created with ID: %u\n", packet->id);
        destroy_packet(packet);
    }

    return 0;
}
