#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024 * 64 // Maximum payload size for a packet

typedef struct Packet {
    int id;
    unsigned long timestamp;
    int payload_length;
    char* payload;
    struct Packet* next;
    struct Packet* prev;
} Packet;

typedef struct MemoryPool {
    void* start;
    void* end;
    void* current;
    size_t block_size;
    size_t free_blocks;
} MemoryPool;

Packet* create_packet(MemoryPool* pool, int id, unsigned long timestamp, const char* payload) {
    if (pool->current + pool->block_size > pool->end) {
        return NULL; // Memory pool exhausted
    }
    Packet* packet = (Packet*)pool->current;
    packet->id = id;
    packet->timestamp = timestamp;
    packet->payload_length = strlen(payload);
    packet->payload = malloc(packet->payload_length + 1); // Allocate memory for payload
    if (!packet->payload) {
        return NULL; // Memory allocation failed
    }
    strcpy(packet->payload, payload);
    pool->current += pool->block_size;
    return packet;
}

void add_packet(Packet** head, Packet* new_packet) {
    if (*head == NULL) {
        *head = new_packet;
        new_packet->next = new_packet->prev = NULL;
    } else {
        new_packet->next = *head;
        new_packet->prev = NULL;
        (*head)->prev = new_packet;
        *head = new_packet;
    }
}

Packet* get_packet_by_id(Packet* head, int id) {
    Packet* current = head;
    while (current != NULL) {
        if (current->id == id) {
            return current;
        }
        current = current->next;
    }
    return NULL; // Packet not found
}

void remove_packet(Packet** head, Packet* packet) {
    if (*head == packet) {
        *head = packet->next;
    }
    if (packet->prev != NULL) {
        packet->prev->next = packet->next;
    }
    if (packet->next != NULL) {
        packet->next->prev = packet->prev;
    }
    free(packet->payload);
    free(packet);
}

void reclaim_memory(MemoryPool* pool, size_t bytes_to_free) {
    while (pool->free_blocks > 0 && bytes_to_free > 0) {
        // Implement logic to find and free unused memory blocks
        pool->current -= pool->block_size;
        pool->free_blocks--;
        bytes_to_free -= pool->block_size;
    }
}

int main() {
    MemoryPool pool;
    pool.start = malloc(1024 * 1024 * 1024); // Allocate 1GB for memory pool
    pool.end = (char*)pool.start + 1024 * 1024 * 1024;
    pool.current = pool.start;
    pool.block_size = sizeof(Packet) + MAX_PACKET_SIZE + 1; // Adjust block size as needed
    pool.free_blocks = 1024 * 1024 / pool.block_size; // Calculate number of free blocks

    Packet* head = NULL;
    Packet* packet = create_packet(&pool, 1, 1633072800, "Hello, world!");
    add_packet(&head, packet);

    Packet* retrieved_packet = get_packet_by_id(head, 1);
    if (retrieved_packet) {
        printf("Retrieved packet: ID=%d, Payload='%s'\n", retrieved_packet->id, retrieved_packet->payload);
    }

    remove_packet(&head, retrieved_packet);

    reclaim_memory(&pool, pool.block_size); // Reclaim memory as needed

    free(pool.start);
    return 0;
}
