    if (num_paths <= 0 || !paths || out_count == NULL) {
        return NULL; // Invalid input
    }

    ImageMetadata **metadata_array = (ImageMetadata**)malloc(num_paths * sizeof(ImageMetadata*));
    if (!metadata_array) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_paths; ++i) {
        size_t path_len = strlen(paths[i]);
        if (path_len > INT_MAX) {
            free(metadata_array);
            return NULL; // Potential integer overflow
        }

        metadata_array[i] = (ImageMetadata*)malloc(sizeof(ImageMetadata));
        if (!metadata_array[i]) {
            for (int j = 0; j < i; ++j) {
                free(metadata_array[j]);
            }
            free(metadata_array);
            return NULL; // Memory allocation failed
        }

        metadata_array[i]->path = (char*)malloc((path_len + 1) * sizeof(char));
        if (!metadata_array[i]->path) {
            for (int j = 0; j <= i; ++j) {
                free(metadata_array[j]);
            }
            free(metadata_array);
            return NULL; // Memory allocation failed
        }

        strcpy(metadata_array[i]->path, paths[i]);
        metadata_array[i]->orientation = -1; // Default orientation
        metadata_array[i]->resolution = 0.0f; // Default resolution

        // Simulate loading metadata (e.g., reading from file)
        // For demonstration purposes, we'll set some dummy values
        if (i % 2 == 0) {
            metadata_array[i]->orientation = 90;
        } else {
            metadata_array[i]->orientation = 180;
        }
        metadata_array[i]->resolution = i * 3.0f + 72.0f; // Example resolution increment
    }

    *out_count = num_paths;
    return metadata_array;
}

// Example usage
