    int path_count = sizeof(paths) / sizeof(paths[0]);
    int result_count;

    ImageMetadata** metadata = process_image_metadata(path_count, paths, &result_count);
    if (metadata) {
        for (int i = 0; i < result_count; ++i) {
            printf("Path: %s, Orientation: %d, Resolution: %.2f\n",
                   metadata[i]->path, metadata[i]->orientation, metadata[i]->resolution);
            free(metadata[i]->path);
            free(metadata[i]);
        }
        free(metadata);
    } else {
        printf("Failed to process image metadata.\n");
    }

    return 0;
}
