            if (entry->d_type == DT_REG) { // Regular file
                char path[MAX_PATH_LENGTH];
                snprintf(path, sizeof(path), "%s/%s", ".", entry->d_name);
                unsigned char *hash = calculate_md5(path);
                ImageMetadata metadata;
                int tag_count = parse_xml("config.xml", &metadata);
                if (tag_count > 0) {
                    image_metadata = realloc(image_metadata, (count + 1) * sizeof(ImageMetadata));
                    memcpy(&image_metadata[count], &metadata, sizeof(ImageMetadata));
                    count++;
                }
                free(hash);
            }
        }
        closedir(dir);
    }

    // Process image metadata
    free_image_metadata(image_metadata, count);

    return 0;
}
