#include <string.h>

typedef struct {
    int id;
    size_t length;
    char* buffer;
} PacketInfo;

typedef struct {
    PacketInfo** packets;
    size_t count;
    size_t allocatedMemory;
    size_t maxMemory;
} PacketManager;

PacketManager* createPacketManager(size_t maxMemory) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;
    manager->packets = NULL;
    manager->count = 0;
    manager->allocatedMemory = 0;
    manager->maxMemory = maxMemory;
    return manager;
}

int addPacket(PacketManager* manager, int id, size_t length, const char* payload) {
    if (manager->allocatedMemory + length > manager->maxMemory) {
        printf("Memory limit exceeded.\n");
        return -1;
    }
    PacketInfo* packet = (PacketInfo*)malloc(sizeof(PacketInfo));
    if (!packet) return -1;
    packet->id = id;
    packet->length = length;
    packet->buffer = (char*)malloc(length);
    if (!packet->buffer) {
        free(packet);
        return -1;
    }
    memcpy(packet->buffer, payload, length);
    manager->packets = realloc(manager->packets, (manager->count + 1) * sizeof(PacketInfo*));
    if (!manager->packets) {
        free(packet->buffer);
        free(packet);
        return -1;
    }
    manager->packets[manager->count++] = packet;
    manager->allocatedMemory += length;
    return 0;
}

void freePacketManager(PacketManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]->buffer);
        free(manager->packets[i]);
    }
    free(manager->packets);
    free(manager);
}

int main() {
    PacketManager* manager = createPacketManager(1024 * 1024); // 1MB limit
    if (!manager) {
        fprintf(stderr, "Failed to initialize packet manager.\n");
        return 1;
    }

    addPacket(manager, 1, 100, "Hello");
    addPacket(manager, 2, 200, "World");

    freePacketManager(manager);
    return 0;
}
