typedef struct {
    size_t length;
    void* payload;
} PacketHeader;

PacketHeader* process_packets(const unsigned char* data, size_t total_size, size_t max_memory, size_t packet_overhead) {
    const size_t max_packets = max_memory / (packet_overhead + 1);
    PacketHeader* headers = malloc(max_packets * sizeof(PacketHeader));
    if (!headers) {
        return NULL;
    }

    size_t current_size = 0;
    size_t packet_count = 0;

    while (current_size < total_size && packet_count < max_packets) {
        const size_t packet_length = data[current_size++];
        if (packet_length == 0 || current_size + packet_length > total_size) {
            break; // Handle edge cases
        }

        headers[packet_count].length = packet_length;
        headers[packet_count].payload = malloc(packet_length);
        if (!headers[packet_count].payload) {
            free(headers);
            return NULL;
        }
        memcpy(headers[packet_count].payload, data + current_size, packet_length);

        current_size += packet_length;
        packet_count++;
    }

    headers = realloc(headers, packet_count * sizeof(PacketHeader));
    if (headers == NULL) {
        for (size_t i = 0; i < packet_count; i++) {
            free(headers[i].payload);
        }
        return NULL;
    }

    return headers;
}
