typedef struct {
    void* data;
    size_t size;
} PacketSubPacket;

typedef struct {
    PacketSubPacket** packets;
    size_t packet_count;
    size_t max_packets;
    pthread_mutex_t lock;
} NetworkPacketArray;

NetworkPacketArray* create_packet_array(size_t initial_size) {
    NetworkPacketArray* array = malloc(sizeof(NetworkPacketArray));
    if (array == NULL) return NULL;

    array->packets = calloc(initial_size, sizeof(PacketSubPacket*));
    if (array->packets == NULL) {
        free(array);
        return NULL;
    }

    array->packet_count = 0;
    array->max_packets = initial_size;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_packet_array(NetworkPacketArray* array) {
    for (size_t i = 0; i < array->packet_count; ++i) {
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_packet(NetworkPacketArray* array, PacketSubPacket* packet) {
    pthread_mutex_lock(&array->lock);

    if (array->packet_count >= array->max_packets) {
        size_t new_size = array->max_packets * 2;
        void** new_packets = realloc(array->packets, new_size * sizeof(PacketSubPacket*));
        if (new_packets == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->packets = new_packets;
        array->max_packets = new_size;
    }

    array->packets[array->packet_count++] = packet;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void iterate_packets(NetworkPacketArray* array, void (*callback)(PacketSubPacket*)) {
    for (size_t i = 0; i < array->packet_count; ++i) {
        callback(array->packets[i]);
    }
}
