typedef struct LinkedList {
    ListNode *head;
    uint32_t count;
    uint32_t maxNodes;
} LinkedList;

LinkedList* createLinkedList(uint32_t initialMaxNodes) {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->maxNodes = initialMaxNodes;

    return list;
}

int addNodeToLinkedList(LinkedList *list, NFAPI_CRC_INDICATION_PDU_T *newData) {
    if (list->count >= list->maxNodes) return -1; // Maximum nodes reached

    ListNode *newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return -2; // Memory allocation failed

    newNode->data = newData;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    return 0;
}

int ensureArrayCapacity(LinkedList *list, NFAPI_CRC_INDICATION_PDU_T **array, uint32_t *arraySize) {
    if (list->count >= *arraySize) {
        *arraySize *= 2; // Double the array size
        void *temp = realloc(*array, *arraySize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!temp) return -1; // Realloc failed

        *array = (NFAPI_CRC_INDICATION_PDU_T**)temp;
    }

    return 0;
}

void freeLinkedList(LinkedList *list) {
    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }
    free(list);
