typedef struct {
    char *name;
    size_t size;
    time_t mtime;
} FileMetadata;

FileMetadata* process_files(int argc, char *argv[], size_t *total_size) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file_path>...\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Calculate the total memory required for the structure array
    size_t num_files = argc - 1;
    size_t metadata_size = num_files * sizeof(FileMetadata);

    if (metadata_size / num_files != sizeof(FileMetadata)) {
        fprintf(stderr, "Error: Integer overflow calculating memory requirements.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the structure array
    FileMetadata *metadata_array = malloc(metadata_size);
    if (!metadata_array) {
        perror("Failed to allocate memory for file metadata.");
        exit(EXIT_FAILURE);
    }

    *total_size = metadata_size;

    // Populate the metadata array with actual file data
    for (size_t i = 0; i < num_files; ++i) {
        struct stat file_stat;
        if (stat(argv[i + 1], &file_stat) != 0) {
            perror("Failed to get file statistics.");
            continue;
        }

        metadata_array[i].name = strdup(argv[i + 1]);
        metadata_array[i].size = file_stat.st_size;
        metadata_array[i].mtime = file_stat.st_mtime;

        if (!metadata_array[i].name) {
            perror("Failed to allocate memory for file name.");
            // Handle error gracefully, e.g., free previously allocated names
            continue;
        }
    }

    return metadata_array;
}

int main(int argc, char *argv[]) {
    size_t total_size;
    FileMetadata *metadata = process_files(argc, argv, &total_size);

    // Use the metadata array as needed...

    // Clean up dynamically allocated memory
    for (size_t i = 0; i < argc - 1; ++i) {
        free(metadata[i].name);
    }
    free(metadata);

    return 0;
}
