#include <pthread.h>

#define MAX_NODES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU **array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} LinkedListManager;

LinkedListManager* create_linkedListManager(size_t initial_size) {
    LinkedListManager *manager = (LinkedListManager*)malloc(sizeof(LinkedListManager));
    manager->array = (NFAPI_CRC_INDICATION_PDU**)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU*));
    manager->allocated_size = initial_size;
    manager->used_size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void free_linkedListManager(LinkedListManager *manager) {
    for (size_t i = 0; i < manager->used_size; ++i) {
        free(manager->array[i]);
    }
    free(manager->array);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int addNode(LinkedListManager *manager, NFAPI_CRC_INDICATION_PDU *node) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->used_size >= MAX_NODES || manager->used_size >= manager->allocated_size - 1) {
        size_t new_size = manager->allocated_size ? manager->allocated_size : 1;
        while (new_size <= manager->used_size + 1) {
            if (new_size > SIZE_MAX / 2) {
                pthread_mutex_unlock(&manager->mutex);
                return -1; // Handle integer overflow
            }
            new_size *= 2;
        }
        NFAPI_CRC_INDICATION_PDU **new_array = realloc(manager->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU*));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Handle memory allocation failure
        }
        manager->array = new_array;
        manager->allocated_size = new_size;
    }

    manager->array[manager->used_size++] = node;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU* createNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU *node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void freeNode(NFAPI_CRC_INDICATION_PDU *node) {
    free(node);
}

int main() {
    LinkedListManager *manager = create_linkedListManager(10);

    for (int i = 0; i < MAX_NODES + 5; ++i) {
        NFAPI_CRC_INDICATION_PDU *node = createNode(i, i * 10, i % 3);
        if (addNode(manager, node) != 0) {
            printf("Failed to add node\n");
            break;
        }
    }

    for (size_t i = 0; i < manager->used_size; ++i) {
        freeNode(manager->array[i]);
    }

    free_linkedListManager(manager);
    return 0;
}
