    if (metadata_count >= max_entries) {
        int new_max_entries = max_entries * 2;
        IMAGE_METADATA_T** new_array = (IMAGE_METADATA_T**)realloc(image_metadata_array, sizeof(IMAGE_METADATA_T*) * new_max_entries);
        if (new_array == NULL) {
            fprintf(stderr, "Failed to reallocate memory for image metadata array\n");
            exit(EXIT_FAILURE);
