    if (image_metadata_array[metadata_count] == NULL) {
        fprintf(stderr, "Failed to allocate memory for individual metadata entry\n");
        exit(EXIT_FAILURE);
    }
    memcpy(image_metadata_array[metadata_count], new_metadata, sizeof(IMAGE_METADATA_T));
    metadata_count++;
    pthread_mutex_unlock(&mutex);
}

void free_image_metadata() {
