    for (int i = 0; i < metadata_count; i++) {
        free(image_metadata_array[i]);
    }
    free(image_metadata_array);
    image_metadata_array = NULL;
    metadata_count = 0;
    max_entries = 0;
    pthread_mutex_unlock(&mutex);
}
