NFapiCrcIndicationPdu* createNode() {
    NFapiCrcIndicationPdu* newNode = (NFapiCrcIndicationPdu*)malloc(sizeof(NFapiCrcIndicationPdu));
    if (!newNode) return NULL;
    memset(newNode, 0, sizeof(NFapiCrcIndicationPdu));
    newNode->next = NULL;
    return newNode;
}

int addStructures(int count, NFapiCrcIndicationPdu** head) {
    if (count <= 0 || count > MAX_STRUCTS) {
        return -1; // Invalid input
    }
    for (int i = 0; i < count; i++) {
        NFapiCrcIndicationPdu* newNode = createNode();
        if (!newNode) {
            return -2; // Memory allocation failed
        }
