        newNode->RNTI = rand() % 65535;
        strcpy(newNode->CRC_INDICATION_REL8_TAG, "CrcIndication");
        newNode->CRCFLAG = rand() & 1;

        if (*head == NULL) {
            *head = newNode;
        } else {
            NFapiCrcIndicationPdu* temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
    return 0; // Success
}

void destroyList(NFapiCrcIndicationPdu** head) {
    NFapiCrcIndicationPdu* current = *head;
    while (current != NULL) {
        NFapiCrcIndicationPdu* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

void traverseList(NFapiCrcIndicationPdu* head) {
    NFapiCrcIndicationPdu* temp = head;
    while (temp != NULL) {
        printf("RX_UE_INFORMATION_TAG: %s, RNTI: %u, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: %u\n",
               temp->RX_UE_INFORMATION_TAG, temp->RNTI, temp->CRC_INDICATION_REL8_TAG, temp->CRCFLAG);
        temp = temp->next;
    }
}

