    int numStructures;
    printf("Enter the number of structures to create (1-%d): ", MAX_STRUCTS);
    scanf("%d", &numStructures);

    if (addStructures(numStructures, &head) == 0) {
        traverseList(head);
    } else {
        printf("Failed to add structures.\n");
    }

    destroyList(&head);
    return 0;
