void addCRCIndication(CRCIndicationList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity + MAX_INCREMENT;
        NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->list = new_list;
        log_memory_allocation("CRCIndicationList", list->list + list->capacity, MAX_INCREMENT * sizeof(NFAPI_CRC_INDICATION_PDU_T), __FILE__, __LINE__);
        list->capacity = new_capacity;
    }
    list->count++;
    NFAPI_CRC_INDICATION_PDU_T* new_entry = &list->list[list->count - 1];
    populateRandomly(new_entry);
    pthread_mutex_unlock(&list->lock);
}

void resetCRCIndicationList(CRCIndicationList* list) {
