FileMetadata* process_file_paths(const char** file_paths, int num_paths, size_t* total_size) {
    if (num_paths <= 0 || !file_paths || !total_size) {
        return NULL;
    }

    struct stat file_stat;
    *total_size = 0;

    // Calculate total memory required for metadata entries
    for (int i = 0; i < num_paths; ++i) {
        if (stat(file_paths[i], &file_stat) == 0) {
            *total_size += sizeof(FileMetadata);
            *total_size += strlen(file_paths[i]) + 1;
        }
    }

    // Allocate memory for metadata array
    FileMetadata* metadata = (FileMetadata*)malloc(*total_size);
    if (!metadata) {
        return NULL; // Memory allocation failed
    }

    size_t offset = 0;

    // Populate metadata entries
    for (int i = 0; i < num_paths; ++i) {
        if (stat(file_paths[i], &file_stat) == 0) {
            metadata[i].name = (char*)((char*)metadata + offset);
            strcpy(metadata[i].name, file_paths[i]);
            metadata[i].size = file_stat.st_size;
            metadata[i].mod_time = file_stat.st_mtime;

            // Calculate the next offset
            size_t entry_size = sizeof(FileMetadata) + strlen(file_paths[i]) + 1;
            if (entry_size > SIZE_MAX - offset) {
                free(metadata);
                return NULL; // Potential integer overflow in total_size calculation
            }
            offset += entry_size;
        }
    }

    return metadata;
}

void free_metadata(FileMetadata* metadata, size_t total_size) {
    if (metadata) {
        free(metadata); // Free allocated memory for metadata array
    }
