#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct PacketMetadata {
    time_t timestamp;
    size_t length;
    int integrity_flag;
} PacketMetadata;

void processNetworkPacketStream(size_t max_packets, size_t memory_limit_bytes) {
    PacketMetadata *packet_buffer = NULL;
    size_t current_size = 0;
    size_t packets_processed = 0;
    size_t packets_retained = 0;
    size_t packets_truncated = 0;

    // Allocate initial buffer
    packet_buffer = (PacketMetadata *)malloc(max_packets * sizeof(PacketMetadata));
    if (!packet_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Simulate incoming network packets
    for (size_t i = 0; i < max_packets; ++i) {
        PacketMetadata packet;
        packet.timestamp = time(NULL);
        packet.length = rand() % 1500 + 128; // Random packet length between 128 and 1624 bytes
        packet.integrity_flag = (rand() % 2 == 0); // 50% chance of integrity flag

        if (current_size + packet.length > memory_limit_bytes) {
            size_t truncated_length = memory_limit_bytes - current_size;
            if (packet.integrity_flag && truncated_length < packet.length) {
                packets_truncated++;
                continue; // Retain critical packets
            }
        }

        // Store the packet in buffer
        packet_buffer[packets_processed++] = packet;
        current_size += packet.length;

        if (current_size > memory_limit_bytes) {
            size_t to_free = current_size - memory_limit_bytes;
            for (size_t j = 0; j < packets_processed; ++j) {
                if (to_free >= packet_buffer[j].length) {
                    to_free -= packet_buffer[j].length;
                } else {
                    packet_buffer[j].length -= to_free;
                    break;
                }
            }
        }

        packets_retained++;
    }

    // Report statistics
    printf("Processed: %zu\n", packets_processed);
    printf("Retained: %zu\n", packets_retained);
    printf("Truncated: %zu\n", packets_truncated);

    // Free allocated memory
    free(packet_buffer);
}

int main() {
    srand(time(NULL));
    processNetworkPacketStream(100, 5 * 1024 * 1024); // Simulate processing up to 100 packets with a 5MB limit
    return 0;
}
```

