ImageMetaData* allocateAndPopulateImageData(const char* filePaths[], int numFiles, size_t maxMemory) {
    ImageMetaData* imageMetadata = NULL;
    int count = 0;
    size_t totalSize = 0;

    for (int i = 0; i < numFiles; i++) {
        FILE* file = fopen(filePaths[i], "rb");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file: %s\n", filePaths[i]);
            continue;
        }

        fseek(file, 0L, SEEK_END);
        size_t fileSize = ftell(file);
        fclose(file);

        if ((totalSize + sizeof(ImageMetaData) + fileSize) > maxMemory) {
            break; // Not enough memory for this file
        }

        imageMetadata = realloc(imageMetadata, (count + 1) * sizeof(ImageMetaData));
        if (imageMetadata == NULL) {
            fprintf(stderr, "Memory allocation failed for Image Metadata\n");
            exit(1);
        }

        imageMetadata[count].filePath = strdup(filePaths[i]);
        imageMetadata[count].image_size = fileSize;
        totalSize += sizeof(ImageMetaData) + fileSize;
        count++;
    }

    return imageMetadata;
}

int main() {
    int N = 10; // Number of elements in the list
    size_t maxMemory = 512 * 1024 * 1024; // Maximum memory in bytes
