    NFAPI_CRC_INDICATION_PDU_T* crcList = createAndPopulateList(N);

    ImageMetaData* imageMetadata = allocateAndPopulateImageData(filePaths, numFiles, maxMemory);

    // Process the list and metadata...

    free(crcList);
    for (int i = 0; i < count; i++) {
        free(imageMetadata[i].filePath);
    }
    free(imageMetadata);

    return 0;
}
