#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void populateNfapiIndications(int numIndications, Node** head) {
    if (numIndications <= 0) {
        *head = NULL;
        return; // Handle edge cases where no nodes are needed
    }

    srand(time(NULL)); // Seed for random number generation

    *head = createNode((NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 1, .RNTI = rand(), .CRC_INDICATION_REL8_TAG = 1, .CRCFLAG = rand() % 2});
    if (*head == NULL) {
        return; // Handle memory allocation failure
    }

    Node* current = *head;
    for (int i = 1; i < numIndications; ++i) {
        Node* newNode = createNode((NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = i+1, .RNTI = rand(), .CRC_INDICATION_REL8_TAG = i+1, .CRCFLAG = rand() % 2});
        if (newNode == NULL) {
            // Handle memory allocation failure
            while (*head != current) {
                Node* temp = *head;
                *head = (*head)->next;
                free(temp);
            }
            free(*head);
            return;
        }
        current->next = newNode;
        current = newNode;
    }
}

void cleanList(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
