        free(cb);
        return NULL;
    }

    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->lock, NULL);

    return cb;
}

void cb_destroy(CircularBuffer* cb) {
    if (cb == NULL) return;
    free(cb->buffer);
    pthread_mutex_destroy(&cb->lock);
    free(cb);
}

int cb_enqueue(CircularBuffer* cb, const unsigned char* packet, size_t size) {
    if (cb == NULL || packet == NULL || size == 0) return -1;

    pthread_mutex_lock(&cb->lock);

    if ((cb->count + 1) * MAX_PACKET_SIZE > cb->capacity) {
        // Handle integer overflow or insufficient capacity
        pthread_mutex_unlock(&cb->lock);
        return -2; // Buffer full
    }

    size_t new_tail = (cb->tail + size) % cb->capacity;
    if ((new_tail >= cb->head && (new_tail < cb->head || size > cb->head)) ||
        (new_tail < cb->head && new_tail < cb->capacity - (cb->head - new_tail))) {
        // Check for buffer overflow
        pthread_mutex_unlock(&cb->lock);
        return -2; // Buffer full
    }

    memcpy(cb->buffer + cb->tail, packet, size);
    cb->tail = new_tail;
    cb->count++;

    pthread_mutex_unlock(&cb->lock);
    return 0;
}

int cb_dequeue(CircularBuffer* cb, unsigned char** packet, size_t* size) {
    if (cb == NULL || packet == NULL || size == NULL) return -1;

    pthread_mutex_lock(&cb->lock);

    if (cb->count == 0) {
        pthread_mutex_unlock(&cb->lock);
        return -2; // Buffer empty
    }

    *packet = cb->buffer + cb->head;
    *size = MAX_PACKET_SIZE;
    cb->head = (cb->head + *size) % cb->capacity;
    cb->count--;

    pthread_mutex_unlock(&cb->lock);
    return 0;
}
