#define MAX_PACKETS 10000

typedef struct Packet {
    char* data;
    size_t length;
} Packet;

typedef struct PacketQueue {
    Packet packets[MAX_PACKETS];
    int front, rear;
    pthread_mutex_t lock;
} PacketQueue;

void init_packet_queue(PacketQueue *queue) {
    queue->front = -1;
    queue->rear = -1;
    pthread_mutex_init(&queue->lock, NULL);
}

int is_full(PacketQueue *queue) {
    return (queue->rear + 1) % MAX_PACKETS == queue->front;
}

int enqueue_packet(PacketQueue *queue, Packet packet) {
    if (is_full(queue)) {
        return -1; // Queue is full
    }
    if (queue->front == -1) {
        queue->front = 0;
    }
    queue->rear = (queue->rear + 1) % MAX_PACKETS;
    queue->packets[queue->rear] = packet;
    return 0;
}

Packet dequeue_packet(PacketQueue *queue) {
    Packet packet;
    if (queue->front == -1) {
        packet.data = NULL;
        packet.length = 0;
    } else {
        packet = queue->packets[queue->front];
        if (queue->front == queue->rear) {
            queue->front = -1;
            queue->rear = -1;
        } else {
            queue->front = (queue->front + 1) % MAX_PACKETS;
        }
    }
    return packet;
}

int process_packets(PacketQueue *queue, void (*process_packet)(Packet)) {
    Packet packet;
    while ((packet = dequeue_packet(queue)).data != NULL) {
        pthread_mutex_lock(&queue->lock);
        // Process the packet
        process_packet(packet);
        pthread_mutex_unlock(&queue->lock);
        free(packet.data); // Free allocated memory for packet data
    }
    return 0;
}

void* packet_processor(void *arg) {
    PacketQueue *queue = (PacketQueue *)arg;
    process_packets(queue, [](Packet packet) {
        printf("Processing packet with length: %zu\n", packet.length);
    });
    pthread_exit(NULL);
}

int main() {
    PacketQueue queue;
    init_packet_queue(&queue);

    // Enqueue packets
    for (int i = 0; i < MAX_PACKETS; i++) {
        Packet packet;
        packet.data = malloc(i * sizeof(char)); // Simulate variable length data
        packet.length = i;
        enqueue_packet(&queue, packet);
    }

    pthread_t threads[MAX_PACKETS];
    for (int i = 0; i < MAX_PACKETS; i++) {
        pthread_create(&threads[i], NULL, packet_processor, &queue);
    }

    for (int i = 0; i < MAX_PACKETS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
