#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    size_t size;
    pthread_mutex_t lock;
} CircularBuffer;

CircularBuffer* create_buffer(size_t initial_capacity) {
    CircularBuffer* cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!cb) return NULL;

    cb->buffer = (char*)malloc(initial_capacity);
    if (!cb->buffer) {
        free(cb);
        return NULL;
    }

    cb->capacity = initial_capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->size = 0;

    pthread_mutex_init(&cb->lock, NULL);

    return cb;
}

void destroy_buffer(CircularBuffer* cb) {
    if (cb) {
        free(cb->buffer);
        pthread_mutex_destroy(&cb->lock);
        free(cb);
    }
}

int enqueue_packet(CircularBuffer* cb, const char* packet, size_t packet_size) {
    pthread_mutex_lock(&cb->lock);

    if (cb->size + packet_size > cb->capacity) {
        pthread_mutex_unlock(&cb->lock);
        return -1; // Buffer overflow
    }

    memcpy(cb->buffer + (cb->head % cb->capacity), packet, packet_size);
    cb->head = (cb->head + packet_size) % cb->capacity;
    cb->size += packet_size;

    pthread_mutex_unlock(&cb->lock);
    return 0;
}

int dequeue_packet(CircularBuffer* cb, char* output_buffer, size_t output_capacity) {
    pthread_mutex_lock(&cb->lock);

    if (cb->size == 0) {
        pthread_mutex_unlock(&cb->lock);
        return -1; // Buffer underflow
    }

    size_t packet_size = (cb->head - cb->tail + cb->capacity) % cb->capacity;
    if (packet_size > output_capacity) {
        pthread_mutex_unlock(&cb->lock);
        return -2; // Output buffer too small
    }

    memcpy(output_buffer, cb->buffer + (cb->tail % cb->capacity), packet_size);
    cb->tail = (cb->tail + packet_size) % cb->capacity;
    cb->size -= packet_size;

    pthread_mutex_unlock(&cb->lock);
    return 0;
}

void resize_buffer(CircularBuffer* cb, size_t new_capacity) {
    pthread_mutex_lock(&cb->lock);

    char* new_buffer = (char*)realloc(cb->buffer, new_capacity);
    if (!new_buffer) {
        pthread_mutex_unlock(&cb->lock);
        return; // Memory allocation failed
    }

    cb->buffer = new_buffer;
    cb->capacity = new_capacity;
    cb->head = 0;
    cb->tail = 0;

    pthread_mutex_unlock(&cb->lock);
}

// Additional functions for managing buffer metadata, caching, monitoring, etc.
