#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define MAX_MEMORY 1024 * 1024 // 1MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool_T {
    void* memory;
    size_t block_size;
    size_t num_blocks;
    size_t free_count;
    pthread_mutex_t lock;
} MemoryPool_T;

MemoryPool_T pool;

void init_memory_pool(size_t block_size, size_t num_blocks) {
    pool.block_size = block_size;
    pool.num_blocks = num_blocks;
    pool.free_count = num_blocks;
    pthread_mutex_init(&pool.lock, NULL);

    pool.memory = malloc(block_size * num_blocks);
    if (!pool.memory) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void* allocate_from_pool() {
    pthread_mutex_lock(&pool.lock);
    if (pool.free_count == 0) {
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    void* block = pool.memory + (pool.num_blocks - pool.free_count) * pool.block_size;
    pool.free_count--;
    pthread_mutex_unlock(&pool.lock);
    return block;
}

void free_to_pool(void* block) {
    pthread_mutex_lock(&pool.lock);
    pool.free_count++;
    pthread_mutex_unlock(&pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaip_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool();
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for NFAPI PDU\n");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = rand() % 100;
    pdu->RNTI = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;

    return pdu;
}

void test_nfaip_pdu(const char* label, void (*f)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_nfaip_pdu();
        if (!pdu) continue;

        printf("Testing module: %s\n", label);
        f(*pdu);

        free_to_pool(pdu);
    }
}

void test_crc_flag(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("Test result: CRCFLAG = %d\n", pdu.CRC_INDICATION_REL8_TAG);
}

int main() {
    srand(time(NULL));

    init_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES);

    test_nfaip_pdu("NFAPI PDU", test_crc_flag);

    return 0;
}
