#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1500
#define BATCH_LIMIT 100

typedef struct {
    uint8_t *data;
    size_t header_size;
    size_t payload_size;
} PacketData;

typedef struct {
    PacketData *packets;
    size_t packet_count;
    size_t total_data_size;
} NetworkBatch;

NetworkBatch process_network_packets(NetworkBatch batch) {
    NetworkBatch processed_batch = {NULL, 0, 0};

    for (size_t i = 0; i < batch.packet_count; ++i) {
        if (batch.packets[i].payload_size > MAX_PACKET_SIZE) {
            // Truncate payload or reject packet
            continue;
        }

        if (processed_batch.total_data_size + batch.packets[i].payload_size > SIZE_MAX) {
            // Handle integer overflow
            break;
        }

        PacketData *new_packet = malloc(sizeof(PacketData));
        new_packet->data = malloc(batch.packets[i].header_size + batch.packets[i].payload_size);
        memcpy(new_packet->data, batch.packets[i].data, batch.packets[i].header_size + batch.packets[i].payload_size);
        new_packet->header_size = batch.packets[i].header_size;
        new_packet->payload_size = batch.packets[i].payload_size;

        processed_batch.packets = realloc(processed_batch.packets, (processed_batch.packet_count + 1) * sizeof(PacketData));
        processed_batch.packets[processed_batch.packet_count++] = *new_packet;
        processed_batch.total_data_size += batch.packets[i].payload_size;

        free(new_packet->data);
        free(new_packet);
    }

    if (processed_batch.packet_count > BATCH_LIMIT) {
        // Limit the number of packets
        processed_batch.packet_count = BATCH_LIMIT;
    }

    return processed_batch;
}

void free_network_batch(NetworkBatch batch) {
    for (size_t i = 0; i < batch.packet_count; ++i) {
        free(batch.packets[i].data);
    }
    free(batch.packets);
}

int main() {
    NetworkBatch batch;
    // Initialize and populate the batch with network packets
    NetworkBatch processed_batch = process_network_packets(batch);

    printf("Processed %zu packets with total data size of %zu\n", processed_batch.packet_count, processed_batch.total_data_size);

    free_network_batch(processed_batch);
    return 0;
}
