        double adjustment_factor = (double)max_memory / total_memory_required;
        n = (int)(adjustment_factor * n);
        if (n <= 0) {
            fprintf(stderr, "Adjusted number of elements results in non-positive value.\n");
            return NULL;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(n * pdu_size);
