void* allocate_structures(size_t N, size_t max_size, int log_level) {
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (N > SIZE_MAX / struct_size || N * struct_size + sizeof(void*) > max_size) {
        // Handle integer overflow or insufficient memory
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** array = malloc((N + 1) * sizeof(void*));
    if (!array) {
        // Handle allocation failure
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i] = malloc(struct_size);
        if (!array[i]) {
            // Free previously allocated structures on failure
            while (i > 0) {
                free(array[--i]);
            }
            free(array);
            return NULL;
        }
        array[i]->RX_UE_INFORMATION_TAG = i; // Example initialization
        array[i]->RNTI = i * 10 + 5;       // Example initialization
        array[i]->CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRCFLAG
    }

    array[N] = NULL; // Null-terminate the array for safe iteration

    if (log_level > 0) {
        printf("Allocated %zu structures\n", N);
    }

    return array;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T** array, int log_level) {
    if (array) {
        size_t i = 0;
        while (array[i]) {
            free(array[i]);
            ++i;
        }
        free(array);

        if (log_level > 0) {
            printf("Freed all structures\n");
        }
    }
}

// Example usage
int main() {
    size_t N = 1000;
    size_t max_size = 5 * 1024 * 1024; // 5 MB
    int log_level = 1;

    NFAPI_CRC_INDICATION_PDU_T** array = allocate_structures(N, max_size, log_level);
    if (!array) {
        printf("Failed to allocate structures\n");
        return EXIT_FAILURE;
    }

    // Use the allocated structures...

    free_structures(array, log_level);

    return EXIT_SUCCESS;
}
