#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_ENTRIES 100

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void *pool;
    size_t size;
    size_t block_size;
    size_t free_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool;

void init_memory_pool(size_t block_size, size_t num_blocks) {
    memory_pool.pool = malloc(block_size * num_blocks);
    if (!memory_pool.pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(1);
    }
    memory_pool.size = block_size * num_blocks;
    memory_pool.block_size = block_size;
    memory_pool.free_count = num_blocks;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void *allocate_from_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.free_count == 0) {
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }
    void *block = memory_pool.pool + (memory_pool.size - memory_pool.block_size * memory_pool.free_count);
    memory_pool.free_count--;
    pthread_mutex_unlock(&memory_pool.lock);
    return block;
}

void free_to_pool(void *block) {
    pthread_mutex_lock(&memory_pool.lock);
    size_t offset = (char *)block - (char *)memory_pool.pool;
    if (offset % memory_pool.block_size != 0 || offset / memory_pool.block_size >= memory_pool.free_count) {
        fprintf(stderr, "Attempt to free invalid block\n");
        pthread_mutex_unlock(&memory_pool.lock);
        return;
    }
    memory_pool.free_count++;
    pthread_mutex_unlock(&memory_pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T *create_nfaip_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool();
    if (!pdu) {
        fprintf(stderr, "Failed to allocate NFAPI CRC Indication PDU\n");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 0xFFFF;
    pdu->CRC_INDICATION_REL8_TAG = (rand() & 1) ? 1 : 0;
    return pdu;
}

void test_nfaip_pdu(const char *label, void (*f)(NFAPI_CRC_INDICATION_PDU_T *)) {
    printf("Testing %s\n", label);
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_nfaip_pdu();
    if (!pdu) {
        printf("%s: Test failed - allocation failed\n", label);
        return;
    }
    f(*pdu);
    free_to_pool(pdu);
    printf("%s: Test passed\n", label);
}

void *create_and_test_nfaapi_list(size_t max_memory, size_t max_entries) {
    if (max_memory > MAX_MEMORY || max_entries > MAX_ENTRIES) {
        fprintf(stderr, "Invalid memory or entry limits\n");
        return NULL;
    }
    init_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), max_entries);

    NFAPI_CRC_INDICATION_PDU_T *list[max_entries];
    for (size_t i = 0; i < max_entries; i++) {
        list[i] = create_nfaip_pdu();
        if (!list[i]) {
            fprintf(stderr, "Failed to create NFAPI CRC Indication PDU\n");
            return NULL;
        }
        test_nfaip_pdu("NFAPI_CRC_INDICATION_PDU_T", [](NFAPI_CRC_INDICATION_PDU_T pdu) {
            printf("RX_UE_INFORMATION_TAG: %u\n", pdu.RX_UE_INFORMATION_TAG);
            printf("RNTI: %u\n", pdu.RNTI);
            printf("CRC_INDICATION_REL8_TAG: %d\n", pdu.CRC_INDICATION_REL8_TAG);
        });
    }

    // Free all allocated memory
    for (size_t i = 0; i < max_entries; i++) {
        free_to_pool(list[i]);
    }

    return list;
}
