#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool[MAX_ENTRIES];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int current_entries = 0;

int create_entry(uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint32_t CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&pool_lock);
    if (current_entries >= MAX_ENTRIES) {
        fprintf(stderr, "Error: Maximum number of entries reached.\n");
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    entry->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pool[current_entries++] = entry;

    pthread_mutex_unlock(&pool_lock);
    return 0;
}

void free_entry(int index) {
    if (index < 0 || index >= current_entries) {
        fprintf(stderr, "Error: Invalid index.\n");
        return;
    }

    pthread_mutex_lock(&pool_lock);
    free(pool[index]);
    memmove(&pool[index], &pool[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (current_entries - index - 1));
    current_entries--;
    pthread_mutex_unlock(&pool_lock);
}

void *worker(void *arg) {
    int *index = (int *)arg;
    uint32_t RX_UE_INFORMATION_TAG = rand();
    uint32_t RNTI = rand();
    uint32_t CRC_INDICATION_REL8_TAG = rand();

    if (create_entry(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG) == 0) {
        printf("Entry created successfully.\n");
    } else {
        printf("Failed to create entry.\n");
    }

    free_entry(*index);
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[MAX_ENTRIES];
    int indices[MAX_ENTRIES];

    for (int i = 0; i < MAX_ENTRIES; i++) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, worker, &indices[i]) != 0) {
            fprintf(stderr, "Error: Failed to create thread.\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_ENTRIES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
