// Function to calculate memory requirements for storing packets
size_t calculateMemoryRequirements(PacketHeader** packets, int num_packets) {
    size_t total_memory = 0;

    for (int i = 0; i < num_packets; i++) {
        // Calculate the required memory for each packet
        size_t required_memory = packets[i]->header_size + sizeof(packets[i]->data_segment);

        // Check for integer overflow before adding to total_memory
        if (required_memory > SIZE_MAX - total_memory) {
            fprintf(stderr, "Error: Integer overflow in memory calculation.\n");
            return 0; // Return an error code or handle the overflow appropriately
        }

        total_memory += required_memory;
    }

    return total_memory;
}

// Example usage of the function
int main() {
    // Create some sample packet headers
    PacketHeader packet1 = {20, NULL};
    PacketHeader packet2 = {30, NULL};

    PacketHeader* packets[] = {&packet1, &packet2};
    int num_packets = sizeof(packets) / sizeof(packets[0]);

    // Calculate memory requirements
    size_t required_memory = calculateMemoryRequirements(packets, num_packets);

    if (required_memory != 0) {
        printf("Required Memory: %zu bytes\n", required_memory);
    }

    return 0;
}
