// Function to allocate memory for an image header and its data
void* allocateImageMemory(const ImageHeader* header) {
    size_t totalSize = calculateMemoryRequirements(header);
    void* memory = malloc(totalSize);
    if (memory == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    // Copy the header into the allocated memory
    memcpy(memory, header, sizeof(ImageHeader));
    return memory;
}

// Function to free the allocated memory for an image header and its data
void freeImageMemory(void* memory) {
    if (memory != NULL) {
        free(memory);
    }
}

