void init_packet_pool(PacketPool* pool) {
    pool->count = 0;
    pool->allocated_count = 0;
}

Packet* allocate_packet(PacketPool* pool, size_t payload_size) {
    if (pool->count >= MAX_PACKETS || pool->allocated_count + 1 > 8 * MAX_PACKETS / 10) {
        return NULL; // Not enough memory or too many allocations
    }

    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        return NULL; // Memory allocation failed
    }

    packet->payload = malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL; // Payload allocation failed
    }

    packet->timestamp = time(NULL);
    snprintf(packet->source_ip, sizeof(packet->source_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    snprintf(packet->destination_ip, sizeof(packet->destination_ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    packet->payload_size = payload_size;
    packet->RX_UE_INFORMATION_TAG = rand();
    packet->RNTI = rand();
    packet->CRC_INDICATION_REL8_TAG = (rand() % 2) == 0;

    pool->packets[pool->count++] = packet;
    pool->allocated_count++;

    return packet;
}

void free_packet_pool(PacketPool* pool) {
    for (int i = 0; i < pool->count; i++) {
        free(pool->packets[i]->payload);
        free(pool->packets[i]);
    }
    init_packet_pool(pool);
}

// Example usage
int main() {
    PacketPool pool;
    init_packet_pool(&pool);

    for (int i = 0; i < MAX_PACKETS; i++) {
        Packet* packet = allocate_packet(&pool, rand() % 1024); // Random payload size
        if (!packet) {
            fprintf(stderr, "Failed to allocate packet\n");
            break;
        }
        // Process the packet...
    }

    free_packet_pool(&pool);
    return 0;
}
```

This code defines a `Packet` structure to hold network packet metadata and payload, and a `PacketPool` structure to manage a pool of packets. The `allocate_packet` function allocates memory for a new packet, including the payload, and populates it with random data. It ensures that no more than 80% of the available system memory is used. The `free_packet_pool` function frees all allocated memory when done. The main function demonstrates how to use the packet pool in an example scenario.']

