typedef struct NetworkPacket {
    uint32_t num_pdus;
    RlcPdu *pdus;
} NetworkPacket;

int calculatePduMemorySize(RlcPdu *pdu, uint32_t bufferLimit) {
    uint32_t pduLength = pdu->length + PDU_HEADER_SIZE;
    if (pduLength > bufferLimit || pduLength < pdu->length) {
        return -1; // Error: Integer overflow or invalid length
    }
    return pduLength;
}

int allocatePduMemory(NetworkPacket *packet, uint32_t *totalSize, uint32_t bufferLimit) {
    int totalPduBytes = 0;
    for (uint32_t i = 0; i < packet->num_pdus; ++i) {
        int pduSize = calculatePduMemorySize(&packet->pdus[i], bufferLimit);
        if (pduSize == -1) {
            return -1; // Error in calculating PDU size
        }
        totalPduBytes += pduSize;
    }

    *totalSize = totalPduBytes;
    packet->pdus = (RlcPdu *)realloc(packet->pdus, totalPduBytes);
    if (!packet->pdus) {
        return -1; // Memory allocation failed
    }

    for (uint32_t i = 0; i < packet->num_pdus; ++i) {
        packet->pdus[i].length += PDU_HEADER_SIZE;
    }

    return 0; // Success
}

void logMemoryUsage(uint32_t totalBytes, uint32_t allocatedBytes) {
    printf("Total bytes: %u, Allocated bytes: %u\n", totalBytes, allocatedBytes);
}

int processNetworkPacket(NetworkPacket *packet, uint32_t bufferLimit) {
    uint32_t totalSize = 0;
    if (allocatePduMemory(packet, &totalSize, bufferLimit)) {
        printf("Failed to allocate memory for PDUs.\n");
        return -1; // Memory allocation failed
    }

    logMemoryUsage(totalSize + PDU_HEADER_SIZE * packet->num_pdus, totalSize);
    // Process PDUs...

    return 0; // Success
}
