    if (log_func) {
        log_func("Memory usage: %lu bytes\n", memory_size);
    }
}

int process_packets(unsigned int packet_count, unsigned int *data_lengths, void **data_segments, void (*log_func)(const char* format, ...)) {
    NetworkPacket *packets = NULL;
    unsigned long total_memory_required = 0;

    // Calculate total memory required
    for (unsigned int i = 0; i < packet_count; i++) {
        if ((total_memory_required += sizeof(NetworkPacket) + data_lengths[i]) > UINT_MAX - sizeof(NetworkPacket)) {
            log_func("Error: Integer overflow in memory calculation\n");
            return -1;
        }
    }

    // Allocate memory for packets
    packets = (NetworkPacket *)malloc(total_memory_required);
    if (!packets) {
        log_func("Error: Memory allocation failed\n");
        return -1;
    }

    unsigned long current_offset = 0;

    // Initialize packets with data segments
    for (unsigned int i = 0; i < packet_count; i++) {
        packets[i].packet_id = i + 1;
        memcpy((char *)packets + sizeof(NetworkPacket) * (i + 1) + current_offset, data_segments[i], data_lengths[i]);
        current_offset += data_lengths[i];
    }

    // Log memory usage
    log_memory_usage(total_memory_required, log_func);

    // Free allocated memory
    free(packets);

    return 0;
}

