        *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*pdu_list == NULL) {
            return -2; // Memory allocation failed
        }
    } else {
        *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    if (*pdu_list == NULL) {
        return -2; // Memory allocation failed
    }

    int indices[M];
    int count = 0;

    // Read up to M integers from standard input
    while (count < M && scanf("%d", &indices[count]) == 1) {
        if (indices[count] >= 0 && indices[count] < N) {
            count++;
        }
    }

    if (count < M) {
        free(*pdu_list);
        return -3; // Not enough valid integers provided
    }

    int max_index = 0;
    for (int i = 0; i < count; i++) {
        if (indices[i] > max_index) {
            max_index = indices[i];
        }
