        if (bytes_received != sizeof(PacketHeader)) {
            fprintf(stderr, "Error: Failed to receive packet header\n");
            return -1;
        }

        // Validate buffer size against system memory limit
        if (packets[i].buffer_size > SYSTEM_MEMORY_LIMIT) {
            fprintf(stderr, "Error: Buffer size exceeds system memory limit\n");
            return -1;
        }

        // Allocate payload buffer
        packets[i].payload_buffer = malloc(packets[i].buffer_size);
        if (!packets[i].payload_buffer) {
            fprintf(stderr, "Error: Failed to allocate buffer\n");
            return -1;
        }

        // Receive payload data
        bytes_received = recv(sockfd, packets[i].payload_buffer, packets[i].buffer_size, 0);
        if (bytes_received != (ssize_t)packets[i].buffer_size) {
            fprintf(stderr, "Error: Failed to receive payload data\n");
            free(packets[i].payload_buffer);
            return -1;
