['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
    size_t memory_budget;
    size_t current_memory_usage;
} LinkedList;

LinkedList* create_list(size_t memory_budget) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list creation.\n");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->memory_budget = memory_budget;
    list->current_memory_usage = 0;
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (pthread_mutex_lock(&list->mutex) != 0) {
        fprintf(stderr, "Failed to lock mutex for adding node.\n");
        return -1;
    }

    size_t new_node_size = sizeof(Node);
    if ((list->current_memory_usage + new_node_size) > list->memory_budget) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Memory budget exceeded. Unable to add node.\n");
        return -2;
    }

    Node* new_node = (Node*)malloc(new_node_size);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return -3;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->current_memory_usage += new_node_size;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    LinkedList* list = create_list(1024 * 1024); // Example memory budget of 1MB
    if (!list) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T data = {1, 2, (rand() % 2 == 0)};
