NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(const char* json_file, int max_entries, pthread_mutex_t* mutex, int* count) {
    if (max_entries > MAX_ENTRIES) {
        fprintf(stderr, "Maximum entries limit exceeded\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(mutex);

    json_object* root = json_tokener_parse_file(json_file);
    if (!root || !json_is_object(root)) {
        fprintf(stderr, "Invalid JSON format\n");
        free(array);
        pthread_mutex_unlock(mutex);
        return NULL;
    }

    json_object* rnti_array_obj;
    if (json_object_object_get_ex(root, "rnti_values", &rnti_array_obj) && json_is_array(rnti_array_obj)) {
        int array_size = json_array_length(rnti_array_obj);
        if (array_size > max_entries) {
            fprintf(stderr, "Too many RNTI values\n");
            free(array);
            pthread_mutex_unlock(mutex);
            return NULL;
        }

        for (int i = 0; i < array_size; ++i) {
            json_object* rnti_obj;
            if (json_array_get_idx(rnti_array_obj, i, &rnti_obj) && json_is_integer(rnti_obj)) {
                int rnti = json_object_get_int(rnti_obj);
                // Populate the array with RNTI values
                array[i].rnti = rnti;
            } else {
                fprintf(stderr, "Invalid RNTI value\n");
                free(array);
                pthread_mutex_unlock(mutex);
                return NULL;
            }
        }

        *count = array_size;
    } else {
        fprintf(stderr, "Missing or invalid RNTI values in JSON\n");
        free(array);
        pthread_mutex_unlock(mutex);
        return NULL;
    }

    pthread_mutex_unlock(mutex);

    return array;
}

int main() {
    const char* json_file = "config.json";
    int max_entries = 512;
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int count;
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(json_file, max_entries, &mutex, &count);
    if (array) {
        printf("Array populated successfully with %d entries\n", count);
        // Free the allocated memory when done
        free(array);
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
