} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node() {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return new_node;
}

void add_node(Node** head, int RX_UE_INFORMATION_TAG, int RNTI, char CRC_INDICATION_REL8_TAG) {
    Node* new_node = create_node();
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->prev = NULL;
    new_node->next = *head;

    if (*head) {
        (*head)->prev = new_node;
    }

    *head = new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));

    Node* head = NULL;

    for (int i = 0; i < 10000; i++) {
        add_node(&head, rand(), rand(), 'A' + rand() % 26);
    }

    free_list(&head);

    return 0;
}
