    if (num_packets > MAX_PACKETS || max_memory < 0) {
        fprintf(stderr, "Invalid input or memory limit.\n");
        return NULL;
    }

    // Calculate total payload size
    int total_payload_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        if (packet_lengths[i] > PAYLOAD_SIZE) {
            fprintf(stderr, "Payload too large for buffer.\n");
            return NULL;
        }
        total_payload_size += packet_lengths[i];
    }

    // Calculate total memory required
    int total_memory_required = sizeof(PacketHeader) * num_packets + total_payload_size;
    if (total_memory_required > max_memory) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return NULL;
    }

    // Allocate memory for PacketHeaders and payloads
    char *memory_block = malloc(total_memory_required);
    if (!memory_block) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    PacketHeader *headers = (PacketHeader *)memory_block;
    char *payloads_start = memory_block + sizeof(PacketHeader) * num_packets;

    for (int i = 0; i < num_packets; ++i) {
        headers[i].header_length = sizeof(PacketHeader);
        headers[i].payload_length = packet_lengths[i];
        headers[i].payload = payloads_start + i * packet_lengths[i];
        memcpy(headers[i].payload, "Example Payload", strlen("Example Payload"));
