    if (headers) {
        for (int i = 0; i < num_packets; ++i) {
            printf("Packet %d: Header Length = %d, Payload Length = %d, Payload Data = %s\n",
                   i, headers[i].header_length, headers[i].payload_length, headers[i].payload);
        }
        free(headers);
    }

    return 0;
}
