#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define INITIAL_MEMORY_BLOCK_SIZE 1024
#define MAX_MEMORY_USAGE_LIMIT (1024 * 1024 * 10) // 10 MB

typedef struct PacketHeader {
    size_t header_length;
    size_t payload_length;
    char* payload_data;
} PacketHeader;

PacketHeader** packet_headers = NULL;
size_t current_packet_count = 0;
size_t total_memory_used = 0;

void log_metrics() {
    printf("Packets Processed: %zu\n", current_packet_count);
    printf("Total Memory Used: %zu bytes\n", total_memory_used);
}

int process_packet_header(const char* header_data, size_t header_length, const char* payload_data, size_t payload_length) {
    if (total_memory_used + header_length + payload_length > MAX_MEMORY_USAGE_LIMIT) {
        return -1; // Memory limit exceeded
    }

    PacketHeader* new_header = (PacketHeader*)realloc(packet_headers, (current_packet_count + 1) * sizeof(PacketHeader));
    if (!new_header) {
        return -2; // Failed to allocate memory
    }
    packet_headers = new_header;

    packet_headers[current_packet_count].header_length = header_length;
    packet_headers[current_packet_count].payload_length = payload_length;
    packet_headers[current_packet_count].payload_data = (char*)realloc(packet_headers[current_packet_count].payload_data, header_length + payload_length);
