#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct PacketHeader {
    size_t payloadSize;
    char *payload;
} PacketHeader;

typedef struct MemoryPool {
    void *poolStart;
    size_t poolSize;
    size_t packetSize;
    int maxPackets;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t totalMemory, size_t headerSize, int max_packets) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->poolStart = malloc(totalMemory);
    if (!pool->poolStart) {
        free(pool);
        return NULL;
    }

    pool->poolSize = totalMemory;
    pool->packetSize = headerSize + sizeof(PacketHeader);
    pool->maxPackets = max_packets;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

PacketHeader* insertPacket(MemoryPool *pool, size_t payloadSize) {
    if (payloadSize > (pool->packetSize - sizeof(PacketHeader))) {
        return NULL; // Payload too large
    }

    PacketHeader *header = (PacketHeader*)((char*)pool->poolStart + pool->maxPackets * pool->packetSize);
    for (int i = 0; i < pool->maxPackets; i++) {
        header = (PacketHeader*)((char*)pool->poolStart + i * pool->packetSize);
        if (!header->payload) {
            pthread_mutex_lock(&pool->lock);
            if (!header->payload) {
                header->payload = (char*)malloc(payloadSize);
                if (!header->payload) {
                    pthread_mutex_unlock(&pool->lock);
                    return NULL;
                }
                header->payloadSize = payloadSize;
                pthread_mutex_unlock(&pool->lock);
                return header;
            }
            pthread_mutex_unlock(&pool->lock);
        }
    }

    return NULL; // Pool full
}

PacketHeader* retrievePacket(MemoryPool *pool, size_t payloadSize) {
    PacketHeader *header = (PacketHeader*)pool->poolStart;
    for (int i = 0; i < pool->maxPackets; i++) {
        header = (PacketHeader*)((char*)pool->poolStart + i * pool->packetSize);
        if (header->payload && header->payloadSize == payloadSize) {
            return header;
        }
    }

    return NULL; // Packet not found
}

void destroyMemoryPool(MemoryPool *pool) {
    for (int i = 0; i < pool->maxPackets; i++) {
        PacketHeader *header = (PacketHeader*)((char*)pool->poolStart + i * pool->packetSize);
        if (header->payload) {
            free(header->payload);
        }
    }

    pthread_mutex_destroy(&pool->lock);
    free(pool->poolStart);
    free(pool);
}
