typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t* pixelData;
} ImageData;

ImageData** initializeImageArray(uint32_t rows, uint32_t cols) {
    if (rows > MAX_HEIGHT || cols > MAX_WIDTH) {
        return NULL; // Prevent excessive memory allocation
    }

    ImageData** imageArray = malloc(rows * sizeof(ImageData*));
    if (!imageArray) {
        return NULL; // Handle initial allocation failure
    }

    for (uint32_t i = 0; i < rows; ++i) {
        imageArray[i] = malloc(cols * sizeof(ImageData));
        if (!imageArray[i]) {
            // Handle allocation failure and clean up
            for (uint32_t j = 0; j < i; ++j) {
                free(imageArray[j]);
            }
            free(imageArray);
            return NULL;
        }

        for (uint32_t j = 0; j < cols; ++j) {
            imageArray[i][j].width = cols;
            imageArray[i][j].height = rows;
            imageArray[i][j].pixelData = malloc(cols * rows * sizeof(uint8_t));
            if (!imageArray[i][j].pixelData) {
                // Handle allocation failure and clean up
                for (uint32_t k = 0; k <= j; ++k) {
                    free(imageArray[i][k].pixelData);
                }
                free(imageArray[i]);
                for (uint32_t m = 0; m < i; ++m) {
                    for (uint32_t n = 0; n < cols; ++n) {
                        free(imageArray[m][n].pixelData);
                    }
                    free(imageArray[m]);
                }
                free(imageArray);
                return NULL;
            }
        }
    }

    return imageArray;
}

// Example usage
int main() {
    uint32_t rows = 100;
    uint32_t cols = 50;
    ImageData** array = initializeImageArray(rows, cols);
    if (array) {
        // Use the array
        // ...
        for (uint32_t i = 0; i < rows; ++i) {
            for (uint32_t j = 0; j < cols; ++j) {
                free(array[i][j].pixelData);
            }
            free(array[i]);
        }
        free(array);
    } else {
        // Handle error
        return -1;
    }
    return 0;
}
