#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 1024
#define PACKET_SIZE sizeof(struct packet)
#define CHUNK_SIZE 4096

struct packet {
    int length;
    char payload[];
};

void process_packets(int num_packets, struct packet *packets, int max_memory) {
    int current_memory = 0;
    int allocated_chunks = 0;

    for (int i = 0; i < num_packets; i++) {
        if ((current_memory + packets[i].length + PACKET_SIZE) > max_memory) {
            // Log warning: Exceeded maximum memory limit
            printf("Warning: Memory limit exceeded, processing paused.\n");
            break;
        }

        int required_chunks = (packets[i].length + PACKET_SIZE + CHUNK_SIZE - 1) / CHUNK_SIZE;

        if ((current_memory + packets[i].length + PACKET_SIZE) % CHUNK_SIZE != 0) {
            // Log warning: Potential integer overflow in memory calculation
            printf("Warning: Potential integer overflow detected.\n");
        }

        for (int j = 0; j < required_chunks; j++) {
            void *new_memory = realloc(packets[i].payload, packets[i].length + PACKET_SIZE);
            if (!new_memory) {
                // Log error: Memory allocation failed
                printf("Error: Failed to allocate memory.\n");
                exit(EXIT_FAILURE);
            }
            packets[i].payload = new_memory;
        }

        current_memory += packets[i].length + PACKET_SIZE;
        allocated_chunks += required_chunks;

        if (current_memory > max_memory) {
            // Log error: Exceeded maximum memory limit
            printf("Error: Memory limit exceeded.\n");
            exit(EXIT_FAILURE);
        }
    }

    // Log information: Memory usage summary
    printf("Total packets processed: %d\n", num_packets);
    printf("Total memory allocated: %d bytes\n", current_memory);
    printf("Total chunks allocated: %d\n", allocated_chunks);
}

int main() {
    struct packet packets[MAX_PACKETS];
    int num_packets = 5;
    int max_memory = 16384; // Example max memory limit

    // Initialize packets with example data
    for (int i = 0; i < num_packets; i++) {
        packets[i].length = 2048 + (i * 1024);
        packets[i].payload = malloc(packets[i].length);
        if (!packets[i].payload) {
            printf("Error: Failed to allocate initial memory for packet %d.\n", i);
            exit(EXIT_FAILURE);
        }
    }

    process_packets(num_packets, packets, max_memory);

    // Free allocated memory
    for (int i = 0; i < num_packets; i++) {
        free(packets[i].payload);
    }

    return 0;
}
