#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define MEMORY_LIMIT (1024 * 1024 * 50) // 50MB

typedef struct {
    int width;
    int height;
    char* filePath;
} ImageTask;

typedef struct {
    ImageTask tasks[MAX_TASKS];
    int count;
    size_t totalMemoryUsed;
    pthread_mutex_t lock;
} TaskManager;

void initializeTaskManager(TaskManager* manager) {
    memset(manager, 0, sizeof(*manager));
    pthread_mutex_init(&manager->lock, NULL);
}

int addImageTask(TaskManager* manager, const char* filePath, int width, int height) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_TASKS) {
        printf("Too many tasks. Cannot add more.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    ImageTask* task = &manager->tasks[manager->count];
    task->width = width;
    task->height = height;
    task->filePath = strdup(filePath);

    size_t newMemoryUsage = manager->totalMemoryUsed + sizeof(ImageTask) + strlen(filePath);
    if (newMemoryUsage > MEMORY_LIMIT) {
        printf("Exceeds memory limit. Cannot add more tasks.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->totalMemoryUsed = newMemoryUsage;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void removeImageTask(TaskManager* manager, int index) {
    pthread_mutex_lock(&manager->lock);

    if (index < 0 || index >= manager->count) {
        printf("Invalid task index.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    ImageTask* task = &manager->tasks[index];
    free(task->filePath);
    memmove(&manager->tasks[index], &manager->tasks[index + 1], (manager->count - index - 1) * sizeof(ImageTask));
    manager->totalMemoryUsed -= (sizeof(ImageTask) + strlen(task->filePath));
    manager->count--;

    pthread_mutex_unlock(&manager->lock);
}

void printTasks(TaskManager* manager) {
    for (int i = 0; i < manager->count; i++) {
        printf("Task %d: File Path = %s, Width = %d, Height = %d\n", 
               i, manager->tasks[i].filePath, manager->tasks[i].width, manager->tasks[i].height);
    }
}

int main() {
    TaskManager manager;
    initializeTaskManager(&manager);

    addImageTask(&manager, "path/to/image1.jpg", 1920, 1080);
    addImageTask(&manager, "path/to/image2.jpg", 640, 480);

    printTasks(&manager);

    removeImageTask(&manager, 0);

    printTasks(&manager);

    return 0;
}
```

