#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define MEMORY_LIMIT (MAX_ENTRIES * sizeof(ImageMetadata))

typedef struct {
    int width;
    int height;
    char format[20];
    char metadata_tags[1024];
} ImageMetadata;

typedef struct {
    ImageMetadata *entries;
    int count;
    pthread_mutex_t lock;
} MetadataManager;

int initialize_metadata_manager(MetadataManager *manager) {
    manager->entries = (ImageMetadata *)malloc(MAX_ENTRIES * sizeof(ImageMetadata));
    if (!manager->entries) {
        return -1; // Memory allocation failed
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return 0;
}

void destroy_metadata_manager(MetadataManager *manager) {
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}

int add_image_metadata(MetadataManager *manager, const ImageMetadata *metadata) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Maximum entries reached
    }
    if ((manager->count + 1) * sizeof(ImageMetadata) > MEMORY_LIMIT) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory limit exceeded
    }

    memcpy(&manager->entries[manager->count], metadata, sizeof(ImageMetadata));
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Example usage
int main() {
    MetadataManager manager;
    if (initialize_metadata_manager(&manager) != 0) {
        fprintf(stderr, "Failed to initialize metadata manager\n");
        return 1;
    }

    ImageMetadata new_image = {800, 600, "JPEG", "exposure=auto"};
    if (add_image_metadata(&manager, &new_image) != 0) {
        fprintf(stderr, "Failed to add image metadata\n");
        destroy_metadata_manager(&manager);
        return 1;
    }

    printf("Image metadata added successfully\n");
    destroy_metadata_manager(&manager);
    return 0;
}
