#define MAX_PACKET_SIZE 1024

typedef struct {
    uint16_t length;
} PacketHeader;

typedef struct {
    PacketHeader header;
    uint8_t payload[MAX_PACKET_SIZE];
} Packet;

typedef enum {
    PACKET_SUCCESS,
    PACKET_OVERFLOW,
    PACKET_ALLOCATION_FAILED
} PacketStatus;

Packet* process_packets(const uint16_t* headers, size_t count, size_t max_buffer_size, size_t max_payload_size, size_t* buffer_size) {
    if (count == 0 || max_buffer_size == 0 || max_payload_size == 0) {
        return NULL;
    }

    PacketStatus status = PACKET_SUCCESS;
    size_t total_required_size = 0;

    for (size_t i = 0; i < count; ++i) {
        if (headers[i] > max_payload_size) {
            status = PACKET_OVERFLOW;
            break;
        }
        total_required_size += sizeof(PacketHeader) + headers[i];
        if (total_required_size > max_buffer_size) {
            status = PACKET_OVERFLOW;
            break;
        }
    }

    if (status != PACKET_SUCCESS) {
        return NULL;
    }

    Packet* buffer = (Packet*)malloc(total_required_size);
    if (buffer == NULL) {
        return NULL;
    }

    *buffer_size = total_required_size;

    size_t offset = 0;
    for (size_t i = 0; i < count; ++i) {
        buffer[offset].header.length = headers[i];
        memcpy(buffer[offset].payload, /* Source payload data */, headers[i]);
        offset += sizeof(PacketHeader) + headers[i];
    }

    return buffer;
}
