#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_IMAGE_FILES 1000
#define MAX_LAYER_PER_FILE 50

typedef struct ImageLayer {
    int file_id;
    int layer_index;
    unsigned char* data;
} ImageLayer;

int load_configuration(const char* config_file, int* num_files, int** layers_per_file) {
    FILE* fp = fopen(config_file, "r");
    if (!fp) {
        perror("Failed to open configuration file");
        return -1;
    }

    if (fscanf(fp, "%d", num_files) != 1 || *num_files > MAX_IMAGE_FILES) {
        fprintf(stderr, "Invalid number of image files in the configuration file\n");
        fclose(fp);
        return -1;
    }

    *layers_per_file = (int*)malloc(*num_files * sizeof(int));
    if (!*layers_per_file) {
        perror("Failed to allocate memory for layers per file");
        fclose(fp);
        return -1;
    }

    for (int i = 0; i < *num_files; ++i) {
        if (fscanf(fp, "%d", &(*layers_per_file)[i]) != 1 || (*layers_per_file)[i] > MAX_LAYER_PER_FILE) {
            fprintf(stderr, "Invalid number of layers in the configuration file\n");
            free(*layers_per_file);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

int load_image_layers(const char* config_file, ImageLayer** layers) {
    int num_files, *layers_per_file;
    if (load_configuration(config_file, &num_files, &layers_per_file) != 0) {
        return -1;
    }

    *layers = (ImageLayer*)malloc(num_files * MAX_LAYER_PER_FILE * sizeof(ImageLayer));
    if (!*layers) {
        perror("Failed to allocate memory for image layers");
        free(layers_per_file);
        return -1;
    }

    int layer_index = 0;
    for (int i = 0; i < num_files; ++i) {
        (*layers)[layer_index].file_id = i + 1;
        for (int j = 0; j < layers_per_file[i]; ++j, ++layer_index) {
            (*layers)[layer_index].layer_index = j + 1;

            // Simulate loading layer data from a file
            char filename[256];
            snprintf(filename, sizeof(filename), "image%d_layer%d.dat", i + 1, j + 1);
            FILE* fp = fopen(filename, "rb");
            if (!fp) {
                perror("Failed to open image layer file");
                continue;
            }

            fseek(fp, 0, SEEK_END);
            long size = ftell(fp);
            fseek(fp, 0, SEEK_SET);

            (*layers)[layer_index].data = (unsigned char*)malloc(size);
            if (!(*layers)[layer_index].data) {
                perror("Failed to allocate memory for layer data");
                fclose(fp);
                continue;
            }

            fread((*layers)[layer_index].data, 1, size, fp);
            fclose(fp);

            (*layers)[layer_index].size = size;
        }
    }

    free(layers_per_file);
    return 0;
}

void free_image_layers(ImageLayer* layers, int num_files, int** layers_per_file) {
    for (int i = 0; i < num_files * MAX_LAYER_PER_FILE; ++i) {
        if (layers[i].data) {
            free(layers[i].data);
        }
    }

    free(*layers_per_file);
    free(layers);
}

// Example usage
int main() {
    ImageLayer* layers;
    int num_files;

    if (load_image_layers("config.txt", &layers, &num_files) == 0) {
        // Process the layers here

        free_image_layers(layers, num_files, NULL);
    }

    return 0;
}
```

