int manage_crc_indications(int max_size, int *current_size) {
    static int instance_count = 0;
    static struct timespec last_time = {0};
    static time_t current_time;

    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (instance_count >= MAX_INSTANCES_PER_SECOND && 
        difftime(current_time.tv_sec, last_time.tv_sec) == 0) {
        return -1; // Maximum instances per second exceeded
    }

    int to_allocate = max_size - *current_size;
    if (to_allocate <= 0) {
        return 0; // No allocation needed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_instances = realloc(*current_size == 0 ? NULL : *current_size, 
                                                       (*current_size + to_allocate) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_instances == NULL) {
        return -1; // Memory allocation failed
    }

    *current_size += to_allocate;
    instance_count++;

    for (int i = 0; i < to_allocate; i++) {
        new_instances[*current_size - 1 + i].ue_info = generate_random_ue_info();
        new_instances[*current_size - 1 + i].rnti = generate_random_rnti();
        new_instances[*current_size - 1 + i].crc_indication = generate_crc_indication_rel8_tag();
        new_instances[*current_size - 1 + i].crcflag = rand() % 2; // Randomly set CRCFLAG
        new_instances[*current_size - 1 + i].timestamp = time(NULL);
    }

    *current_size = new_instances;
    last_time.tv_sec = current_time.tv_sec;

    return to_allocate;
