#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

NFAPI_CRC_INDICATION_PDU_T* populate_doubly_linked_list(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of nodes\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator
    NFAPI_CRC_INDICATION_PDU_T* head = create_node(1, 0); // Create a dummy node for simplicity
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    for (int i = 2; i <= N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(i, i % 100); // Example data generation
        current->next = new_node;
        new_node->prev = current;
        current = new_node;
    }

    return head;
}

void free_doubly_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int N = 10; // Example number of nodes
    NFAPI_CRC_INDICATION_PDU_T* list_head = populate_doubly_linked_list(N);

    // Example traversal and verification
    NFAPI_CRC_INDICATION_PDU_T* current = list_head->next;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRCFLAG);
        current = current->next;
    }

    free_doubly_linked_list(list_head);
    return 0;
}
