#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_SIZE 1024 * 1024 * 1024 // Maximum memory size of 1GB
#define INITIAL_CHUNK_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, size_t* total_size) {
    if (N <= 0 || total_size == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    *total_size = 0;
    int chunk_size = INITIAL_CHUNK_SIZE;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    pthread_mutex_t lock;

    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return NULL;
    }

    while (*total_size + chunk_size < MAX_MEMORY_SIZE && N > 0) {
        NFAPI_CRC_INDICATION_PDU_T* new_chunk = realloc(list, *total_size + chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_chunk == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_destroy(&lock);
            return list;
        }

        list = new_chunk;
        for (int i = 0; i < chunk_size && N > 0; i++) {
            list[*total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T) + i].RX_UE_INFORMATION_TAG = rand();
            list[*total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T) + i].RNTI = (unsigned short)(rand() % 65536);
            list[*total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T) + i].CRC_INDICATION_REL8_TAG = rand();
            N--;
        }

        *total_size += chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (N > 0 && chunk_size < INITIAL_CHUNK_SIZE * 10) {
            chunk_size *= 2; // Increase chunk size for better efficiency
        }
    }

    pthread_mutex_destroy(&lock);
    return list;
}
