    manager->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_allocation, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pool) {
        free(manager);
        return NULL; // Memory allocation failed
    }
    manager->pool_size = initial_allocation;
    manager->max_pool_size = max_pool_size;
    manager->current_usage = 0;
    manager->allocation_limit = 2 * initial_allocation; // Example limit, can be adjusted
    return manager;
