### PHP Function: `userAccountManagement`

```php
<?php
class UserDatabase {
    private $users = [];

    public function createUser($id, $name, $email, $password) {
        if (!isset($this->users[$id])) {
            $this->users[$id] = ['name' => $name, 'email' => $email, 'password' => password_hash($password, PASSWORD_DEFAULT)];
            return true;
        }
        return false;
    }

    public function updateUser($id, $name, $email, $password) {
        if (isset($this->users[$id])) {
            $this->users[$id]['name'] = $name;
            $this->users[$id]['email'] = $email;
            $this->users[$id]['password'] = password_hash($password, PASSWORD_DEFAULT);
            return true;
        }
        return false;
    }

    public function deleteUser($id) {
        if (isset($this->users[$id])) {
            unset($this->users[$id]);
            return true;
        }
        return false;
    }
}

function userAccountManagement($requestBody) {
    $data = json_decode($requestBody, true);

    if (!isset($data['name']) || !isset($data['email']) || !isset($data['password'])) {
        return json_encode(['message' => 'error', 'reason' => 'Missing fields']);
    }

    $action = isset($data['action']) ? $data['action'] : null;
    $id = isset($data['id']) ? intval($data['id']) : 0;

    $db = new UserDatabase();

    if ($action === 'delete') {
        if ($db->deleteUser($id)) {
            return json_encode(['message' => 'success']);
        } else {
            return json_encode(['message' => 'error', 'reason' => 'User not found']);
        }
    } elseif ($id) {
        if ($db->updateUser($id, $data['name'], $data['email'], $data['password'])) {
            return json_encode(['message' => 'success']);
        } else {
            return json_encode(['message' => 'error', 'reason' => 'User not found']);
        }
    } else {
        if ($db->createUser($id, $data['name'], $data['email'], $data['password'])) {
            return json_encode(['message' => 'success']);
        } else {
            return json_encode(['message' => 'error', 'reason' => 'User already exists']);
        }
    }
}
?>
