#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} NFAPICrcPool;

NFAPICrcPool* createCrcPool(size_t maxLimit, int enableLogging) {
    if (maxLimit == 0 || maxLimit < 0) {
        return NULL; // Invalid limit
    }

    NFAPICrcPool *pool = (NFAPICrcPool*)malloc(sizeof(NFAPICrcPool));
    if (!pool) {
        return NULL; // Memory allocation failed
    }

    pool->capacity = maxLimit;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(maxLimit, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL; // Memory allocation failed
    }

    return pool;
}

void destroyCrcPool(NFAPICrcPool *pool) {
    if (pool) {
        pthread_mutex_lock(&pool->lock);
        free(pool->pool);
        pthread_mutex_unlock(&pool->lock);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateCrcStruct(NFAPICrcPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }

    NFAPI_CRC_INDICATION_PDU_T *ptr = &pool->pool[pool->used++];
    ptr->RX_UE_INFORMATION_TAG = rand(); // Randomly set tag
    ptr->RNTI = rand();
    ptr->CRCFLAG = (rand() % 2); // Randomly set CRC flag

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void deallocateCrcStruct(NFAPICrcPool *pool, NFAPI_CRC_INDICATION_PDU_T *ptr) {
    if (!ptr || !pool) {
        return; // Invalid pointer
    }

    pthread_mutex_lock(&pool->lock);

    size_t index = (size_t)(ptr - pool->pool);
    if (index < pool->used) {
        pool->used--;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return; // Pointer not in the pool
    }

    pthread_mutex_unlock(&pool->lock);
}

size_t getCrcPoolUsage(NFAPICrcPool *pool) {
    if (!pool) {
        return 0; // Invalid pool
    }

    pthread_mutex_lock(&pool->lock);
    size_t usage = pool->used;
    pthread_mutex_unlock(&pool->lock);

    return usage;
}
