#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_POOL_SIZE 1000

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    bool crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pool[MAX_POOL_SIZE];
    size_t next_index;
    pthread_mutex_t lock;
} PDU_Pool;

PDU_Pool pdu_pool;

void init_pdu_pool() {
    pthread_mutex_init(&pdu_pool.lock, NULL);
    pdu_pool.next_index = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&pdu_pool.lock);
    if (pdu_pool.next_index >= MAX_POOL_SIZE) {
        pthread_mutex_unlock(&pdu_pool.lock);
        return NULL; // Pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_pool.pool[pdu_pool.next_index++];
    pthread_mutex_unlock(&pdu_pool.lock);

    pdu->rx_ue_information_tag = rand();
    pdu->rnti = rand();
    pdu->crc_flag = (rand() % 2) == 0;

    return pdu;
}

void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pdu_pool.lock);
    // Logic to deallocate and recycle the pdu
    pthread_mutex_unlock(&pdu_pool.lock);
}

int get_current_pool_usage() {
    return pdu_pool.next_index;
}
