    if (metadata == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Reopen directory and load metadata
    dir = opendir(directory);
    if (dir == NULL) {
        perror("Failed to reopen directory");
        free(metadata);
        return NULL;
    }

    *num_images = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (ends_with(entry->d_name, ".jpg") || ends_with(entry->d_name, ".png")) {
