    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL && (*images)[file_count].filename == NULL) {
        if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            (*images)[file_count].filename = strdup(entry->d_name);
