#include <string.h>

#define MAX_SESSIONS 10000
#define MAX_PACKETS_PER_SESSION 1000

typedef struct PacketInfo {
    unsigned int timestamp;
    size_t payload_length;
    char checksum_tag[2];
} PacketInfo;

typedef struct SessionData {
    PacketInfo packets[MAX_PACKETS_PER_SESSION];
    size_t packet_count;
} SessionData;

SessionData *sessions[MAX_SESSIONS] = {NULL};

unsigned int get_session_id() {
    // Simulate getting a session ID
    static unsigned int id = 0;
    return id++;
}

void process_packet(unsigned int session_id, PacketInfo *packet) {
    if (session_id >= MAX_SESSIONS) {
        fprintf(stderr, "Error: Invalid session ID\n");
        return;
    }

    if (!sessions[session_id]) {
        sessions[session_id] = (SessionData *)malloc(sizeof(SessionData));
        if (!sessions[session_id]) {
            perror("Memory allocation failed");
            return;
        }
    }

    SessionData *sd = sessions[session_id];
    if (sd->packet_count >= MAX_PACKETS_PER_SESSION) {
        fprintf(stderr, "Error: Packet limit exceeded for session %u\n", session_id);
        return;
    }

    memcpy(&sd->packets[sd->packet_count], packet, sizeof(PacketInfo));
    sd->packet_count++;
}

void cleanup() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i]) {
            free(sessions[i]);
            sessions[i] = NULL;
        }
    }
}

// Example usage
int main() {
    PacketInfo packet;
    unsigned int session_id = get_session_id();

    // Simulate processing a packet
    packet.timestamp = 1234567890;
    packet.payload_length = 1024;
    strcpy(packet.checksum_tag, "AB");

    process_packet(session_id, &packet);

    cleanup();
    return 0;
}
