    int num_images = read_config("config.txt", &metadata);

    if (num_images >= 0) {
        printf("Successfully initialized %d images:\n", num_images);
        for (int i = 0; i < num_images; ++i) {
            printf("%s: %dx%d\n", metadata[i].filename, metadata[i].width, metadata[i].height);
        }
        free(metadata);
    } else {
        printf("Failed to initialize image metadata.\n");
    }

    return 0;
}
