#include <stdio.h>

#define MAX_NFAPIS 1024

typedef struct {
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t max_size;
    size_t current_size;
    pthread_mutex_t mutex;
} CustomMemoryPool;

CustomMemoryPool pool;

int init_pool(size_t max_size) {
    if (max_size > MAX_NFAPIS) return -1; // Error: Exceeds maximum limit
    pool.pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool.pool) return -2; // Error: Memory allocation failed
    pool.max_size = max_size;
    pool.current_size = 0;
    pthread_mutex_init(&pool.mutex, NULL);
    return 0;
}

int create_and_populate(size_t num_structs) {
    if (num_structs + pool.current_size > pool.max_size) return -3; // Error: Exceeds maximum limit
    int result = pthread_mutex_lock(&pool.mutex);
    if (result != 0) return -4; // Error: Locking failed

    for (size_t i = 0; i < num_structs; ++i) {
        pool.pool[pool.current_size + i].RNTI = rand();
        pool.pool[pool.current_size + i].CRCFLAG = rand() % 2;
    }

    pool.current_size += num_structs;

    pthread_mutex_unlock(&pool.mutex);
    return 0;
}

int delete_by_rnti(uint32_t rnti) {
    int result = pthread_mutex_lock(&pool.mutex);
    if (result != 0) return -4; // Error: Locking failed

    for (size_t i = 0; i < pool.current_size; ++i) {
        if (pool.pool[i].RNTI == rnti) {
            memmove(&pool.pool[i], &pool.pool[i + 1], (pool.current_size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --pool.current_size;
            break;
        }
    }

    pthread_mutex_unlock(&pool.mutex);
    return 0;
}

void cleanup() {
    free(pool.pool);
    pthread_mutex_destroy(&pool.mutex);
}
