#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

Node* createPDU(int RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL; // Memory allocation failed
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;
    return newNode;
}

Node* generatePDULinkedList(int N) {
    if (N > MAX_PDU_COUNT) {
        return (Node*)-1; // Error code for exceeding maximum limit
    }

    Node* head = NULL;
    Node** current = &head;

    srand(time(0)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        Node* newNode = createPDU(rand() % 100, rand() % 65536, rand() % 100);
        if (!newNode) {
            // Memory allocation failed, clean up and return error
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return (Node*)-1; // Error code for memory allocation failure
        }

        *current = newNode;
        current = &newNode->next;
    }

    return head;
}
