#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
    size_t allocated_size;
    size_t used_size;
} SessionMemoryManager;

SessionMemoryManager* create_session_memory_manager(size_t initial_allocation) {
    if (initial_allocation > MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL; // Exceeds maximum memory limit
    }
    SessionMemoryManager* manager = malloc(sizeof(SessionMemoryManager));
    if (!manager) {
        return NULL; // Memory allocation failed
    }
    manager->pdu_array = malloc(initial_allocation * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_array) {
        free(manager);
        return NULL;
    }
    manager->allocated_size = initial_allocation;
    manager->used_size = 0;
    srand(time(NULL)); // Seed for random number generation
    return manager;
}

int allocate_pdu(SessionMemoryManager* manager, size_t N) {
    if (N > MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Exceeds maximum memory limit
    }
    while (manager->used_size + N > manager->allocated_size) {
        size_t new_size = manager->allocated_size * 2;
        if (new_size > MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            return -1; // Exceeds maximum memory limit
        }
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->pdu_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return -1; // Memory reallocation failed
        }
        manager->pdu_array = new_array;
        manager->allocated_size = new_size;
    }
    for (size_t i = 0; i < N; ++i) {
        manager->pdu_array[manager->used_size + i].RX_UE_INFORMATION_TAG = rand();
        manager->pdu_array[manager->used_size + i].RNTI = rand() % 65536;
        manager->pdu_array[manager->used_size + i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    manager->used_size += N;
    return 0; // Allocation successful
}

void deallocate_pdu(SessionMemoryManager* manager) {
    free(manager->pdu_array);
    free(manager);
}

int main() {
    size_t initial_allocation = 100;
    SessionMemoryManager* manager = create_session_memory_manager(initial_allocation);
    if (!manager) {
        return -1; // Failed to create session memory manager
    }
    size_t N = 50;
    if (allocate_pdu(manager, N) != 0) {
        deallocate_pdu(manager);
        return -1; // Failed to allocate PDU
    }
    // Use the allocated PDUs
    deallocate_pdu(manager);
    return 0; // Success
}
