        free(list->list);
        free(list);
    }
}

int nfapi_crc_list_add(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) {
        return -1;
    }
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            return -1;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }
    list->list[list->count++] = pdu;
    return 0;
}

int nfapi_crc_list_update(NFAPI_CRC_LIST_T* list, size_t index, uint32_t crcflag) {
