typedef struct {
    compressed_image_t **images;
    size_t count;
} image_list_t;

image_list_t* create_image_list(size_t initial_capacity) {
    image_list_t *list = (image_list_t*)malloc(sizeof(image_list_t));
    if (!list) return NULL;

    list->images = (compressed_image_t**)calloc(initial_capacity, sizeof(compressed_image_t*));
    if (!list->images) {
        free(list);
        return NULL;
    }
    list->count = 0;

    return list;
}

void destroy_image_list(image_list_t *list) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->images[i]->compressed_data) {
            free(list->images[i]->compressed_data);
        }
        free(list->images[i]);
    }
    free(list->images);
    free(list);
}

int add_image_to_list(image_list_t *list, int width, int height, size_t compressed_size) {
    if (!list || !width || !height || compressed_size > SIZE_MAX / sizeof(unsigned char *)) return -1;

    list->count++;
    list->images = (compressed_image_t**)realloc(list->images, list->count * sizeof(compressed_image_t*));
    if (!list->images) {
        --list->count;
        return -1;
    }

    compressed_image_t *image = (compressed_image_t*)malloc(sizeof(compressed_image_t));
    if (!image) {
        --list->count;
        return -1;
    }

    image->width = width;
    image->height = height;

    image->compressed_data = (unsigned char*)calloc(compressed_size, sizeof(unsigned char));
    if (!image->compressed_data) {
        free(image);
        --list->count;
        return -1;
    }

    list->images[list->count - 1] = image;
    return 0;
}

int update_image_in_list(image_list_t *list, size_t index, int new_width, int new_height, size_t compressed_size) {
    if (!list || index >= list->count || !new_width || !new_height || compressed_size > SIZE_MAX / sizeof(unsigned char *)) return -1;

    compressed_image_t *image = list->images[index];

    if (image->compressed_data) {
        free(image->compressed_data);
    }

    image->width = new_width;
    image->height = new_height;

    image->compressed_data = (unsigned char*)realloc(image->compressed_data, compressed_size * sizeof(unsigned char));
    if (!image->compressed_data) {
        return -1;
    }

    return 0;
}

int get_image_from_list(const image_list_t *list, size_t index, int *width, int *height, unsigned char **compressed_data) {
    if (!list || index >= list->count) return -1;

    const compressed_image_t *image = list->images[index];

    *width = image->width;
    *height = image->height;
    *compressed_data = image->compressed_data;

    return 0;
}
