    time_t expiration_time;
} UserSession;

UserSession** sessions = NULL;
int session_count = 0;
int max_sessions = MAX_SESSIONS;

void initialize_sessions() {
    sessions = (UserSession**)malloc(max_sessions * sizeof(UserSession*));
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void add_session(int user_id, char* data, time_t duration) {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (!session) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    session->user_id = user_id;
    session->data = strdup(data);
    session->start_time = time(NULL);
    session->expiration_time = session->start_time + duration;

    sessions[session_count++] = session;
}

void expire_sessions() {
    for (int i = 0; i < session_count; ) {
        if (time(NULL) >= sessions[i]->expiration_time) {
            free(sessions[i]->data);
            free(sessions[i]);
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
        } else {
            i++;
        }
    }
}

void cleanup_sessions() {
    for (int i = 0; i < session_count; i++) {
        free(sessions[i]->data);
        free(sessions[i]);
    }
    free(sessions);
}

int main() {
    initialize_sessions();

    add_session(1, "session_data_1", 60); // Example session
    add_session(2, "session_data_2", 300);

    while (1) {
        expire_sessions();
        sleep(1); // Simulate time passing
    }

    cleanup_sessions();
    return 0;
}
