int allocate_images(int num_images, size_t* total_size, image_t** images) {
    if (num_images <= 0 || *total_size > MAX_IMAGE_SIZE) {
        fprintf(stderr, "Invalid input: Number of images must be positive and total size must not exceed 1 GB.\n");
        return -1;
    }

    size_t aligned_total_size = ((*total_size + 15) / 16) * 16; // Align to 16 bytes

    if (aligned_total_size > MAX_IMAGE_SIZE) {
        fprintf(stderr, "Error: Total size exceeds maximum allowed memory of 1 GB.\n");
        return -2;
    }

    *images = malloc(num_images * sizeof(image_t));
    if (*images == NULL) {
        perror("Failed to allocate memory for image list.");
        return -3;
    }

    unsigned char* data_start = (unsigned char*)malloc(aligned_total_size);
    if (data_start == NULL) {
        free(*images);
        perror("Failed to allocate memory for image data.");
        return -4;
    }

    *total_size = aligned_total_size;

    for (int i = 0; i < num_images; ++i) {
        (*images)[i].pixels = data_start + (i * MAX_IMAGE_SIZE);
    }

    return 0;
}

void free_images(image_t* images, int num_images) {
    if (images == NULL || num_images <= 0) {
        return;
    }

    // Free the pixel data first to avoid dangling pointers
    for (int i = 0; i < num_images; ++i) {
        free(images[i].pixels);
    }

    // Then free the image list
    free(images);
}

int main() {
    int num_images = 5;
    size_t total_size = 0;

    image_t* images = NULL;
    if (allocate_images(num_images, &total_size, &images) != 0) {
        fprintf(stderr, "Failed to allocate images.\n");
        return -1;
    }

    // Example usage of allocated images
    for (int i = 0; i < num_images; ++i) {
        strcpy(images[i].filename, "image_");
        sprintf(images[i].filename + strlen("image_"), "%d", i);
        images[i].width = 1920;
        images[i].height = 1080;
        memset(images[i].pixels, 0, MAX_IMAGE_SIZE); // Initialize pixels
    }

    free_images(images, num_images);

    return 0;
}
