['```c
#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <sys/stat.h>

typedef struct {
    int width;
    int height;
    unsigned char* pixels;
} image_data_t;

size_t calculate_total_size(const char* directory);
int process_images(const char* directory, image_data_t** images);

size_t calculate_total_size(const char* directory) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    size_t total_size = 0;

    dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        if (stat(path, &file_stat) == 0) {
            total_size += file_stat.st_size;
        } else {
            perror("stat");
        }
    }

    closedir(dir);
    return total_size;
}

int process_images(const char* directory, image_data_t** images) {
    DIR *dir;
    struct dirent *entry;
    size_t total_size = calculate_total_size(directory);

    if (total_size == -1) {
        return -1;
    }

    *images = malloc(total_size);
    if (*images == NULL) {
        perror("malloc");
        return -1;
    }

    dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        free(*images);
        return -1;
    }

    char* ptr = (char*)*images;
    while ((entry = readdir(dir)) != NULL) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        FILE *file = fopen(path, "rb");
        if (file == NULL) {
            perror("fopen");
            continue;
        }

        size_t bytes_read = fread(ptr, 1, file_stat.st_size, file);
        fclose(file);

        if (bytes_read != file_stat.st_size) {
            perror("fread");
        }

        ptr += file_stat.st_size;
    }

    closedir(dir);
    return 0;
}
