#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LEVEL 4

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char *message;
    // Optional metadata fields can be added here
} LogEntry;

typedef struct Logger {
    LogEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int log_level_threshold;
} Logger;

Logger* create_logger(size_t initial_capacity) {
    Logger *logger = (Logger*)malloc(sizeof(Logger));
    logger->entries = (LogEntry**)calloc(initial_capacity, sizeof(LogEntry*));
    logger->capacity = initial_capacity;
    logger->count = 0;
    pthread_mutex_init(&logger->lock, NULL);
    pthread_cond_init(&logger->cond, NULL);
    logger->log_level_threshold = LOG_DEBUG;
    return logger;
}

void destroy_logger(Logger *logger) {
    for (size_t i = 0; i < logger->count; ++i) {
        free(logger->entries[i]->message);
        free(logger->entries[i]);
    }
    free(logger->entries);
    pthread_mutex_destroy(&logger->lock);
    pthread_cond_destroy(&logger->cond);
    free(logger);
}

void log_entry(Logger *logger, LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);

    if (level < logger->log_level_threshold) {
        va_end(args);
        return;
    }

    pthread_mutex_lock(&logger->lock);

    while (logger->count >= logger->capacity) {
        pthread_cond_wait(&logger->cond, &logger->lock);
    }

    LogEntry *entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->level = level;
    size_t message_length = vsnprintf(NULL, 0, format, args) + 1;
    entry->message = (char*)malloc(message_length);
    vsnprintf(entry->message, message_length, format, args);

    logger->entries[logger->count++] = entry;
    pthread_cond_signal(&logger->cond);
    pthread_mutex_unlock(&logger->lock);

    va_end(args);
}

void *log_retrieval_thread(void *arg) {
    Logger *logger = (Logger*)arg;

    while (1) {
        pthread_mutex_lock(&logger->lock);
        while (logger->count == 0) {
            pthread_cond_wait(&logger->cond, &logger->lock);
        }

        LogEntry *entry = logger->entries[--logger->count];
        pthread_mutex_unlock(&logger->lock);

        // Process the log entry
        printf("Level: %d, Timestamp: %ld, Message: %s\n", entry->level, (long)entry->timestamp, entry->message);
        free(entry->message);
        free(entry);
    }

    return NULL;
}

int main() {
    Logger *logger = create_logger(100);

    pthread_t retrieval_thread;
    pthread_create(&retrieval_thread, NULL, log_retrieval_thread, logger);

    // Simulate logging
    for (int i = 0; i < 500; ++i) {
        log_entry(logger, LOG_INFO, "Log entry %d", i);
        usleep(1000); // Simulate varying log frequency
    }

    pthread_join(retrieval_thread, NULL);

    destroy_logger(logger);
    return 0;
}
```

This code snippet provides a basic implementation of a high-throughput logging system in C. It includes functions for creating and destroying the logger, logging entries, and a separate thread for retrieving and processing log entries. The logger uses mutexes to ensure thread safety and condition variables to manage waiting and signaling between threads. The log retrieval thread continuously waits for new log entries and processes them as they become available.

Please note that this is a simplified example and may need further enhancements and optimizations based on specific requirements and constraints.']

