} img_t;

typedef struct image_node {
    img_t* img;
    struct image_node* next;
} image_node;

image_node* load_images(const char** file_paths, int num_files) {
    if (num_files > MAX_IMAGES) {
        return NULL; // Exceeds maximum number of images
    }

    image_node* head = NULL;
    size_t total_memory_used = 0;

    for (int i = 0; i < num_files; ++i) {
        img_t* new_img = malloc(sizeof(img_t));
        if (!new_img) {
            goto cleanup;
        }

        // Simulate loading image metadata and pixels
        new_img->width = 800;
        new_img->height = 600;
        size_t pixel_size = (size_t)new_img->width * (size_t)new_img->height * sizeof(unsigned char);
        new_img->pixels = malloc(pixel_size);
        if (!new_img->pixels) {
            free(new_img);
            goto cleanup;
        }

        // Simulate loading pixels
        memset(new_img->pixels, 0x00, pixel_size);

        image_node* new_node = malloc(sizeof(image_node));
        if (!new_node) {
            free(new_img->pixels);
            free(new_img);
            goto cleanup;
        }
        new_node->img = new_img;
        new_node->next = head;
        head = new_node;

        total_memory_used += sizeof(img_t) + pixel_size;
        if (total_memory_used > MEMORY_THRESHOLD * 0.95) {
            // Approaching memory threshold, stop loading
            break;
        }
    }

    return head;

cleanup:
    // Clean up any partially loaded images and nodes
    image_node* current = head;
    while (current) {
        img_t* img = current->img;
        free(img->pixels);
        free(img);
        image_node* next = current->next;
        free(current);
        current = next;
    }
    return NULL; // Return failure status
}

void free_image_list(image_node* head) {
    while (head) {
        img_t* img = head->img;
        free(img->pixels);
        free(img);
        image_node* next = head->next;
        free(head);
        head = next;
    }
}

int main() {
    const char* file_paths[] = {"image1.jpg", "image2.png", "image3.bmp"};
    int num_files = sizeof(file_paths) / sizeof(file_paths[0]);

    image_node* images = load_images(file_paths, num_files);
    if (!images) {
        printf("Failed to load images.\n");
        return 1;
    }

    // Process loaded images
    // ...

    free_image_list(images);
    return 0;
}
