typedef struct PacketData {
    unsigned char* data;
    size_t length;
} PacketData;

size_t calculateTotalBytesToProcess(size_t* packetHeaders, int numHeaders) {
    // Calculate total bytes to process with overflow protection
    size_t totalBytes = 0;
    for (int i = 0; i < numHeaders; ++i) {
        if (totalBytes > SIZE_MAX - packetHeaders[i]) {
            fprintf(stderr, "Error: Integer overflow detected.\n");
            exit(EXIT_FAILURE);
        }
        totalBytes += packetHeaders[i];
    }
    return totalBytes;
}

PacketData* allocatePacketDataArray(size_t totalBytes, size_t* packetLengths, int numPackets) {
    PacketData* packetArray = (PacketData*)malloc(numPackets * sizeof(PacketData));
    if (!packetArray) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    unsigned char* dataBuffer = (unsigned char*)malloc(totalBytes);
    if (!dataBuffer) {
        free(packetArray);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    size_t offset = 0;
    for (int i = 0; i < numPackets; ++i) {
        packetArray[i].data = dataBuffer + offset;
        packetArray[i].length = packetLengths[i];
        offset += packetLengths[i];
    }

    return packetArray;
}

void processNetworkPackets(size_t* packetHeaders, size_t* packetLengths, int numHeaders) {
    size_t totalBytes = calculateTotalBytesToProcess(packetHeaders, numHeaders);
    PacketData* packetArray = allocatePacketDataArray(totalBytes, packetLengths, numHeaders);

    // Simulate processing packets
    for (int i = 0; i < numHeaders; ++i) {
        printf("Processing packet of size: %zu\n", packetArray[i].length);
        // Process each packet data here
    }

    // Free allocated memory
    free(packetArray->data);
    free(packetArray);
}

