#include <stdlib.h>
#include <stdio.h>

typedef struct FrameHeader {
    void** dataBuffers;
    size_t* bufferSizes;
    size_t numBuffers;
} FrameHeader;

FrameHeader* createFrameHeaders(size_t initialCapacity) {
    FrameHeader* headers = (FrameHeader*)malloc(initialCapacity * sizeof(FrameHeader));
    if (!headers) {
        fprintf(stderr, "Failed to allocate memory for FrameHeaders\n");
        return NULL;
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        headers[i].dataBuffers = NULL;
        headers[i].bufferSizes = NULL;
        headers[i].numBuffers = 0;
    }

    return headers;
}

void resizeFrameHeader(FrameHeader* header, size_t newCapacity) {
    void** newDataBuffers = (void**)realloc(header->dataBuffers, newCapacity * sizeof(void*));
    if (!newDataBuffers) {
        fprintf(stderr, "Failed to reallocate memory for data buffers\n");
        return;
    }

    size_t* newBufferSizes = (size_t*)realloc(header->bufferSizes, newCapacity * sizeof(size_t));
    if (!newBufferSizes) {
        fprintf(stderr, "Failed to reallocate memory for buffer sizes\n");
        free(newDataBuffers);
        return;
    }

    header->dataBuffers = newDataBuffers;
    header->bufferSizes = newBufferSizes;
}

void addFrameBuffer(FrameHeader* header, void* data, size_t size) {
    if (header->numBuffers >= MAX_BUFFERS_PER_HEADER) {
        fprintf(stderr, "Maximum number of buffers per header exceeded\n");
        return;
    }

    header->dataBuffers[header->numBuffers] = malloc(size);
    if (!header->dataBuffers[header->numBuffers]) {
        fprintf(stderr, "Failed to allocate memory for buffer data\n");
        return;
    }

    memcpy(header->dataBuffers[header->numBuffers], data, size);
    header->bufferSizes[header->numBuffers] = size;
    ++header->numBuffers;
}

void freeFrameHeaders(FrameHeader* headers, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        for (size_t j = 0; j < headers[i].numBuffers; ++j) {
            free(headers[i].dataBuffers[j]);
        }
        free(headers[i].dataBuffers);
        free(headers[i].bufferSizes);
    }
    free(headers);
}
```

### Explanation:
- **Memory Allocation**: The function `createFrameHeaders` dynamically allocates memory for an array of `FrameHeader` structures. It initializes the structure members to default values.
- **Dynamic Resizing**: The function `resizeFrameHeader` reallocates memory for the data buffers and buffer sizes arrays when needed.
- **Adding Buffers**: The function `addFrameBuffer` adds a new data buffer to a `FrameHeader`. It checks if the maximum number of buffers per header has been reached.
- **Memory Management**: The function `freeFrameHeaders` frees all allocated memory for the data buffers and the headers themselves.

### Assumptions:
- External libraries are assumed to provide robust memory management functions (`malloc`, `realloc`, `free`) that adhere to standard C behavior.
- Error handling is minimal and primarily focused on allocation failures. Additional validation should be added based on specific requirements.
- The maximum number of buffers per header (`MAX_BUFFERS_PER_HEADER`) is a predefined constant that must be defined elsewhere in the code.

### Usage:
To use this function, you would typically call `createFrameHeaders` to initialize an array of `FrameHeader` structures. Then, you can dynamically add data buffers using `addFrameBuffer`. When done, clean up by calling `freeFrameHeaders`.

```c
#define MAX_BUFFERS_PER_HEADER 10

int main() {
    FrameHeader* headers = createFrameHeaders(5);
    if (headers) {
        void* buffer = malloc(1024); // Example buffer data
        addFrameBuffer(headers, buffer, 1024);

        free(buffer);
        freeFrameHeaders(headers, 5);
    }

    return 0;
}
