int populate_nfaapi_pdu_set(NFAPI_PDU_SET_T **pdu_set, size_t *num_structs) {
    size_t num_blocks = (*num_structs + MAX_STRUCTURES - 1) / MAX_STRUCTURES;
    size_t total_size = num_blocks * sizeof(NFAPI_PDU_SET_T);

    // Check for potential integer overflow
    if (total_size / num_blocks != sizeof(NFAPI_PDU_SET_T)) {
        return -1; // Integer overflow detected
    }

    NFAPI_PDU_SET_T *new_pdu_set = realloc(*pdu_set, total_size);
    if (!new_pdu_set) {
        return -2; // Memory allocation failed
    }

    *pdu_set = new_pdu_set;

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < *num_structs; ++i) {
        (*pdu_set)[i].rx_ue_info_tag = generate_rx_ue_information_tag();
        (*pdu_set)[i].RNTI = generate_random_rnti();
