#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Packet {
    char* payload;
    size_t length;
} Packet;

Packet* process_packets(size_t packet_count, const size_t* packet_sizes) {
    if (packet_count == 0 || packet_sizes == NULL) {
        fprintf(stderr, "Invalid input: packet_count must be greater than 0 and packet_sizes must not be NULL.\n");
        return NULL;
    }

    Packet* packets = (Packet*)malloc(packet_count * sizeof(Packet));
    if (packets == NULL) {
        perror("Failed to allocate memory for packets.");
        return NULL;
    }

    size_t total_payload_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        if (packet_sizes[i] == 0) {
            fprintf(stderr, "Invalid packet size: size must be greater than 0.\n");
            free(packets);
            return NULL;
        }
        total_payload_size += packet_sizes[i];
    }

    char* all_payloads = (char*)malloc(total_payload_size * sizeof(char));
    if (all_payloads == NULL) {
        perror("Failed to allocate memory for payloads.");
        free(packets);
        return NULL;
    }

    packets[0].payload = all_payloads;
    for (size_t i = 1; i < packet_count; ++i) {
        packets[i].payload = packets[i - 1].payload + packets[i - 1].length;
    }

    for (size_t i = 0; i < packet_count; ++i) {
        packets[i].length = packet_sizes[i];
        memcpy(packets[i].payload, "Example Payload", packet_sizes[i]);
    }

    return packets;
}

void free_packets(Packet* packets, size_t packet_count) {
    if (packets != NULL) {
        for (size_t i = 0; i < packet_count; ++i) {
            if (packets[i].payload != NULL) {
                // Simulate payload processing
                printf("Processing payload of length %zu\n", packets[i].length);
            }
        }
        free(packets[0].payload);
        free(packets);
    }
}

int main() {
    size_t packet_sizes[] = {20, 30, 40};
    size_t packet_count = sizeof(packet_sizes) / sizeof(packet_sizes[0]);

    Packet* packets = process_packets(packet_count, packet_sizes);
    if (packets != NULL) {
        free_packets(packets, packet_count);
    }

    return 0;
}
