typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N) {
    if (N < 1 || N > 10000) { // Validate user input
        fprintf(stderr, "Invalid number of elements. Must be between 1 and 10000.\n");
        return NULL;
    }

    size_t total_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_memory > MAX_MEM_LIMIT) { // Check for integer overflow
        fprintf(stderr, "Memory allocation would exceed maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory);
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000000; // Example range
        array[i].RNTI = rand() % 4096; // Example range
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000000; // Example range
        int crcflag = rand() % 2; // Valid range for CRCFLAG
        if (crcflag >= 0 && crcflag <= 1) {
            array[i].CRCFLAG = crcflag;
        } else {
            fprintf(stderr, "Invalid CRCFLAG value. Setting to 0.\n");
            array[i].CRCFLAG = 0;
        }
    }

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
