#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_ALLOCATION 1024 * 1024 // 1MB

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t allocated_memory;
} CRC_LIST_T;

CRC_LIST_T* crc_list_init() {
    CRC_LIST_T *crc_list = (CRC_LIST_T *)malloc(sizeof(CRC_LIST_T));
    if (!crc_list) return NULL;
    crc_list->list = NULL;
    crc_list->count = 0;
    crc_list->capacity = 0;
    pthread_mutex_init(&crc_list->mutex, NULL);
    pthread_cond_init(&crc_list->cond, NULL);
    crc_list->allocated_memory = 0;
    return crc_list;
}

void crc_list_free(CRC_LIST_T *crc_list) {
    if (crc_list) {
        free(crc_list->list);
        pthread_mutex_destroy(&crc_list->mutex);
        pthread_cond_destroy(&crc_list->cond);
        free(crc_list);
    }
}

int crc_list_add(CRC_LIST_T *crc_list, RX_UE_INFORMATION_TAG rx_ue_info, uint16_t rnti) {
    pthread_mutex_lock(&crc_list->mutex);
    if (crc_list->allocated_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_ALLOCATION) {
        pthread_mutex_unlock(&crc_list->mutex);
        return -1; // Memory allocation limit reached
    }
    if (crc_list->count == crc_list->capacity) {
        size_t new_capacity = crc_list->capacity ? crc_list->capacity * 2 : 4;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&crc_list->mutex);
            return -1; // Realloc failed
        }
        crc_list->list = new_list;
        crc_list->capacity = new_capacity;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = &crc_list->list[crc_list->count++];
    pdu->rx_ue_info = rx_ue_info;
    pdu->rnti = rnti;
    pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    crc_list->allocated_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_cond_signal(&crc_list->cond);
    pthread_mutex_unlock(&crc_list->mutex);
    return 0;
}

void crc_list_log_memory_usage(CRC_LIST_T *crc_list) {
    pthread_mutex_lock(&crc_list->mutex);
    printf("Memory Usage: %zu / %zu\n", crc_list->allocated_memory, MAX_MEMORY_ALLOCATION);
    pthread_mutex_unlock(&crc_list->mutex);
}
