#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ALLOCATIONS_PER_SECOND 1000

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** dynamic_list = NULL;
int current_size = 0;
int max_size = 0;
pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_allocation_time = 0;

int allocate_nfa_pi_pdus(int N) {
    pthread_mutex_lock(&allocation_lock);
    time_t current_time = time(NULL);

    if (current_size + N > max_size) {
        int new_max_size = current_size + N + 1000; // Increase by a factor of 1.5
        dynamic_list = realloc(dynamic_list, new_max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!dynamic_list) {
            pthread_mutex_unlock(&allocation_lock);
            return -1;
        }
        max_size = new_max_size;
    }

    int allocations_this_second = current_time == last_allocation_time ? N : 0;
    if (allocations_this_second > MAX_ALLOCATIONS_PER_SECOND) {
        pthread_mutex_unlock(&allocation_lock);
        return -2; // Exceeded allocation limit
    }

    for (int i = 0; i < N; i++) {
        dynamic_list[current_size + i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!dynamic_list[current_size + i]) {
            pthread_mutex_unlock(&allocation_lock);
            return -1;
        }
        dynamic_list[current_size + i]->RX_UE_INFORMATION_TAG = rand();
        dynamic_list[current_size + i]->RNTI = rand();
        dynamic_list[current_size + i]->CRC_INDICATION_REL8_TAG = rand();
        dynamic_list[current_size + i]->CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
        dynamic_list[current_size + i]->timestamp = time(NULL);
    }

    current_size += N;
    if (current_time != last_allocation_time) {
        allocations_this_second = N;
    }
    last_allocation_time = current_time;

    pthread_mutex_unlock(&allocation_lock);
    return N;
}

void free_nfa_pi_pdus() {
    pthread_mutex_lock(&allocation_lock);
    for (int i = 0; i < current_size; i++) {
        free(dynamic_list[i]);
    }
    free(dynamic_list);
    dynamic_list = NULL;
    current_size = 0;
    max_size = 0;
    last_allocation_time = 0;
    pthread_mutex_unlock(&allocation_lock);
}

void log_memory_usage() {
    pthread_mutex_lock(&allocation_lock);
    printf("Current memory usage: %d structures\n", current_size);
    printf("Max allocated size: %d structures\n", max_size);
    printf("Allocations this second: %ld\n", time(NULL) == last_allocation_time ? current_size : 0);
    pthread_mutex_unlock(&allocation_lock);
}
