#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    unsigned long timestamp;
    char source_ip[16];
    char destination_ip[16];
    char protocol_type[10];
} PacketMetadata;

PacketMetadata* packet_buffer = NULL;
size_t buffer_size = 0;
size_t current_index = 0;

void resize_packet_buffer(size_t new_size) {
    if (new_size <= buffer_size) return;

    PacketMetadata* new_buffer = realloc(packet_buffer, new_size * sizeof(PacketMetadata));
    if (new_buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    packet_buffer = new_buffer;
    buffer_size = new_size;
}

void process_packet(unsigned long timestamp, const char* source_ip, const char* destination_ip, const char* protocol_type) {
    if (current_index >= buffer_size) {
        size_t new_size = (buffer_size == 0) ? INITIAL_BUFFER_SIZE : buffer_size * 2;
        resize_packet_buffer(new_size);
    }

    packet_buffer[current_index].timestamp = timestamp;
    strncpy(packet_buffer[current_index].source_ip, source_ip, sizeof(packet_buffer[current_index].source_ip));
    strncpy(packet_buffer[current_index].destination_ip, destination_ip, sizeof(packet_buffer[current_index].destination_ip));
    strncpy(packet_buffer[current_index].protocol_type, protocol_type, sizeof(packet_buffer[current_index].protocol_type));

    current_index++;
}

void initialize_packet_processor() {
    packet_buffer = NULL;
    buffer_size = 0;
    current_index = 0;
}

void finalize_packet_processor() {
    if (packet_buffer != NULL) {
        free(packet_buffer);
        packet_buffer = NULL;
    }
}
