#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int resolution;
    size_t file_size;
    int processing_status;
} ImageProcessing;

typedef struct {
    ImageProcessing *list;
    size_t allocated_count;
    size_t used_count;
    pthread_mutex_t mutex;
} ImageList;

ImageList *create_image_list(size_t initial_capacity) {
    ImageList *list = (ImageList *)malloc(sizeof(ImageList));
    list->list = (ImageProcessing *)calloc(initial_capacity, sizeof(ImageProcessing));
    list->allocated_count = initial_capacity;
    list->used_count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int add_image(ImageList *list, ImageProcessing img) {
    pthread_mutex_lock(&list->mutex);
    if (list->used_count >= list->allocated_count) {
        size_t new_capacity = list->allocated_count * 2;
        list->list = realloc(list->list, new_capacity * sizeof(ImageProcessing));
        if (!list->list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->allocated_count = new_capacity;
    }
    list->list[list->used_count++] = img;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_image_list(ImageList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
