#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1500
#define MAX_PAYLOAD_LENGTH 1468
#define MAX_PACKETS 1000

typedef struct {
    uint32_t packet_id;
    uint64_t timestamp;
    uint32_t source_ip;
    uint32_t destination_ip;
    uint8_t *payload;
} Packet;

typedef struct {
    Packet *packets;
    size_t allocated_packets;
    size_t used_packets;
    size_t max_size;
    pthread_mutex_t lock;
} PacketBuffer;

void init_packet_buffer(PacketBuffer *buffer, size_t max_size) {
    buffer->packets = (Packet *)malloc(max_size * sizeof(Packet));
    if (!buffer->packets) {
        fprintf(stderr, "Failed to allocate memory for packet buffer\n");
        exit(EXIT_FAILURE);
    }
    buffer->allocated_packets = max_size;
    buffer->used_packets = 0;
    buffer->max_size = max_size;
    pthread_mutex_init(&buffer->lock, NULL);
}

void free_packet_buffer(PacketBuffer *buffer) {
    for (size_t i = 0; i < buffer->used_packets; ++i) {
        free(buffer->packets[i].payload);
    }
    free(buffer->packets);
    pthread_mutex_destroy(&buffer->lock);
}

int add_packet_to_buffer(PacketBuffer *buffer, Packet *packet, size_t payload_length) {
    if (pthread_mutex_lock(&buffer->lock) != 0) {
        fprintf(stderr, "Failed to lock packet buffer\n");
        return -1;
    }

    if (buffer->used_packets >= buffer->allocated_packets) {
        size_t new_size = buffer->allocated_packets * 2;
        Packet *new_packets = (Packet *)realloc(buffer->packets, new_size * sizeof(Packet));
        if (!new_packets) {
            fprintf(stderr, "Failed to reallocate memory for packet buffer\n");
            pthread_mutex_unlock(&buffer->lock);
            return -1;
        }
        buffer->packets = new_packets;
        buffer->allocated_packets = new_size;
    }

    if (payload_length > MAX_PAYLOAD_LENGTH) {
        fprintf(stderr, "Payload length exceeds maximum allowed\n");
        pthread_mutex_unlock(&buffer->lock);
        return -1;
    }

    packet->payload = (uint8_t *)malloc(payload_length);
    if (!packet->payload) {
        fprintf(stderr, "Failed to allocate memory for packet payload\n");
        pthread_mutex_unlock(&buffer->lock);
        return -1;
    }
    memcpy(packet->payload, packet->payload, payload_length);

    buffer->packets[buffer->used_packets++] = *packet;

    if (pthread_mutex_unlock(&buffer->lock) != 0) {
        fprintf(stderr, "Failed to unlock packet buffer\n");
        return -1;
    }

    return 0;
}

// Example usage
int main() {
    PacketBuffer buffer;
    init_packet_buffer(&buffer, MAX_PACKETS);

    Packet new_packet = { .packet_id = 1, .timestamp = time(NULL), .source_ip = 0x7F000001, .destination_ip = 0x7F000002 };
    uint8_t payload[MAX_PAYLOAD_LENGTH] = "Hello, world!";
    new_packet.payload = payload;
    size_t payload_length = strlen((char *)payload) + 1;

    if (add_packet_to_buffer(&buffer, &new_packet, payload_length) == -1) {
        fprintf(stderr, "Failed to add packet to buffer\n");
    }

    free_packet_buffer(&buffer);
    return 0;
}
