#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFORMATION;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION;

typedef struct {
    UE_INFORMATION ue_info;
    CRC_INDICATION crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int N) {
    if (N > MAX_STRUCTS || N < 1) {
        printf("Error: Invalid number of structures. Must be between 1 and %d.\n", MAX_STRUCTS);
        return NULL;
    }

    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_size / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Error: Integer overflow detected in size calculation.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_size);
    if (!pdus) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    UE_INFORMATION ue_info;
    CRC_INDICATION crc_indication;

    for (int i = 0; i < N; ++i) {
        // Simulate fetching values from external network library
        ue_info.RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Valid range
        ue_info.RNTI = rand() % 4096 + 1; // Valid range

        crc_indication.CRCFLAG = rand() % 2; // Randomly set

        pdus[i].ue_info = ue_info;
        pdus[i].crc_indication = crc_indication;

