#include <string.h>

#define MAX_IP_LEN 16

typedef struct {
    int protocol_version;
    char source_ip[MAX_IP_LEN];
    char destination_ip[MAX_IP_LEN];
    size_t packet_length;
} PacketHeader;

PacketHeader* process_packet_headers(int num_packets, ...) {
    if (num_packets <= 0) {
        return NULL; // Invalid number of packets
    }

    va_list args;
    va_start(args, num_packets);

    // Calculate total memory required for packet headers
    size_t total_size = sizeof(PacketHeader) * num_packets;
    if (total_size / num_packets != sizeof(PacketHeader)) {
        va_end(args);
        return NULL; // Integer overflow detected
    }

    PacketHeader* headers = (PacketHeader*)malloc(total_size);
    if (!headers) {
        va_end(args);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_packets; i++) {
        PacketHeader* header = &headers[i];
        header->protocol_version = va_arg(args, int);
        strncpy(header->source_ip, va_arg(args, const char*), MAX_IP_LEN - 1);
        strncpy(header->destination_ip, va_arg(args, const char*), MAX_IP_LEN - 1);
        header->packet_length = va_arg(args, size_t);
    }

    va_end(args);
    return headers;
}

int main() {
    // Example usage
    PacketHeader* headers = process_packet_headers(3, 
        4, "192.168.1.1", "10.0.0.1", 1500,
        6, "172.16.0.1", "192.168.1.1", 2048,
        17, "10.0.0.1", "172.16.0.1", 512
    );

    if (headers) {
        for (int i = 0; i < 3; i++) {
            printf("Packet %d: Protocol Version=%d, Source IP=%s, Destination IP=%s, Packet Length=%zu\n",
                   i + 1, headers[i].protocol_version,
                   headers[i].source_ip, headers[i].destination_ip, headers[i].packet_length);
        }
        free(headers);
    }

    return 0;
}
