    for (int i = 0; i < requestedCount; i++) {
        array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array[i] == NULL) {
            *errorCount = -4 + i;
            // Free previously allocated elements
            for (int j = 0; j < totalAllocated; j++) {
                free(array[j]);
            }
            free(array);
            return NULL; // Memory allocation failed for individual element
        }
        array[i]->data = i * 10; // Example initialization
