#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <pthread.h>

#define MAX_ALLOCATIONS 10000
#define MIN_RESIZE_THRESHOLD 5

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_Array;

NFAPI_CRC_Array* create_nfaapi_crc_array(size_t initial_capacity, size_t max_capacity) {
    if (initial_capacity == 0 || initial_capacity > max_capacity) {
        return NULL; // Invalid capacity
    }

    NFAPI_CRC_Array *array = malloc(sizeof(NFAPI_CRC_Array));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    array->array = realloc(NULL, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL; // Memory allocation failed
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_nfaapi_crc_array(NFAPI_CRC_Array *array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_nfaapi_crc_element(NFAPI_CRC_Array *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : MIN_RESIZE_THRESHOLD;
        if (new_capacity > MAX_ALLOCATIONS) {
            new_capacity = MAX_ALLOCATIONS;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }

        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);

    return 0; // Success
}
