#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 10 // 10 MB

typedef struct {
    uint32_t source_ip;
    uint32_t destination_ip;
    uint8_t protocol_type;
    size_t payload_size;
} PacketHeader;

// Function to validate IP address
bool is_valid_ip(uint32_t ip) {
    return (ip >= 0 && ip <= UINT32_MAX);
}

// Function to validate protocol type
bool is_valid_protocol(uint8_t protocol) {
    // Example: Allow only TCP and UDP
    return (protocol == IPPROTO_TCP || protocol == IPPROTO_UDP);
}

// Function to process network packets into packet headers
PacketHeader* process_packets(const uint8_t *packet_data, size_t total_size, size_t *num_headers, bool *memory_error) {
    static PacketHeader headers[1024]; // Fixed array for simplicity; should be dynamically allocated in a real scenario
    size_t header_index = 0;
    size_t current_position = 0;

    while (current_position < total_size && header_index < sizeof(headers) / sizeof(headers[0])) {
        if (current_position + sizeof(PacketHeader) > total_size) {
            *memory_error = true;
            break;
        }

        PacketHeader header;
        memcpy(&header, packet_data + current_position, sizeof(PacketHeader));
        current_position += sizeof(PacketHeader);

        // Validate IP addresses and protocol type
        if (!is_valid_ip(header.source_ip) || !is_valid_ip(header.destination_ip) || !is_valid_protocol(header.protocol_type)) {
            continue; // Skip invalid packets
        }

        // Check for payload size limits
        if (header.payload_size > 1024 * 1024) { // 1MB limit
            continue; // Skip large payloads
        }

        headers[header_index++] = header;
    }

    *num_headers = header_index;
    return headers;
}

int main() {
    uint8_t packet_data[] = {/* Example packet data */};
    size_t total_size = sizeof(packet_data);
    size_t num_headers;
    bool memory_error;

    PacketHeader* headers = process_packets(packet_data, total_size, &num_headers, &memory_error);

    if (memory_error) {
        printf("Memory allocation error occurred.\n");
    } else {
        for (size_t i = 0; i < num_headers; ++i) {
            printf("Packet %zu: Source IP - %u, Destination IP - %u, Protocol Type - %hhu, Payload Size - %zu\n",
                   i, headers[i].source_ip, headers[i].destination_ip, headers[i].protocol_type, headers[i].payload_size);
        }
    }

    return 0;
}
