#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_PACKET_SIZE 1024
#define MEMORY_BUDGET 10 * 1024 * 1024 // 10 MB

typedef struct Packet {
    int size;
    char data[MAX_PACKET_SIZE];
} Packet;

typedef struct MemoryPool {
    Packet* pool;
    int poolSize;
    int available;
} MemoryPool;

MemoryPool memoryPool;

void initMemoryPool(int poolSize) {
    memoryPool.pool = (Packet*)malloc(poolSize * sizeof(Packet));
    if (!memoryPool.pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    memoryPool.poolSize = poolSize;
    memoryPool.available = poolSize;
}

void* allocateFromMemoryPool(int size) {
    if (memoryPool.available == 0 || size > MAX_PACKET_SIZE) {
        fprintf(stderr, "Insufficient memory in the pool\n");
        return NULL;
    }

    for (int i = 0; i < memoryPool.poolSize; ++i) {
        if (!memoryPool.pool[i].size) {
            memoryPool.pool[i].size = size;
            memoryPool.available--;
            return &memoryPool.pool[i];
        }
    }

    fprintf(stderr, "Failed to find a free slot in the pool\n");
    return NULL;
}

void freeToMemoryPool(void* packetPtr) {
    Packet* packet = (Packet*)packetPtr;
    if (!packet->size) {
        fprintf(stderr, "Attempting to free an already freed memory block\n");
        return;
    }

    for (int i = 0; i < memoryPool.poolSize; ++i) {
        if (&memoryPool.pool[i] == packet) {
            memoryPool.pool[i].size = 0;
            memoryPool.available++;
            break;
        }
    }
}

void processPacket(const char* data, int size) {
    if (size > MAX_PACKET_SIZE || size * 100.0 / MEMORY_BUDGET > 5) {
        fprintf(stderr, "Packet exceeds maximum allowed size or budget\n");
        return;
    }

    void* packet = allocateFromMemoryPool(size);
    if (!packet) {
        fprintf(stderr, "Failed to allocate memory for packet\n");
        return;
    }

    memcpy(packet, data, size);
    // Process the packet
    printf("Packet processed: size %d\n", size);

    freeToMemoryPool(packet);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_packets>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int numberOfPackets = atoi(argv[1]);
    initMemoryPool(numberOfPackets);

    // Simulate receiving packets
    for (int i = 0; i < numberOfPackets; ++i) {
        char data[MAX_PACKET_SIZE];
        int size = rand() % MAX_PACKET_SIZE;
        randombytes_buf(data, size);
        processPacket(data, size);
    }

    free(memoryPool.pool);
    return EXIT_SUCCESS;
}
