    if (N <= 0) {
        fprintf(stderr, "Invalid number of packets: %d\n", N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *packet_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!packet_list) {
        fprintf(stderr, "Failed to allocate memory for packet list\n");
        return NULL;
    }

