    if (!metadata_list) {
        free(packet_list);
        fprintf(stderr, "Failed to allocate memory for metadata list\n");
        return NULL;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    for (int i = 0; i < N; i++) {
        if (payload_lengths[i] <= 0) {
            fprintf(stderr, "Invalid payload length: %d\n", payload_lengths[i]);
            continue;
        }

        PacketMetadata *metadata = malloc(sizeof(PacketMetadata));
        if (!metadata) {
            fprintf(stderr, "Failed to allocate memory for packet metadata\n");
            return NULL;
        }

        metadata->packet_id = i + 1;
        metadata->timestamp = timestamps[i];
        metadata->payload_length = payload_lengths[i];
        metadata->payload = malloc(payload_lengths[i]);
        if (!metadata->payload) {
            free(metadata);
            fprintf(stderr, "Failed to allocate memory for packet payload\n");
            return NULL;
        }

        // Simulate random CRCFLAG
        metadata->crc_indication.crcflag = rand() % 2;

        packet_list[i].ue_info_tag = i + 1; // Example tag value
        packet_list[i].rnti = i + 1;        // Example RNTI value
        packet_list[i].crc_indication = metadata->crc_indication;

        metadata_list[i] = metadata;
    }

    clock_gettime(CLOCK_REALTIME, &end);

    double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    printf("Time taken to populate list: %.6f seconds\n", elapsed_time);

    // Free allocated memory for metadata and payload
    for (int i = 0; i < N; i++) {
        if (metadata_list[i]) {
            free(metadata_list[i]->payload);
            free(metadata_list[i]);
        }
    }

    free(metadata_list);

    return packet_list;
}
