int initialize_loader(ImageLoader *loader, char **directory_paths, int num_paths, size_t memory_threshold) {
    loader->images = NULL;
    loader->total_images = 0;
    loader->loaded_images = 0;
    loader->memory_threshold = memory_threshold;

    // Count total images and estimate memory requirement
    for (int i = 0; i < num_paths; i++) {
        DIR *dir;
        struct dirent *ent;
        if ((dir = opendir(directory_paths[i])) != NULL) {
            while ((ent = readdir(dir)) != NULL) {
                char file_path[MAX_PATH_LENGTH];
                snprintf(file_path, sizeof(file_path), "%s/%s", directory_paths[i], ent->d_name);
                // Simulate file size estimation
                int file_size = 1024 * rand() % 100; // Random size for demonstration
                loader->total_images++;
            }
        } else {
            perror("opendir");
            return -1;
        }
    }

    // Allocate memory for image information array
    loader->images = (ImageInfo **)malloc(loader->total_images * sizeof(ImageInfo *));
    if (!loader->images) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Simulate loading images using thread pool
    pthread_t threads[THREAD_POOL_SIZE];
    for (size_t i = 0; i < loader->total_images; i++) {
        ImageInfo *info = malloc(sizeof(ImageInfo));
        info->path = strdup("dummy_path");
        info->file_size = rand() % 100;
        loader->images[i] = info;

        if (i < THREAD_POOL_SIZE) {
            pthread_create(&threads[i], NULL, load_image, NULL);
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < THREAD_POOL_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void cleanup_loader(ImageLoader *loader) {
    if (loader->images) {
        for (size_t i = 0; i < loader->total_images; i++) {
            free(loader->images[i]->path);
            free(loader->images[i]);
        }
        free(loader->images);
    }
    // Additional cleanup can be added here
}

int main() {
    char *directories[] = {"dir1", "dir2"};
    int num_directories = 2;
    size_t memory_threshold = 1024 * 1024 * 10; // 10 MB

    ImageLoader loader;
    if (initialize_loader(&loader, directories, num_directories, memory_threshold) == 0) {
        printf("Loaded %zu images\n", loader.loaded_images);
        cleanup_loader(&loader);
    } else {
        fprintf(stderr, "Failed to load images\n");
    }

    return 0;
}
