#define MAX_COMPRESSION_LEVEL 9

typedef struct {
    int width;
    int height;
    int compression_level;
} Image;

typedef struct {
    Image *images;
    size_t num_images;
    size_t max_memory_kb;
    pthread_mutex_t lock;
} ImageCache;

int load_image(const char *path, Image *image) {
    // Simulate image loading and populate image structure
    image->width = rand() % MAX_IMAGE_DIM + 1;
    image->height = rand() % MAX_IMAGE_DIM + 1;
    image->compression_level = rand() % (MAX_COMPRESSION_LEVEL + 1);
    return 0; // Success
}

int check_memory(const ImageCache *cache, size_t new_size_kb) {
    pthread_mutex_lock(&cache->lock);
    size_t total_memory_kb = cache->num_images * new_size_kb;
    if (total_memory_kb > cache->max_memory_kb) {
        pthread_mutex_unlock(&cache->lock);
        return -1; // Memory limit exceeded
    }
    pthread_mutex_unlock(&cache->lock);
    return 0; // Memory available
}

int load_images(const char **paths, size_t num_paths, ImageCache *cache) {
    for (size_t i = 0; i < num_paths; ++i) {
        Image image;
        if (load_image(paths[i], &image) != 0) {
            return -1; // Error loading image
        }
        int new_size_kb = image.width * image.height / 1024; // Approximate memory usage per image
        if (check_memory(cache, new_size_kb) == -1) {
            // Handle memory limit exceeded
            printf("Memory limit reached. Some images may not be loaded.\n");
            break;
        }
        pthread_mutex_lock(&cache->lock);
        cache->images = realloc(cache->images, (cache->num_images + 1) * sizeof(Image));
        if (!cache->images) {
            pthread_mutex_unlock(&cache->lock);
            return -1; // Memory allocation failed
        }
        cache->images[cache->num_images++] = image;
        pthread_mutex_unlock(&cache->lock);
    }
    return 0; // Success
}

int main() {
    const char *image_paths[] = {"path/to/image1.jpg", "path/to/image2.png"};
    size_t num_paths = sizeof(image_paths) / sizeof(image_paths[0]);
    ImageCache cache = {NULL, 0, 512 * 1024, PTHREAD_MUTEX_INITIALIZER}; // 512MB max memory limit

    if (load_images(image_paths, num_paths, &cache) != 0) {
        printf("Failed to load images.\n");
    }

    for (size_t i = 0; i < cache.num_images; ++i) {
        printf("Image %zu: Width=%d, Height=%d, Compression Level=%d\n", i, 
               cache.images[i].width, cache.images[i].height, cache.images[i].compression_level);
    }

    // Free allocated memory
    free(cache.images);

    return 0;
}
