function renderFooterScripts(scriptArray) {
    if (!Array.isArray(scriptArray)) {
        console.error('Invalid input: Expected an array of script objects');
        return '';
    }

    let html = '';

    scriptArray.forEach(script => {
        const { key, code, async = false } = script;

        if (typeof key !== 'string' || !key) {
            console.error(`Invalid script object at index ${scriptArray.indexOf(script)}: Key must be a non-empty string`);
            return;
        }

        if (typeof code !== 'string' || !code) {
            console.error(`Invalid script object at index ${scriptArray.indexOf(script)}: Code must be a non-empty string`);
            return;
        }

        const asyncAttr = async ? 'async' : '';
        html += `<script key="${key}" ${asyncAttr}>${code}</script>`;
    });

    return html;
}
