typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N) {
    if (N <= 0) return NULL;

    // Seed the random number generator
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            // Handle memory allocation failure
            if (current != NULL) {
                current->next = NULL;
                while (head != NULL) {
                    NFAPI_CRC_INDICATION_PDU_T *temp = head;
                    head = head->next;
                    free(temp);
                }
            }
            return NULL; // Return NULL to indicate failure
        }

        new_node->RX_UE_INFORMATION_TAG = i + 1; // Example tag value
        new_node->RNTI = rand() % 1024; // Random RNTI between 0 and 1023
        new_node->CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}
