#define MAX_WIDTH 1920
#define MAX_HEIGHT 1080
#define MAX_DEPTH 4
#define GLOBAL_MEMORY_BUDGET (10 * 1024 * 1024) // 10 MB

typedef struct {
    int width;
    int height;
    int depth;
} ImageHeader;

int validate_image_header(const ImageHeader* header) {
    return (header->width > 0 && header->height > 0 && header->depth > 0 &&
            header->width <= MAX_WIDTH && header->height <= MAX_HEIGHT && header->depth <= MAX_DEPTH);
}

void process_images(ImageHeader* headers, int count, void** image_data_pointers) {
    static size_t total_allocated_memory = 0;

    for (int i = 0; i < count; ++i) {
        if (!validate_image_header(&headers[i])) {
            printf("Invalid image header at index %d\n", i);
            continue;
        }

        size_t required_memory = headers[i].width * headers[i].height * headers[i].depth * sizeof(unsigned char);
        if (total_allocated_memory + required_memory > GLOBAL_MEMORY_BUDGET) {
            printf("Memory budget exceeded\n");
            return;
        }

        image_data_pointers[i] = malloc(required_memory);
        if (!image_data_pointers[i]) {
            printf("Failed to allocate memory for image at index %d\n", i);
            continue;
        }

        total_allocated_memory += required_memory;
    }
}

void free_image_data(void** image_data_pointers, int count) {
    for (int i = 0; i < count; ++i) {
        if (image_data_pointers[i]) {
            free(image_data_pointers[i]);
            image_data_pointers[i] = NULL;
        }
    }
}

int main() {
    ImageHeader headers[] = {{800, 600, 3}, {1280, 720, 4}, {1920, 1080, 3}};
    int count = sizeof(headers) / sizeof(headers[0]);
    void* image_data_pointers[count];

    process_images(headers, count, image_data_pointers);

    // Use image_data_pointers for further processing

    free_image_data(image_data_pointers, count);
    return 0;
}
