#define MAX_NF_API_CRC_INDICATION_PDUS 1000

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    int crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_pool[MAX_NF_API_CRC_INDICATION_PDUS];
sem_t pool_semaphore;

void init_nfaip_crc_indication_pdu_pool(int max_pdus) {
    sem_init(&pool_semaphore, 0, max_pdus);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_indication_pdu(RX_UE_INFORMATION_TAG rxUeInfoTag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    sem_wait(&pool_semaphore);

    for (int i = 0; i < MAX_NF_API_CRC_INDICATION_PDUS; ++i) {
        if (!nfapi_crc_indication_pdu_pool[i]) {
            pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pdu) {
                nfapi_crc_indication_pdu_pool[i] = pdu;
                break;
            }
        }
    }

    if (!pdu) {
        sem_post(&pool_semaphore);
        return NULL; // Memory allocation failed
    }

    pdu->rxUeInfoTag = rxUeInfoTag;
    pdu->rnti = rnti;
    pdu->crcIndicationRel8Tag = generate_random_crc_indication_rel8_tag(); // Replace with actual function to generate random CRC tag
    pdu->crcFlag = rand() % 2; // Randomly set CRC flag

    return pdu;
}

void deallocate_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    for (int i = 0; i < MAX_NF_API_CRC_INDICATION_PDUS; ++i) {
        if (nfapi_crc_indication_pdu_pool[i] == pdu) {
            free(pdu);
            nfapi_crc_indication_pdu_pool[i] = NULL;
            break;
        }
    }

    sem_post(&pool_semaphore);
}

void update_max_pdus(int new_max_pdus) {
    int current_used_pdus = 0;

    for (int i = 0; i < MAX_NF_API_CRC_INDICATION_PDUS; ++i) {
        if (nfapi_crc_indication_pdu_pool[i]) {
            current_used_pdus++;
        }
    }

    sem_t new_semaphore;
    sem_init(&new_semaphore, 0, new_max_pdus - current_used_pdus);

    // Replace the old semaphore with the new one
    sem_destroy(&pool_semaphore);
    pool_semaphore = new_semaphore;
}
