    pool_size = (SYSTEM_MEMORY * 0.8) / sizeof(Packet);
    packet_pool = (Packet*)malloc(pool_size * sizeof(Packet));
    if (packet_pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for packet pool\n");
        exit(EXIT_FAILURE);
    }
}

void* process_packet(const char* payload, size_t length) {
    if (length > MAX_PAYLOAD_SIZE || used_packets >= pool_size) {
        return NULL;
    }

    Packet* packet = &packet_pool[used_packets++];
    srand(time(NULL));
    packet->RX_UE_INFORMATION_TAG = rand();
    packet->RNTI = (unsigned short)rand();
    packet->CRC_INDICATION_REL8_TAG = (unsigned char)rand();

    // Simulate processing the payload
    memcpy(packet, payload, length);

    return packet;
}

void destroy_packet_pool() {
    free(packet_pool);
