typedef struct {
    pthread_mutex_t mutex;
    void* buffer;
    size_t allocated_size;
    size_t used_size;
    size_t max_allowed_size;
} PacketBufferManager;

void initialize_buffer_manager(PacketBufferManager* manager, size_t max_size) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->buffer = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->allocated_size = max_size;
    manager->used_size = 0;
    manager->max_allowed_size = max_size;
}

void* allocate_packet_space(PacketBufferManager* manager, size_t packet_size) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->used_size + packet_size > manager->allocated_size) {
        // Handle memory reallocation logic here
        // For simplicity, we'll exit on failure for this example
        fprintf(stderr, "Not enough space in buffer\n");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }
    void* address = (char*)manager->buffer + manager->used_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    manager->used_size += packet_size;
    pthread_mutex_unlock(&manager->mutex);
    return address;
}

void free_packet_buffer_manager(PacketBufferManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->buffer);
    manager->buffer = NULL;
    manager->allocated_size = 0;
    manager->used_size = 0;
    manager->max_allowed_size = 0;
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

