#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit of 1MB

typedef struct {
    uint32_t payload_length;
    // Add other header fields here
} PacketHeader;

typedef struct {
    PacketHeader header;
    char payload[];
} Packet;

int calculate_total_memory_size(PacketHeader* headers, int count) {
    if (headers == NULL || count <= 0) return -1; // Input validation

    size_t total_size = 0;
    for (int i = 0; i < count; i++) {
        if (headers[i].payload_length > UINT32_MAX) return -2; // Payload length too large
        size_t packet_size = sizeof(PacketHeader) + headers[i].payload_length;
        if (total_size > SIZE_MAX - packet_size) return -3; // Integer overflow check
        total_size += packet_size;
    }

    if (total_size > MAX_MEMORY_LIMIT) return -4; // Memory limit exceeded

    return (int)total_size;
}

int main() {
    PacketHeader headers[] = {{1024}, {2048}};
    int count = sizeof(headers) / sizeof(headers[0]);
    int result = calculate_total_memory_size(headers, count);

    if (result < 0) {
        printf("Error: %d\n", result);
    } else {
        printf("Total memory size: %d bytes\n", result);
    }

    return 0;
}
