#define MAX_IMAGE_SIZE 1024 * 1024  // Maximum size per image in bytes
#define INITIAL_TASK_POOL_SIZE 16    // Initial number of tasks in the pool

typedef struct ImageTask {
    int width;
    int height;
    char file_path[256];
    int status;  // 0 for pending, 1 for completed
} ImageTask;

ImageTask* task_pool = NULL;
int task_count = 0;
int max_task_count = INITIAL_TASK_POOL_SIZE;

void initialize_task_pool() {
    task_pool = (ImageTask*)malloc(max_task_count * sizeof(ImageTask));
    if (!task_pool) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void add_image_task(int width, int height, const char* file_path) {
    if (task_count >= max_task_count) {
        // Double the size of the task pool
        ImageTask* new_pool = (ImageTask*)realloc(task_pool, max_task_count * 2 * sizeof(ImageTask));
        if (!new_pool) {
            fprintf(stderr, "Memory reallocation failed.\n");
            exit(EXIT_FAILURE);
        }
        task_pool = new_pool;
        max_task_count *= 2;
    }

    ImageTask* new_task = &task_pool[task_count++];
    new_task->width = width;
    new_task->height = height;
    strncpy(new_task->file_path, file_path, sizeof(new_task->file_path) - 1);
    new_task->status = 0;  // Set status to pending
}

void process_image_tasks() {
    for (int i = 0; i < task_count; ++i) {
        ImageTask* task = &task_pool[i];
        if (task->status == 0) {
            // Simulate image processing
            printf("Processing image %s with dimensions %d x %d\n", task->file_path, task->width, task->height);
            task->status = 1;  // Mark as completed
        }
    }
}

void free_task_pool() {
    free(task_pool);
}

int main() {
    initialize_task_pool();

    add_image_task(800, 600, "image1.jpg");
    add_image_task(1920, 1080, "image2.jpg");

    process_image_tasks();

    free_task_pool();
    return 0;
}
