NFAPI_CRC_INDICATION_PDU_T* process_crc_indications(const char* input_str, size_t size_limit, int max_structures) {
    if (input_str == NULL || input_str[0] == '\0') {
        return NULL;
    }

    if (strlen(input_str) >= size_limit) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = NULL;
    size_t str_len = strlen(input_str);

    // Allocate memory for the input string plus the slash
    char* modified_str = malloc(str_len + 2);
    if (modified_str == NULL) {
        return NULL;
    }

    strcpy(modified_str, input_str);
    modified_str[str_len] = '/';
    modified_str[str_len + 1] = '\0';

    // Allocate memory for the NFAPI CRC indications
    size_t total_size = max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T) != max_structures) {
        free(modified_str);
        return NULL;
    }

    crc_indications = malloc(total_size);
    if (crc_indications == NULL) {
        free(modified_str);
        return NULL;
    }

    // Initialize the CRC flags randomly
    srand(time(NULL));
    for (int i = 0; i < max_structures; i++) {
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return crc_indications;
}
