    pthread_mutex_lock(&mutex);
    printf("Current number of structures: %d\n", count);
    pthread_mutex_unlock(&mutex);
}

void* cleanup_thread(void* arg) {
    while (1) {
        sleep(60); // Cleanup every 60 seconds
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < count; i++) {
            if (array[i] != NULL && time(NULL) - array[i]->last_used > 3600) { // Remove structures not used in the last hour
                free(array[i]);
                array[i] = NULL;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

void* add_struct_thread(void* arg) {
    int* new_struct_count = (int*)arg;
    while (*new_struct_count > 0) {
        pthread_mutex_lock(&mutex);
        if (count < MAX_STRUCTS) {
            NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_struct != NULL) {
                array[count++] = new_struct;
                *new_struct_count -= 1;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

void export_state() {
    pthread_mutex_lock(&mutex);
    json_object* root = json_object_new_array();
    for (int i = 0; i < count; i++) {
        json_object* obj = json_object_new_object();
        // Add fields to the object
        json_object_array_add(root, obj);
