    if (fp != NULL) {
        char* str = json_object_to_json_string_ext(root, JSON_C_TO_STRING_PRETTY);
        fprintf(fp, "%s\n", str);
        free(str);
        fclose(fp);
    }
    json_object_put(root);
    pthread_mutex_unlock(&mutex);
}

void memory_leak_check() {
    // Implement memory leak detection here
}

