    int max_structs = MAX_STRUCTS;
    if (argc > 1) {
        max_structs = atoi(argv[1]);
    }
    pthread_t cleanup_tid, add_struct_tid;
    int new_struct_count = 0;

    signal(SIGUSR1, log_state);
    pthread_create(&cleanup_tid, NULL, cleanup_thread, NULL);

    while (1) {
        // Simulate adding new structures
        sleep(5); // Add a new structure every 5 seconds
        new_struct_count += 1;
        if (new_struct_count > max_structs) {
            new_struct_count = max_structs;
        }
        pthread_create(&add_struct_tid, NULL, add_struct_thread, &new_struct_count);
        pthread_join(add_struct_tid, NULL);

        if (new_struct_count == 0) {
            export_state();
        }
    }

    memory_leak_check();
    return 0;
}
