int process_image_files(const char* directory, IMAGE_DATA_T** image_array, int* total_images) {
    DIR *dir;
    struct dirent *entry;
    int count = 0;
    long long total_memory_used = 0;

    dir = opendir(directory);
    if (dir == NULL) {
        perror("Error opening directory");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL && count < MAX_IMAGE_FILES) {
        char file_path[256];
        snprintf(file_path, sizeof(file_path), "%s/%s", directory, entry->d_name);

        // Simulate image metadata extraction
        IMAGE_DATA_T image;
        if (extract_image_metadata(file_path, &image) != 0) {
            printf("Failed to extract metadata for %s\n", file_path);
            continue;
        }

        if (image.width > MAX_DIMENSION_PIXELS || image.height > MAX_DIMENSION_PIXELS) {
            printf("Dimension out of limit for %s\n", file_path);
            continue;
        }

        long long memory_required = sizeof(IMAGE_DATA_T) + strlen(file_path) * sizeof(char);
        if ((total_memory_used + memory_required) > MEMORY_LIMIT_BYTES) {
            printf("Memory limit reached, stopping processing.\n");
            break;
        }

        image_array[count] = (IMAGE_DATA_T*)malloc(memory_required);
        if (image_array[count] == NULL) {
            perror("Failed to allocate memory for image data");
            closedir(dir);
            return -1;
        }

        memcpy(image_array[count], &image, sizeof(IMAGE_DATA_T));
        strcpy(image_array[count]->file_path, file_path);
        count++;
        total_memory_used += memory_required;
    }

    closedir(dir);
    *total_images = count;
    return 0;
}

