int main() {
    FILE *file = fopen("log_file.log", "r");
    if (!file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    pthread_t threads[NUM_THREADS];
    int thread_index = 0;

    while (/* File has remaining data */) {
        // Read chunk from file
        char *chunk = malloc(CHUNK_SIZE);
        if (!chunk) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            return EXIT_FAILURE;
        }

        size_t bytes_read = fread(chunk, 1, CHUNK_SIZE, file);
        if (bytes_read < 0) {
            perror("Failed to read log file chunk");
            free(chunk);
            fclose(file);
            return EXIT_FAILURE;
        } else if (bytes_read == 0) {
            // End of file reached
            break;
        }

        // Process chunk in a separate thread
        if (pthread_create(&threads[thread_index], NULL, process_chunk, chunk) != 0) {
            perror("Failed to create thread");
            free(chunk);
            fclose(file);
            return EXIT_FAILURE;
        }

        thread_index = (thread_index + 1) % NUM_THREADS;

        // Check for successful completion of previous threads
        if (thread_index == 0) {
            for (int i = 0; i < NUM_THREADS; i++) {
                pthread_join(threads[i], NULL);
            }
        }

        free(chunk);
    }

    // Wait for remaining threads to complete
    for (int i = 0; i < thread_index; i++) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);

    return EXIT_SUCCESS;
}
