    if (!array) return NULL;

    size_t initial_size = n > 16 ? n : 16; // Start with a minimum of 16 elements
    array->array = realloc(array->array, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);

    array->allocated_size = initial_size;
