    if (!array || new_size <= array->used_size) return;

    pthread_mutex_lock(&array->mutex);

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        array->array = new_array;
        array->allocated_size = new_size;

        for (size_t i = array->used_size; i < array->used_size; ++i) {
            array->array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            array->array[i].RNTI = (unsigned short)(rand() % 65536);
            array->array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        }
    } else {
        log_message("Memory allocation failed during resize, keeping current size: %zu", array->allocated_size);
    }

    pthread_mutex_unlock(&array->mutex);
}

void destroy_nfaapi_crc_array(NFAPI_CRC_ARRAY* array) {
    if (!array) return;

    pthread_mutex_destroy(&array->mutex);

    free(array->array);
    free(array);
}
