#define MAX_MEMORY_THRESHOLD 1048576 // Example threshold in bytes

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    struct MemoryNode *next;
} MemoryNode;

MemoryNode *memoryPool = NULL;
pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;

size_t getCurrentMemoryUsage() {
    // Implement a function to get the current memory usage
}

void logMemoryUsage(size_t requestedSize, size_t allocatedSize) {
    // Implement a function to log memory usage details
}

NFAPI_CRC_INDICATION_PDU_T* allocateNFAPICRCIndicationPDUs(size_t n) {
    pthread_mutex_lock(&memoryMutex);

    if (n > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        logMemoryUsage(n * sizeof(NFAPI_CRC_INDICATION_PDU_T), 0);
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    size_t totalSize = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (getCurrentMemoryUsage() + totalSize > MAX_MEMORY_THRESHOLD) {
        logMemoryUsage(totalSize, 0);
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    MemoryNode *current = memoryPool;
    while (current && current->count < n) {
        current = current->next;
    }

    if (current) {
        NFAPI_CRC_INDICATION_PDU_T *data = current->data + current->count;
        current->count += n;
        pthread_mutex_unlock(&memoryMutex);
        return data;
    }

    MemoryNode *newNode = (MemoryNode *)malloc(sizeof(MemoryNode));
    if (!newNode) {
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    newNode->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(totalSize);
    if (!newNode->data) {
        free(newNode);
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        newNode->data[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        newNode->data[i].RNTI = rand() % 65536;
        newNode->data[i].CRCFLAG = (unsigned char)(rand() % 2);
    }

    newNode->count = n;
    newNode->next = memoryPool;
    memoryPool = newNode;

    pthread_mutex_unlock(&memoryMutex);
    return newNode->data;
}

void deallocateNFAPICRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T *data, size_t n) {
    pthread_mutex_lock(&memoryMutex);

    MemoryNode *current = memoryPool;
    MemoryNode *previous = NULL;

    while (current && current->data != data) {
        previous = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&memoryMutex);
        return;
    }

    if (previous) {
        previous->next = current->next;
    } else {
        memoryPool = current->next;
    }

    free(current->data);
    free(current);

    pthread_mutex_unlock(&memoryMutex);
}
