    char format[32];
    long fileSize;
    time_t modTimestamp;
} ImageMetadata;

NFAPI_CRC_INDICATION_PDU_T* allocateNFAPIPDUList(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1024;
        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return list;
}

ImageMetadata* extractImageMetadata(const char* dirPath, int* metadataCount) {
    DIR *dir;
    struct dirent *ent;
    ImageMetadata* metadataList = NULL;
    int count = 0;

    if ((dir = opendir(dirPath)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", dirPath, ent->d_name);

            struct stat fileStat;
            if (stat(path, &fileStat) == 0 && S_ISREG(fileStat.st_mode)) {
                count++;
            }
        }

        closedir(dir);

        metadataList = (ImageMetadata*)malloc(count * sizeof(ImageMetadata));
        if (!metadataList) return NULL;

        int index = 0;
        if ((dir = opendir(dirPath)) != NULL) {
            while ((ent = readdir(dir)) != NULL) {
                char path[256];
                snprintf(path, sizeof(path), "%s/%s", dirPath, ent->d_name);

                struct stat fileStat;
                if (stat(path, &fileStat) == 0 && S_ISREG(fileStat.st_mode)) {
                    strcpy(metadataList[index].filePath, path);
                    metadataList[index].fileSize = fileStat.st_size;
                    metadataList[index].modTimestamp = fileStat.st_mtime;

                    // Placeholder for extracting resolution and format
                    metadataList[index].resolution[0] = 1920; // Example width
                    metadataList[index].resolution[1] = 1080; // Example height
                    strcpy(metadataList[index].format, "JPEG"); // Example format

                    index++;
                }
            }

            closedir(dir);
        }
    } else {
        perror("opendir");
        return NULL;
    }

    *metadataCount = count;
    return metadataList;
}

int main() {
    const char* dirPath = "/path/to/images";
    int N = 10;

    NFAPI_CRC_INDICATION_PDU_T* pduList = allocateNFAPIPDUList(N);
    if (!pduList) {
        fprintf(stderr, "Failed to allocate NFAPI PDU list\n");
        return EXIT_FAILURE;
    }

    int metadataCount;
    ImageMetadata* metadataList = extractImageMetadata(dirPath, &metadataCount);
    if (!metadataList) {
        fprintf(stderr, "Failed to extract image metadata\n");
        free(pduList);
        return EXIT_FAILURE;
    }

    // Process the data...

    free(metadataList);
    free(pduList);

    return EXIT_SUCCESS;
}
