#define MAX_FILE_SIZE 4GB // Define based on system capabilities
#define CHUNK_SIZE 64KB
#define NUM_THREADS 8 // Default number of threads, can be adjusted

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
