class DynamicMemoryAllocator {
private:
    std::mt19937 generator;
    std::uniform_real_distribution<float> floatDistribution;
    std::uniform_int_distribution<int> intDistribution;

public:
    DynamicMemoryAllocator() : generator(std::random_device{}()), floatDistribution(0.0f, 1.0f), intDistribution(0, 100) {}

    void* allocate(size_t size) {
        // Custom allocation logic with checks
        if (size < MIN_ALLOC_SIZE || size > MAX_ALLOC_SIZE) {
            std::cerr << "Invalid memory allocation request" << std::endl;
            return nullptr;
        }
        return ::operator new(size);
    }

    void deallocate(void* ptr, size_t size) {
        // Custom deallocation logic
        ::operator delete(ptr);
    }

    float generateRandomFloat(float min, float max) {
        return floatDistribution(generator);
    }

    int generateRandomInt(int min, int max) {
        return intDistribution(generator);
    }
};

void generateNFADynamicCRCIndications(DynamicMemoryAllocator& allocator, std::vector<NFAPI_CRC_INDICATION_PDU_T>& crcIndications, int rangeStart, int rangeEnd, int updateInterval) {
    if (rangeStart < 0 || rangeEnd > 100 || updateInterval <= 0) {
        std::cerr << "Invalid input parameters" << std::endl;
        return;
    }

    for (int i = 0; i < crcIndications.size(); ++i) {
        NFAPI_CRC_INDICATION_PDU_T& indication = crcIndications[i];
        indication.RX_UE_INFORMATION_TAG = allocator.generateRandomInt(1, 100);
        indication.RNTI = allocator.generateRandomInt(1, 256);
        indication.CRC_INDICATION_REL8_TAG.CRCFLAG = allocator.generateRandomInt(rangeStart, rangeEnd);
    }

    // Simulate callback mechanism
    for (int i = 0; i < crcIndications.size(); ++i) {
        NFAPI_CRC_INDICATION_PDU_T& indication = crcIndications[i];
        std::cout << "CRC Indication Update: RX_UE_INFORMATION_TAG=" << indication.RX_UE_INFORMATION_TAG
                  << ", RNTI=" << indication.RNTI
                  << ", CRCFLAG=" << indication.CRC_INDICATION_REL8_TAG.CRCFLAG << std::endl;
        // Sleep to simulate update interval
        std::this_thread::sleep_for(std::chrono::milliseconds(updateInterval));
    }
}
