class MetaDataExtractor {
private:
    long minFileSize;
    long maxFileSize;
    std::pair<int, int> minDimensions;
    std::pair<int, int> maxDimensions;

public:
    MetaDataExtractor(long minSize, long maxSize, std::pair<int, int> minDim, std::pair<int, int> maxDim)
        : minFileSize(minSize), maxFileSize(maxSize), minDimensions(minDim), maxDimensions(maxDim) {}

    ImageMetaData extract(const std::string& filePath) {
        ImageMetaData metaData;
        // Simulate metadata extraction logic
        std::ifstream file(filePath);
        if (file.is_open()) {
            // Assume successful extraction and validation here
            metaData.fileSize = 1024; // Dummy value
            metaData.dimensions = {800, 600}; // Dummy value
            metaData.exifData = "Exif data"; // Dummy value
        }
        return metaData;
    }

    bool validate(const ImageMetaData& metadata) {
        return metadata.fileSize >= minFileSize && metadata.fileSize <= maxFileSize &&
               metadata.dimensions.first >= minDimensions.first && metadata.dimensions.first <= maxDimensions.first &&
               metadata.dimensions.second >= minDimensions.second && metadata.dimensions.second <= maxDimensions.second;
    }
};

std::vector<ImageMetaData> processImageMetadata(const std::vector<std::string>& filePaths, MetaDataExtractor& extractor) {
    std::vector<ImageMetaData> metadataList;
    for (const auto& path : filePaths) {
        ImageMetaData metaData = extractor.extract(path);
        if (extractor.validate(metaData)) {
            metadataList.push_back(metaData);
        }
    }
    return metadataList;
}

int main() {
    MetaDataExtractor extractor(1024, 10 * 1024 * 1024, {640, 480}, {4K resolution});
    std::vector<std::string> filePaths = {"path/to/image1.jpg", "path/to/image2.jpg"};
    std::vector<ImageMetaData> metadataList = processImageMetadata(filePaths, extractor);
    // Process metadataList as needed
    return 0;
}
