typedef struct {
    size_t payload_size;
    char* payload;
} NetworkPacket;

NetworkPacket* allocate_packets(size_t num_packets, const void* external_data_source, size_t data_size) {
    if (num_packets == 0 || data_size == 0) {
        return NULL; // Handle edge case: no packets or no data
    }

    NetworkPacket* packets = malloc(num_packets * sizeof(NetworkPacket));
    if (!packets) {
        perror("Failed to allocate memory for packet array");
        return NULL;
    }

    const char* data_ptr = (const char*)external_data_source;

    for (size_t i = 0; i < num_packets && data_ptr + sizeof(size_t) <= data_ptr + data_size; ++i) {
        size_t payload_size = *(const size_t*)data_ptr;
        data_ptr += sizeof(size_t);

        if (payload_size > MAX_PACKET_SIZE || payload_size > data_size - (data_ptr - (const char*)external_data_source)) {
            fprintf(stderr, "Invalid packet size or insufficient data\n");
            for (size_t j = 0; j < i; ++j) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        packets[i].payload_size = payload_size;
        packets[i].payload = malloc(payload_size);
        if (!packets[i].payload) {
            perror("Failed to allocate memory for packet payload");
            for (size_t j = 0; j <= i; ++j) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        memcpy(packets[i].payload, data_ptr, payload_size);
        data_ptr += payload_size;
    }

    if (data_ptr != (const char*)external_data_source + data_size) {
        fprintf(stderr, "Malformed data source: unused bytes at the end\n");
        for (size_t i = 0; i < num_packets; ++i) {
            free(packets[i].payload);
        }
        free(packets);
        return NULL;
    }

    return packets;
}

void free_packets(NetworkPacket* packets, size_t num_packets) {
    if (!packets) {
        return;
    }

    for (size_t i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}
