#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

#define MEMORY_LIMIT 1024 * 1024 * 1024 // 1 GB
#define MAX_TASKS 1000

typedef struct {
    int width;
    int height;
    int parameters;
    int task_id;
    int priority;
} task_t;

typedef struct {
    task_t **tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} task_collection_t;

task_collection_t *create_task_collection() {
    task_collection_t *collection = (task_collection_t *)malloc(sizeof(task_collection_t));
    collection->tasks = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

bool add_task(task_collection_t *collection, task_t *task) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= MAX_TASKS || collection->count >= collection->capacity - 1) {
        size_t new_capacity = (collection->capacity == 0) ? 4 : collection->capacity * 2;
        task_t **new_tasks = realloc(collection->tasks, new_capacity * sizeof(task_t *));
        if (new_tasks == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return false; // Memory allocation failed
        }
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
    }

    if (collection->count < MAX_TASKS && collection->count + 1 <= collection->capacity - 1 &&
        (collection->count == 0 || task->priority >= collection->tasks[collection->count - 1]->priority)) {
        collection->tasks[collection->count++] = task;
        pthread_mutex_unlock(&collection->lock);
        return true;
    }

    pthread_mutex_unlock(&collection->lock);
    return false; // Task not added due to priority
}

void destroy_task_collection(task_collection_t *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->tasks[i]);
    }
    free(collection->tasks);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

