#define MAX_PACKETS 10000
#define MAX_MEMORY 10 * 1024 * 1024 // 10 MB

typedef struct Packet {
    size_t payload_length;
    time_t timestamp;
    char* payload;
    struct Packet* next;
} Packet;

Packet* head = NULL;
size_t current_memory_usage = 0;

int add_packet(size_t payload_length, const char* payload) {
    if (payload_length > MAX_MEMORY || current_memory_usage + payload_length > MAX_MEMORY) {
        return -1; // Memory allocation failed
    }

    Packet* new_packet = malloc(sizeof(Packet));
    if (!new_packet) {
        return -2; // Memory allocation failed
    }

    new_packet->payload_length = payload_length;
    new_packet->timestamp = time(NULL);
    new_packet->payload = malloc(payload_length);
    if (!new_packet->payload) {
        free(new_packet);
        return -3; // Memory allocation failed
    }

    memcpy(new_packet->payload, payload, payload_length);

    current_memory_usage += payload_length;

    new_packet->next = head;
    head = new_packet;

    return 0;
}

void process_packets() {
    Packet* current = head;
    while (current) {
        // Process packet
        printf("Processing packet with length: %zu, timestamp: %ld\n", current->payload_length, current->timestamp);

        // Free resources
        free(current->payload);
        free(current);

        current = head;
        if (current) {
            head = current->next;
        }
    }
}
