#include <stdlib.h>
#include <string.h>
#include <errno.h>

typedef struct PacketHeader {
    uint8_t *header;
    size_t header_size;
} PacketHeader;

typedef struct PacketPayload {
    uint8_t *payload;
    size_t payload_size;
} PacketPayload;

typedef struct PacketMetadata {
    uint32_t tag;
} PacketMetadata;

typedef struct Packet {
    PacketHeader header;
    PacketPayload payload;
    PacketMetadata metadata;
} Packet;

Packet** allocate_packets(size_t max_packet_size, size_t buffer_capacity) {
    if (max_packet_size == 0 || buffer_capacity == 0) {
        errno = EINVAL;
        return NULL;
    }

    size_t total_memory_size = buffer_capacity * (sizeof(PacketHeader) + sizeof(PacketPayload) + sizeof(PacketMetadata));
    Packet** packet_list = malloc(total_memory_size);
    if (!packet_list) {
        return NULL;
    }

    for (size_t i = 0; i < buffer_capacity; ++i) {
        packet_list[i] = (Packet*)(packet_list + buffer_capacity) + i;

        packet_list[i]->header.header = malloc(max_packet_size);
        packet_list[i]->header.header_size = max_packet_size;
        if (!packet_list[i]->header.header) {
            free_packets(packet_list, i);
            return NULL;
        }

        packet_list[i]->payload.payload = malloc(max_packet_size);
        packet_list[i]->payload.payload_size = max_packet_size;
        if (!packet_list[i]->payload.payload) {
            free_packets(packet_list, i);
            return NULL;
        }

        memset(&packet_list[i]->metadata, 0, sizeof(PacketMetadata));
    }

    return packet_list;
}

void free_packets(Packet** packet_list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (packet_list[i]) {
            free(packet_list[i]->header.header);
            free(packet_list[i]->payload.payload);
        }
    }

    free(packet_list);
}

int process_packets(Packet** packet_list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (!packet_list[i]) {
            continue;
        }

        // Simulate processing of each packet
        printf("Processing packet %zu\n", i);
    }

    return 0;
}

int main() {
    size_t max_packet_size = 1500; // Example value
    size_t buffer_capacity = 10;   // Example value

    Packet** packets = allocate_packets(max_packet_size, buffer_capacity);
