        packet_headers[i].length = avg_packet_size / sizeof(PacketHeader) - (rand() % 10); // Varying length

        // Ensure the total memory consumption does not exceed the limit
        if (sizeof(packet_headers) + i * packet_headers[i].length > max_total_memory) {
            fprintf(stderr, "Memory limit exceeded. Packet header %d discarded.\n", i);
