typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* updateUEInfo(void* arg) {
    // Simulate external data source
    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_mutex_lock(&lock);
        if (head == NULL || (Node*)malloc(sizeof(Node)) == NULL) {
            pthread_mutex_unlock(&lock);
            break;
        }
        Node* newNode = (Node*)malloc(sizeof(Node));
        // Populate newNode with data
        head->next = newNode;
        newNode->next = NULL;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void* processCRCIndications(void* arg) {
    // Process CRC indications from the linked list
    Node* current = head;
    while (current != NULL) {
        // Handle CRC indication processing
        current = current->next;
    }
    return NULL;
}

int main() {
    pthread_t updateThread, processThread;

    if (pthread_create(&updateThread, NULL, updateUEInfo, NULL) != 0 ||
        pthread_create(&processThread, NULL, processCRCIndications, NULL)) {
        fprintf(stderr, "Error creating threads\n");
        return 1;
    }

    pthread_join(updateThread, NULL);
    pthread_join(processThread, NULL);

    // Clean up and release resources
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
