    if (packet_count > MAX_PACKETS) {
        printf("Error: Too many packets.\n");
        return -1;
    }

    result->packet_count = 0;
    result->total_header_size = 0;

    for (int i = 0; i < packet_count; i++) {
        if (packets[i].header_count > MAX_HEADERS) {
            printf("Error: Too many headers in packet %d.\n", i);
            return -1;
        }

        int current_packet_size = 0;
        for (int j = 0; j < packets[i].header_count; j++) {
            if (strlen(packets[i].headers[j].data) >= sizeof(result->buffer)) {
                printf("Error: Header data too large.\n");
                return -1;
            }

            strcpy(&result->buffer[result->total_header_size], packets[i].headers[j].data);
            result->total_header_size += strlen(packets[i].headers[j].data) + 1; // +1 for null terminator
            current_packet_size += strlen(packets[i].headers[j].data) + 1;

            if (result->total_header_size > BUFFER_LIMIT - current_packet_size) {
                printf("Error: Buffer overflow.\n");
                return -1;
            }
        }

        result->packet_count++;
    }

    return 0;
}

