#include <stdlib.h>
#include <stdio.h>

#define MAX_PACKET_SIZE 1024
#define THRESHOLD_MEMORY_USAGE 5 * (1024 * 1024) // 5 MB

typedef struct Packet {
    int payload_size;
    char* payload;
} Packet;

Packet** process_packets(int* packet_count, int max_packet_size, int threshold_memory_usage) {
    int count = 0;
    int total_size = 0;
    Packet** packets = (Packet**)malloc(sizeof(Packet*) * (*packet_count));

    for (int i = 0; i < *packet_count; i++) {
        // Simulate packet reception
        int received_payload_size = rand() % max_packet_size;

        if ((total_size + received_payload_size) > threshold_memory_usage) {
            printf("Memory usage limit reached. Processing incomplete.\n");
            break;
        }

        packets[count] = (Packet*)malloc(sizeof(Packet));
        packets[count]->payload_size = received_payload_size;
        packets[count]->payload = (char*)malloc(packets[count]->payload_size);

        // Simulate payload copying
        for (int j = 0; j < received_payload_size; j++) {
            packets[count]->payload[j] = 'A' + (j % 26);
        }

        total_size += packets[count]->payload_size;
        count++;
    }

    *packet_count = count;
    return packets;
}

void free_packets(Packet** packets, int packet_count) {
    for (int i = 0; i < packet_count; i++) {
        if (packets[i]) {
            free(packets[i]->payload);
            free(packets[i]);
        }
    }
    free(packets);
}

int main() {
    int packet_count = 10;
    Packet** packets = process_packets(&packet_count, MAX_PACKET_SIZE, THRESHOLD_MEMORY_USAGE);

    // Simulate packet processing
    for (int i = 0; i < packet_count; i++) {
        printf("Processed packet with payload size: %d\n", packets[i]->payload_size);
    }

    free_packets(packets, packet_count);
    return 0;
}
