#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_STRUCTS 1000
#define MAX_MEMORY 1 * 1024 * 1024 // 1 MB

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t total_size;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->total_size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_struct(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTS || list->total_size + sizeof(Node) > MAX_MEMORY) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    new_node->data = *data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    list->total_size += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_first_struct(List* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* result = (list->head) ? &list->head->data : NULL;
    pthread_mutex_unlock(&list->lock);
    return result;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
