#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STREAMS 1024
#define MEMORY_THRESHOLD 1024 * 1024 * 1024 // 1GB
#define FIXED_OVERHEAD 100

typedef struct {
    int stream_count;
    char** metadata;
} MediaPacket;

int process_udp_packet(MediaPacket* packet, void* system_state) {
    if (packet == NULL || system_state == NULL) {
        return -1; // Invalid input
    }

    int* current_memory_usage = (int*)system_state;
    int max_streams = MAX_STREAMS;
    int memory_threshold = MEMORY_THRESHOLD;

    // Calculate total size needed for metadata
    size_t required_size = packet->stream_count * sizeof(char*);
    for (int i = 0; i < packet->stream_count; ++i) {
        required_size += strlen(packet->metadata[i]) + 1;
    }

    if (packet->stream_count > max_streams) {
        return -2; // Exceeds maximum number of streams
    }

    if (*current_memory_usage + required_size > memory_threshold) {
        return -3; // Memory allocation would exceed threshold
    }

    // Check for integer overflow during calculation
    if ((size_t)(*current_memory_usage) + required_size < *current_memory_usage) {
        return -4; // Integer overflow detected
    }

    // Allocate memory for metadata pointers
    char** new_metadata = (char**)realloc(packet->metadata, packet->stream_count * sizeof(char*));
    if (new_metadata == NULL) {
        return -5; // Memory allocation failed
    }
    packet->metadata = new_metadata;

    // Copy and allocate memory for each stream's metadata
    for (int i = 0; i < packet->stream_count; ++i) {
        size_t metadata_len = strlen(packet->metadata[i]) + 1;
        char* new_meta = (char*)malloc(metadata_len);
        if (new_meta == NULL) {
            // Free previously allocated memory and return failure
            for (int j = 0; j < i; ++j) {
                free(new_metadata[j]);
            }
            free(packet->metadata);
            return -6; // Memory allocation failed for stream metadata
        }
        strcpy(new_meta, packet->metadata[i]);
        new_metadata[i] = new_meta;
    }

    *current_memory_usage += required_size;

    return 0; // Success
}
