#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define MAX_STREAMS_PER_PACKET 10
#define MAX_METADATA_LENGTH 128

typedef struct {
    unsigned long timestamp;
    int resolution[2];
    char codec[MAX_METADATA_LENGTH];
} MediaStreamMetadata;

typedef struct {
    MediaStreamMetadata streams[MAX_STREAMS_PER_PACKET];
    int stream_count;
} PacketData;

void processPacket(unsigned char* packet, int packet_size) {
    if (packet_size > MAX_PACKET_SIZE) {
        printf("Warning: Packet size exceeds maximum threshold.\n");
        return;
    }

    PacketData packet_data;
    memset(&packet_data, 0, sizeof(PacketData));

    // Parse the packet to extract media stream metadata
    int offset = 0;
    while (offset < packet_size) {
        if (offset + sizeof(MediaStreamMetadata) > packet_size) {
            printf("Warning: Packet contains invalid stream metadata.\n");
            break;
        }

        memcpy(&packet_data.streams[packet_data.stream_count], &packet->offset, sizeof(MediaStreamMetadata));
        offset += sizeof(MediaStreamMetadata);
        packet_data.stream_count++;
    }

    // Validate timestamp consistency
    unsigned long first_timestamp = packet_data.streams[0].timestamp;
    for (int i = 1; i < packet_data.stream_count; i++) {
        if (packet_data.streams[i].timestamp != first_timestamp) {
            printf("Warning: Inconsistent timestamps detected in packet.\n");
            break;
        }
    }

    // Allocate memory dynamically based on stream count
    MediaStreamMetadata* dynamic_metadata = malloc(packet_data.stream_count * sizeof(MediaStreamMetadata));
    if (dynamic_metadata == NULL) {
        printf("Error: Memory allocation failed for dynamic metadata.\n");
        return;
    }

    memcpy(dynamic_metadata, packet_data.streams, packet_data.stream_count * sizeof(MediaStreamMetadata));

    // Log processing details
    printf("Packet processed successfully with %d streams. Total memory used: %lu bytes.\n",
           packet_data.stream_count, packet_data.stream_count * sizeof(MediaStreamMetadata));

    free(dynamic_metadata);
}

int main() {
    unsigned char packet[MAX_PACKET_SIZE];
    int packet_size = 512; // Example packet size

    // Simulate receiving a packet
    memset(packet, 0, MAX_PACKET_SIZE);

    processPacket(packet, packet_size);

    return 0;
}
