#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define MAX_STREAMS 1024
#define SYSTEM_MEMORY_THRESHOLD 1024 * 1024 * 512 // 512MB

typedef struct {
    int stream_count;
    void* metadata[MAX_STREAMS];
} Packet;

int validate_config(int new_max_streams, size_t new_memory_threshold) {
    if (new_max_streams > MAX_STREAMS || new_memory_threshold > SYSTEM_MEMORY_THRESHOLD) {
        return -1;
    }
    return 0;
}

void update_config(int *max_streams, size_t *memory_threshold, int new_max_streams, size_t new_memory_threshold) {
    pthread_mutex_lock(&config_mutex);
    if (validate_config(new_max_streams, new_memory_threshold) == 0) {
        *max_streams = new_max_streams;
        *memory_threshold = new_memory_threshold;
    }
    pthread_mutex_unlock(&config_mutex);
}

int process_packet(Packet* packet, int max_streams, size_t memory_threshold, int *total_streams, size_t *used_memory) {
    pthread_mutex_lock(&packet_mutex);

    if (packet->stream_count > max_streams || packet->stream_count < 0) {
        fprintf(stderr, "Invalid stream count: %d\n", packet->stream_count);
        pthread_mutex_unlock(&packet_mutex);
        return -1;
    }

    size_t required_memory = packet->stream_count * sizeof(void*);
    if (required_memory > memory_threshold || required_memory + *used_memory > SYSTEM_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation exceeded.\n");
        pthread_mutex_unlock(&packet_mutex);
        return -1;
    }

    for (int i = 0; i < packet->stream_count; i++) {
        if (packet->metadata[i] == NULL) {
            packet->metadata[i] = malloc(sizeof(void*));
            *used_memory += sizeof(void*);
        }
    }

    *total_streams += packet->stream_count;

    pthread_mutex_unlock(&packet_mutex);
    return 0;
}

void log_event(const char* event, int stream_count) {
    struct timeval now;
    gettimeofday(&now, NULL);
    printf("[%ld.%06ld] %s: Stream count = %d\n", now.tv_sec, now.tv_usec, event, stream_count);
}
```

