NFAPI_CRC_INDICATION_PDU_T* manageNFAPIList(int N, double performanceThreshold) {
    if (N <= 0 || performanceThreshold <= 0) {
        return NULL;
    }

    size_t requiredSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    if (requiredSize / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL; // Integer overflow check
    }

    clock_t startTime = clock();
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(requiredSize);
    if (!list) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    clock_t endTime = clock();

    double elapsedTime = (double)(endTime - startTime) / CLOCKS_PER_SEC;
    if (elapsedTime > performanceThreshold) {
        free(list);
        printf("Performance threshold exceeded during memory allocation.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        list[i].tag = RX_UE_INFORMATION_TAG;
        list[i].RNTI = rand() % 65536; // Example RNTI range
        list[i].CRCFLAG = rand() % 256; // Random CRC flag
    }

    return list;
}
