#define MAX_STRUCTS 1000000

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char* message, const char* file, int line) {
    static FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s: %s:%d\n", message, file, line);
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_structures(int num_structs, const char* config_file, int log_level) {
    FILE* config = fopen(config_file, "r");
    if (config == NULL) {
        perror("Failed to open configuration file");
        return NULL;
    }

    // Read and validate num_structs from the configuration file
    int parsed_num_structs;
    fscanf(config, "%d", &parsed_num_structs);
    if (parsed_num_structs <= 0 || parsed_num_structs > MAX_STRUCTS) {
        log_message("Invalid number of structures in config file", __FILE__, __LINE__);
        fclose(config);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structs = malloc(parsed_num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structs == NULL) {
        perror("Failed to allocate memory for structures");
        fclose(config);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < parsed_num_structs; i++) {
        structs[i].rx_ue_info_tag = rand() % 100000;
        structs[i].rnti = rand() % 1024;
        structs[i].crc_indication_rel8_tag = rand() % 2;
    }

    fclose(config);
    return structs;
}

int main() {
