#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PACKET_ID 65535

typedef struct Packet {
    unsigned short id;
    time_t timestamp;
    size_t payload_length;
    char *payload;
} Packet;

Packet* process_packets(size_t max_limit, size_t packet_count, size_t payload_size) {
    if (packet_count > MAX_PACKET_ID || max_limit < sizeof(Packet)) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    size_t total_payload_size = packet_count * payload_size;
    if ((max_limit - total_payload_size) / sizeof(Packet) < packet_count) {
        fprintf(stderr, "Memory allocation limit exceeded.\n");
        return NULL;
    }

    Packet* packets = (Packet*)malloc(max_limit);
    if (!packets) {
        perror("Failed to allocate memory for packets.");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < packet_count; ++i) {
        packets[i].id = (unsigned short)i;
        packets[i].timestamp = time(NULL);
        packets[i].payload_length = payload_size;

        packets[i].payload = (char*)malloc(packets[i].payload_length);
        if (!packets[i].payload) {
            perror("Failed to allocate memory for packet payload.");
            // Free previously allocated packets
            for (size_t j = 0; j < i; ++j) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        // Populate payload with random bytes
        for (size_t j = 0; j < packets[i].payload_length; ++j) {
            packets[i].payload[j] = (char)(rand() % 256);
        }
    }

    return packets;
}

int main() {
    size_t max_limit = 1024 * 1024; // 1 MB
    size_t packet_count = 100;
    size_t payload_size = 128;

    Packet* packets = process_packets(max_limit, packet_count, payload_size);
    if (packets) {
        printf("Successfully processed %zu packets.\n", packet_count);

        // Clean up allocated memory
        for (size_t i = 0; i < packet_count; ++i) {
            free(packets[i].payload);
        }
        free(packets);
    }

    return 0;
}
