#define MAX_PACKET_SIZE 1500 // Example maximum packet size

typedef struct {
    uint8_t protocol_type;
    uint32_t source_ip;
    uint32_t destination_ip;
    uint16_t payload_length;
} PacketHeader;

PacketHeader* create_packet_headers(int num_packets, int max_payload_length, size_t *total_size) {
    if (num_packets <= 0 || max_payload_length > MAX_PACKET_SIZE) {
        return NULL; // Invalid input
    }

    size_t packet_header_size = sizeof(PacketHeader);
    size_t payload_overhead = sizeof(uint8_t); // Assuming variable-length payload

    size_t required_memory = num_packets * (packet_header_size + payload_overhead);

    // Check for integer overflow
    if (required_memory / num_packets != (packet_header_size + payload_overhead)) {
        return NULL; // Integer overflow detected
    }

    if (required_memory > MAX_PACKET_SIZE) {
        return NULL; // Exceeds maximum allowed memory size
    }

    *total_size = required_memory;
    PacketHeader *headers = (PacketHeader*)malloc(required_memory);

    if (headers == NULL) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_packets; ++i) {
        headers[i].protocol_type = 6; // Example: TCP protocol
        headers[i].source_ip = 0x12345678; // Example source IP
        headers[i].destination_ip = 0x87654321; // Example destination IP
        headers[i].payload_length = max_payload_length;
    }

    return headers;
}

int main() {
    int num_packets = 10;
    size_t total_size;

    PacketHeader *headers = create_packet_headers(num_packets, MAX_PACKET_SIZE, &total_size);

    if (headers != NULL) {
        printf("Memory allocated for %zu packet headers with a total size of %zu bytes.\n", num_packets, total_size);
        free(headers);
    } else {
        printf("Failed to allocate memory for packet headers.\n");
    }

    return 0;
}
