#include <string.h>

#define MAX_PACKETS 1000
#define MAX_PACKET_SIZE 4096

typedef struct {
    int id;
    char* payload;
} PacketMetaData;

PacketMetaData* process_packets(int* packet_ids, int* packet_sizes, int num_packets, int memory_limit) {
    PacketMetaData* packets = (PacketMetaData*)malloc(num_packets * sizeof(PacketMetaData));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    size_t total_size = 0;
    for (int i = 0; i < num_packets; i++) {
        size_t payload_size = (size_t)packet_sizes[i];
        if (payload_size > MAX_PACKET_SIZE || payload_size > memory_limit - total_size) {
            fprintf(stderr, "Packet size exceeds limit or is too large\n");
            for (int j = 0; j < i; j++) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        packets[i].id = packet_ids[i];
        packets[i].payload = (char*)malloc(payload_size * sizeof(char));
        if (!packets[i].payload) {
            fprintf(stderr, "Memory allocation failed for payload\n");
            for (int j = 0; j <= i; j++) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        total_size += payload_size;
    }

    return packets;
}

int main() {
    int packet_ids[MAX_PACKETS] = {1, 2, 3};
    int packet_sizes[MAX_PACKETS] = {512, 1024, 2048};
    int num_packets = 3;
    int memory_limit = MAX_PACKET_SIZE * MAX_PACKETS;

    PacketMetaData* packets = process_packets(packet_ids, packet_sizes, num_packets, memory_limit);
    if (packets) {
        for (int i = 0; i < num_packets; i++) {
            printf("Packet ID: %d, Payload Size: %zu\n", packets[i].id, strlen(packets[i].payload));
            free(packets[i].payload);
        }
        free(packets);
    }

    return 0;
}
