NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_list(int n) {
    char *crc_dir = getenv("CRC_DIR");
    if (!crc_dir) {
        char dir_name[128];
        snprintf(dir_name, sizeof(dir_name), "/tmp/crc_%d", getpid());
        if (mkdir(dir_name, 0755) == -1) {
            perror("Failed to create CRC directory");
            return NULL;
        }
        crc_dir = dir_name;
        setenv("CRC_DIR", crc_dir, 1);
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        list[i].ue_info_tag = rand() % MAX_RX_UE_INFORMATION_TAG;
        list[i].rnti = rand() % MAX_RNTI;
        list[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    return list;
}
