    ImageMetadata **metadata = malloc(sizeof(ImageMetadata *) * count);
    if (metadata == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        metadata[i] = malloc(sizeof(ImageMetadata));
        if (metadata[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for image %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(metadata[j]);
            }
            free(metadata);
            return NULL;
        }

        metadata[i]->filePath = strdup(file_paths[i]);
        if (metadata[i]->filePath == NULL) {
            fprintf(stderr, "Memory allocation failed for file path of image %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(metadata[j]->filePath);
                free(metadata[j]);
            }
            free(metadata);
            return NULL;
        }

        // Placeholder for loading metadata from file
        metadata[i]->width = 800; // Example value
        metadata[i]->height = 600; // Example value
    }

    return metadata;
}

void free_image_metadata(ImageMetadata **metadata, int count) {
    for (int i = 0; i < count; ++i) {
        free(metadata[i]->filePath);
        free(metadata[i]);
    }
    free(metadata);
}

int main() {
    const char *file_paths[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    int count = sizeof(file_paths) / sizeof(file_paths[0]);

    ImageMetadata **metadata = load_image_metadata(file_paths, count);
    if (metadata != NULL) {
        // Process metadata
        for (int i = 0; i < count; ++i) {
            printf("File Path: %s, Width: %d, Height: %d\n", 
                   metadata[i]->filePath, metadata[i]->width, metadata[i]->height);
        }

        free_image_metadata(metadata, count);
    }

    return 0;
}
