#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define BUFFER_LIMIT 1048576 // 1 MB

typedef struct {
    char* buffer;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} PacketBuffer;

void init_buffer(PacketBuffer* buffer) {
    buffer->buffer = (char*)malloc(BUFFER_LIMIT);
    if (!buffer->buffer) {
        fprintf(stderr, "Failed to allocate initial buffer\n");
        exit(EXIT_FAILURE);
    }
    buffer->allocated_size = BUFFER_LIMIT;
    buffer->used_size = 0;
    pthread_mutex_init(&buffer->lock, NULL);
}

void free_buffer(PacketBuffer* buffer) {
    pthread_mutex_lock(&buffer->lock);
    free(buffer->buffer);
    pthread_mutex_unlock(&buffer->lock);
    pthread_mutex_destroy(&buffer->lock);
}

int add_packet_to_buffer(PacketBuffer* buffer, const char* packet, size_t size) {
    pthread_mutex_lock(&buffer->lock);
    if (size > BUFFER_LIMIT - buffer->used_size) {
        pthread_mutex_unlock(&buffer->lock);
        return -1; // Not enough space
    }
    memcpy(buffer->buffer + buffer->used_size, packet, size);
    buffer->used_size += size;
    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

void* process_packets(void* arg) {
    PacketBuffer* buffer = (PacketBuffer*)arg;
    // Simulate packet processing
    while (1) {
        // Wait for packets to arrive
        // For demonstration, we'll simulate a delay and add a dummy packet
        usleep(50000); // 50 ms delay

        const char* dummy_packet = "Dummy Packet";
        size_t dummy_size = strlen(dummy_packet);
        if (add_packet_to_buffer(buffer, dummy_packet, dummy_size) == -1) {
            printf("Packet too large to add\n");
        } else {
            printf("Processed packet of size %zu\n", dummy_size);
        }
    }
    return NULL;
}

int main() {
    PacketBuffer buffer;
    init_buffer(&buffer);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_packets, &buffer) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        free_buffer(&buffer);
        return EXIT_FAILURE;
    }

    // Simulate main program doing other tasks
    sleep(10);

    pthread_cancel(thread_id);
    pthread_join(thread_id, NULL);

    free_buffer(&buffer);
    return EXIT_SUCCESS;
}
