struct MemoryPool {
    void* pool_start;
    size_t pool_size;
    size_t block_size;
    uint8_t* free_list;
    pthread_mutex_t lock;
};

typedef struct MemoryPool MemoryPool;

MemoryPool* create_memory_pool(size_t total_size, size_t block_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    pool->pool_start = malloc(total_size);
    if (!pool->pool_start) {
        free(pool);
        return NULL;
    }
    pool->pool_size = total_size;

    // Initialize the free list
    for (size_t offset = 0; offset < total_size - block_size; offset += block_size) {
        ((uint8_t*)pool->free_list)[offset] = (uint8_t*)(pool->free_list + offset + block_size);
    }
    ((uint8_t*)pool->free_list)[total_size - block_size] = NULL;

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    uint8_t* free_block = pool->free_list;
    if (free_block) {
        pool->free_list = *(uint8_t**)free_block;
    }
    pthread_mutex_unlock(&pool->lock);
    return free_block;
}

void deallocate_to_pool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    *((uint8_t**)block) = pool->free_list;
    pool->free_list = (uint8_t*)block;
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool* pool) {
    void* block = allocate_from_pool(pool);
    if (!block) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)block;
    // Initialize the PDU with data from external source
    // Example: populate_pdu(pdu);

    return pdu;
}

void deallocate_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Free any additional resources associated with the PDU if necessary

    deallocate_to_pool(pool, pdu);
}

void adjust_memory_budget(MemoryPool* pool, size_t new_budget) {
    pthread_mutex_lock(&pool->lock);
    void* old_start = pool->pool_start;
    size_t old_size = pool->pool_size;

    pool->pool_start = realloc(pool->pool_start, new_budget);
    if (!pool->pool_start) {
        pool->pool_start = old_start;
        pool->pool_size = old_size;
    } else {
        pool->pool_size = new_budget;
        // Re-initialize the free list
        for (size_t offset = 0; offset < new_budget - pool->block_size; offset += pool->block_size) {
            ((uint8_t*)pool->free_list)[offset] = (uint8_t*)(pool->free_list + offset + pool->block_size);
        }
        ((uint8_t*)pool->free_list)[new_budget - pool->block_size] = NULL;
    }
    pthread_mutex_unlock(&pool->lock);
}

// Example usage:
MemoryPool* my_pool = create_memory_pool(INITIAL_MEMORY_BUDGET, sizeof(NFAPI_CRC_INDICATION_PDU_T));
if (my_pool) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu(my_pool);
    if (pdu) {
        // Use the PDU
        deallocate_pdu(my_pool, pdu);
    }
    free_memory_pool(my_pool);
}
