    }
    current_size = max_size;
}

void resize_array(int new_max_size) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array, new_max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Failed to reallocate memory for array\n");
        exit(EXIT_FAILURE);
    }
