    if (log_file) {
        fprintf(log_file, "%s\n", event);
        fflush(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int N) {
    if (N > MAX_STRUCTURES) {
        log_event("Error: Request exceeds maximum allowed structures.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        log_event("Error: Memory allocation failed.");
        return NULL;
    }

    pthread_mutex_lock(&allocation_mutex);
    total_allocated_structures += N;

    if (total_allocated_structures > MEMORY_THRESHOLD / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_event("Warning: Exceeding memory threshold.");
        free(pdu_array);
        total_allocated_structures -= N;
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdu_array[i].rx_ue_information_tag = rand();
        pdu_array[i].rnti = rand();
        pdu_array[i].crc_indication_rel8_tag = rand();
        pdu_array[i].crcflag = rand() % 2;
    }

    log_event("Successfully allocated structures.");
    pthread_mutex_unlock(&allocation_mutex);

    return pdu_array;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int N) {
    if (pdu_array) {
        free(pdu_array);
        pthread_mutex_lock(&allocation_mutex);
        total_allocated_structures -= N;
        log_event(" Freed structures.");
        pthread_mutex_unlock(&allocation_mutex);
    }
}
