#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024

typedef struct Packet {
    int size;
    char *data;
    struct Packet *next;
} Packet;

typedef struct PacketManager {
    size_t budget;
    size_t used_memory;
    Packet *head;
    pthread_mutex_t lock;
} PacketManager;

PacketManager* create_packet_manager(size_t budget) {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->budget = budget;
    manager->used_memory = 0;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    Packet *current = manager->head;
    while (current != NULL) {
        Packet *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_packet(PacketManager *manager, int size, const char *data) {
    if (size > MAX_PACKET_SIZE || size <= 0) return -1;

    Packet *new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) return -2;

    new_packet->size = size;
    new_packet->data = (char*)malloc(size);
    if (!new_packet->data) {
        free(new_packet);
        return -3;
    }

    memcpy(new_packet->data, data, size);
    new_packet->next = NULL;

    pthread_mutex_lock(&manager->lock);
    if ((manager->used_memory + size > manager->budget)) {
        pthread_mutex_unlock(&manager->lock);
        free(new_packet->data);
        free(new_packet);
        return -4;
    }

    if (manager->head == NULL) {
        manager->head = new_packet;
    } else {
        Packet *current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_packet;
    }
    manager->used_memory += size;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void remove_packets(PacketManager *manager, int min_size) {
    pthread_mutex_lock(&manager->lock);
    Packet *current = manager->head;
    Packet *prev = NULL;

    while (current != NULL) {
        if (current->size < min_size) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data);
            free(current);
            current = prev ? prev->next : manager->head;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    PacketManager *manager = create_packet_manager(10240); // 10KB budget
    if (manager) {
        add_packet(manager, 1000, "Hello");
        add_packet(manager, 500, "World");
        remove_packets(manager, 600);
        destroy_packet_manager(manager);
    }
    return 0;
}
