    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
} LinkedList;

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    if (list->tail == NULL) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->size++;
}

void offloadList(LinkedList* list) {
    if (list->size <= THRESHOLD) return;

    Node* temp = list->head;
    while (temp != NULL && list->size > THRESHOLD) {
        Node* nextNode = temp->next;
        free(temp);
        temp = nextNode;
        list->size--;
    }
    list->head = temp;
}

void logCreation(NFAPI_CRC_INDICATION_PDU_T data, int transactionID, time_t timestamp) {
    // Assuming a logging function is already implemented
    printf("CRC Indication Created - RNTI: %d, Transaction ID: %d, Timestamp: %ld\n", data.RNTI, transactionID, timestamp);
}

void updateRealTimeStats(LinkedList* list) {
    // Assuming real-time stats are tracked and updated elsewhere
    printf("Current List Size: %d\n", list->size);
}

int main() {
    LinkedList list;
    initializeLinkedList(&list);

    srand(time(NULL));
    for (int i = 0; i < MAX_ENTRIES; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 2;

        insertNode(&list, pdu);
        logCreation(pdu, i, time(NULL));
        updateRealTimeStats(&list);

        if (i % 60 == 0) {
            offloadList(&list);
        }
    }

    return 0;
}
