#define MAX_PACKETS 1000
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    uint32_t metadata;
    char payload[MAX_PAYLOAD_SIZE];
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    size_t packet_count;
    size_t total_memory_used;
    size_t max_memory_budget;
    pthread_mutex_t lock;
} PacketProcessor;

void init_packet_processor(PacketProcessor *processor, size_t budget) {
    processor->packet_count = 0;
    processor->total_memory_used = 0;
    processor->max_memory_budget = budget;
    pthread_mutex_init(&processor->lock, NULL);
}

int add_packet(PacketProcessor *processor, uint32_t metadata, const char *payload, size_t payload_size) {
    pthread_mutex_lock(&processor->lock);

    if (processor->packet_count >= MAX_PACKETS || processor->total_memory_used + payload_size > processor->max_memory_budget) {
        pthread_mutex_unlock(&processor->lock);
        return -1; // Resource limit exceeded
    }

    Packet *new_packet = &processor->packets[processor->packet_count++];
    new_packet->metadata = metadata;
    memcpy(new_packet->payload, payload, payload_size);
    processor->total_memory_used += payload_size;

    pthread_mutex_unlock(&processor->lock);
    log_success("Packet added successfully");
    return 0;
}

void print_statistics(PacketProcessor *processor) {
    double average_payload_size = (double)processor->total_memory_used / processor->packet_count;
    printf("Number of packets processed: %zu\n", processor->packet_count);
    printf("Average payload size: %.2f bytes\n", average_payload_size);
    printf("Total memory used: %zu bytes\n", processor->total_memory_used);
}

void free_packets(PacketProcessor *processor) {
    pthread_mutex_lock(&processor->lock);

    for (size_t i = 0; i < processor->packet_count; ++i) {
        // No need to free payload as it's a fixed-size array
    }

    processor->packet_count = 0;
    processor->total_memory_used = 0;

    pthread_mutex_unlock(&processor->lock);
}
