#define MAX_PACKETS 1024

typedef struct {
    int payload_length;
    char *payload;
} NetworkPacketHeader;

int validate_payload(NetworkPacketHeader *header, int expected_length) {
    if (expected_length != header->payload_length) {
        return -1; // Payload length mismatch
    }
    return 0; // Payload is valid
}

NetworkPacketHeader **process_network_traffic(char *traffic, size_t traffic_size, size_t max_payload_size, int (*validate_payload_func)(NetworkPacketHeader *, int)) {
    NetworkPacketHeader **valid_packets = (NetworkPacketHeader **)malloc(MAX_PACKETS * sizeof(NetworkPacketHeader *));
    if (!valid_packets) {
        perror("Failed to allocate memory for valid packets");
        return NULL;
    }

    size_t packet_count = 0;
    size_t current_index = 0;

    while (current_index < traffic_size) {
        NetworkPacketHeader header;
        // Parse header from traffic buffer
        memcpy(&header.payload_length, traffic + current_index, sizeof(header.payload_length));
        current_index += sizeof(header.payload_length);

        if (header.payload_length > max_payload_size || header.payload_length <= 0) {
            printf("Invalid payload length: %d\n", header.payload_length);
            continue;
        }

        // Check for integer overflow
        size_t required_memory = current_index + header.payload_length;
        if (required_memory < current_index || required_memory > traffic_size) {
            perror("Integer overflow detected");
            free(valid_packets);
            return NULL;
        }

        header.payload = (char *)traffic + current_index;
        current_index += header.payload_length;

        if (validate_payload_func(&header, max_payload_size) == 0) {
            valid_packets[packet_count++] = (NetworkPacketHeader *)malloc(sizeof(NetworkPacketHeader));
            if (!valid_packets[packet_count - 1]) {
                perror("Failed to allocate memory for packet");
                free(valid_packets);
                return NULL;
            }
            memcpy(valid_packets[packet_count - 1], &header, sizeof(header));
        } else {
            printf("Invalid packet detected\n");
        }

        if (packet_count >= MAX_PACKETS) {
            break; // Limit reached
        }
    }

    valid_packets[packet_count] = NULL;
    return valid_packets;
}

