#define MAX_CONFIGS 1000
#define MEM_CAP (MAX_CONFIGS * sizeof(interface_config_t))

typedef struct {
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
    char dns_server[16];
} interface_config_t;

interface_config_t* config_list = NULL;
int current_configs = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void check_memory_allocation(size_t size) {
    if (size > MEM_CAP - sizeof(interface_config_t)) {
        // Handle error: memory allocation exceeds cap
        exit(EXIT_FAILURE);
    }
}

interface_config_t* add_config(const char* ip, const char* subnet_mask, const char* gateway, const char* dns_server) {
    pthread_mutex_lock(&lock);
    if (current_configs >= MAX_CONFIGS) {
        // Handle error: config list is full
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    check_memory_allocation(current_configs + 1);
    interface_config_t* new_config = &config_list[current_configs++];
    strcpy(new_config->ip, ip);
    strcpy(new_config->subnet_mask, subnet_mask);
    strcpy(new_config->gateway, gateway);
    strcpy(new_config->dns_server, dns_server);
    pthread_mutex_unlock(&lock);
    return new_config;
}

void update_config(interface_config_t* config, const char* ip, const char* subnet_mask, const char* gateway, const char* dns_server) {
    if (config >= &config_list[current_configs] || config < config_list) {
        // Handle error: invalid configuration pointer
        return;
    }
    pthread_mutex_lock(&lock);
    strcpy(config->ip, ip);
    strcpy(config->subnet_mask, subnet_mask);
    strcpy(config->gateway, gateway);
    strcpy(config->dns_server, dns_server);
    pthread_mutex_unlock(&lock);
}

void remove_config(interface_config_t* config) {
    if (config >= &config_list[current_configs] || config < config_list) {
        // Handle error: invalid configuration pointer
        return;
    }
    pthread_mutex_lock(&lock);
    memmove(config, config + 1, (current_configs - (config - config_list) - 1) * sizeof(interface_config_t));
    current_configs--;
    pthread_mutex_unlock(&lock);
}

void initialize_config_list() {
    config_list = (interface_config_t*)malloc(MEM_CAP);
    if (!config_list) {
        // Handle error: memory allocation failed
        exit(EXIT_FAILURE);
    }
}

void free_config_list() {
    free(config_list);
}
