int check_integer_overflow(int size, size_t element_size) {
    if (size > 0 && SIZE_MAX / size < element_size) {
        return -1;
    }
    return 0;
}

compressed_image_t* allocate_compressed_images(int *N, int max_N, double* retry_delay) {
    static int retry_count = 0;

    // Calculate dynamic threshold
    *N = get_dynamic_threshold();

    // Ensure N does not exceed max allowed number
    if (*N > max_N) {
        *N = max_N;
    }

    size_t element_size = sizeof(compressed_image_t);
    size_t total_size = *N * element_size;

    if (check_integer_overflow(*N, element_size) != 0) {
        fprintf(stderr, "Integer overflow detected in memory allocation.\n");
        return NULL;
    }

    compressed_image_t* images = malloc(total_size);

    if (!images) {
        retry_count++;
        if (retry_count < MAX_RETRY_ATTEMPTS) {
            *retry_delay *= 1.5; // Exponential backoff
            fprintf(stderr, "Memory allocation failed. Retrying after %.2f seconds...\n", *retry_delay);
            sleep((unsigned int)(*retry_delay));
            return allocate_compressed_images(N, max_N, retry_delay);
        } else {
            fprintf(stderr, "Failed to allocate memory after %d attempts.\n", MAX_RETRY_ATTEMPTS);
            return NULL;
        }
    }

    retry_count = 0; // Reset retry count on successful allocation

    for (int i = 0; i < *N; i++) {
        images[i].id = i;
        // Initialize pixel data or allocate memory for it
        images[i].data.width = rand() % 1024 + 1;
        images[i].data.height = rand() % 768 + 1;
        size_t pixels_size = images[i].data.width * images[i].data.height;
        if (check_integer_overflow(pixels_size, sizeof(unsigned char)) != 0) {
            fprintf(stderr, "Integer overflow detected in pixel data allocation for image %d.\n", i);
            return NULL;
        }
        images[i].data.pixels = malloc(pixels_size * sizeof(unsigned char));
        if (!images[i].data.pixels) {
            fprintf(stderr, "Failed to allocate memory for pixel data of image %d.\n", i);
            // Free previously allocated images
            for (int j = 0; j < i; j++) {
                free(images[j].data.pixels);
            }
            free(images);
            return NULL;
        }
    }

    return images;
}

void free_compressed_images(compressed_image_t* images, int N) {
    for (int i = 0; i < N; i++) {
        free(images[i].data.pixels);
    }
    free(images);
}

int main() {
    srand(time(NULL));
    double retry_delay = 1.0;
    int max_N = 20;
    int N;

    compressed_image_t* images = allocate_compressed_images(&N, max_N, &retry_delay);

    if (images) {
        printf("Allocated %d compressed image structures successfully.\n", N);
        // Use the allocated images
        free_compressed_images(images, N);
    }

    return 0;
}
