#include <time.h>

#define MAX_PDU_COUNT 1000
#define MIN_REQUEST_LIMIT 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    MEMORY_SUCCESS,
    MEMORY_FAILURE,
    MEMORY_STRESS
} MemoryStatus;

void logMemoryUsage(size_t allocatedSize, size_t totalAllocations, MemoryStatus status) {
    printf("Allocated Size: %zu bytes\n", allocatedSize);
    printf("Total Allocations: %zu\n", totalAllocations);
    if (status == MEMORY_FAILURE) {
        printf("Memory Allocation Failed!\n");
    } else if (status == MEMORY_STRESS) {
        printf("Simulating Memory Stress!\n");
    }
}

size_t simulateMemoryStress(size_t size, int stressPercentage) {
    return (size * stressPercentage) / 100;
}

NFAPI_CRC_INDICATION_PDU_T* allocatePduArray(int requestLimit, int memoryStressPercentage) {
    if (requestLimit < MIN_REQUEST_LIMIT || requestLimit > MAX_PDU_COUNT) {
        logMemoryUsage(0, 0, MEMORY_FAILURE);
        return NULL;
    }

    size_t totalSize = requestLimit * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t effectiveSize = simulateMemoryStress(totalSize, memoryStressPercentage);

    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(effectiveSize);
    if (!pduArray) {
        logMemoryUsage(0, 0, MEMORY_FAILURE);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < requestLimit; i++) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pduArray[i].RNTI = rand() % 256;
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pduArray[i].CRCFLAG = (rand() % 2) ? 'C' : 'N';
    }

    logMemoryUsage(effectiveSize, requestLimit, MEMORY_SUCCESS);
    return pduArray;
}

int main() {
    int requestLimit = 500;
    int memoryStressPercentage = 30;

    NFAPI_CRC_INDICATION_PDU_T* pduArray = allocatePduArray(requestLimit, memoryStressPercentage);

    if (pduArray) {
        // Use the allocated array
        free(pduArray);
    }

    return 0;
}
