    if (count <= 0 || count > MAX_IMAGE_COUNT) {
        return NULL; // Invalid count
    }

    for (int i = 0; i < count; ++i) {
        if (*width * *height > MAX_RESOLUTION) {
            return NULL; // Exceeds resolution limit
        }
        *width *= *height;
    }

    ImageMetadata** metadata_array = (ImageMetadata**)malloc(count * sizeof(ImageMetadata*));
    if (!metadata_array) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < count; ++i) {
        metadata_array[i] = (ImageMetadata*)malloc(sizeof(ImageMetadata));
        if (!metadata_array[i]) {
            // Free previously allocated memory in case of failure
            for (int j = 0; j < i; ++j) {
                free(metadata_array[j]);
            }
            free(metadata_array);
            return NULL;
        }
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize metadata array with data from external source
    // ...

    pthread_mutex_destroy(&lock);

    return metadata_array;
}

void free_image_metadata(ImageMetadata** metadata_array, int count) {
    for (int i = 0; i < count; ++i) {
        if (metadata_array[i]) {
            free(metadata_array[i]);
        }
    }
    free(metadata_array);
}
