LinkedListManager* create_linked_list_manager() {
    LinkedListManager* manager = (LinkedListManager*)malloc(sizeof(LinkedListManager));
    if (manager == NULL) {
        perror("Failed to allocate memory for LinkedListManager");
        exit(EXIT_FAILURE);
    }
    manager->head = NULL;
    manager->total_memory_used = 0;
    manager->structure_count = 0;
    return manager;
}

NFAPI_CRC_INDICATION_PDU_T* create_new_structure() {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_struct == NULL) {
