        exit(EXIT_FAILURE);
    }
    return new_struct;
}

void populate_structure(NFAPI_CRC_INDICATION_PDU_T* struct_ptr, int rx_tag, int rnti) {
    static int crc_flag = 0;
    struct_ptr->RX_UE_INFORMATION_TAG = rx_tag;
    struct_ptr->RNTI = rnti;
    struct_ptr->CRC_INDICATION_REL8_TAG = rand() % 10; // Random CRC Indication
    struct_ptr->CRCFLAG = crc_flag++;
    struct_ptr->next = NULL;
}

void add_to_list(LinkedListManager* manager, NFAPI_CRC_INDICATION_PDU_T* new_struct) {
    if (manager->head == NULL) {
        manager->head = new_struct;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_struct;
    }
}

void manage_memory_usage(LinkedListManager* manager, size_t memory_to_allocate) {
    if (manager->total_memory_used + memory_to_allocate > 1024 * 1024) {
        printf("Memory limit exceeded. Structure not added.\n");
    } else {
        manager->total_memory_used += memory_to_allocate;
        manager->structure_count++;
        printf("Structure added. Total Memory Used: %zu, Structure Count: %zu\n", manager->total_memory_used, manager->structure_count);
    }
}

void simulate_external_data_source(LinkedListManager* manager) {
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_struct = create_new_structure();
        populate_structure(new_struct, rand() % 100, rand() % 256);
        manage_memory_usage(manager, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        add_to_list(manager, new_struct);
    }
}

void free_linked_list(LinkedListManager* manager) {
    NFAPI_CRC_INDICATION_PDU_T* current = manager->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }
    free(manager);
}

int main() {
    LinkedListManager* manager = create_linked_list_manager();
    simulate_external_data_source(manager);
    free_linked_list(manager);
    return 0;
}
