    ImageNode *head;
    ImageNode *tail;
    int maxImages;
    int currentCount;
} ImagePipeline;

ImageNode* createImageNode(Image *img) {
    ImageNode *node = (ImageNode*)malloc(sizeof(ImageNode));
    node->img = img;
    node->next = NULL;
    return node;
}

void freeImageNode(ImageNode *node) {
    if (node) {
        free(node);
    }
}

ImagePipeline* createImagePipeline(int maxImages) {
    ImagePipeline *pipeline = (ImagePipeline*)malloc(sizeof(ImagePipeline));
    pipeline->head = pipeline->tail = NULL;
    pipeline->maxImages = maxImages;
    pipeline->currentCount = 0;
    return pipeline;
}

void freeImagePipeline(ImagePipeline *pipeline) {
    if (pipeline) {
        ImageNode *current = pipeline->head;
        while (current) {
            ImageNode *next = current->next;
            free(current);
            current = next;
        }
        free(pipeline);
    }
}

