        return;
    }

    ImageNode *newNode = createImageNode(img);
    if (!pipeline->head) {
        pipeline->head = pipeline->tail = newNode;
    } else {
        pipeline->tail->next = newNode;
        pipeline->tail = newNode;
    }
    pipeline->currentCount++;
}

