#include <stdio.h>
#include <stdlib.h>

#define MAX_LAYERS 1000
#define MAX_SIZE 1024 * 1024 // 1 MB

typedef struct Layer {
    int width;
    int height;
    unsigned char* data;
} Layer;

typedef struct Image {
    Layer** layers;
    int numLayers;
} Image;

Image* loadImage(const char* configFilePath) {
    FILE* configFile = fopen(configFilePath, "r");
    if (!configFile) {
        fprintf(stderr, "Failed to open configuration file.\n");
        return NULL;
    }

    Image* image = malloc(sizeof(Image));
    if (!image) {
        perror("Failed to allocate memory for image structure.");
        fclose(configFile);
        return NULL;
    }
    image->layers = NULL;
    image->numLayers = 0;

    int width, height;
    while (fscanf(configFile, "%d %d", &width, &height) == 2) {
        if (image->numLayers >= MAX_LAYERS || width <= 0 || height <= 0 || width > MAX_SIZE / height) {
            fprintf(stderr, "Invalid layer dimensions or configuration file too large.\n");
            free(image);
            fclose(configFile);
            return NULL;
        }

        Layer* layer = malloc(sizeof(Layer));
        if (!layer) {
            perror("Failed to allocate memory for layer structure.");
            free(image->layers);
            free(image);
            fclose(configFile);
            return NULL;
        }
        layer->width = width;
        layer->height = height;

        layer->data = malloc(width * height);
        if (!layer->data) {
            perror("Failed to allocate memory for layer data.");
            free(layer);
            free(image->layers);
            free(image);
            fclose(configFile);
            return NULL;
        }

        // Initialize layer data (e.g., set to zero)
        memset(layer->data, 0, width * height);

        image->numLayers++;
        if (!(image->layers = realloc(image->layers, image->numLayers * sizeof(Layer*)))) {
            perror("Failed to reallocate memory for layers array.");
            free(layer->data);
            free(layer);
            free(image->layers);
            free(image);
            fclose(configFile);
            return NULL;
        }
        image->layers[image->numLayers - 1] = layer;
    }

    fclose(configFile);
    return image;
}

void processImage(Image* image) {
    if (!image || !image->layers) {
        fprintf(stderr, "Invalid image or layers data.\n");
        return;
    }

    for (int i = 0; i < image->numLayers; i++) {
        Layer* layer = image->layers[i];
        // Process each layer's data
        printf("Processing layer %d with dimensions %dx%d\n", i, layer->width, layer->height);
        // Example processing: invert colors
        for (int y = 0; y < layer->height; y++) {
            for (int x = 0; x < layer->width; x++) {
                layer->data[y * layer->width + x] = 255 - layer->data[y * layer->width + x];
            }
        }
    }
}

void freeImage(Image* image) {
    if (!image || !image->layers) {
        return;
    }

    for (int i = 0; i < image->numLayers; i++) {
        Layer* layer = image->layers[i];
        free(layer->data);
        free(layer);
    }
    free(image->layers);
    free(image);
}

int main() {
    Image* image = loadImage("image_config.txt");
    if (image) {
        processImage(image);
        freeImage(image);
    }

    return 0;
}
