}

void resize_image(NFAPI_CRC_INDICATION_PDU_T *service, int index, int new_width, int new_height) {
    if (index >= 0 && index < service->num_images) {
        service->images[index].width = new_width;
        service->images[index].height = new_height;
    } else {
        printf("Error: Invalid image index.\n");
    }
}

