    int max_count;
} SessionData;

SessionData* create_session(int max_structs) {
    if (max_structs > MAX_STRUCTS_PER_SESSION) {
        printf("Error: Max structs per session exceeded.\n");
        return NULL;
    }

    SessionData* session = (SessionData*)malloc(sizeof(SessionData));
    if (!session) {
        printf("Memory allocation failed for session data.\n");
        return NULL;
    }

    session->structs = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!session->structs) {
        printf("Memory allocation failed for session structs.\n");
        free(session);
        return NULL;
    }

    session->max_count = max_structs;
    session->current_count = 0;

    return session;
}

int add_structure(SessionData* session, NFAPI_CRC_INDICATION_PDU_T* new_struct) {
    if (session->current_count >= session->max_count) {
        printf("Error: Session has reached the maximum number of structures.\n");
        return -1;
    }

    session->structs[session->current_count] = new_struct;
    session->current_count++;
    return 0;
}

void destroy_session(SessionData* session) {
    if (session->structs) {
        free(session->structs);
    }
    free(session);
}

int main() {
    // Example usage
