#define MAX_FILE_PATH 256

typedef struct {
    char path[MAX_FILE_PATH];
    int width;
    int height;
} Image;

Image* load_images_from_directory(const char* directory_path, size_t* total_memory_required) {
    DIR* dir;
    struct dirent* ent;
    size_t num_images = 0;
    Image* images = NULL;

    dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        return NULL;
    }

    // First pass: count the number of image files
    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, ".jpg") || strstr(ent->d_name, ".png")) {
            num_images++;
        }
    }

    if (num_images == 0) {
        printf("No images found in the directory.\n");
        closedir(dir);
        return NULL;
    }

    // Allocate memory for image array
    images = malloc(num_images * sizeof(Image));
    if (!images) {
        perror("Failed to allocate memory for image array");
        closedir(dir);
        return NULL;
    }

    // Second pass: load the images and compute total memory required
    rewinddir(dir);
    size_t current_memory_used = num_images * sizeof(Image);

    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, ".jpg") || strstr(ent->d_name, ".png")) {
            snprintf(images[current_memory_used / sizeof(Image)].path, MAX_FILE_PATH, "%s/%s", directory_path, ent->d_name);
            // Simulate loading image dimensions
            images[current_memory_used / sizeof(Image)].width = 800;
            images[current_memory_used / sizeof(Image)].height = 600;

            current_memory_used += strlen(images[current_memory_used / sizeof(Image)].path) + 1; // Add space for null terminator

            if (current_memory_used > SIZE_MAX - sizeof(Image)) {
                printf("Integer overflow detected. Proceeding with partial loading.\n");
                break;
            }
        }
    }

    closedir(dir);

    *total_memory_required = current_memory_used;

    return images;
}

int main() {
    size_t total_memory_required;
    Image* images = load_images_from_directory("path_to_image_directory", &total_memory_required);

    if (images) {
        printf("Total memory required for image data: %zu bytes\n", total_memory_required);
        free(images);
    }

    return 0;
}
