ImageMetadata* process_directory(const char* directory, size_t* num_images) {
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return NULL;
    }

    struct dirent* entry;
    ImageMetadata* metadata = NULL;
    size_t initial_estimate = 0;

    // Estimate memory needed
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file check
            struct stat st;
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
            if (stat(path, &st) == 0) {
                initial_estimate += sizeof(ImageMetadata);
            }
        }
    }

    // Allocate memory with some margin for growth
    metadata = realloc(NULL, initial_estimate + (initial_estimate / 4));
    if (metadata == NULL) {
        perror("realloc");
        closedir(dir);
        return NULL;
    }

    // Populate the structure array
    rewinddir(dir);
    size_t count = 0;
    while ((entry = readdir(dir)) != NULL && count < MAX_FILES) {
        if (entry->d_type == DT_REG) {
            struct stat st;
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
            if (stat(path, &st) == 0) {
                strcpy(metadata[count].filename, entry->d_name);
                metadata[count].width = rand() % 1920 + 1; // Random width between 1 and 1920
                metadata[count].height = rand() % 1080 + 1; // Random height between 1 and 1080
                metadata[count].file_size = st.st_size;

                if (metadata[count].file_size < MIN_FILE_SIZE || metadata[count].file_size > MAX_FILE_SIZE) {
                    fprintf(stderr, "Invalid file size for %s\n", metadata[count].filename);
                    count--;
                }

                count++;
            }
        }
    }

    *num_images = count;
    closedir(dir);
    return metadata;
}

void free_metadata(ImageMetadata* metadata, size_t count) {
    // Free any dynamically allocated memory within the structure array
    for (size_t i = 0; i < count; i++) {
        // Assuming no dynamic memory is allocated inside ImageMetadata, this step is redundant.
        // If dynamic memory were used, it should be freed here.
    }

    free(metadata);
}
