typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

void dynamic_list_init(DynamicList *list, size_t initial_capacity) {
    list->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        fprintf(stderr, "List size limit reached\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    list->list[list->size++] = item;

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_destroy(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->list);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
