#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertAtHead(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    newNode->next = *head;
    *head = newNode;
}

int main() {
    srand(time(0));
    int N = 10; // Example number of structures to create
    int safetyMargin = 5; // Safety margin for memory allocation

    Node* head = NULL;

    for (int i = 0; i < N + safetyMargin; i++) {
        if (i >= N) {
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 1000;
        data.RNTI = rand() % 1024;
        data.CRC_INDICATION_REL8_TAG = (unsigned char)(rand() % 3); // Randomly set CRCFLAG

        insertAtHead(&head, data);
    }

    Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRC_INDICATION_REL8_TAG: %hhu\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG);
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}
```

