#include <time.h>

#define MAX_UE_DEVICES 1000

typedef struct {
    // Define your RX_UE_INFORMATION_TAG structure here
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned short RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned long long get_valid_rx_ue_information_tag() {
    // Implement logic to fetch a valid RX_UE_INFORMATION_TAG from the network interface
    static unsigned long long tag = 0;
    tag++;
    return tag % MAX_UE_DEVICES; // Simulate fetching a valid tag within the range of available devices
}

unsigned short get_valid_rnti() {
    // Implement logic to fetch a valid RNTI from the network interface
    static unsigned short rnti = 0;
    rnti++;
    return rnti % MAX_UE_DEVICES; // Simulate fetching a valid RNTI within the range of available devices
}

void generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **pdus, int N) {
    if (N <= 0 || N > MAX_UE_DEVICES * 2) {
        printf("Invalid number of PDUs requested: %d\n", N);
        return;
    }

    pdus = realloc(pdus, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        printf("Memory allocation failed for %d PDUs\n", N);
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; i++) {
        pdus[i].RNTI = get_valid_rnti();
        pdus[i].RX_UE_INFORMATION_TAG.tag = get_valid_rx_ue_information_tag(); // Assuming tag is a member of RX_UE_INFORMATION_TAG
    }
}

int main() {
    int N;
    printf("Enter the number of PDUs to generate (1-%d): ", MAX_UE_DEVICES * 2);
    scanf("%d", &N);

    NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!pdus) {
        printf("Memory allocation failed for PDUs list\n");
        return 1;
    }

    generate_crc_indication_pdu(pdus, N);

    // Use the generated PDUs as needed

    free(pdus);
    return 0;
}
